Below is a complete C program that uses nftw() to traverse a directory tree, supports -cp (copy) and -mv (move), preserves directory hierarchy, excludes up to 6 extensions, ensures source/destination are under the user's home directory, creates the destination if missing, and handles errors. It also includes sample runs.

Notes:
- Usage: prog_name (-cp|-mv) <source_dir> <dest_dir> [ext1 ext2 ... up to 6]
- Extensions should be provided without the leading dot (e.g., tmp log bak).

Code:

#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/sendfile.h>
#include <fcntl.h>
#include <unistd.h>
#include <libgen.h>
#include <limits.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_EXCLUDES 6

static char home_path[PATH_MAX];
static char src_root[PATH_MAX];
static char dst_root[PATH_MAX];
static int do_move = 0; // 0=copy, 1=move
static char *excludes[MAX_EXCLUDES];
static int excludes_count = 0;

static int has_excluded_ext(const char *path, const struct stat *st)
{
    if (!S_ISREG(st->st_mode)) return 0; // only exclude regular files by extension
    const char *dot = strrchr(path, '.');
    if (!dot || dot == path) return 0;
    const char *ext = dot + 1; // skip '.'
    for (int i = 0; i < excludes_count; ++i) {
        if (strcasecmp(ext, excludes[i]) == 0) return 1;
    }
    return 0;
}

static int ensure_parent_dirs(const char *path, mode_t mode)
{
    // Make parent directories as needed (like mkdir -p)
    char temp[PATH_MAX];
    snprintf(temp, sizeof(temp), "%s", path);

    // Remove trailing slash if any (except root)
    size_t len = strlen(temp);
    while (len > 1 && temp[len-1] == '/') {
        temp[--len] = '\0';
    }

    char *p = temp;
    if (*p == '/') p++; // skip leading slash for iteration

    for (; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(temp, mode) == -1 && errno != EEXIST) {
                perror("mkdir");
                return -1;
            }
            *p = '/';
        }
    }
    if (mkdir(temp, mode) == -1 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode)
{
    int in = open(src, O_RDONLY);
    if (in < 0) {
        perror("open src");
        return -1;
    }
    // Create with mode, then apply chmod to preserve exact perms
    int out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out < 0) {
        perror("open dst");
        close(in);
        return -1;
    }

#ifdef __linux__
    struct stat st;
    if (fstat(in, &st) == 0) {
        off_t offset = 0;
        ssize_t sent;
        while (offset < st.st_size) {
            sent = sendfile(out, in, &offset, st.st_size - offset);
            if (sent <= 0) {
                if (errno == EINTR) continue;
                perror("sendfile");
                close(in);
                close(out);
                return -1;
            }
        }
    } else {
        perror("fstat");
        close(in);
        close(out);
        return -1;
    }
#else
    char buf[1 << 16];
    ssize_t r;
    while ((r = read(in, buf, sizeof(buf))) > 0) {
        ssize_t woff = 0;
        while (woff < r) {
            ssize_t w = write(out, buf + woff, r - woff);
            if (w < 0) {
                if (errno == EINTR) continue;
                perror("write");
                close(in);
                close(out);
                return -1;
            }
            woff += w;
        }
    }
    if (r < 0) {
        perror("read");
        close(in);
        close(out);
        return -1;
    }
#endif

    // Preserve mode and times (best effort)
    fchmod(out, mode);

    close(in);
    close(out);
    return 0;
}

static int within_prefix(const char *path, const char *prefix)
{
    size_t lp = strlen(prefix);
    if (lp == 0) return 0;
    if (strncmp(path, prefix, lp) != 0) return 0;
    // Ensure boundary: prefix match either exact or followed by '/'
    return path[lp] == '\0' || path[lp] == '/';
}

static int relpath_from_src(const char *full, char *rel, size_t relsz)
{
    size_t ls = strlen(src_root);
    if (strncmp(full, src_root, ls) != 0) return -1;
    const char *p = full + ls;
    if (*p == '/') p++;
    snprintf(rel, relsz, "%s", p);
    return 0;
}

static int process_entry(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
    (void)ftwbuf;

    // Compute destination path preserving hierarchy
    char rel[PATH_MAX];
    if (relpath_from_src(fpath, rel, sizeof(rel)) != 0) {
        fprintf(stderr, "Path outside of source root: %s\n", fpath);
        return 0; // skip
    }
    char dst_path[PATH_MAX];
    if (rel[0] == '\0') {
        // root itself maps to dst_root
        snprintf(dst_path, sizeof(dst_path), "%s", dst_root);
    } else {
        snprintf(dst_path, sizeof(dst_path), "%s/%s", dst_root, rel);
    }

    switch (typeflag) {
        case FTW_D:
        case FTW_DP:
        case FTW_DNR: {
            // Create destination directory mirroring source
            mode_t mode = sb->st_mode & 0777;
            if (ensure_parent_dirs(dst_path, 0755) == -1) return -1;
            if (mkdir(dst_path, mode) == -1 && errno != EEXIST) {
                perror("mkdir dst dir");
                return -1;
            }
            break;
        }
        case FTW_F:
        case FTW_SL:
        case FTW_SLN:
        default: {
            if (has_excluded_ext(fpath, sb)) {
                // Skip excluded extensions
                return 0;
            }
            // Ensure directory exists for file
            if (ensure_parent_dirs(dst_path, 0755) == -1) return -1;

            if (S_ISREG(sb->st_mode)) {
                if (copy_file(fpath, dst_path, sb->st_mode & 0777) == -1) return -1;
            } else if (S_ISLNK(sb->st_mode)) {
                // Recreate symlink target
                char target[PATH_MAX];
                ssize_t n = readlink(fpath, target, sizeof(target)-1);
                if (n < 0) {
                    perror("readlink");
                    return -1;
                }
                target[n] = '\0';
                // Remove existing if any, then symlink
                unlink(dst_path);
                if (symlink(target, dst_path) == -1) {
                    perror("symlink");
                    return -1;
                }
            } else {
                // Other types (devices, fifos): try mknod with same mode
#ifdef __linux__
                if (mknod(dst_path, sb->st_mode, 0) == -1) {
                    // Best-effort: skip with warning
                    fprintf(stderr, "warn: cannot recreate special file %s: %s\n", fpath, strerror(errno));
                }
#endif
            }
            break;
        }
    }

    return 0;
}

static int remove_source_entry(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
    (void)sb; (void)ftwbuf;
    // Remove in post-order to delete directories after files
    if (typeflag == FTW_DP || typeflag == FTW_D || typeflag == FTW_DNR) {
        if (rmdir(fpath) == -1) {
            perror("rmdir");
            return -1;
        }
    } else {
        if (unlink(fpath) == -1) {
            perror("unlink");
            return -1;
        }
    }
    return 0;
}

static int is_dir(const char *p)
{
    struct stat st;
    if (stat(p, &st) == -1) return 0;
    return S_ISDIR(st.st_mode);
}

static int resolve_realpath(const char *in, char *out, size_t outsz)
{
    char *rp = realpath(in, NULL);
    if (!rp) return -1;
    snprintf(out, outsz, "%s", rp);
    free(rp);
    return 0;
}

static void usage(const char *prog)
{
    fprintf(stderr, "Usage: %s (-cp|-mv) <source_dir> <dest_dir> [ext1 ext2 ... up to 6]\n", prog);
}

int main(int argc, char *argv[])
{
    const char *prog = argv[0];

    const char *hp = getenv("HOME");
    if (!hp) {
        fprintf(stderr, "Error: HOME environment variable not set.\n");
        return EXIT_FAILURE;
    }
    if (!realpath(hp, home_path)) {
        perror("realpath HOME");
        return EXIT_FAILURE;
    }

    if (argc < 4) {
        usage(prog);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "-cp") == 0) {
        do_move = 0;
    } else if (strcmp(argv[1], "-mv") == 0) {
        do_move = 1;
    } else {
        usage(prog);
        return EXIT_FAILURE;
    }

    const char *src_arg = argv[2];
    const char *dst_arg = argv[3];

    // Parse optional extensions
    excludes_count = 0;
    for (int i = 4; i < argc && excludes_count < MAX_EXCLUDES; ++i) {
        excludes[excludes_count++] = argv[i];
    }

    // Resolve real paths and validate
    if (resolve_realpath(src_arg, src_root, sizeof(src_root)) == -1) {
        fprintf(stderr, "Error: Source directory does not exist: %s\n", src_arg);
        return EXIT_FAILURE;
    }
    // Destination may not exist; try to resolve parent
    char dst_tmp[PATH_MAX];
    char dst_parent[PATH_MAX];
    snprintf(dst_tmp, sizeof(dst_tmp), "%s", dst_arg);
    char tmp_copy[PATH_MAX];
    snprintf(tmp_copy, sizeof(tmp_copy), "%s", dst_tmp);
    char *base = basename(tmp_copy);

    char parent_copy[PATH_MAX];
    snprintf(parent_copy, sizeof(parent_copy), "%s", dst_tmp);
    char *dirp = dirname(parent_copy);

    char parent_real[PATH_MAX];
    if (resolve_realpath(dirp, parent_real, sizeof(parent_real)) == -1) {
        fprintf(stderr, "Error: Destination parent directory does not exist: %s\n", dirp);
        return EXIT_FAILURE;
    }
    snprintf(dst_root, sizeof(dst_root), "%s/%s", parent_real, base);

    // Validate both under HOME
    if (!within_prefix(src_root, home_path)) {
        fprintf(stderr, "Error: Source is not within home directory: %s\n", src_root);
        return EXIT_FAILURE;
    }
    if (!within_prefix(dst_root, home_path)) {
        fprintf(stderr, "Error: Destination is not within home directory: %s\n", dst_root);
        return EXIT_FAILURE;
    }

    // Ensure destination directory exists (create if missing)
    if (ensure_parent_dirs(dst_root, 0755) == -1) return EXIT_FAILURE;
    if (!is_dir(dst_root)) {
        if (mkdir(dst_root, 0755) == -1) {
            perror("mkdir dest_root");
            return EXIT_FAILURE;
        }
    }

    // Verify source is a directory
    if (!is_dir(src_root)) {
        fprintf(stderr, "Error: Source is not a directory: %s\n", src_root);
        return EXIT_FAILURE;
    }

    // Traverse and copy/mirror to destination
    int flags = FTW_PHYS; // don't follow symlinks
    // Use a reasonably large number of FDs
    if (nftw(src_root, process_entry, 32, flags | FTW_ACTIONRETVAL) == -1) {
        perror("nftw process");
        return EXIT_FAILURE;
    }

    // If move, remove source tree after successful copy, in post-order
    if (do_move) {
        if (nftw(src_root, remove_source_entry, 32, FTW_DEPTH | FTW_PHYS) == -1) {
            perror("nftw remove");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

Sample runs:
- Copy preserving structure, excluding .tmp and .log files:
  ./prog -cp ~/projects/myapp ~/backup/myapp_copy tmp log

- Move directory tree, excluding .bak files, creating destination if needed:
  ./prog -mv ~/downloads/data ~/archive/data bak

- Error if source is outside HOME:
  ./prog -cp /tmp/outside ~/backup/outside
  Output: Error: Source is not within home directory: /tmp/outside

Below is a complete C program that:
- Uses nftw() to traverse a source directory tree.
- Supports -cp (copy) and -mv (move) options.
- Maintains directory hierarchy at the destination.
- Creates the destination directory if it does not exist (under $HOME).
- Excludes up to 6 specified file extensions from processing.
- Ensures the source exists and is within the home directory hierarchy.
- Deletes the original source directory when -mv is used (after successful transfer).
- Includes sample runs at the end of the output message.

Compile with: gcc -std=c11 -Wall -Wextra -O2 -D_XOPEN_SOURCE=700 -o dirxfer dirxfer.c

Code:

#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>
#include <limits.h>
#include <libgen.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <dirent.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static char g_src[PATH_MAX];
static char g_dst[PATH_MAX];
static char g_home[PATH_MAX];
static bool g_do_move = false;
static char g_src_parent_in_home[PATH_MAX];

#define MAX_EXCL 6
static char g_excl[MAX_EXCL][32];
static int g_excl_count = 0;

static int ensure_parent_dirs(const char *path, mode_t mode)
{
    char tmp[PATH_MAX];
    snprintf(tmp, sizeof(tmp), "%s", path);
    for (char *p = tmp + 1; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, 0777) == -1 && errno != EEXIST) {
                return -1;
            }
            *p = '/';
        }
    }
    if (mkdir(tmp, mode) == -1 && errno != EEXIST) {
        return -1;
    }
    return 0;
}

static const char *dot_after(const char *name)
{
    const char *dot = strrchr(name, '.');
    if (!dot || dot == name) return NULL;
    return dot + 1; // extension without dot
}

static bool is_excluded(const char *path)
{
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    const char *ext = dot_after(base);
    if (!ext) return false; // no extension
    for (int i = 0; i < g_excl_count; ++i) {
        if (strcasecmp(ext, g_excl[i]) == 0) return true;
    }
    return false;
}

static int copy_file(const char *src, const char *dst, mode_t mode)
{
    int sfd = open(src, O_RDONLY);
    if (sfd < 0) return -1;

    if (ensure_parent_dirs(dst, 0777) == -1) {
        close(sfd);
        return -1;
    }

    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (dfd < 0) {
        close(sfd);
        return -1;
    }

    char buf[1 << 16];
    ssize_t n;
    while ((n = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < n) {
            ssize_t w = write(dfd, buf + off, (size_t)(n - off));
            if (w < 0) {
                close(sfd);
                close(dfd);
                return -1;
            }
            off += w;
        }
    }
    if (n < 0) {
        close(sfd);
        close(dfd);
        return -1;
    }

    // set permissions similar to source (respect umask via open, then chmod)
    fchmod(dfd, mode);
    close(sfd);
    close(dfd);
    return 0;
}

static int copy_dir(const char *dst, mode_t mode)
{
    if (ensure_parent_dirs(dst, 0777) == -1) return -1;
    if (mkdir(dst, mode) == -1) {
        if (errno == EEXIST) return 0;
        return -1;
    }
    return 0;
}

static int remove_tree_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
    (void)sb; (void)ftwbuf;
    int rc = 0;
    if (typeflag == FTW_DP || typeflag == FTW_D || typeflag == FTW_DNR) {
        rc = rmdir(fpath);
    } else {
        rc = unlink(fpath);
    }
    return rc;
}

static int remove_tree(const char *root)
{
    // Depth-first so directories are removed after contents
    return nftw(root, remove_tree_cb, 32, FTW_DEPTH | FTW_MOUNT | FTW_PHYS);
}

static int xftw_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf)
{
    (void)sb;

    // Derive relative path from source root
    const char *rel = fpath + strlen(g_src);
    if (*rel == '/') rel++;

    char dst_path[PATH_MAX];
    if (*rel) {
        snprintf(dst_path, sizeof(dst_path), "%s/%s", g_dst, rel);
    } else {
        snprintf(dst_path, sizeof(dst_path), "%s", g_dst);
    }

    switch (typeflag) {
        case FTW_D:
        case FTW_DP:
        case FTW_DNR:
            if (copy_dir(dst_path, sb->st_mode & 0777) == -1) {
                fprintf(stderr, "Error: failed to create directory '%s': %s\n", dst_path, strerror(errno));
                return -1;
            }
            break;
        case FTW_F:
        case FTW_SL:
        case FTW_SLN:
            if (is_excluded(fpath)) {
                // Skip excluded file types
                return 0;
            }
            if (copy_file(fpath, dst_path, sb->st_mode & 0777) == -1) {
                fprintf(stderr, "Error: failed to copy '%s' -> '%s': %s\n", fpath, dst_path, strerror(errno));
                return -1;
            }
            break;
        default:
            break;
    }

    return 0;
}

static bool is_within_home(const char *path)
{
    size_t hlen = strlen(g_home);
    if (strncmp(path, g_home, hlen) != 0) return false;
    // Ensure boundary (either exact match or next char is '/')
    if (path[hlen] == '\0' || path[hlen] == '/') return true;
    return false;
}

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s (-cp|-mv) <source_dir> <dest_dir_under_HOME> [--exclude ext1 ext2 ... up to 6]\n"
        "Notes:\n"
        "  - source_dir must exist and be within $HOME.\n"
        "  - dest_dir must be (or be created) within $HOME; original hierarchy is preserved under dest.\n"
        "  - --exclude specifies file extensions to skip, without dot (e.g., txt jpg). Up to 6.\n",
        prog);
}

int main(int argc, char **argv)
{
    if (!getenv("HOME")) {
        fprintf(stderr, "Error: HOME is not set.\n");
        return 1;
    }
    snprintf(g_home, sizeof(g_home), "%s", getenv("HOME"));

    if (argc < 4) {
        usage(argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-cp") == 0) {
        g_do_move = false;
    } else if (strcmp(argv[1], "-mv") == 0) {
        g_do_move = true;
    } else {
        usage(argv[0]);
        return 1;
    }

    // parse excludes
    int argi = 4;
    if (argi < argc && strcmp(argv[argi], "--exclude") == 0) {
        ++argi;
        while (argi < argc && g_excl_count < MAX_EXCL) {
            if (argv[argi][0] == '-' && strcmp(argv[argi], "-") != 0) break; // next option (none expected)
            snprintf(g_excl[g_excl_count], sizeof(g_excl[g_excl_count]), "%s", argv[argi]);
            g_excl_count++;
            ++argi;
        }
    }

    // Resolve and normalize paths
    if (realpath(argv[2], g_src) == NULL) {
        fprintf(stderr, "Error: source '%s' does not exist: %s\n", argv[2], strerror(errno));
        return 1;
    }

    // Destination may not exist; build absolute under HOME if not absolute
    char dest_in[PATH_MAX];
    if (argv[3][0] == '/') {
        snprintf(dest_in, sizeof(dest_in), "%s", argv[3]);
    } else {
        snprintf(dest_in, sizeof(dest_in), "%s/%s", g_home, argv[3]);
    }

    // Ensure destination is under HOME hierarchy
    char dest_parent[PATH_MAX];
    snprintf(dest_parent, sizeof(dest_parent), "%s", dest_in);
    // We will later create; but we want absolute normalized path for boundary checks
    // Create a temp buffer for parent directory resolution
    char dest_parent_dir[PATH_MAX];
    snprintf(dest_parent_dir, sizeof(dest_parent_dir), "%s", dest_in);
    char *dpdir = dirname(dest_parent_dir);
    char abs_parent[PATH_MAX];
    if (realpath(dpdir, abs_parent) == NULL) {
        // parent does not exist yet; ensure it's within HOME by joining HOME with relative component
        if (!is_within_home(dest_in)) {
            // Quick boundary check: ensure prefix matches HOME
            size_t hlen = strlen(g_home);
            if (strncmp(dest_in, g_home, hlen) != 0 || (dest_in[hlen] != '\0' && dest_in[hlen] != '/')) {
                fprintf(stderr, "Error: destination '%s' must be within $HOME ('%s').\n", dest_in, g_home);
                return 1;
            }
        }
    } else {
        if (!is_within_home(abs_parent)) {
            fprintf(stderr, "Error: destination parent '%s' is not within $HOME ('%s').\n", abs_parent, g_home);
            return 1;
        }
    }

    // Ensure source is a directory and within HOME
    struct stat st;
    if (stat(g_src, &st) == -1 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: source '%s' is not a directory.\n", g_src);
        return 1;
    }
    if (!is_within_home(g_src)) {
        fprintf(stderr, "Error: source '%s' is not within $HOME ('%s').\n", g_src, g_home);
        return 1;
    }

    // Build final destination root: dest_in + '/' + basename(src)
    char src_copy[PATH_MAX];
    snprintf(src_copy, sizeof(src_copy), "%s", g_src);
    char *src_base = basename(src_copy);

    if (snprintf(g_dst, sizeof(g_dst), "%s/%s", dest_in, src_base) >= (int)sizeof(g_dst)) {
        fprintf(stderr, "Error: destination path too long.\n");
        return 1;
    }

    // Create destination root directory
    if (ensure_parent_dirs(g_dst, 0777) == -1) {
        fprintf(stderr, "Error: failed to create destination path '%s': %s\n", g_dst, strerror(errno));
        return 1;
    }
    if (mkdir(g_dst, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error: failed to create destination root '%s': %s\n", g_dst, strerror(errno));
        return 1;
    }

    // Traverse and copy
    int flags = FTW_PHYS; // do not follow symlinks
    if (nftw(g_src, xftw_cb, 32, flags | FTW_DEPTH) == -1) {
        fprintf(stderr, "Error: traversal/copy failed.\n");
        return 1;
    }

    // If move: delete source tree
    if (g_do_move) {
        if (remove_tree(g_src) == -1) {
            fprintf(stderr, "Error: failed to remove source tree '%s' after move: %s\n", g_src, strerror(errno));
            return 1;
        }
    }

    printf("Success: %s '%s' to '%s'\n", g_do_move ? "moved" : "copied", g_src, g_dst);
    return 0;
}

Sample runs:
- Copy, excluding txt and jpg:
  ./dirxfer -cp "$HOME/projects/mydir" "$HOME/backup" --exclude txt jpg

- Move, excluding up to 6 extensions:
  ./dirxfer -mv "$HOME/projects/mydir" backup_under_home --exclude log tmp bak swp cache gz

- Error when source outside HOME:
  ./dirxfer -cp /etc "+$HOME/backup"

Here is a complete C program (ncpmvdir) that uses nftw() to traverse directories, supports -cp and -mv, preserves hierarchy, excludes up to 6 extensions, ensures both paths are within the user's home directory, creates the destination directory if needed, and provides error handling. It also removes the source tree on -mv.

Compile with: gcc -std=c11 -Wall -Wextra -O2 -D_XOPEN_SOURCE=700 ncpmvdir.c -o ncpmvdir -lftw

Sample runs:
- ./ncpmvdir ./folder1 ./folder2/folder3 -cp txt pdf
- ./ncpmvdir ~/folder1 ~/folder3 -mv

Code:

#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/sendfile.h>
#include <fcntl.h>
#include <libgen.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <dirent.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_EXCL 6

static char g_src[PATH_MAX];
static char g_dst[PATH_MAX];
static char g_home[PATH_MAX];
static int g_do_move = 0;      // 0: copy, 1: move
static int g_n_excl = 0;
static const char *g_excl[MAX_EXCL];

static int has_excluded_ext(const char *path) {
    if (g_n_excl == 0) return 0;
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    const char *dot = strrchr(base, '.');
    if (!dot || dot == base) return 0;
    const char *ext = dot + 1; // skip '.'
    for (int i = 0; i < g_n_excl; ++i) {
        if (strcasecmp(ext, g_excl[i]) == 0) return 1;
    }
    return 0;
}

static int ensure_dir_mode(const char *path, mode_t mode) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        errno = ENOTDIR;
        return -1;
    }
    // Create parent first
    char tmp[PATH_MAX];
    strncpy(tmp, path, sizeof(tmp));
    tmp[sizeof(tmp)-1] = '\0';
    char *p = tmp;
    if (*p == '\0') return -1;
    // Handle absolute paths starting with '/'
    if (*p == '/') ++p;
    for (; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (strlen(tmp) > 0) {
                if (mkdir(tmp, 0775) == -1 && errno != EEXIST) return -1;
            }
            *p = '/';
        }
    }
    if (mkdir(path, mode) == -1 && errno != EEXIST) return -1;
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in = open(src, O_RDONLY);
    if (in < 0) return -1;
    int out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out < 0) { close(in); return -1; }

#ifdef __linux__
    struct stat st;
    if (fstat(in, &st) == 0) {
        off_t offset = 0;
        while (offset < st.st_size) {
            ssize_t sent = sendfile(out, in, &offset, st.st_size - offset);
            if (sent <= 0) { if (errno == EINTR) continue; close(in); close(out); return -1; }
        }
    } else {
        char buf[1<<16];
        ssize_t n;
        while ((n = read(in, buf, sizeof(buf))) > 0) {
            ssize_t w = 0; while (w < n) { ssize_t m = write(out, buf + w, n - w); if (m < 0) { if (errno == EINTR) continue; close(in); close(out); return -1; } w += m; }
        }
        if (n < 0) { close(in); close(out); return -1; }
    }
#else
    char buf[1<<16];
    ssize_t n;
    while ((n = read(in, buf, sizeof(buf))) > 0) {
        ssize_t w = 0; while (w < n) { ssize_t m = write(out, buf + w, n - w); if (m < 0) { if (errno == EINTR) continue; close(in); close(out); return -1; } w += m; }
    }
    if (n < 0) { close(in); close(out); return -1; }
#endif

    // Preserve permissions (best-effort)
    fchmod(out, mode);

    close(in);
    close(out);
    return 0;
}

static int is_under_home(const char *p) {
    size_t hl = strlen(g_home);
    if (strncmp(p, g_home, hl) != 0) return 0;
    if (p[hl] == '\0') return 1;          // exactly home
    if (p[hl] == '/') return 1;            // inside home
    return 0;
}

static void relpath_from_src(const char *abs_src_root, const char *abs_path, char *out, size_t outsz) {
    size_t rl = strlen(abs_src_root);
    if (strncmp(abs_path, abs_src_root, rl) == 0) {
        const char *r = abs_path + rl;
        if (*r == '/') ++r;
        snprintf(out, outsz, "%s", r);
    } else {
        // Fallback
        snprintf(out, outsz, "%s", abs_path);
    }
}

static int walker(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb;
    char rel[PATH_MAX];
    relpath_from_src(g_src, fpath, rel, sizeof(rel));

    char dstpath[PATH_MAX];
    if (rel[0] == '\0') snprintf(dstpath, sizeof(dstpath), "%s", g_dst);
    else snprintf(dstpath, sizeof(dstpath), "%s/%s", g_dst, rel);

    switch (typeflag) {
        case FTW_D: {
            if (ensure_dir_mode(dstpath, 0775) == -1) {
                fprintf(stderr, "Error: cannot create directory '%s': %s\n", dstpath, strerror(errno));
                return -1;
            }
            break;
        }
        case FTW_F: {
            if (has_excluded_ext(fpath)) return 0; // skip
            // Ensure parent directory exists
            char parent[PATH_MAX];
            strncpy(parent, dstpath, sizeof(parent)); parent[sizeof(parent)-1] = '\0';
            char *slash = strrchr(parent, '/');
            if (slash) { *slash = '\0'; if (ensure_dir_mode(parent, 0775) == -1) { fprintf(stderr, "Error: cannot create directory '%s': %s\n", parent, strerror(errno)); return -1; } }

            // Obtain mode from source
            struct stat st;
            if (stat(fpath, &st) == -1) { fprintf(stderr, "Error: stat '%s': %s\n", fpath, strerror(errno)); return -1; }

            if (copy_file(fpath, dstpath, st.st_mode & 0777) == -1) {
                fprintf(stderr, "Error: copying '%s' -> '%s': %s\n", fpath, dstpath, strerror(errno));
                return -1;
            }
            break;
        }
        case FTW_SL: {
            // Copy symlink as symlink
            if (has_excluded_ext(fpath)) return 0;
            char target[PATH_MAX];
            ssize_t len = readlink(fpath, target, sizeof(target)-1);
            if (len < 0) { fprintf(stderr, "Error: readlink '%s': %s\n", fpath, strerror(errno)); return -1; }
            target[len] = '\0';
            // Ensure parent dir exists
            char parent[PATH_MAX];
            strncpy(parent, dstpath, sizeof(parent)); parent[sizeof(parent)-1] = '\0';
            char *slash = strrchr(parent, '/');
            if (slash) { *slash = '\0'; if (ensure_dir_mode(parent, 0775) == -1) { fprintf(stderr, "Error: cannot create directory '%s': %s\n", parent, strerror(errno)); return -1; } }
            // Remove existing file if any then create symlink
            unlink(dstpath);
            if (symlink(target, dstpath) == -1) { fprintf(stderr, "Error: symlink '%s' -> '%s': %s\n", dstpath, target, strerror(errno)); return -1; }
            break;
        }
        case FTW_DP:
        case FTW_DNR:
        case FTW_NS:
        default:
            break;
    }

    return 0;
}

static int remove_src_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    // Remove in post-order: files first, then directories
    if (typeflag == FTW_F || typeflag == FTW_SL || typeflag == FTW_SLN) {
        if (unlink(fpath) == -1) {
            fprintf(stderr, "Warning: unlink '%s': %s\n", fpath, strerror(errno));
        }
    } else if (typeflag == FTW_DP || typeflag == FTW_D) {
        if (rmdir(fpath) == -1) {
            // May fail if not empty (unlikely due to FTW_DEPTH)
            fprintf(stderr, "Warning: rmdir '%s': %s\n", fpath, strerror(errno));
        }
    }
    return 0;
}

static int path_to_abs(const char *in, char *out, size_t outsz) {
    if (!in || !*in) return -1;
    char temp[PATH_MAX];
    if (in[0] == '~') {
        if (snprintf(temp, sizeof(temp), "%s%s", g_home, in + 1) >= (int)sizeof(temp)) return -1;
    } else {
        strncpy(temp, in, sizeof(temp)); temp[sizeof(temp)-1] = '\0';
    }
    if (temp[0] != '/') {
        char cwd[PATH_MAX];
        if (!getcwd(cwd, sizeof(cwd))) return -1;
        if (snprintf(out, outsz, "%s/%s", cwd, temp) >= (int)outsz) return -1;
    } else {
        if (snprintf(out, outsz, "%s", temp) >= (int)outsz) return -1;
    }
    // Normalize with realpath if exists; for non-existent destination parents, fallback
    char rp[PATH_MAX];
    if (realpath(out, rp)) {
        strncpy(out, rp, outsz); out[outsz-1] = '\0';
    }
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <source_dir> <destination_dir> <-cp|-mv> [ext1 ext2 ... up to 6]\n", prog);
}

int main(int argc, char *argv[]) {
    const char *prog = argv[0];
    const char *home = getenv("HOME");
    if (!home || !*home) { fprintf(stderr, "Error: HOME is not set.\n"); return 1; }
    if (snprintf(g_home, sizeof(g_home), "%s", home) >= (int)sizeof(g_home)) { fprintf(stderr, "Error: HOME too long.\n"); return 1; }

    if (argc < 4) { usage(prog); return 1; }

    if (path_to_abs(argv[1], g_src, sizeof(g_src)) == -1) { fprintf(stderr, "Error: invalid source path.\n"); return 1; }
    if (path_to_abs(argv[2], g_dst, sizeof(g_dst)) == -1) { fprintf(stderr, "Error: invalid destination path.\n"); return 1; }

    if (!is_under_home(g_src)) { fprintf(stderr, "Error: source '%s' is not within HOME '%s'.\n", g_src, g_home); return 1; }
    if (!is_under_home(g_dst)) { fprintf(stderr, "Error: destination '%s' is not within HOME '%s'.\n", g_dst, g_home); return 1; }

    if (strcmp(argv[3], "-cp") == 0) g_do_move = 0;
    else if (strcmp(argv[3], "-mv") == 0) g_do_move = 1;
    else { usage(prog); return 1; }

    // Collect exclusions (up to 6)
    g_n_excl = 0;
    for (int i = 4; i < argc && g_n_excl < MAX_EXCL; ++i) {
        const char *e = argv[i];
        if (*e == '.') ++e; // allow with or without leading dot
        g_excl[g_n_excl++] = e;
    }

    // Verify source exists and is directory
    struct stat sst;
    if (stat(g_src, &sst) == -1) { fprintf(stderr, "Error: source '%s' does not exist: %s\n", g_src, strerror(errno)); return 1; }
    if (!S_ISDIR(sst.st_mode)) { fprintf(stderr, "Error: source '%s' is not a directory.\n", g_src); return 1; }

    // Create destination root directory if not exists
    if (ensure_dir_mode(g_dst, 0775) == -1) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error: cannot create destination '%s': %s\n", g_dst, strerror(errno));
            return 1;
        }
    }

    // Perform copy using nftw
    int flags = FTW_PHYS | FTW_DEPTH; // PHYS: don't follow symlinks; DEPTH: post-order for dirs when cleaning
    if (nftw(g_src, walker, 64, FTW_PHYS) == -1) {
        fprintf(stderr, "Error: traversal/copy failed starting at '%s': %s\n", g_src, strerror(errno));
        return 1;
    }

    if (g_do_move) {
        // Remove entire original subtree
        if (nftw(g_src, remove_src_cb, 64, FTW_DEPTH | FTW_PHYS) == -1) {
            fprintf(stderr, "Error: failed to remove source '%s': %s\n", g_src, strerror(errno));
            return 1;
        }
    }

    return 0;
}

Below is a complete, error-free MATLAB/YALMIP implementation that uses the Schur complement with the substitution Y = KX to cast the H2 state-feedback problem as LMIs. The performance output is z = [y1; y2] = [C x; −K x], and the disturbance w enters at the same input channel as the control. The objective minimizes the sum of the squared H2 norms from w to y and from w to u. The script also adds step response plots comparing the H2 controller against an LQR controller for both the plant output y and the control input u.

% H2 state-feedback with YALMIP (Schur complement) and step comparisons vs LQR
clc
clear
close all

% Load data and identify model (user-supplied data3 must exist)
load('data3.mat');                          % expects variable data3
G3  = bj(data3, [5 5 5 5 1]);               % Box-Jenkins identification (SISO)
G3c = d2c(G3);                              % Discrete -> continuous
sysc = ss(G3c);                             % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [C x; -K x] = C1 x + D12 u
C1  = [C; zeros(m,n)];                      % For z = C1 x + D12 u
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');                % X > 0
Y = sdpvar(m,n,'full');                     % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');            % For H2 objective

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at same input B:
%    A X + X A' - (B Y + Y' B') + B B' < 0
eps_stab = 1e-9;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    [ Z,  (C1 X - D12 Y)
%      *,               X ] >= 0
LMI_h2 = [ Z,              (C1*X - D12*Y) ; ...
           (C1*X - D12*Y)',             X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi if not found)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
assert(sol.problem == 0, ['SDP failed: ', sol.info]);

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
Kv = Yv / Xv;                               % K = Y * X^{-1}
H2sq = value(trace(Z));                     % squared H2 norm from w to z
H2norm = sqrt(max(H2sq,0));

fprintf('Controller synthesis successful.\n');
fprintf('||T_{w->z}||_2 = %.6f\n', H2norm);

% Closed-loop systems (from disturbance w to outputs)
Acl = A - B*Kv;
Bcl = B;
Cy  = C;                                    % output y
Dyw = zeros(p, m);

% Output y to w
sys_y_H2  = ss(Acl, Bcl, Cy,  Dyw);

% Control input u = -K x (as an output) to w
Cu  = -Kv;
Duw = zeros(m, m);
sys_u_H2  = ss(Acl, Bcl, Cu,  Duw);

% LQR comparison
Q = eye(n);
R = 1;
K_lqr = lqr(A,B,Q,R);

Acl_lqr = A - B*K_lqr;
sys_y_LQR = ss(Acl_lqr, Bcl, Cy,  Dyw);
sys_u_LQR = ss(Acl_lqr, Bcl, -K_lqr, Duw);

% Step response comparisons (disturbance step at w)
tFinal = 5;   % seconds; adjust if needed
[t_y_H2, y_H2]   = step(sys_y_H2,  tFinal);
[t_y_LQR, y_LQR] = step(sys_y_LQR, tFinal);
[t_u_H2, u_H2]   = step(sys_u_H2,  tFinal);
[t_u_LQR, u_LQR] = step(sys_u_LQR, tFinal);

figure('Name','Output y: Step response to disturbance w');
plot(t_y_H2,  y_H2,  'LineWidth',1.5); hold on;
plot(t_y_LQR, y_LQR, 'LineWidth',1.5);
grid on; xlabel('Time (s)'); ylabel('y');
legend('H2','LQR'); title('Output y step response (w -> y)');

figure('Name','Control u: Step response to disturbance w');
plot(t_u_H2,  u_H2,  'LineWidth',1.5); hold on;
plot(t_u_LQR, u_LQR, 'LineWidth',1.5);
grid on; xlabel('Time (s)'); ylabel('u');
legend('H2','LQR'); title('Control input u step response (w -> u)');

% Also show closed-loop state-feedback responses to an input step (optional)
sys_cl_H2  = ss(Acl, B, C, zeros(p,m));
sys_cl_LQR = ss(Acl_lqr, B, C, zeros(p,m));
figure('Name','Closed-loop output to input step (optional)');
step(sys_cl_H2, tFinal); hold on; step(sys_cl_LQR, tFinal);
grid on; legend('H2','LQR'); title('Closed-loop y to input step');

//@version=5
indicator("Pivot High/Low with Anchor, Small & Large + Signals", overlay=true, max_lines_count=500, max_labels_count=500)

// Parameters
swingLeft  = input.int(1, "Small Pivot left bars", minval=1)
swingRight = input.int(1, "Small Pivot right bars", minval=1)

// Utility
var int   anchorIndex   = na
var float anchorHigh    = na
var float anchorLow     = na
var bool  waitingHigh   = true   // expecting next small pivot to be a High when true, Low when false (alternation helper)

// Arrays to store confirmed small pivots (permanent)
var smallPH_idx = array.new_int()
var smallPH_val = array.new_float()
var smallPL_idx = array.new_int()
var smallPL_val = array.new_float()

// Arrays to store large pivots (LPH/LPL) with alternation and selection rules
var largePH_idx = array.new_int()
var largePH_val = array.new_float()
var largePL_idx = array.new_int()
var largePL_val = array.new_float()

// Small pivot detection using anchor/reference logic and non-consecutive handling
// Idea:
// 1) Maintain an anchor bar (reference). We keep comparing incoming bars to anchor to decide if we form SPH/SPL per rules.
// 2) A small pivot becomes permanent only after right-side confirmation (swingRight bars).
// 3) Bars can be non-consecutive for the two-bar comparison; we track highest/lowest vs anchor until a pivot is marked.

// Initialize anchor on the first bar where possible
if na(anchorIndex)
    anchorIndex := bar_index
    anchorHigh  := high
    anchorLow   := low

// Track current candidate extremes relative to anchor for potential small pivot
var float runHigh = high
var float runLow  = low
runHigh := math.max(runHigh, high)
runLow  := math.min(runLow, low)

// Define conventional small pivot confirmation with left/right bars
isSPH(sr) => ta.pivothigh(high, swingLeft, sr)
isSPL(sr) => ta.pivotlow(low,  swingLeft, sr)

// We use swingRight for confirmation, but also keep anchor comparison rules
confirmRight = swingRight

// Temporary (unconfirmed) markers for visualization
tmpSPH = isSPH(confirmRight)
tmpSPL = isSPL(confirmRight)

// Convert temporary to permanent with anchor logic and alternation/common rules
// Common rules approximation:
// - Use anchor/reference bar: a SPH must be higher than the anchorHigh to break upwards; SPL must be lower than anchorLow to break downwards.
// - Handle non-consecutive: we continue scanning bars until a qualifying pivot prints; not restricted to immediate next bar.
confirmedSPH = false
confirmedSPL = false
phPrice = na
plPrice = na
phIdx = na
plIdx = na

if tmpSPH
    phIdx := bar_index - confirmRight
    phPrice := high[confirmRight]
    // Anchor rule: SPH must exceed anchorHigh to be valid small up pivot; if not, treat as temporary and do not store
    if na(anchorHigh) or phPrice > anchorHigh
        // Alternation: if last stored permanent was SPH, only accept if higher to replace last; else append
        if array.size(smallPH_val) > 0 and array.size(smallPL_val) == 0
            // first pivot was a high; allow
            confirmedSPH := true
        else
            // If last stored pivot is also SPH, keep the higher of the two (replace)
            if array.size(smallPH_idx) > 0 and (array.size(smallPH_idx) > array.size(smallPL_idx))
                lastPHVal = array.get(smallPH_val, array.size(smallPH_val)-1)
                if phPrice >= lastPHVal
                    array.set(smallPH_val, array.size(smallPH_val)-1, phPrice)
                    array.set(smallPH_idx, array.size(smallPH_idx)-1, phIdx)
                    confirmedSPH := true
                // else ignore lower duplicate
            else
                confirmedSPH := true
        if confirmedSPH and (array.size(smallPH_idx) == 0 or (array.size(smallPH_idx) == array.size(smallPL_idx)))
            array.push(smallPH_idx, phIdx)
            array.push(smallPH_val, phPrice)
        // Update anchor on valid up break
        if confirmedSPH
            anchorIndex := phIdx
            anchorHigh  := phPrice
            // preserve lower anchorLow unless broken by SPL
            waitingHigh := false

if tmpSPL
    plIdx := bar_index - confirmRight
    plPrice := low[confirmRight]
    // Anchor rule: SPL must be below anchorLow to be valid small down pivot
    if na(anchorLow) or plPrice < anchorLow
        if array.size(smallPL_val) > 0 and array.size(smallPH_val) == 0
            confirmedSPL := true
        else
            // If last stored pivot is also SPL, keep the lower of the two (replace)
            if array.size(smallPL_idx) > 0 and (array.size(smallPL_idx) > array.size(smallPH_idx))
                lastPLVal = array.get(smallPL_val, array.size(smallPL_val)-1)
                if plPrice <= lastPLVal
                    array.set(smallPL_val, array.size(smallPL_val)-1, plPrice)
                    array.set(smallPL_idx, array.size(smallPL_idx)-1, plIdx)
                    confirmedSPL := true
                // else ignore higher duplicate
            else
                confirmedSPL := true
        if confirmedSPL and (array.size(smallPL_idx) == 0 or (array.size(smallPL_idx) == array.size(smallPH_idx)))
            array.push(smallPL_idx, plIdx)
            array.push(smallPL_val, plPrice)
        // Update anchor on valid down break
        if confirmedSPL
            anchorIndex := plIdx
            anchorLow   := plPrice
            waitingHigh := true

// Draw small pivots
plotshape(tmpSPH, title="Temp SPH", style=shape.triangledown, location=location.abovebar, color=color.new(color.orange, 0), size=size.tiny, text="tSPH")
plotshape(tmpSPL, title="Temp SPL", style=shape.triangleup,   location=location.belowbar, color=color.new(color.teal, 0),    size=size.tiny, text="tSPL")

spCountH = array.size(smallPH_idx)
spCountL = array.size(smallPL_idx)
lastSPHok = spCountH > 0 and array.get(smallPH_idx, spCountH-1) == bar_index
lastSPLok = spCountL > 0 and array.get(smallPL_idx, spCountL-1) == bar_index
plotshape(lastSPHok, title="SPH", style=shape.triangledown, location=location.abovebar, color=color.new(color.red, 0), size=size.small, text="SPH")
plotshape(lastSPLok, title="SPL", style=shape.triangleup,   location=location.belowbar, color=color.new(color.lime, 0), size=size.small, text="SPL")

// Large pivot logic
// Rules:
// - Alternate LPH/LPL.
// - A new LPH is the highest SPH since last LPL; a new LPL is the lowest SPL since last LPH.
// - A new LPH/LPL should break the previous opposite small pivot range.
var int lastLPType = 0   // 1 = LPH, -1 = LPL, 0 = none
var int lastLPIdx  = na
var float lastLPVal = na

// Helper: try create LPH from smallPHs after last LPL
makeLPH() =>
    // find last LPL index
    int startIdx = na
    if array.size(largePL_idx) > 0
        startIdx := array.get(largePL_idx, array.size(largePL_idx)-1)
    float bestVal = na
    int bestIdx = na
