"use client";
import * as React from "react";

export function Outline({ markdown }: { markdown: string }) {
  const headings = React.useMemo(() => {
    const lines = markdown.split(/\r?\n/);
    return lines
      .map((l, i) => {
        const m = /^(#{1,6})\s+(.+)$/.exec(l);
        if (!m) return null;
        return { depth: m[1].length, text: m[2], line: i + 1 };
      })
      .filter(Boolean) as { depth: number; text: string; line: number }[];
  }, [markdown]);

  return (
    <aside className="sticky top-4 max-h-[70vh] overflow-auto rounded border p-3 text-sm">
      <div className="mb-2 font-semibold">Outline</div>
      <ul className="space-y-1">
        {headings.map((h, idx) => (
          <li key={idx} className="truncate" style={{ paddingLeft: (h.depth - 1) * 12 }}>
            <span className="text-muted-foreground">{"#".repeat(h.depth)}</span> {h.text}
          </li>
        ))}
      </ul>
    </aside>
  );
}
