export function normalizeDoc({ title, content }: { title: string; content: string }) {
  const lines = content.replace(/\r\n/g, "\n").split("\n");
  // remove existing top-level H1s
  const filtered = lines.filter((l) => !/^#\s+/.test(l.trim()));
  // ensure a single H1 derived from title at top
  const withH1 = [`# ${title.trim()}`, "", ...filtered];
  // collapse 3+ blank lines to 2
  const collapsed = withH1.join("\n").replace(/\n{3,}/g, "\n\n");
  // ensure trailing newline
  return collapsed.endsWith("\n") ? collapsed : collapsed + "\n";
}
