"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  setDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { Outline } from "@/components/Outline";
import { normalizeDoc } from "@/lib/formatting";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [docData, setDocData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  const router = useRouter();

  // Subscribe to Firestore doc by slug
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (!snap.exists()) {
        setDocData(null);
        setTitle("");
        setTagsText("");
        setContent("");
        return;
      }
      const d = snap.data() as DocData;
      setDocData(d);
      setTitle(d.title || "");
      setTagsText((d.tags || []).join(", "));
      setContent(d.content || "");
    });
    return () => unsub();
  }, [slug]);

  async function uploadImageToStorage(file: File) {
    const objectRef = ref(storage, `docs/${slug}/images/${Date.now()}_${file.name}`);
    const snap = await uploadBytes(objectRef, file);
    return await getDownloadURL(snap.ref);
  }

  async function saveDoc() {
    setSaving(true);
    try {
      const normalized = normalizeDoc({ title, content });
      const refDoc = doc(db, "docs", slug);
      await setDoc(refDoc, {
        title,
        content: normalized,
        tags: tagsText
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        updatedAt: serverTimestamp(),
        createdAt: (await getDoc(refDoc)).exists() ? undefined : serverTimestamp(),
      }, { merge: true });
      setContent(normalized);
      setLastSavedAt(new Date());
    } finally {
      setSaving(false);
    }
  }

  async function renameDoc(newTitle: string) {
    const newSlug = slugify(newTitle);
    if (!newSlug || newSlug === slug) return;
    setRenaming(true);
    try {
      const srcRef = doc(db, "docs", slug);
      const dstRef = doc(db, "docs", newSlug);
      const snap = await getDoc(srcRef);
      if (!snap.exists()) return;
      const data = snap.data() as DocData;
      await setDoc(dstRef, { ...data, title: newTitle, updatedAt: serverTimestamp() });
      await deleteDoc(srcRef);
      router.replace(`/docs/${newSlug}`);
    } finally {
      setRenaming(false);
    }
  }

  async function deleteDocPermanently() {
    setDeleting(true);
    try {
      await deleteDoc(doc(db, "docs", slug));
      router.replace("/docs");
    } finally {
      setDeleting(false);
    }
  }

  return (
    <div className="grid grid-cols-1 gap-6 md:grid-cols-[1fr_280px]">
      <div>
        <div className="mb-4 flex flex-col gap-2 md:flex-row md:items-center">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full rounded border px-3 py-2"
            placeholder="Document title"
          />
          <div className="flex gap-2">
            <button onClick={saveDoc} className="rounded border px-3 py-2" disabled={saving}>
              {saving ? "Saving…" : "Save"}
            </button>
            <button onClick={() => renameDoc(title)} className="rounded border px-3 py-2" disabled={renaming}>
              Rename to Title
            </button>
            <button onClick={deleteDocPermanently} className="rounded border px-3 py-2 text-red-600" disabled={deleting}>
              Delete
            </button>
          </div>
        </div>
        <input
          value={tagsText}
          onChange={(e) => setTagsText(e.target.value)}
          className="mb-3 w-full rounded border px-3 py-2"
          placeholder="tags: comma, separated"
        />
        <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={uploadImageToStorage} />
        {lastSavedAt && (
          <div className="mt-2 text-xs text-muted-foreground">Last saved {lastSavedAt.toLocaleTimeString()}</div>
        )}
      </div>
      <div>
        <Outline markdown={content} />
        <div className="mt-4 rounded border p-3">
          <div className="mb-2 text-sm font-semibold">Preview</div>
          <MarkdownRXPreview value={content} />
        </div>
