Here’s a JavaScript-based solution using Canvas that creates a full-width (100%) horizontal line at the vertical center of a 32px-tall area, with a dot moving left-to-right that briefly “pulses” up and down (no visible triangle waveform on the line itself). It mimics a cardio-style spike by scaling the dot vertically for a short duration.

HTML:
<div id="ecg" style="width:100%; max-width:100%;"></div>

CSS (optional, to ensure 32px height):
<style>
  #ecg canvas { display:block; height:32px; width:100%; }
  /* Ensure the container controls layout; Canvas backing store uses attributes */
  #ecg { width:100%; }
</style>

JavaScript:
<script>
(function() {
  const container = document.getElementById('ecg');
  const canvas = document.createElement('canvas');
  // Logical pixel size; will be resized on layout changes
  const HEIGHT = 32; // required 32px height
  canvas.height = HEIGHT; // back-buffer height
  container.appendChild(canvas);
  const ctx = canvas.getContext('2d');

  // Resize canvas to match container width and fixed 32px height
  function resize() {
    const rect = container.getBoundingClientRect();
    // Backing store width to match CSS width in device pixels
    canvas.width = Math.max(1, Math.floor(rect.width));
    canvas.height = HEIGHT;
  }
  resize();
  window.addEventListener('resize', resize);

  // Animation parameters
  const lineColor = '#d00';
  const dotColor = '#06f';
  const bgColor = '#000';

  const durationMs = 2000; // time for dot to traverse left->right
  const baseDotRadius = 2.5; // base dot radius in px
  const spikeScale = 6.0; // vertical scale during pulse
  const spikeWidthMs = 160; // how long the spike lasts
  const spikeEase = t => 1 - Math.pow(1 - t, 3); // ease-out cubic for spike envelope

  // Either fixed position or randomize the spike trigger each pass
  let spikePosNorm = 0.45; // 0..1 along width; can be randomized per pass

  let startTime = performance.now();
  let lastCycle = 0;

  function drawFrame(now) {
    const w = canvas.width;
    const h = canvas.height; // 32px
    const midY = Math.floor(h / 2) + 0.5; // crisp 1px line

    // Clear
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, w, h);

    // Tight center line across full width
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, midY);
    ctx.lineTo(w, midY);
    ctx.stroke();

    // Progress 0..1 across duration
    const tCycle = (now - startTime) % durationMs;
    const cycleIndex = Math.floor((now - startTime) / durationMs);

    // On each new pass, optionally randomize the spike location
    if (cycleIndex !== lastCycle) {
      lastCycle = cycleIndex;
      // Choose a random spike position in the middle 70% to avoid edges
      spikePosNorm = 0.15 + Math.random() * 0.7;
    }

    const progress = tCycle / durationMs; // 0..1
    const x = Math.round(progress * (w - 1)) + 0.5; // crisp positioning

    // Determine if we are in spike window
    const spikeX = spikePosNorm * (w - 1) + 0.5;
    const pxPerMs = (w - 1) / durationMs;
    const timeFromSpikeMs = Math.abs((x - spikeX) / pxPerMs);
    const inSpike = timeFromSpikeMs <= spikeWidthMs / 2;

    // Compute vertical scale envelope for the dot
    let scaleY = 1.0;
    if (inSpike) {
      const half = spikeWidthMs / 2;
      const local = 1 - (timeFromSpikeMs / half); // 0..1..0
      const envelope = spikeEase(Math.max(0, local));
      scaleY = 1 + (spikeScale - 1) * envelope;
    }

    // Draw the moving dot, scaled vertically without altering the baseline line
    // The dot expands up and down from the center (no triangle trace on the line)
    ctx.save();
    ctx.translate(x, midY);
    ctx.scale(1, scaleY);

    ctx.fillStyle = dotColor;
    ctx.beginPath();
    ctx.arc(0, 0, baseDotRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    requestAnimationFrame(drawFrame);
  }

  requestAnimationFrame(drawFrame);
})();
</script>

Notes:
- Height is fixed at 32px (canvas.height = 32), and the line spans 100% of the container’s width via responsive canvas.width on resize.
- The dot moves left-to-right every 2 seconds and briefly scales vertically to mimic a cardio pulse. The underlying line remains a tight 1px center line; no triangle waveform is drawn on the line itself.
- The spike position randomizes each pass; set spikePosNorm to a fixed value (e.g., 0.5) to keep it constant.
- You can adjust durationMs, spikeWidthMs, and spikeScale to tune the effect.

Below is a complete, self-contained HTML + JavaScript example that renders a cardio-like pulsing line with a moving dot and periodic triangular spike. It is 32px tall, 100% wide, and uses JavaScript to control timing and drawing. After the code, a brief explanation covers why JS is preferred over pure CSS for this effect.

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Cardio Pulse (Canvas)</title>
  <style>
    body { background:#0b0f14; color:#cfe3ff; font-family:sans-serif; }
    .wrap { max-width: 900px; margin: 32px auto; }
    canvas { display:block; width:100%; height:32px; /* CSS height for layout */ }
    /* make the container exactly 32px tall visually */
    .scope { width:100%; height:32px; border:1px solid #16324a; border-radius:4px; background:linear-gradient(180deg,#07101a 0%, #0b1420 100%); }
  </style>
</head>
<body>
  <div class="wrap">
    <h2>Cardio-like Pulse (moving dot + triangular spike)</h2>
    <div class="scope">
      <canvas id="scope"></canvas>
    </div>
  </div>

  <script>
    // Config
    const LINE_COLOR = '#45f3ff';
    const DOT_COLOR  = '#fff';
    const BASELINE_Y_RATIO = 0.6; // baseline at 60% of height
    const DOT_RADIUS = 2;
    const LINE_WIDTH = 2;

    // Spike pattern (triangular waveform) parameters
    const SPIKE_INTERVAL_MS = 900;   // time between spikes
    const SPIKE_RISE_MS     = 60;    // sharp up ramp
    const SPIKE_FALL_MS     = 120;   // softer down ramp
    const SPIKE_DECAY_MS    = 220;   // return to baseline

    // Canvas setup with HiDPI support
    const canvas = document.getElementById('scope');
    const ctx = canvas.getContext('2d');

    function resizeCanvas() {
      const dpr = Math.max(1, window.devicePixelRatio || 1);
      const cssWidth = canvas.clientWidth;
      const cssHeight = canvas.clientHeight; // 32px from CSS
      canvas.width = Math.floor(cssWidth * dpr);
      canvas.height = Math.floor(cssHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // draw in CSS pixels
      ctx.lineWidth = LINE_WIDTH;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
    }

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    // State for scrolling trace
    let lastTime = performance.now();
    let scrollX = 0;              // how far we've scrolled (in px)
    const pxPerSec = 220;         // horizontal speed of the dot/trace

    // Spike timing
    let nextSpikeAt = performance.now() + SPIKE_INTERVAL_MS;
    let spikeStart = null; // timestamp when spike begins

    // Return vertical offset (relative to baseline) given ms since spike start
    function spikeOffset(ms, height) {
      // triangular spike shape: rise, fall, decay back to 0
      const spikePeak = -Math.min(10, Math.round(height * 0.28)); // up is negative (canvas y grows down)
      const mid = Math.round(spikePeak * 0.55);                    // intermediate level during fall

      if (ms < 0) return 0;
      if (ms <= SPIKE_RISE_MS) {
        const t = ms / SPIKE_RISE_MS;           // 0..1
        return t * spikePeak;                   // linear rise up (negative)
      }
      if (ms <= SPIKE_RISE_MS + SPIKE_FALL_MS) {
        const t = (ms - SPIKE_RISE_MS) / SPIKE_FALL_MS; // 0..1
        return spikePeak + t * (mid - spikePeak);       // partial fall
      }
      if (ms <= SPIKE_RISE_MS + SPIKE_FALL_MS + SPIKE_DECAY_MS) {
        const t = (ms - SPIKE_RISE_MS - SPIKE_FALL_MS) / SPIKE_DECAY_MS; // 0..1
        return mid + t * (0 - mid);               // decay to baseline
      }
      return 0; // back to baseline
    }

    // Offscreen buffer for smooth scrolling trace
    let buffer = document.createElement('canvas');
    let bctx = buffer.getContext('2d');

    function resizeBuffer() {
      buffer.width = canvas.clientWidth;
      buffer.height = canvas.clientHeight;
      bctx.lineWidth = LINE_WIDTH;
      bctx.lineCap = 'round';
      bctx.lineJoin = 'round';
    }
    resizeBuffer();

    // Draw one vertical slice at x for the current y value
    function drawColumn(ctx2d, x, yBase, yVal) {
      ctx2d.strokeStyle = LINE_COLOR;
      ctx2d.beginPath();
      ctx2d.moveTo(x, yBase);
      ctx2d.lineTo(x, yVal);
      ctx2d.stroke();
    }

    function loop(now) {
      const dt = Math.min(50, now - lastTime); // clamp dt
      lastTime = now;

      const w = canvas.clientWidth;
      const h = canvas.clientHeight; // visual height: 32px
      const baselineY = Math.round(h * BASELINE_Y_RATIO);

      // advance scroll
      scrollX += (pxPerSec * dt) / 1000;

      // determine current spike offset
      if (now >= nextSpikeAt) {
        spikeStart = now;
        nextSpikeAt = now + SPIKE_INTERVAL_MS;
      }
      const yOff = spikeStart ? spikeOffset(now - spikeStart, h) : 0;
      const currentY = baselineY + yOff;

      // scroll the buffer left by dx and draw new column at right edge
      const dx = Math.floor((pxPerSec * dt) / 1000) || 1;
      const old = bctx.getImageData(dx, 0, buffer.width - dx, buffer.height);
      bctx.clearRect(0, 0, buffer.width, buffer.height);
      bctx.putImageData(old, 0, 0);

      // draw the new vertical segment at the right edge
      const xNew = buffer.width - 1;
      drawColumn(bctx, xNew, baselineY, currentY);

      // clear main canvas and paint buffer
      ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
      ctx.drawImage(buffer, 0, 0);

      // draw moving dot at the right edge following the same y
      ctx.fillStyle = DOT_COLOR;
      ctx.beginPath();
      ctx.arc(xNew, currentY, DOT_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      requestAnimationFrame(loop);
    }

    // Keep the offscreen buffer in sync with size changes
    const ro = new ResizeObserver(() => {
      resizeCanvas();
      resizeBuffer();
    });
    ro.observe(canvas);

    requestAnimationFrame(loop);
  </script>
</body>
</html>

Why JavaScript over CSS for this effect
- Control of timing and state: The cardio spike is a non-uniform triangular pulse with specific phases (sharp rise, partial fall, decay, baseline). JavaScript lets you compute and schedule these segments precisely in milliseconds.
- Dynamic drawing and width independence: With JS you render to canvas at 100% width and fixed 32px height regardless of device pixel ratio, keeping the line crisp and timing constant while the viewport changes.
- Realistic signal synthesis: The waveform can be procedurally generated (e.g., change intervals, amplitudes, noise, artifacts) without predefining multiple CSS keyframes or complex SVG path animations.
- Performance and smoothness: requestAnimationFrame aligns updates to the display refresh, often yielding smoother motion and better control than chained CSS animations for custom waveforms.

Notes
- Height is visually 32px (CSS), and the canvas is scaled for HiDPI so it stays sharp.
- The moving dot rides the same y-value as the trace, and the spike is triangular in time (rise/fall/decay), which reads as a sharp peak visually without a fully drawn triangle fill.

