// Templates: generic repository for any exhibit-like type
template <typename T>
class Repository {
private:
    std::vector<std::shared_ptr<T>> items_;
public:
    using value_type = T;

    void add(const std::shared_ptr<T>& item) { items_.push_back(item); }
    // Method template: add many via iterators
    template <typename It>
    void addRange(It first, It last) {
        for (; first != last; ++first) items_.push_back(*first);
    }

    std::vector<std::shared_ptr<T>>& items() { return items_; }
    const std::vector<std::shared_ptr<T>>& items() const { return items_; }

    size_t size() const { return items_.size(); }

    // Operator overloading: concatenate repositories
    Repository operator+(const Repository& other) const {
        Repository res;
        res.items_ = items_;
        res.items_.insert(res.items_.end(), other.items_.begin(), other.items_.end());
        return res;
    }
};

// Analyzer: template with policies for data analysis and processing
struct StatsResult {
    size_t count{0};
    std::map<std::string, size_t> byType; // type -> count
    std::optional<double> globalAvgRating; // across all exhibits that have ratings
};

class AnalyzerBase {
public:
    virtual ~AnalyzerBase() = default;
    virtual StatsResult analyze(const std::vector<std::shared_ptr<Exhibit>>& data) const = 0;
};

// Templated Analyzer that can filter using a predicate
template <typename Predicate>
class Analyzer : public AnalyzerBase {
private:
    Predicate pred_;
public:
    explicit Analyzer(Predicate p) : pred_(std::move(p)) {}

    StatsResult analyze(const std::vector<std::shared_ptr<Exhibit>>& data) const override {
        StatsResult r;
        std::vector<double> allRatings; allRatings.reserve(data.size());
        for (const auto& e : data) {
            if (!pred_(*e)) continue;
            ++r.count;
            r.byType[e->type()]++;
            if (auto avg = e->averageRating()) allRatings.push_back(*avg);
        }
        if (!allRatings.empty()) {
            r.globalAvgRating = std::accumulate(allRatings.begin(), allRatings.end(), 0.0) / allRatings.size();
        }
        return r;
    }
};

// Museum class managing exhibits (encapsulation, uses STL)
class Museum {
private:
    Repository<Exhibit> repo_;
public:
    void add(const std::shared_ptr<Exhibit>& e) { repo_.add(e); }

    template <typename E, typename... Args>
    std::shared_ptr<E> makeAndAdd(Args&&... args) {
        static_assert(std::is_base_of<Exhibit, E>::value, "E must derive from Exhibit");
        auto ptr = std::make_shared<E>(std::forward<Args>(args)...);
        add(ptr);
        return ptr;
    }

