from __future__ import annotations

import abc
import math
import re
from collections import Counter, defaultdict
from collections.abc import Iterable as IterableABC
from functools import singledispatchmethod
from statistics import mean
from typing import Callable, Dict, Generic, Iterable, Iterator, List, Optional, Tuple, TypeVar


# ---------- Data processing utilities ----------

def tokenize(text: str) -> List[str]:
    # Lowercase, remove punctuation, split on non-letters
    return [t for t in re.split(r"[^a-zA-Z]+", text.lower()) if t]


T = TypeVar("T")
K = TypeVar("K")


def group_by(items: Iterable[T], key: Callable[[T], K]) -> Dict[K, List[T]]:
    """Template-like generic function to group items by a computed key."""
    groups: Dict[K, List[T]] = defaultdict(list)
    for it in items:
        groups[key(it)].append(it)
    return dict(groups)


def summarize_numeric(items: Iterable[T], value: Callable[[T], float]) -> Optional[Dict[str, float]]:
    """Template-like generic summary over numeric data derived from T."""
    vals = [float(value(it)) for it in items]
    if not vals:
        return None
    n = len(vals)
    s = math.fsum(vals)
    mn = min(vals)
    mx = max(vals)
    avg = s / n
    # population stddev
    var = math.fsum((x - avg) ** 2 for x in vals) / n
    std = math.sqrt(var)
    return {"count": float(n), "min": mn, "max": mx, "mean": avg, "std": std}


# ---------- Encapsulated Value Object with Operator Overloading ----------

class Dimension:
    def __init__(self, width: float, height: float, depth: float):
        # Encapsulation: private attributes
        self.__width = float(width)
        self.__height = float(height)
        self.__depth = float(depth)

    # Read-only properties
    @property
    def width(self) -> float:
        return self.__width

    @property
    def height(self) -> float:
        return self.__height

    @property
    def depth(self) -> float:
        return self.__depth

    def volume(self) -> float:
        return self.__width * self.__height * self.__depth

    # Operator overloading for convenience
    def __add__(self, other: "Dimension") -> "Dimension":
        return Dimension(self.width + other.width, self.height + other.height, self.depth + other.depth)

    def __mul__(self, scalar: float) -> "Dimension":
        return Dimension(self.width * scalar, self.height * scalar, self.depth * scalar)

    __rmul__ = __mul__

    def __repr__(self) -> str:
        return f"Dimension({self.width} x {self.height} x {self.depth}, vol={self.volume():.2f})"


# ---------- Abstract Base Class and Derived Types (Inheritance + Polymorphism) ----------

class Exhibit(abc.ABC):
    def __init__(self, name: str, year: int, description: str = ""):
        self._name = name
        self._year = int(year)
        self._description = description
        self._ratings: List[int] = []

    # Encapsulation via properties
    @property
    def name(self) -> str:
        return self._name

    @property
    def year(self) -> int:
        return self._year

    @property
    def description(self) -> str:
        return self._description

    @property
    def ratings(self) -> Tuple[int, ...]:
        return tuple(self._ratings)

    # Method overloading via singledispatchmethod
    @singledispatchmethod
    def add_rating(self, arg) -> None:
        raise TypeError("Unsupported rating type")

    @add_rating.register
    def _(self, r: int) -> None:
        if not 1 <= r <= 5:
            raise ValueError("Rating must be 1..5")
        self._ratings.append(int(r))

    # Overloaded to accept iterables of ratings
    @add_rating.register
    def _(self, rs: IterableABC) -> None:
        if isinstance(rs, (str, bytes)):
            raise TypeError("Iterable of ratings cannot be str/bytes")
        for r in rs:
            self.add_rating(r)

    def average_rating(self) -> Optional[float]:
        return mean(self._ratings) if self._ratings else None

    # Polymorphic interface
    @abc.abstractmethod
    def display(self) -> None:
        ...

    @abc.abstractmethod
    def kind(self) -> str:
        ...

    # Operator overloading for sorting and printing
    def __lt__(self, other: "Exhibit") -> bool:
        if self.name != other.name:
            return self.name < other.name
        return self.year < other.year

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Exhibit):
            return NotImplemented
        return (self.name, self.year, self.kind()) == (other.name, other.year, other.kind())

    def __str__(self) -> str:
        avg = self.average_rating()
        avg_str = f"{avg:.2f}" if avg is not None else "n/a"
        return f"[{self.kind()}] {self.name} ({self.year}) avg={avg_str}"


class Painting(Exhibit):
    def __init__(self, name: str, year: int, artist: str, technique: str = "Oil", description: str = ""):
        super().__init__(name, year, description=description)
        self._artist = artist
        self._technique = technique

    @property
    def artist(self) -> str:
        return self._artist

    @property
    def technique(self) -> str:
        return self._technique

    def display(self) -> None:
        print(f"Displaying painting: {self.name} by {self.artist} "
              f"({self.technique}, {self.year})")

    def kind(self) -> str:
        return "Painting"


class Sculpture(Exhibit):
    def __init__(self, name: str, year: int, material: str, size: Dimension, description: str = ""):
        super().__init__(name, year, description=description)
        self._material = material
        self._size = size

    @property
    def material(self) -> str:
        return self._material

    @property
    def size(self) -> Dimension:
        return self._size

    def display(self) -> None:
        print(f"Displaying sculpture: {self.name} made of {self.material} "
              f"size {self.size} ({self.year})")

    def kind(self) -> str:
        return "Sculpture"


class Photograph(Exhibit):
    def __init__(self, name: str, year: int, photographer: str, medium: str = "Film", description: str = ""):
        super().__init__(name, year, description=description)
        self._photographer = photographer
        self._medium = medium

    @property
    def photographer(self) -> str:
        return self._photographer

    @property
    def medium(self) -> str:
        return self._medium

    def display(self) -> None:
        print(f"Displaying photograph: {self.name} by {self.photographer} "
              f"({self.medium}, {self.year})")

    def kind(self) -> str:
        return "Photograph"


class Installation(Exhibit):
    def __init__(self, name: str, year: int, components: List[str], area_m2: float, description: str = ""):
        super().__init__(name, year, description=description)
        self._components = list(components)
        self._area_m2 = float(area_m2)

    @property
    def components(self) -> Tuple[str, ...]:
        return tuple(self._components)

    @property
    def area_m2(self) -> float:
        return self._area_m2

    def display(self) -> None:
        comp = ", ".join(self._components[:3]) + ("..." if len(self._components) > 3 else "")
        print(f"Displaying installation: {self.name} ({self.year}), "
              f"components: {comp}, area={self.area_m2:.1f} m^2")

    def kind(self) -> str:
        return "Installation"


# ---------- Generic Repository (Template-like via Generics) ----------

class Repository(Generic[T]):
    def __init__(self):
        self._items: List[T] = []

    def add(self, item: T) -> None:
        self._items.append(item)

    def extend(self, items: IterableABC) -> None:
        for it in items:
            self.add(it)

    def where(self, predicate: Callable[[T], bool]) -> List[T]:
        return [x for x in self._items if predicate(x)]

    def sort_by(self, key: Callable[[T], object], reverse: bool = False) -> None:
        self._items.sort(key=key, reverse=reverse)

    def map(self, fn: Callable[[T], K]) -> List[K]:
        return [fn(x) for x in self._items]

    def __iter__(self) -> Iterator[T]:
        return iter(self._items)

    def __len__(self) -> int:
        return len(self._items)

    def __getitem__(self, idx: int) -> T:
        return self._items[idx]

    def to_list(self) -> List[T]:
        return list(self._items)


# ---------- Analyzer (Generic templates for methods/classes) ----------

class Analyzer(Generic[T]):
    def __init__(self, items: Iterable[T]):
        self._items = list(items)

    def token_frequencies(self, source: Callable[[T], str], tok: Callable[[str], List[str]] = tokenize) -> Counter:
        c = Counter()
        for it in self._items:
            c.update(tok(source(it)))
        return c

    def top_n(self, score: Callable[[T], float], n: int) -> List[T]:
        return sorted(self._items, key=score, reverse=True)[:n]

    def summary(self, value: Callable[[T], float]) -> Optional[Dict[str, float]]:
        return summarize_numeric(self._items, value)

    def histogram(self, bucket: Callable[[T], K]) -> Dict[K, int]:
        h: Dict[K, int] = defaultdict(int)
        for it in self._items:
            h[bucket(it)] += 1
        return dict(h)


# ---------- Example data analysis integration over exhibits ----------

def analyze_exhibits(repo: Repository[Exhibit]) -> Dict[str, object]:
    analyzer = Analyzer(repo.to_list())

    # Text processing on descriptions and names
    word_freqs = analyzer.token_frequencies(lambda e: f"{e.name} {getattr(e, 'description', '')}")

    # Rating statistics
    rating_stats = analyzer.summary(lambda e: e.average_rating() or 0.0)

    # Group by type and year buckets
    by_kind = group_by(repo, lambda e: e.kind())
    by_decade_hist = analyzer.histogram(lambda e: (e.year // 10) * 10)

    # Top exhibits by average rating
    top_rated = analyzer.top_n(lambda e: e.average_rating() or 0.0, 3)

    # Size/volume stats for sculptures if present
    sculptures = [e for e in repo if isinstance(e, Sculpture)]
    volume_stats = summarize_numeric(sculptures, lambda s: s.size.volume()) if sculptures else None

    return {
        "word_freqs": word_freqs,
        "rating_stats": rating_stats,
        "by_kind_counts": {k: len(v) for k, v in by_kind.items()},
        "by_decade_hist": by_decade_hist,
        "top_rated": [str(e) for e in top_rated],
        "sculpture_volume_stats": volume_stats,
    }
