<script>
(function() {
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));

  const overlay = $('#fp-overlay');
  const tabLogin = $('#fp-tab-login');
  const tabRegister = $('#fp-tab-register');
  const formLogin = $('#fp-form-login');
  const formRegister = $('#fp-form-register');
  const loginError = $('#fp-login-error');
  const registerError = $('#fp-register-error');

  function switchTab(which) {
    const isLogin = which === 'login';
    tabLogin.classList.toggle('active', isLogin);
    tabRegister.classList.toggle('active', !isLogin);
    tabLogin.setAttribute('aria-selected', String(isLogin));
    tabRegister.setAttribute('aria-selected', String(!isLogin));
    formLogin.hidden = !isLogin;
    formRegister.hidden = isLogin;
  }

  tabLogin?.addEventListener('click', () => switchTab('login'));
  tabRegister?.addEventListener('click', () => switchTab('register'));
  $('#fp-to-login')?.addEventListener('click', () => switchTab('login'));

  function saveUser(user) {
    localStorage.setItem('tg:user', JSON.stringify(user));
    sessionStorage.setItem('tg:session', JSON.stringify({ email: user.email, at: Date.now() }));
  }
  function getUserByEmail(email) {
    const u = localStorage.getItem('tg:user');
    if (!u) return null;
    try { const user = JSON.parse(u); return user.email === email ? user : null; } catch { return null; }
  }
  function isAuthed() { return !!sessionStorage.getItem('tg:session'); }
  function hideOverlayAndStart() {
    document.body.classList.add('fp-authenticated');
    overlay?.setAttribute('aria-hidden', 'true');
    window.dispatchEvent(new CustomEvent('frontpage:authenticated'));
    if (typeof window.startGame === 'function') window.startGame();
    else if (typeof window.initGame === 'function') window.initGame();
  }

  // Auto-hide if already logged in
  if (isAuthed()) { hideOverlayAndStart(); }

  formRegister?.addEventListener('submit', (e) => {
    e.preventDefault();
    registerError.textContent = '';
    const username = $('#fp-reg-username').value.trim();
    const email = $('#fp-reg-email').value.trim().toLowerCase();
    const password = $('#fp-reg-password').value;

    if (!username || !email || !password) {
      registerError.textContent = 'Please fill in all fields.';
      return;
    }
    if (password.length < 6) {
      registerError.textContent = 'Password must be at least 6 characters.';
      return;
    }
    const existing = getUserByEmail(email);
    if (existing) {
      registerError.textContent = 'An account with this email already exists. Please log in.';
      switchTab('login');
      return;
    }
    const user = { username, email, passwordHash: btoa(password) };
    saveUser(user);
    switchTab('login');
    loginError.textContent = 'Account created. You can sign in now.';
  });

  formLogin?.addEventListener('submit', (e) => {
    e.preventDefault();
    loginError.textContent = '';
    const email = $('#fp-login-email').value.trim().toLowerCase();
    const password = $('#fp-login-password').value;
    const u = getUserByEmail(email);
    if (!u || u.passwordHash !== btoa(password)) {
      loginError.textContent = 'Invalid email or password.';
      return;
    }
    saveUser(u);
    hideOverlayAndStart();
  });
})();
</script>

