<script>
(function(){
  // Basic state kept in-memory/localStorage for demo
  const pairingStatus = document.getElementById('pairingStatus');
  const roomIdInput = document.getElementById('roomIdInput');
  const btnJoin = document.getElementById('btnJoinRoom');
  const btnCreate = document.getElementById('btnCreateRoom');
  const btnRandom = document.getElementById('btnRandomMatch');

  const goOverlay = document.getElementById('go-overlay');
  const goTimeUsed = document.getElementById('go-time-used');
  const goStatsBody = document.getElementById('go-stats-body');
  const btnPlayAgain = document.getElementById('btnPlayAgain');
  const btnLogoutGO = document.getElementById('btnLogoutGO');

  // Helpers aligning to existing game page style/flow
  function showPairing(msg){ if (pairingStatus) pairingStatus.textContent = msg || ''; }
  function randomRoomId(){ return 'ROOM-' + Math.random().toString(36).slice(2,7).toUpperCase(); }
  function saveRoom(id){ sessionStorage.setItem('tennis.roomId', id); }
  function getRoom(){ return sessionStorage.getItem('tennis.roomId'); }

  // Wire pairing buttons
  if (btnCreate) btnCreate.addEventListener('click', () => {
    const id = randomRoomId();
    saveRoom(id);
    roomIdInput && (roomIdInput.value = id);
    showPairing(`Room created: ${id}. Share this ID with your friend.`);
    // Dispatch event so your networking layer can actually create the room
    document.dispatchEvent(new CustomEvent('tennis:room:create', { detail: { roomId: id } }));
  });

  if (btnJoin) btnJoin.addEventListener('click', () => {
    const id = (roomIdInput && roomIdInput.value || '').trim();
    if (!id) { showPairing('Please enter a room ID to join.'); return; }
    saveRoom(id);
    showPairing(`Joining room: ${id}...`);
    document.dispatchEvent(new CustomEvent('tennis:room:join', { detail: { roomId: id } }));
  });

  if (btnRandom) btnRandom.addEventListener('click', () => {
    const id = 'MM-' + Math.random().toString(36).slice(2,8).toUpperCase();
    saveRoom(id);
    showPairing('Finding a random opponent...');
    document.dispatchEvent(new CustomEvent('tennis:matchmaking', { detail: { ticket: id } }));
  });

  // Expose simple API for your game code to open/close Game Over overlay
  window.TennisUI = window.TennisUI || {};

  // Call when a match has ended. Pass stats array for table rows.
  // stats example item: { ranking: 1, player: 'You', score: 8, health: 2, hits: 35, oppHits: 12, pickups: 5 }
  window.TennisUI.showGameOver = function({ timeUsed = '00:00', stats = [] } = {}){
    if (goStatsBody) goStatsBody.innerHTML = '';
    (stats || []).forEach(row => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>${row.ranking ?? '-'}</td>
        <td>${row.player ?? '-'}</td>
        <td>${row.score ?? 0}</td>
        <td>${row.health ?? 0}</td>
        <td>${row.hits ?? 0}</td>
        <td>${row.oppHits ?? 0}</td>
        <td>${row.pickups ?? 0}</td>`;
      goStatsBody.appendChild(tr);
    });
    if (goTimeUsed) goTimeUsed.textContent = timeUsed;
    goOverlay.style.display = 'grid';
  };

  window.TennisUI.hideGameOver = function(){ goOverlay.style.display = 'none'; };

  // Buttons
  if (btnPlayAgain) btnPlayAgain.addEventListener('click', () => {
    // Hide GO, clear any transient match state, and restart the game if available
    window.TennisUI.hideGameOver();
    // optional: preserve room for rematch; dispatch event so game can re-init
    document.dispatchEvent(new CustomEvent('tennis:play:again', { detail: { roomId: getRoom() } }));
    if (typeof window.startGame === 'function') window.startGame();
    else if (typeof window.initGame === 'function') window.initGame();
  });

  if (btnLogoutGO) btnLogoutGO.addEventListener('click', () => {
    // Clear auth and room; rely on your existing front-page auth overlay styles
    localStorage.removeItem('tennis.user');
    sessionStorage.removeItem('tennis.roomId');
    document.body.classList.remove('fp-authenticated');
    // Hide Game Over and return to front page
    window.TennisUI.hideGameOver();
  });

  // Optional: listen for your game’s loss event to show overlay
  document.addEventListener('tennis:game:over', (e) => {
    window.TennisUI.showGameOver(e.detail || {});
  });
})();
</script>

