<script>
(function(){
  const qs = sel => document.querySelector(sel);
  const $ = {
    overlay: qs('#fp-overlay'),
    tabLogin: qs('#tab-login'),
    tabReg: qs('#tab-register'),
    panelLogin: qs('#panel-login'),
    panelReg: qs('#panel-register'),
    loginUser: qs('#login-username'),
    loginPass: qs('#login-password'),
    btnLogin: qs('#btn-login'),
    loginErr: qs('#login-error'),
    regUser: qs('#reg-username'),
    regPass: qs('#reg-password'),
    btnReg: qs('#btn-register'),
    regErr: qs('#reg-error'),
    // Pairing
    btnHost: qs('#btn-host'),
    roomId: qs('#room-id'),
    btnJoin: qs('#btn-join'),
    btnFind: qs('#btn-find'),
    pairStatus: qs('#pair-status'),
    // Game Over
    goOverlay: qs('#go-overlay'),
    goTime: qs('#go-time'),
    goTable: qs('#go-table tbody'),
    goPlayAgain: qs('#go-play-again'),
    goLogout: qs('#go-logout')
  };

  // Tabs
  function setTab(which){
    const isLogin = which === 'login';
    $.tabLogin.classList.toggle('active', isLogin);
    $.tabReg.classList.toggle('active', !isLogin);
    $.tabLogin.setAttribute('aria-selected', String(isLogin));
    $.tabReg.setAttribute('aria-selected', String(!isLogin));
    $.panelLogin.hidden = !isLogin;
    $.panelReg.hidden = isLogin;
  }
  $.tabLogin?.addEventListener('click', ()=>setTab('login'));
  $.tabReg?.addEventListener('click', ()=>setTab('register'));

  // Auth (demo only)
  function saveUser(u, p){ localStorage.setItem('tg:user:'+u, JSON.stringify({u, p})); }
  function getUser(u){ const v = localStorage.getItem('tg:user:'+u); return v? JSON.parse(v): null; }
  function login(u){ sessionStorage.setItem('tg:session', JSON.stringify({u, t: Date.now()})); document.body.classList.add('fp-authenticated'); $.overlay?.setAttribute('aria-hidden','true'); window.dispatchEvent(new CustomEvent('frontpage:authenticated', {detail:{user:u}})); if(window.startGame) try{ window.startGame(); }catch{} else if(window.initGame) try{ window.initGame(); }catch{}; window.__gameStartTime = Date.now(); }

  $.btnReg?.addEventListener('click', ()=>{
    $.regErr.textContent='';
    const u = ($.regUser.value||'').trim();
    const p = ($.regPass.value||'').trim();
    if(!u || !p){ $.regErr.textContent = 'Username and password are required.'; return; }
    if(getUser(u)){ $.regErr.textContent = 'Username already exists.'; return; }
    saveUser(u,p);
    setTab('login');
    $.loginUser.value = u; $.loginPass.value='';
  });

  $.btnLogin?.addEventListener('click', ()=>{
    $.loginErr.textContent='';
    const u = ($.loginUser.value||'').trim();
    const p = ($.loginPass.value||'').trim();
    const rec = getUser(u);
    if(!rec || rec.p !== p){ $.loginErr.textContent = 'Invalid username or password.'; return; }
    login(u);
  });

  // Pairing logic
  const bc = ('BroadcastChannel' in window) ? new BroadcastChannel('tg-matchmaking') : null;
  let myRoom = null; let matchmaking = false; let mmToken = Math.random().toString(36).slice(2,8);

  function updatePairStatus(msg){ if($.pairStatus) $.pairStatus.textContent = msg || ''; }

  // Host a private room
  $.btnHost?.addEventListener('click', ()=>{
    myRoom = Math.random().toString(36).slice(2,8).toUpperCase();
    $.roomId.value = myRoom;
    updatePairStatus('Hosting room '+myRoom+' — share this ID.');
  });

  // Join a private room (notifying via BroadcastChannel)
  $.btnJoin?.addEventListener('click', ()=>{
    const rid = ($.roomId.value||'').trim().toUpperCase();
    if(!rid){ updatePairStatus('Enter a Room ID.'); return; }
    if(bc){ bc.postMessage({type:'join', room:rid, from:mmToken}); }
    updatePairStatus('Requested to join room '+rid+'. Waiting for host...');
  });

  // Random matchmaking
  $.btnFind?.addEventListener('click', ()=>{
    if(!bc){ updatePairStatus('Matchmaking not supported in this browser.'); return; }
    matchmaking = true;
    updatePairStatus('Searching for an opponent...');
    bc.postMessage({type:'mm:find', token:mmToken});
  });

  // Handle BroadcastChannel messages
  if(bc){
    bc.onmessage = (e)=>{
      const m = e.data||{};
      if(m.type==='join' && myRoom && m.room === myRoom){
        updatePairStatus('Player joined room '+myRoom+'. Starting match...');
        bc.postMessage({type:'room:confirmed', room:myRoom});
        startMatch({mode:'private', room:myRoom});
      }
      if(m.type==='room:confirmed' && $.roomId.value.trim().toUpperCase() === m.room){
        updatePairStatus('Host confirmed. Starting match...');
        startMatch({mode:'private', room:m.room});
      }
      if(m.type==='mm:find' && m.token !== mmToken && matchmaking){
        // pair this client with the other
        const pairId = ['MM', Math.random().toString(36).slice(2,6).toUpperCase()].join('-');
        bc.postMessage({type:'mm:pair', a:mmToken, b:m.token, room:pairId});
      }
      if(m.type==='mm:pair' && (m.a===mmToken || m.b===mmToken)){
        updatePairStatus('Opponent found. Room '+m.room+'. Starting match...');
        startMatch({mode:'random', room:m.room});
      }
    };
  }

  function startMatch(info){
    // Hide overlay if authenticated
    const sess = sessionStorage.getItem('tg:session');
    if(!sess){ updatePairStatus('Please login first.'); return; }
    document.body.classList.add('fp-authenticated');
    $.overlay?.setAttribute('aria-hidden','true');
    window.dispatchEvent(new CustomEvent('match:ready', { detail: info }));
    if(window.startGame) try{ window.startGame(info); }catch{} else if(window.initGame) try{ window.initGame(info); }catch{};
    window.__gameStartTime = Date.now();
  }

  // GAME OVER handling
  function fmtTime(ms){
    const s = Math.max(0, Math.floor(ms/1000));
    const mm = String(Math.floor(s/60)).padStart(2,'0');
    const ss = String(s%60).padStart(2,'0');
    return mm+':'+ss;
  }

  window.showGameOver = function(stats){
    const start = window.__gameStartTime || Date.now();
    const used = (stats && stats.timeMs!=null) ? stats.timeMs : (Date.now() - start);
    if($.goTime) $.goTime.textContent = 'Time Used: ' + fmtTime(used);

    const rows = Array.isArray(stats?.players) ? stats.players : [
      // Fallback demo row
      { rank: 1, player: (JSON.parse(sessionStorage.getItem('tg:session')||'{}').u)||'You', score: 0, hp: 0, hits: 0, opponentHits: 0, collect: 0 }
    ];

    $.goTable.innerHTML = rows.map(r=>`<tr>`+
      `<td>${r.rank??''}</td>`+
      `<td class="${r.rank===1?'winner':''}">${r.player??''}</td>`+
      `<td>${r.score??0}</td>`+
      `<td>${r.hp??0}</td>`+
      `<td>${r.hits??0}</td>`+
      `<td>${r.opponentHits??0}</td>`+
      `<td>${r.collect??0}</td>`+
    `</tr>`).join('');

    document.body.classList.add('go-open');
    $.goOverlay?.focus?.();
  };

  window.addEventListener('game:over', e=> window.showGameOver(e.detail||{}));

  // GO buttons
  $.goPlayAgain?.addEventListener('click', ()=>{
    document.body.classList.remove('go-open');
    // Reset game if available
    if(window.resetGame) try{ window.resetGame(); }catch{}
    if(window.startGame) try{ window.startGame(); }catch{} else if(window.initGame) try{ window.initGame(); }catch{};
    window.__gameStartTime = Date.now();
  });
  $.goLogout?.addEventListener('click', ()=>{
    sessionStorage.removeItem('tg:session');
    document.body.classList.remove('go-open');
    document.body.classList.remove('fp-authenticated');
    qs('#fp-overlay')?.setAttribute('aria-hidden','false');
  });
})();
</script>
