#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL<<62);

struct Edge { int to; int w; };

vector<ll> dijkstra(int n, const vector<vector<Edge>>& g, int src){
    vector<ll> dist(n+1, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[src]=0; pq.push({0,src});
    while(!pq.empty()){
        auto [d,u]=pq.top(); pq.pop();
        if(d!=dist[u]) continue;
        for(const auto &e: g[u]){
            int v=e.to; ll nd=d+e.w;
            if(nd<dist[v]){ dist[v]=nd; pq.push({nd,v}); }
        }
    }
    return dist;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m,k;
    if(!(cin>>n>>m>>k)) return 0;
    vector<vector<Edge>> g(n+1);
    for(int i=0;i<m;i++){
        int u,v; int w; cin>>u>>v>>w;
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    }

    // Precompute shortest path distances from 1 and from n
    vector<ll> d1 = dijkstra(n, g, 1);
    vector<ll> dn = dijkstra(n, g, n);

    // For each day, read speeds a (Thuan from 1) and b (Dong from n)
    // We want to minimize max(d1[i]/a, dn[i]/b). Since a,b are per-day, compute on the fly.
    for(int day=0; day<k; ++day){
        long double a,b; cin>>a>>b;
        long double best = numeric_limits<long double>::infinity();
        for(int i=1;i<=n;i++){
            if(d1[i]==INF || dn[i]==INF) continue; // unreachable node can't be meeting point
            long double t1 = (long double)d1[i]/a;
            long double t2 = (long double)dn[i]/b;
            long double wait = max(t1,t2);
            if(wait < best) best = wait;
        }
        // Output minimal waiting time. If no meeting point exists, print -1.
        if(!isfinite(best)){
            cout << -1 << '\n';
        }else{
            // If the problem expects integer times, round appropriately. Here we output with high precision or as integer if it fits.
            // Since specification not explicit, print with 10 decimals trimmed.
            cout.setf(std::ios::fixed); cout<<setprecision(10)<<best<<"\n";
        }
    }
    return 0;
}

