class TournamentApp(tk.Tk):
    """
    Tkinter GUI for managing participants, events, results, points, and leaderboards.
    Uses a ttk.Notebook with tabs.
    """
    def __init__(self):
        super().__init__()
        self.title("E-Sports Tournament Scoring")
        self.geometry("1100x700")
        self.minsize(1000, 640)
        self.data = TournamentData()
