        file_menu = tk.Menu(menubar, tearoff=0)
        file_menu.add_command(label="New", command=self.new_file)
        file_menu.add_command(label="Open...", command=self.open_file)
        file_menu.add_command(label="Save", command=self.save_file)
        file_menu.add_command(label="Save As...", command=self.save_file_as)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=file_menu)
        self.config(menu=menubar)

    def new_file(self):
        if not messagebox.askyesno("Confirm", "Start a new tournament? Unsaved changes will be lost."):
            return
        self.data = TournamentData()
        self.current_file = None
        self.refresh_all()

    def open_file(self):
        path = filedialog.askopenfilename(title="Open Tournament JSON", filetypes=[("JSON", "*.json")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                self.data.load_json(f.read())
            self.current_file = path
            self.refresh_all()
        except Exception as e:
            messagebox.showerror("Open Failed", str(e))

    def save_file(self):
        if not self.current_file:
            return self.save_file_as()
        try:
            with open(self.current_file, "w", encoding="utf-8") as f:
                f.write(self.data.to_json())
            messagebox.showinfo("Saved", f"Saved to {self.current_file}")
        except Exception as e:
            messagebox.showerror("Save Failed", str(e))

    def save_file_as(self):
        path = filedialog.asksaveasfilename(title="Save Tournament JSON", defaultextension=".json",
                                            filetypes=[("JSON", "*.json")])
        if not path:
            return
        self.current_file = path
        self.save_file()

