    # ----- Participants actions -----
    def refresh_chosen_event_boxes(self):
        team_events = [e for e in self.data.events.values() if e.type == "Team"]
        ind_events = [e for e in self.data.events.values() if e.type == "Individual"]
        self.team_chosen_event["values"] = [f"{e.id}: {e.name}" for e in team_events]
        self.ind_chosen_event["values"] = [f"{e.id}: {e.name}" for e in ind_events]

    def add_team(self):
        try:
            name = self.team_name_var.get()
            members = [v.get() for v in self.member_vars if v.get().strip()]
            one_only = self.team_one_event_var.get()
            chosen = self._parse_combo_id(self.team_chosen_event_var.get())
            if not one_only:
                chosen = None
            self.data.add_team(name, members, one_event_only=one_only, chosen_event_id=chosen)
            self.refresh_all()
            self.clear_team_form()
        except Exception as e:
            messagebox.showerror("Add Team Failed", str(e))

    def update_team(self):
        try:
            sel = self._selected_team_id()
            if sel is None:
                raise ValueError("Select a team to update.")
            name = self.team_name_var.get()
            members = [v.get() for v in self.member_vars if v.get().strip()]
            one_only = self.team_one_event_var.get()
            chosen = self._parse_combo_id(self.team_chosen_event_var.get())
            if not one_only:
                chosen = None
            self.data.edit_team(sel, name, members, one_only, chosen)
            self.refresh_all()
        except Exception as e:
            messagebox.showerror("Update Team Failed", str(e))

    def remove_team(self):
        try:
            sel = self._selected_team_id()
            if sel is None:
                raise ValueError("Select a team to remove.")
            if not messagebox.askyesno("Confirm", "Delete selected team?"):
                return
            self.data.remove_team(sel)
            self.refresh_all()
            self.clear_team_form()
        except Exception as e:
            messagebox.showerror("Remove Team Failed", str(e))

    def clear_team_form(self):
        self.team_list.selection_clear(0, tk.END)
        self.team_name_var.set("")
        for v in self.member_vars:
            v.set("")
        self.team_one_event_var.set(False)
        self.team_chosen_event_var.set("")

    def on_team_select(self, _evt=None):
        sel = self._selected_team_id()
        if sel is None:
            return
        t = self.data.teams[sel]
        self.team_name_var.set(t.name)
        for i, v in enumerate(self.member_vars):
            v.set(t.members[i] if i < len(t.members) else "")
        self.team_one_event_var.set(t.one_event_only)
        self.refresh_chosen_event_boxes()
        if t.chosen_event_id and t.one_event_only:
            self.team_chosen_event_var.set(self._format_combo_value(t.chosen_event_id))
        else:
            self.team_chosen_event_var.set("")

    def _selected_team_id(self) -> Optional[int]:
        idxs = self.team_list.curselection()
        if not idxs:
            return None
        item = self.team_list.get(idxs[0])
        return self._parse_leading_id(item)

