    def load_results_entrants(self):
        self.available_list.delete(0, tk.END)
        self.ordered_list.delete(0, tk.END)
        eid = self._parse_combo_id(self.results_event_var.get())
        if eid is None or eid not in self.data.events:
            return
        ev = self.data.events[eid]
        if ev.type == "Team":
            for t in sorted(self.data.teams.values(), key=lambda x: x.name.lower()):
                self.available_list.insert(tk.END, f"{t.id}: {t.name}")
        else:
            for i in sorted(self.data.individuals.values(), key=lambda x: x.name.lower()):
                self.available_list.insert(tk.END, f"{i.id}: {i.name}")
        # Load existing ordered results
        for pid in self.data.results.get(eid, []):
            if ev.type == "Team":
                name = self.data.teams.get(pid).name if pid in self.data.teams else f"Team {pid}"
            else:
                name = self.data.individuals.get(pid).name if pid in self.data.individuals else f"Ind {pid}"
            self.ordered_list.insert(tk.END, f"{pid}: {name}")

    def add_to_results(self):
        for idx in self.available_list.curselection():
            item = self.available_list.get(idx)
            if not self._listbox_contains(self.ordered_list, item):
                self.ordered_list.insert(tk.END, item)

    def remove_from_results(self):
        sel = list(self.ordered_list.curselection())
        for idx in reversed(sel):
            self.ordered_list.delete(idx)

    def move_up(self):
        sel = list(self.ordered_list.curselection())
        if not sel:
            return
        for idx in sel:
            if idx == 0:
                continue
            text = self.ordered_list.get(idx)
            self.ordered_list.delete(idx)
            self.ordered_list.insert(idx-1, text)
            self.ordered_list.selection_set(idx-1)

    def move_down(self):
        sel = list(self.ordered_list.curselection())
        if not sel:
            return
        count = self.ordered_list.size()
        for idx in reversed(sel):
            if idx >= count - 1:
                continue
            text = self.ordered_list.get(idx)
            self.ordered_list.delete(idx)
            self.ordered_list.insert(idx+1, text)
            self.ordered_list.selection_set(idx+1)

    def save_results(self):
        try:
            eid = self._parse_combo_id(self.results_event_var.get())
            if eid is None:
                raise ValueError("Please select an event.")
            ordered_ids = [self._parse_leading_id(self.ordered_list.get(i)) for i in range(self.ordered_list.size())]
            self.data.set_event_results(eid, ordered_ids)
            messagebox.showinfo("Saved", "Results saved.")
            self.refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Save Results Failed", str(e))

    # ----- Leaderboards actions -----
    def refresh_leaderboards(self):
        # Clear trees
        for tree in (self.team_tree, self.ind_tree):
            for iid in tree.get_children():
                tree.delete(iid)
        team_pts, ind_pts = self.data.aggregate_points()
        # Teams
        sorted_teams = sorted(self.data.teams.values(), key=lambda t: (-team_pts.get(t.id, 0), t.name.lower()))
        for rank, t in enumerate(sorted_teams, start=1):
            events_entered = sum(1 for eid, order in self.data.results.items() if self.data.events.get(eid, Event(0, '', '')).type == "Team" and t.id in order)
            self.team_tree.insert("", tk.END, values=(rank, t.name, team_pts.get(t.id, 0), events_entered))
        # Individuals
        sorted_inds = sorted(self.data.individuals.values(), key=lambda i: (-ind_pts.get(i.id, 0), i.name.lower()))
        for rank, i in enumerate(sorted_inds, start=1):
            events_entered = sum(1 for eid, order in self.data.results.items() if self.data.events.get(eid, Event(0, '', '')).type == "Individual" and i.id in order)
            self.ind_tree.insert("", tk.END, values=(rank, i.name, ind_pts.get(i.id, 0), events_entered))

    # ----- Points actions -----
    def apply_scheme(self):
        try:
            val = self.points_scheme_var.get()
            if val == "F1":
                self.data.points_map = {1:25,2:18,3:15,4:12,5:10,6:8,7:6,8:4,9:2,10:1}
            elif val == "Top8":
                self.data.points_map = {1:10,2:8,3:6,4:5,5:4,6:3,7:2,8:1}
            elif val == "WTA":
                self.data.points_map = {1:10,2:0,3:0,4:0,5:0}
            messagebox.showinfo("Points Applied", "Global points scheme updated.")
            self.refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Apply Scheme Failed", str(e))

    def apply_custom_points(self):
        try:
            csv = self.custom_points_var.get().strip()
            if not csv:
                raise ValueError("Enter a CSV of integers for ranks, e.g., 25,18,15")
            nums = [int(x.strip()) for x in csv.split(',') if x.strip()]
            if any(n < 0 for n in nums):
                raise ValueError("Points must be non-negative.")
            # Build map rank->points
            pts = {rank+1: p for rank, p in enumerate(nums)}
            self.data._validate_points_map(pts)
            self.data.points_map = pts
            messagebox.showinfo("Points Applied", "Custom global points updated.")
            self.refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Custom Points Failed", str(e))

    # ----- Utilities & Refresh -----
    def refresh_all(self):
        # Rebuild listboxes and combos from model
        self.refresh_participants_lists()
        self.refresh_events_list()
        self.refresh_results_event_combo()
        self.refresh_chosen_event_boxes()
        self.refresh_leaderboards()

    def refresh_participants_lists(self):
        self.team_list.delete(0, tk.END)
        for t in sorted(self.data.teams.values(), key=lambda x: x.name.lower()):
            self.team_list.insert(tk.END, f"{t.id}: {t.name}")
        self.ind_list.delete(0, tk.END)
        for i in sorted(self.data.individuals.values(), key=lambda x: x.name.lower()):
            self.ind_list.insert(tk.END, f"{i.id}: {i.name}")

    def refresh_events_list(self):
        self.event_list.delete(0, tk.END)
        for e in sorted(self.data.events.values(), key=lambda x: x.name.lower()):
            self.event_list.insert(tk.END, f"{e.id}: {e.name} [{e.type}]")

    def refresh_results_event_combo(self):
        self.results_event_combo["values"] = [self._format_combo_value(e.id, e.name) for e in sorted(self.data.events.values(), key=lambda x: x.name.lower())]
        if not self.results_event_var.get() and self.results_event_combo["values"]:
            self.results_event_var.set(self.results_event_combo["values"][0])

    @staticmethod
    def _parse_points_map(text: str) -> Optional[Dict[int, int]]:
        text = (text or "").strip()
        if not text:
            return None
        result: Dict[int, int] = {}
        for part in text.split(','):
            if not part.strip():
                continue
            if ':' not in part:
                raise ValueError("Use 'rank:points' pairs, separated by commas.")
            k, v = part.split(':', 1)
            rank = int(k.strip()); points = int(v.strip())
            if rank <= 0 or points < 0:
                raise ValueError("Ranks must be >0 and points >=0.")
            result[rank] = points
        # Validate non-increasing
        prev = None
        for r in sorted(result):
            if prev is not None and result[r] > prev:
                raise ValueError("Points should not increase for lower ranks.")
            prev = result[r]
        return result

    @staticmethod
    def _format_combo_value(eid: int, name: Optional[str] = None) -> str:
        return f"{eid}: {name}" if name is not None else f"{eid}"

    @staticmethod
    def _parse_combo_id(text: str) -> Optional[int]:
        text = (text or "").strip()
        if not text:
            return None
        try:
            return int(text.split(":", 1)[0])
        except Exception:
            return None

    @staticmethod
    def _parse_leading_id(text: str) -> int:
        return int(text.split(":", 1)[0])

    @staticmethod
    def _listbox_contains(lst: tk.Listbox, item: str) -> bool:
        return any(lst.get(i) == item for i in range(lst.size()))


if __name__ == "__main__":
    app = TournamentApp()
    app.refresh_all()
    app.mainloop()
