#!/usr/bin/env python3
import os
import re
import shutil
import subprocess
from pathlib import Path
from typing import List, Optional


FEATURE_BRANCH = "TK/14278_TM-13"
MAIN_REMOTE_BRANCH = "origin/main"
TARGET_LINE = "o.Select().Filter().OrderBy().Count().Expand().SetMaxTop(100);"
INSERT_LINE = "o.TimeZone = TimeZoneInfo.Utc;"
API_PACKAGE = ("Ewl.Platform.Common.Api", "1.0.0")
STORAGE_PACKAGE = ("Ewl.Platform.Common.Storage", "1.0.0")


def run(cmd: List[str], cwd: Optional[Path] = None, check: bool = True) -> subprocess.CompletedProcess:
    print(f"[RUN] {cmd} (cwd={cwd})")
    return subprocess.run(cmd, cwd=str(cwd) if cwd else None, check=check)


def safe_run(cmd: List[str], cwd: Optional[Path] = None) -> bool:
    try:
        res = run(cmd, cwd=cwd, check=False)
        return res.returncode == 0
    except Exception as e:
        print(f"[WARN] Failed to run {cmd}: {e}")
        return False


def is_git_repo(path: Path) -> bool:
    return (path / ".git").exists()


def ensure_on_main_at_origin(repo_dir: Path) -> None:
    run(["git", "fetch", "origin", "--prune"], cwd=repo_dir)
    run(["git", "checkout", "-B", "main", MAIN_REMOTE_BRANCH], cwd=repo_dir)
    run(["git", "reset", "--hard", MAIN_REMOTE_BRANCH], cwd=repo_dir)


def ensure_feature_branch_from_origin_main(repo_dir: Path) -> None:
    exists = safe_run(["git", "rev-parse", "--verify", FEATURE_BRANCH], cwd=repo_dir)
    if exists:
        run(["git", "checkout", FEATURE_BRANCH], cwd=repo_dir)
        run(["git", "reset", "--hard", MAIN_REMOTE_BRANCH], cwd=repo_dir)
    else:
        run(["git", "checkout", "-b", FEATURE_BRANCH, MAIN_REMOTE_BRANCH], cwd=repo_dir)


def find_first_solution(repo_dir: Path) -> Optional[Path]:
    slns = list(repo_dir.glob("*.sln"))
    return slns[0] if slns else None


def find_cs_files(repo_dir: Path, filename: str) -> List[Path]:
    results = []
    for p in repo_dir.rglob(filename):
        rel_parts = set(part.lower() for part in p.parts)
        if "bin" in rel_parts or "obj" in rel_parts:
            continue
        results.append(p)
    return results


def insert_timezone_after_target_line(file_path: Path) -> bool:
    text = file_path.read_text(encoding="utf-8", errors="ignore")
    newline = "\r\n" if "\r\n" in text else "\n"

    lines = text.splitlines(keepends=True)
    modified = False

    i = 0
    while i < len(lines):
        if lines[i].strip() == TARGET_LINE:
            next_is_insert = False
            if i + 1 < len(lines) and lines[i + 1].strip() in {INSERT_LINE, INSERT_LINE.rstrip(";")}:  # tolerate stray semicolon logic
                next_is_insert = True
            if not next_is_insert:
                indent = re.match(r"\s*", lines[i]).group(0)
                lines.insert(i + 1, f"{indent}{INSERT_LINE}{newline}")
                modified = True
                i += 1
        i += 1

    if modified:
        file_path.write_text("".join(lines), encoding="utf-8")
        print(f"[INFO] Updated {file_path}")
    else:
        print(f"[INFO] No changes needed in {file_path}")

    return modified


def find_main_project_csproj(repo_dir: Path, folder_name: str) -> Optional[Path]:
    candidate_dir = repo_dir / "src" / folder_name
    if candidate_dir.exists():
        csprojs = list(candidate_dir.glob("*.csproj"))
        if csprojs:
            exact = [p for p in csprojs if p.stem == folder_name]
            return exact[0] if exact else csprojs[0]
    csprojs = list((repo_dir / "src").rglob("*.csproj"))
    if not csprojs:
        return None
    exact = [p for p in csprojs if p.stem == folder_name]
    return exact[0] if exact else csprojs[0]


def find_storage_csprojs(repo_dir: Path) -> List[Path]:
    results = []
    for p in (repo_dir / "src").rglob("*.csproj"):
        if p.name.lower().endswith(".storage.csproj"):
            results.append(p)
    return results


def nuget_available() -> bool:
    return shutil.which("nuget") is not None


def update_package_in_project(csproj: Path, package_id: str, version: str) -> None:
    if nuget_available():
        ok = safe_run(
            ["nuget", "update", str(csproj), "-Id", package_id, "-Version", version],
            cwd=csproj.parent,
        )
        if ok:
            print(f"[INFO] nuget updated {package_id} to {version} in {csproj}")
            return
    # Fallback: dotnet add package (keeps intent if nuget.exe not present)
    safe_run(["dotnet", "remove", str(csproj), "package", package_id], cwd=csproj.parent)
    safe_run(["dotnet", "add", str(csproj), "package", package_id, "--version", version], cwd=csproj.parent)


def run_tests_for_solution(repo_dir: Path, sln: Optional[Path]) -> None:
    if sln and sln.exists():
        run(["dotnet", "test", str(sln), "-v", "m"], cwd=repo_dir)
    else:
        run(["dotnet", "test", "-v", "m"], cwd=repo_dir)


def process_repo(repo_root: Path, folder_name: str) -> None:
    repo_dir = repo_root / folder_name
    if not repo_dir.exists():
        print(f"[WARN] {repo_dir} does not exist, skipping")
        return
    if not is_git_repo(repo_dir):
        print(f"[WARN] {repo_dir} is not a git repo, skipping")
        return

    ensure_on_main_at_origin(repo_dir)
    ensure_feature_branch_from_origin_main(repo_dir)

    # Code replacement in MvcBuilderExtensions.cs
    targets = find_cs_files(repo_dir, "MvcBuilderExtensions.cs")
    if not targets:
        print(f"[WARN] No MvcBuilderExtensions.cs found under {repo_dir}")
    for cs in targets:
        insert_timezone_after_target_line(cs)

    # NuGet updates
    main_csproj = find_main_project_csproj(repo_dir, folder_name)
    if main_csproj:
        update_package_in_project(main_csproj, *API_PACKAGE)
    else:
        print(f"[WARN] Main project for {folder_name} not found under src/")

    for storage_csproj in find_storage_csprojs(repo_dir):
        update_package_in_project(storage_csproj, *STORAGE_PACKAGE)

    # Tests
    sln = find_first_solution(repo_dir)
    run_tests_for_solution(repo_dir, sln)


def main():
    start_dir = Path.cwd()
    try:
        folders = [
            "Ewl.Platform.Analytics",
        ]
        for folder in folders:
            process_repo(start_dir, folder)
    finally:
        os.chdir(start_dir)
        print(f"[INFO] Returned to starting directory: {start_dir}")


if __name__ == "__main__":
    main()

