(function() {
  'use strict';

  // Zero step: ensure this code runs only in the first tab of the browser.
  // Heuristic: Use localStorage as a single-tab lock claimed by the earliest-opened tab.
  const LOCK_KEY = 'tm_first_tab_lock_v1';
  const MY_ID = `${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const LOCK_TTL_MS = 8000; // refresh every 5s, expire after 8s

  function nowMs() { return Date.now(); }

  function acquireOrRefreshLock() {
    const raw = localStorage.getItem(LOCK_KEY);
    const now = nowMs();
    if (!raw) {
      localStorage.setItem(LOCK_KEY, JSON.stringify({ owner: MY_ID, ts: now }));
      return true;
    }
    try {
      const obj = JSON.parse(raw);
      if (!obj || typeof obj !== 'object') throw 0;
      // If lock is stale, take it
      if ((now - obj.ts) > LOCK_TTL_MS) {
        localStorage.setItem(LOCK_KEY, JSON.stringify({ owner: MY_ID, ts: now }));
        return true;
      }
      // If I own it, refresh
      if (obj.owner === MY_ID) {
        localStorage.setItem(LOCK_KEY, JSON.stringify({ owner: MY_ID, ts: now }));
        return true;
      }
      return false;
    } catch(e) {
      localStorage.setItem(LOCK_KEY, JSON.stringify({ owner: MY_ID, ts: now }));
      return true;
    }
  }

  function startLockHeartbeat() {
    const iv = setInterval(() => {
      const ok = acquireOrRefreshLock();
