    const m = d.getMinutes();
    const mins = h * 60 + m;
    const start = 22 * 60 + 30; // 22:30 -> 1350
    const end = 3 * 60 + 30;    // 03:30 -> 210
    // Window crosses midnight: valid if mins >= start OR mins <= end
    return (mins >= start) || (mins <= end);
  }

  function sleep(ms){ return new Promise(r => setTimeout(r, ms)); }

  // Third & fourth steps loop: check exact text, reload if found; else go to next tab
