  const OWNER_TTL_MS = 5 * 60 * 1000; // 5 minutes lease, auto-renewed by the owner
  const now = Date.now();
  try {
    const raw = localStorage.getItem(OWNER_KEY);
    let isOwner = false;
    if (raw) {
      const data = JSON.parse(raw);
      if (data && typeof data.expires === 'number' && data.expires > now) {
        // Someone else owns it; do not run in this tab
        isOwner = false;
      } else {
        // Expired claim; take ownership
        isOwner = true;
      }
    } else {
      // No owner yet; take ownership
      isOwner = true;
    }

    if (!isOwner) return; // Not the first tab => do not run

    function renewLease() {
      const payload = { expires: Date.now() + OWNER_TTL_MS };
      localStorage.setItem(OWNER_KEY, JSON.stringify(payload));
    }
    renewLease();
    setInterval(renewLease, Math.floor(OWNER_TTL_MS / 2));
  } catch (e) {
    // If storage is unavailable, fall back to a per-tab guard: only proceed if no visibility change to hidden happened yet.
    if (document.visibilityState === 'hidden') return;
  }

  // First step: Ensure we are on the MAIN page only (handled by @match) and not branches.
  // Extra guard in case of redirects
  const u = new URL(location.href);
  if (!(u.hostname === 'www.drtorkzadeh.com' || u.hostname === 'drtorkzadeh.com') || !(u.pathname === '/' || u.pathname === '')) {
    return;
  }

  // Second step: time window check (22:30 to 03:30 local time)
  function inAllowedWindow(d = new Date()) {
    const h = d.getHours();
    const m = d.getMinutes();
    const mins = h * 60 + m;
    // Window spans midnight: [22:30, 24:00) U [00:00, 03:30]
    return (mins >= 22 * 60 + 30) || (mins <= 3 * 60 + 30);
  }

  function msUntilNextStart(d = new Date()) {
    if (inAllowedWindow(d)) return 0;
    const startToday = new Date(d);
    startToday.setHours(22, 30, 0, 0);
    if (d < startToday) return startToday - d;
    const startTomorrow = new Date(startToday.getTime() + 24 * 60 * 60 * 1000);
    return startTomorrow - d;
  }

  function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

  async function waitUntilWindow() {
    while (true) {
      const delay = msUntilNextStart();
      if (delay <= 0) return;
      await sleep(Math.min(30000, delay));
    }
  }

  // Third & Fourth & Fifth steps implementation
  const TARGET_TEXT = 'رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است';

  async function mainLoop() {
