      // Tampermonkey in a regular web page cannot programmatically switch browser tabs due to browser security.
      // However, we can attempt to signal the user and try a best-effort approach using the Page Visibility API hint.
      // Additionally, we try Ctrl+Tab via simulated key events only if the browser allows it (most will not). We still provide the logic.

      try {
        // Attempt to send Ctrl+Tab (will usually be blocked by browsers for security reasons)
        const evt = new KeyboardEvent('keydown', { key: 'Tab', code: 'Tab', ctrlKey: true, bubbles: true });
        document.dispatchEvent(evt);
      } catch (_) { /* ignore */ }

      // Show a clear prompt to switch and auto-complete the click in second tab via a companion userscript or manual action.
      alert('Switch to the second tab now (Ctrl+Tab). The script there should click the submit button.');

      // Since we cannot act in another tab from this tab, stop here.
      return;
    }
  }

  // Optional: companion logic that, if this script is also installed and active in the SECOND tab page,
  // will click the specified element and then stop. We guard it so it only runs when the page is NOT the main page.
  function maybeRunSecondTabAction() {
    const isMain = (location.pathname === '/' || location.pathname === '');
    if (isMain) return; // Only main-tab logic here; second-tab action should be on its loaded page

    try {
      // fifth step target: INPUT:SUBMIT with id=submit inside form action=http://www.drtorkzadeh.com/
      const form = document.querySelector('form[action="http://www.drtorkzadeh.com/"]');
      const btn = document.querySelector('input[type="submit"]#submit');
      if (form && btn && form.contains(btn)) {
        btn.click();
      }
    } catch (e) { /* ignore */ }
  }

  // Decide which path to run based on current page (main vs other). @match ensures we are on main for this script,
  // but keep the check to be safe if user extends @match to second tab page manually.
  const onMain = (location.pathname === '/' || location.pathname === '');
  if (onMain) {
    mainLoop();
  } else {
    maybeRunSecondTabAction();
  }
})();

