        umart_handle_submission($profile_user_id);
    }

    // Render either edit form (owner) or read-only view (viewer)
    $post = umart_get_user_artiste_post($profile_user_id, umart_config()['one_per_user']['include_trashed']);

    if ($is_owner && umart_user_can_manage($profile_user_id)) {
        echo umart_render_form($post); // edit/create form
    } else {
        echo umart_render_read_only($post); // read-only for viewers
    }
}

function umart_user_can_manage($user_id) {
    $cfg = umart_config();
    $user = get_user_by('id', $user_id);
    if (!$user) return false;

    // Role gate
    $allowed = array_intersect($cfg['um']['access_roles'], (array) $user->roles);
    if (empty($allowed)) return false;

    // Capability gate (CPT-specific if you defined custom caps)
    $cpt = $cfg['cpt'];
    $can = user_can($user_id, 'edit_posts'); // fallback; replace with custom caps if set
    return (bool) $can;
}

function umart_get_user_artiste_post($user_id, $include_trashed = false) {
    $cfg = umart_config();
    $statuses = array('publish','pending','draft');
    if ($include_trashed) $statuses[] = 'trash';

    $q = get_posts(array(
        'post_type'      => $cfg['cpt'],
        'author'         => $user_id,
        'post_status'    => $statuses,
        'posts_per_page' => 1,
        'orderby'        => 'ID',
        'order'          => 'DESC',
        'fields'         => 'all',
    ));
    return $q ? $q[0] : null;
}

function umart_handle_submission($profile_user_id) {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') return;

    $cfg = umart_config();
    if (!isset($_POST[$cfg['security']['nonce_field']]) ||
        !wp_verify_nonce($_POST[$cfg['security']['nonce_field']], $cfg['security']['nonce_action'])) {
        return; // silent fail for security
    }

    if (!umart_user_can_manage($profile_user_id)) return;

    $action = isset($_POST['umart_action']) ? sanitize_text_field($_POST['umart_action']) : '';
    $existing = umart_get_user_artiste_post($profile_user_id, $cfg['one_per_user']['include_trashed']);

    // Delete
    if ($action === 'delete' && $existing && (int)$existing->post_author === $profile_user_id) {
        if ($cfg['one_per_user']['delete_behavior'] === 'force') {
            wp_delete_post($existing->ID, true);
        } else {
            wp_trash_post($existing->ID);
        }
        add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice success">'.esc_html($cfg['messages']['deleted']).'</div>'; });
        return;
    }

    // Enforce one-per-user
    $post_id = $existing ? (int) $existing->ID : 0;
    if (!$existing && $cfg['one_per_user']['enforce']) {
        // ok to create
    } elseif ($existing && $cfg['one_per_user']['enforce'] && $cfg['one_per_user']['on_second_attempt'] === 'error' && $action === 'create') {
        add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['one_only']).'</div>'; });
        return;
    }

    // Collect/sanitize fields
    $clean = array();
    foreach ($cfg['fields'] as $f) {
        $key = $f['key'];
        $required = !empty($f['required']);
        $sanitize = isset($f['sanitize_cb']) ? $f['sanitize_cb'] : 'sanitize_text_field';

        if ($key === 'post_title') {
            $val = isset($_POST['post_title']) ? wp_unslash($_POST['post_title']) : '';
            $val = call_user_func($sanitize, $val);
            if ($required && $val === '') {
                add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['invalid']).'</div>'; });
                return;
            }
            $clean['post_title'] = $val;
        } else {
            $val = isset($_POST[$key]) ? wp_unslash($_POST[$key]) : '';
            $val = ($f['type'] === 'textarea') ? wp_kses_post($val) : call_user_func($sanitize, $val);
            if ($required && $val === '') {
                add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['invalid']).'</div>'; });
                return;
            }
            $clean['meta'][$key] = $val;
        }
    }

    // Create or update post
    if (!$post_id) {
        $post_id = wp_insert_post(array(
            'post_type'   => $cfg['cpt'],
            'post_status' => $cfg['status']['create'],
            'post_title'  => $clean['post_title'],
            'post_author' => $profile_user_id,
        ));
        if (is_wp_error($post_id)) return;
        add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice success">'.esc_html($cfg['messages']['created']).'</div>'; });
    } else {
        wp_update_post(array(
            'ID'          => $post_id,
            'post_status' => $cfg['status']['update'],
            'post_title'  => $clean['post_title'],
        ));
        add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice success">'.esc_html($cfg['messages']['updated']).'</div>'; });
    }

    // Save meta
    if (!empty($clean['meta'])) {
        foreach ($clean['meta'] as $k => $v) {
            update_post_meta($post_id, $k, $v);
        }
    }

    // Handle featured image
    $media = $cfg['media']['featured_image'];
    if (!empty($media['enabled']) && isset($_FILES[$media['input']]) && !empty($_FILES[$media['input']]['name'])) {
        $file = $_FILES[$media['input']];
        // Validate MIME
        $ft = wp_check_filetype($file['name']);
        if (!in_array($ft['type'], $media['allowed_mime_types'], true)) {
            add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['file_type']).'</div>'; });
            return;
        }
        // Validate size
        $max_bytes = (int) ($media['max_mb'] * 1024 * 1024);
        if ((int)$file['size'] > $max_bytes) {
            add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['file_size']).'</div>'; });
            return;
        }
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $att_id = media_handle_upload($media['input'], $post_id);
        if (!is_wp_error($att_id)) {
            set_post_thumbnail($post_id, $att_id);
        } else {
            add_action('um_before_profile_header', function() use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['upload_err']).'</div>'; });
        }
    }
}

function umart_render_form($post) {
    $cfg = umart_config();
    $is_edit = $post && $post->post_status !== 'trash';
    $values = array(
        'post_title' => $is_edit ? $post->post_title : '',
    );
    foreach ($cfg['fields'] as $f) {
        if ($f['key'] === 'post_title') continue;
        $values[$f['key']] = $is_edit ? get_post_meta($post->ID, $f['key'], true) : '';
    }

    ob_start();
    echo '<form method="post" enctype="multipart/form-data" class="umart-form">';
    wp_nonce_field($cfg['security']['nonce_action'], $cfg['security']['nonce_field']);

    foreach ($cfg['fields'] as $f) {
        $key = esc_attr($f['key']);
        $label = esc_html($f['label']);
        $required = !empty($f['required']) ? 'required' : '';
        $val = isset($values[$key]) ? $values[$key] : '';
        echo '<p class="um-field">';
        echo '<label for="'.$key+'">'.$label.'</label>';
        if ($f['type'] === 'textarea') {
            echo '<textarea name="'.$key+'" id="'.$key+'" '.$required.'>'.esc_textarea($val).'</textarea>';
        } else {
            $type_attr = $f['type'] === 'url' ? 'url' : 'text';
            echo '<input type="'.$type_attr.'" name="'.$key+'" id="'.$key+'" value="'.esc_attr($val).'" '.$required.' />';
        }
        echo '</p>'; 
    }

    if (!empty($cfg['media']['featured_image']['enabled'])) {
        $name = esc_attr($cfg['media']['featured_image']['input']);
        echo '<p class="um-field"><label for="'.$name.'">Featured Image</label><input type="file" name="'.$name.'" id="'.$name.'" accept="image/*"></p>';
    }

    if ($is_edit) {
        echo '<button type="submit" name="umart_action" value="update" class="um-button">'.esc_html($cfg['messages']['updated']).'</button> ';
        echo '<button type="submit" name="umart_action" value="delete" class="um-button um-button-danger" onclick="return confirm(\'Are you sure?\');">Delete Artiste</button>';
    } else {
        echo '<button type="submit" name="umart_action" value="create" class="um-button">Create Artiste</button>';
    }

    echo '</form>';
    return ob_get_clean();
}

function umart_render_read_only($post) {
    $cfg = umart_config();
    ob_start();
    if (!$post || $post->post_status === 'trash') {
        echo '<p>'.esc_html($cfg['messages']['not_found']).'</p>';
        return ob_get_clean();
    }

    echo '<div class="umart-view">';
    echo '<h3>'.esc_html(get_the_title($post)).'</h3>';
    if (has_post_thumbnail($post)) {
        echo get_the_post_thumbnail($post, 'medium');
    }
    foreach ($cfg['fields'] as $f) {
        if ($f['key'] === 'post_title') continue;
        $val = get_post_meta($post->ID, $f['key'], true);
        if ($val === '') continue;
        echo '<p><strong>'.esc_html($f['label']).':</strong> ';
        if ($f['type'] === 'url') {
            $url = esc_url($val);
            echo '<a href="'.$url+'" rel="nofollow noopener" target="_blank">'.$url.'</a>';
        } elseif ($f['type'] === 'textarea') {
            echo wp_kses_post(wpautop($val));
        } else {
            echo esc_html($val);
        }
        echo '</p>';
    }
    echo '</div>';

    return ob_get_clean();
}
