function source_panel_main()
% 2-D Source Panel Method (MATLAB)
% - Reads panel points from a text file
% - Prompts user for flow conditions
% - Computes Cp distribution and lift coefficient (via Kutta–Joukowski)
% - Compares to analytical results when available (circle/ellipse)
% - Checks convergence with panel refinement
% - Basic error handling and clear structure
%
% Usage:
%   1) Prepare an input text file with point coordinates defining the body
%      boundary in order (counter-clockwise preferred). Each row: x y
%      The first and last points need NOT be identical; code will close it.
%   2) Run: source_panel_main
%
% Notes:
%   - This implementation is a purely source-only panel method (no vortex).
%     For symmetric closed bodies at small AoA, net lift is theoretically
%     zero; Kutta–Joukowski lift here comes from numerical leakage of
%     circulation and/or user-specified circulation if enabled.
%   - For analytical comparison, the script can recognize a circle and use
%     potential-flow Cp for a cylinder with optional circulation.

clc; close all; clearvars -except -regexp ^OCTAVE_VERSION$;

try
    fprintf('=== 2-D Source Panel Method ===\n');

    % --- Input file ---
    panelFile = input('Enter panel points file path (e.g., airfoil_pts.txt): ', 's');
    if ~isfile(panelFile)
        error('FileNotFound:Input','Input file not found: %s', panelFile);
    end

    P = read_panel_points(panelFile); % Nx2 array [x y]
    if size(P,2) ~= 2 || size(P,1) < 3
        error('BadInput:Points','Input must contain at least 3 points with two columns [x y].');
    end

    % --- Flow inputs ---
    Uinf = input_with_default('Enter free-stream speed U_inf [m/s] (default 1): ', 1.0, @(v)isnumeric(v)&&isscalar(v)&&v>0);
    alpha_deg = input_with_default('Enter angle of attack alpha [deg] (default 0): ', 0.0, @(v)isnumeric(v)&&isscalar(v));
    rho = input_with_default('Enter density rho [kg/m^3] (default 1.225): ', 1.225, @(v)isnumeric(v)&&isscalar(v)&&v>0);

    % Optional circulation for analytical comparison on circle
    useGamma = input_with_default('Specify nonzero circulation for cylinder? 0/1 (default 0): ', 0, @(v)isnumeric(v)&&isscalar(v)&&(v==0||v==1));
    Gamma_user = 0.0;
    if useGamma==1
        Gamma_user = input_with_default('Enter circulation Gamma [m^2/s] (default 0): ', 0.0, @(v)isnumeric(v)&&isscalar(v));
    end

    % --- Panel refinement settings for accuracy study ---
    doRefine = input_with_default('Perform panel refinement study? 0/1 (default 1): ', 1, @(v)isnumeric(v)&&isscalar(v)&&(v==0||v==1));
    refineLevels = [];
    if doRefine==1
        refineLevels = input_with_default('Enter refinement factors as vector (e.g., [1 2 4]) (default [1 2 4]): ', [1 2 4], @(v)isnumeric(v)&&isvector(v)&&all(v>0));
    else
        refineLevels = 1;
    end

    % --- Convert AoA to radians ---
    alpha = deg2rad(alpha_deg);

    % --- Run baseline and refinement ---
    results = struct('N',{},'CL',{},'CL_analytical',{},'CL_err',{},'Cp',{},'xcp',{},'ycp',{});

    baseN = size(P,1)-1; % if polyline closed later, this is for reference
    fprintf('\nRunning cases...\n');

    k = 1;
    for r = refineLevels(:)'
        [P_ref, Np] = resample_closed_polyline(P, r);

        caseInfo = sprintf('Npan=%d', Np);
        fprintf(' - %s\n', caseInfo);

        % Build panels
        panels = build_panels(P_ref);

        % Solve source strengths
        [sigma, Vt, Cp, xcp, ycp, Vx, Vy] = source_panel_solve(panels, Uinf, alpha);

        % Characteristic length (spanwise unit depth assumed)
        % Use chord-like length: max(x)-min(x)
        Lref = max(P_ref(:,1)) - min(P_ref(:,1));
        if Lref <= 0
            Lref = path_length(P_ref); % fallback to perimeter as scale
        end

        % Compute lift via Kutta–Joukowski using estimated effective circulation
        % Gamma_eff approximated from tangential velocity integral around body.
        Gamma_eff = -trapz_along_panels(panels, Vt); % sign per convention
        Lprime = rho * Uinf * Gamma_eff; % per unit span
        CL_numeric = Lprime / (0.5*rho*Uinf^2*Lref);

        % Analytical comparison if geometry ~ circle/ellipse; focus on circle
        [isCircle, xcirc, ycirc, Rcirc] = detect_circle(P_ref);
        CL_anal = NaN;
        Cp_anal = [];
        if isCircle
            % For a cylinder with circulation Gamma_a, lift per unit span = rho*U*Gamma_a
            % Choose analytical Gamma_a from user if provided, else 0
            Gamma_a = Gamma_user;
            Lprime_a = rho*Uinf*Gamma_a;
            CL_anal = Lprime_a / (0.5*rho*Uinf^2*(2*Rcirc)); % use diameter as Lref

            % Analytical Cp(theta) = 1 - (2 sin(theta) + Gamma_a/(2*pi*R*U))^2 - (2 cos(theta))^2? No:
            % For cylinder with circulation: V_theta = 2U sin(theta) + Gamma/(2piR)
            % Cp = 1 - (V/U)^2, where V = |V_theta|
            theta = atan2(ycp - ycirc, xcp - xcirc);
            Vtheta = 2*Uinf*sin(theta) + Gamma_a/(2*pi*Rcirc);
            Cp_anal = 1 - (Vtheta./Uinf).^2; % potential-flow analytical
        end

        % Error metrics
        CL_err = NaN;
        if ~isnan(CL_anal)
            CL_err = abs(CL_numeric - CL_anal)/max(1e-12,abs(CL_anal));
        end

        % Store
        results(k).N = Np;
        results(k).CL = CL_numeric;
        results(k).CL_analytical = CL_anal;
        results(k).CL_err = CL_err;
        results(k).Cp = Cp;
        results(k).xcp = xcp; results(k).ycp = ycp;

        % Plots
        figure('Name',sprintf('Geometry and Cp - %s',caseInfo));
        subplot(1,2,1); hold on; axis equal; grid on;
        plot([panels.xb, panels.xe]', [panels.yb, panels.ye]','k-');
        quiver(xcp, ycp, Vx, Vy, 2,'r');
        title(sprintf('Panels and Velocity Vectors (%s)',caseInfo)); xlabel('x'); ylabel('y');

        subplot(1,2,2); hold on; grid on;
        plot((1:numel(Cp))', Cp,'b.-','DisplayName','Numeric Cp');
        if ~isempty(Cp_anal)
            plot((1:numel(Cp_anal))', Cp_anal,'ro','DisplayName','Analytical Cp (cylinder)');
        end
        set(gca,'YDir','reverse'); % conventional Cp plotting
        xlabel('Panel index'); ylabel('C_p'); title('Pressure Coefficient'); legend('Location','best');

        k = k+1;
    end

    % --- Report summary for refinement study ---
    fprintf('\nSummary (N, CL_numeric, CL_analytical, rel_error):\n');
    for i=1:numel(results)
        fprintf('%6d  % .6f  % .6f  % .3e\n', results(i).N, results(i).CL, results(i).CL_analytical, results(i).CL_err);
    end

    % Simple convergence indicator if analytical available
    if any(~isnan([results.CL_analytical]))
        fprintf('\nObserved |CL-CL_a| vs N:\n');
        for i=1:numel(results)
            if ~isnan(results(i).CL_analytical)
                fprintf('N=%d  |dCL|=% .3e\n', results(i).N, abs(results(i).CL - results(i).CL_analytical));
            end
        end
    end

    fprintf('\nDone.\n');

catch ME
    warning('An error occurred: %s', ME.message);
    if ~isempty(ME.identifier)
        fprintf('Identifier: %s\n', ME.identifier);
    end
    fprintf('Stack trace (last call):\n');
    for s = 1:numel(ME.stack)
        fprintf('  in %s at %d\n', ME.stack(s).name, ME.stack(s).line);
    end
end
end

function P = read_panel_points(fname)
    data = readmatrix(fname);
    if any(isnan(data(:)))
        % try textscan for mixed delimiters
        fid = fopen(fname,'r');
        C = textscan(fid,'%f %f','CommentStyle','#');
        fclose(fid);
        data = [C{1}, C{2}];
    end
    P = data(:,1:2);
end

function [Pout, Np] = resample_closed_polyline(Pin, refineFactor)
    % Ensure closed polyline
    if norm(Pin(1,:)-Pin(end,:))>1e-12
        Pin = [Pin; Pin(1,:)];
    end
    % Uniformly subdivide each original segment by refineFactor
    pts = [];
    for i=1:size(Pin,1)-1
        A = Pin(i,:); B = Pin(i+1,:);
        for j=0:refineFactor-1
            t = j/refineFactor;
            pts(end+1,:) = (1-t)*A + t*B; %#ok<AGROW>
        end
    end
    pts(end+1,:) = pts(1,:); % close
    Pout = pts;
    Np = size(Pout,1)-1;
end

function panels = build_panels(P)
    % Panel endpoints
    xb = P(1:end-1,1); yb = P(1:end-1,2);
    xe = P(2:end,1);   ye = P(2:end,2);

    xc = 0.5*(xb+xe); yc = 0.5*(yb+ye); % collocation points
    dx = xe - xb; dy = ye - yb;         % panel vectors
    S = hypot(dx,dy);                   % lengths

    % Orientation: local panel coordinates (tangent, normal)
    phi = atan2(dy,dx);                 % panel angle from x-axis
    nx =  sin(phi); ny = -cos(phi);     % outward normal (assuming CCW ordering)
    tx =  cos(phi); ty =  sin(phi);     % unit tangent

    panels = struct('xb',xb,'yb',yb,'xe',xe,'ye',ye,'xc',xc,'yc',yc, ...
                    'S',S,'phi',phi,'nx',nx,'ny',ny,'tx',tx,'ty',ty);
end

function [sigma, Vt, Cp, xcp, ycp, Vx, Vy] = source_panel_solve(panels, Uinf, alpha)
    N = numel(panels.S);

    % Influence matrices for normal velocity at collocation points
    An = zeros(N); RHS = zeros(N,1);

    for i=1:N % collocation i
        xi = panels.xc(i); yi = panels.yc(i);
        nx = panels.nx(i); ny = panels.ny(i);

        for j=1:N % panel j as source panel
            [Ixn, Iyn] = source_panel_influence_normal(xi, yi, panels, j);
            An(i,j) = Ixn*nx + Iyn*ny; % normal component from unit-strength source density on panel j
        end

        % RHS = - freestream normal velocity at point i
        U = Uinf*cos(alpha); V = Uinf*sin(alpha);
        RHS(i) = -(U*nx + V*ny);
    end

    % Enforce zero-net source for closed body (optional, usually redundant)
    % Not enforced here explicitly since formulation with collocation suffices.

    % Solve for source strengths (constant per panel)
    sigma = An\RHS;

    % Tangential velocity along each collocation point
    Vt = zeros(N,1); Vx = zeros(N,1); Vy = zeros(N,1);
    for i=1:N
        U = Uinf*cos(alpha); V = Uinf*sin(alpha);
        ui = U; vi = V; % start with freestream
        for j=1:N
            [Ix, Iy] = source_panel_influence_total(panels.xc(i), panels.yc(i), panels, j);
            ui = ui + sigma(j)*Ix; vi = vi + sigma(j)*Iy;
        end
        % Tangential component
        Vt(i) = ui*panels.tx(i) + vi*panels.ty(i);
        Vx(i) = ui; Vy(i) = vi;
    end

    % Pressure coefficient
    Vmag = hypot(Vx, Vy);
    Cp = 1 - (Vmag./Uinf).^2;

    xcp = panels.xc; ycp = panels.yc;
end

function [Ixn, Iyn] = source_panel_influence_normal(x, y, panels, j)
    % Return velocity at (x,y) due to unit-strength source distributed uniformly
    % over panel j, then extract its components (Ixn, Iyn) directly.
    [Ix, Iy] = source_panel_influence_total(x, y, panels, j);
    Ixn = Ix; Iyn = Iy;
end

function [Ix, Iy] = source_panel_influence_total(x, y, panels, j)
    % Standard logarithmic/atan influence of a constant-strength source panel
    xj1 = panels.xb(j); yj1 = panels.yb(j);
    xj2 = panels.xe(j); yj2 = panels.ye(j);

    % Transform to panel-local coordinates
    phi = panels.phi(j);
    cosT = cos(phi); sinT = sin(phi);

    % Shift and rotate point into panel frame
    xrel = (x - xj1)*cosT + (y - yj1)*sinT;
    yrel = -(x - xj1)*sinT + (y - yj1)*cosT;

    Sj = panels.S(j);

    % Avoid singularities
    epsy = 1e-12;
    yrel = sign(yrel).*max(abs(yrel), epsy);

    % Endpoints in local x
    x1 = 0; x2 = Sj;

    % Analytical integrals for constant-strength source panel (per unit strength)
    % Velocity in local frame (u_loc, v_loc)
    r1 = hypot(xrel - x1, yrel);
    r2 = hypot(xrel - x2, yrel);
    theta1 = atan2(yrel, xrel - x1);
    theta2 = atan2(yrel, xrel - x2);

    u_loc = (1/(2*pi)) * log(r2./r1);
    v_loc = (1/(2*pi)) * (theta2 - theta1);

    % Rotate back to global frame
    Ix =  u_loc*cosT - v_loc*sinT;
    Iy =  u_loc*sinT + v_loc*cosT;
end

function L = path_length(P)
    L = sum(hypot(diff(P(:,1)), diff(P(:,2))));
end

function val = input_with_default(prompt, defaultVal, validator)
    if nargin<3, validator = @(x) true; end
    str = input(prompt,'s');
    if isempty(str)
        val = defaultVal; return;
    end
    tmp = str2num(str); %#ok<ST2NM>
    if isempty(tmp)
        warning('Invalid input. Using default: %g', defaultVal);
        val = defaultVal; return;
    end
    if ~validator(tmp)
        warning('Input failed validation. Using default: %g', defaultVal);
        val = defaultVal; return;
    end
    val = tmp;
end

function area = polygon_area(P)
    if norm(P(1,:)-P(end,:))>1e-12, P=[P; P(1,:)]; end
    area = 0.5*sum(P(1:end-1,1).*P(2:end,2) - P(2:end,1).*P(1:end-1,2));
end

function [isCircle, xc, yc, R] = detect_circle(P)
    % Roughly detect circle by fitting center and radius via least squares.
    if norm(P(1,:)-P(end,:))>1e-12, P=[P; P(1,:)]; end
    Pc = P(1:end-1,:);
    x = Pc(:,1); y = Pc(:,2);
    A = [2*x, 2*y, ones(size(x))];
    b = x.^2 + y.^2;
    sol = A\b;
    xc = sol(1); yc = sol(2); c = sol(3);
    R = sqrt(max(1e-12, xc^2 + yc^2 + c));
    % Assess circularity by radius variance
    r = hypot(x - xc, y - yc);
    cv = std(r)/mean(r);
    isCircle = cv < 0.02; % 2% variation threshold
end

function G = trapz_along_panels(panels, Vt)
    % Approximate circulation integral Γ = ∮ V · dl = ∑ Vt_i * S_i
    G = sum(Vt(:) .* panels.S(:));
end

Below is a self-contained, structured MATLAB implementation of a 2-D source panel method. It reads panel points from a text file, prompts the user for flow conditions, computes pressure coefficients and lift via Kutta–Joukowski, and includes optional comparison against an analytical circular-cylinder solution when applicable. It also varies the number of panels (via resampling) to report accuracy trends. Save all functions in one file (script with local functions) or separate files as desired.

% ============================
% File: run_source_panel.m
% ============================
function run_source_panel()
    clc; clear; close all;

    fprintf('2-D Source Panel Method (MATLAB)\n');
    fprintf('--------------------------------\n');

    % --- Input: panel points file ---
    defaultFile = 'airfoil_points.txt';
    ptsFile = input(sprintf('Enter panel points filename (default: %s): ', defaultFile), 's');
    if isempty(strtrim(ptsFile))
        ptsFile = defaultFile;
    end

    % --- Read geometry points (x,y) from text file ---
    try
        P = readPointsFromFile(ptsFile); % Nx2
    catch ME
        fprintf(2, 'Error reading file: %s\n', ME.message);
        return;
    end

    % --- Flow conditions ---
    Vinf = inputWithDefault('Enter free-stream speed Vinf [m/s] (default 1): ', 1.0, @(v)isnumeric(v)&&isscalar(v)&&v>0);
    alpha_deg = inputWithDefault('Enter angle of attack alpha [deg] (default 0): ', 0.0, @(v)isnumeric(v)&&isscalar(v));
    rho = inputWithDefault('Enter fluid density rho [kg/m^3] (default 1.225): ', 1.225, @(v)isnumeric(v)&&isscalar(v)&&v>0);

    % --- Options for accuracy study ---
    doAccuracy = inputWithDefault('Run accuracy study over multiple panel counts? 1=yes,0=no (default 1): ', 1, @(v)isscalar(v)&&(v==0||v==1));

    % Ensure geometry is closed and ordered counter-clockwise
    P = ensureClosedCCW(P);

    % Baseline run with provided discretization
    fprintf('\nRunning source panel solution on provided geometry (N=%d panels)...\n', size(P,1)-1);
    result = sourcePanelSolve(P, Vinf, deg2rad(alpha_deg));
    reportResults(result, rho, Vinf);

    % Optional comparison with analytical solution (circular cylinder)
    compareAnalyticalIfCylinder(result, Vinf, alpha_deg, rho);

    % Accuracy study by resampling geometry to multiple N
    if doAccuracy
        Ns = inputWithDefault('Enter vector of panel counts as [64 128 256] (leave empty for default): ', [], @(v)isnumeric(v));
        if isempty(Ns)
            Ns = [64 128 256];
        end
        fprintf('\nAccuracy study over N = %s\n', mat2str(Ns));
        ref = result; % treat current as reference for convergence indicator if no analytic
        doCylinder = isApproxCircle(result.geom);
        if doCylinder
            cyl = fitCircle(result.geom);
        end
        accTbl = zeros(numel(Ns), 5); % [N, CL, CL_err, maxCpErr, L2CpErr]
        for i = 1:numel(Ns)
            Ni = Ns(i);
            Pi = resampleClosedPolyline(P, Ni);
            Ri = sourcePanelSolve(Pi, Vinf, deg2rad(alpha_deg));
            if doCylinder
                [Cp_ana, sAna] = analyticalCpCylinder(Ri); %#ok<ASGLU>
                % Map numerical Cp to analytical arclength sampling
                [maxErr, L2Err] = cpErrorVsAnalytical(Ri, Cp_ana);
                CL_err = abs(Ri.CL - 0); % Cylinder has zero lift for pure source panel w/o circulation
            else
                % Compare to baseline via interpolation along s/L
                [maxErr, L2Err] = cpErrorVsReference(Ri, ref);
                CL_err = abs(Ri.CL - ref.CL);
            end
            accTbl(i,:) = [Ni, Ri.CL, CL_err, maxErr, L2Err];
        end
        fprintf('\nAccuracy summary (N, CL, |CL-CL_ref| or |CL-CL_ana|, max|dCp|, L2|dCp|):\n');
        disp(accTbl);
    end

    fprintf('\nDone.\n');
end

