% ----------------------------------------
% Read points (x y per line) with validation
% ----------------------------------------
function P = readPointsFromFile(fname)
    if ~isfile(fname)
        error('File not found: %s', fname);
    end
    data = readmatrix(fname);
    if size(data,2) < 2
        error('File must contain at least two columns (x y).');
    end
    P = data(:,1:2);
    if any(~isfinite(P), 'all')
        error('Non-finite values found in point file.');
    end
    % Remove duplicates in sequence except allow closure duplicate
    if norm(P(1,:)-P(end,:),2) < 1e-12
        P = uniqueClose(P);
    end
end

function P = uniqueClose(P)
    % Keep first point, remove immediate duplicates except final closure
    Q = P(1,:);
    for i=2:size(P,1)-1
        if norm(P(i,:)-Q(end,:),2) > 1e-12
            Q = [Q; P(i,:)]; %#ok<AGROW>
        end
    end
    if norm(Q(1,:)-P(end,:),2) > 1e-12
        Q = [Q; Q(1,:)];
    else
        Q = [Q; Q(1,:)];
    end
    P = Q;
end

% ------------------------
% Ensure closed and CCW
% ------------------------
function P = ensureClosedCCW(P)
    if norm(P(1,:)-P(end,:),2) > 1e-12
        P = [P; P(1,:)];
    end
    A = polyarea(P(:,1), P(:,2));
    if A < 0 % CW
        P = flipud(P);
    end
end

% --------------------------------------
% Resample closed polyline to N panels
% --------------------------------------
function Pn = resampleClosedPolyline(P, Npan)
    % P is closed (first=last). Output closed with Npan panels (Npan+1 points)
    s = [0; cumsum(vecnorm(diff(P),2,2))];
    L = s(end);
    s_target = linspace(0,L,Npan+1)';
    x = interp1(s, P(:,1), s_target, 'linear');
    y = interp1(s, P(:,2), s_target, 'linear');
    Pn = [x y];
    Pn(end,:) = Pn(1,:); % ensure closure
    Pn = ensureClosedCCW(Pn);
end

% -------------------------------------
% Core Source Panel Solver (no vortex)
% -------------------------------------
function R = sourcePanelSolve(P, Vinf, alpha)
    % Inputs:
    %   P: (N+1)x2 closed polygon vertices CCW
    %   Vinf: free-stream speed
    %   alpha: angle of attack (radians)
    % Output struct R with fields:
    %   geom, N, xc,yc, phi, S, nx,ny, tx,ty, sigma, Vt, Cp, CL

    N = size(P,1)-1; % panels
    % Panel geometry
    x = P(:,1); y = P(:,2);
    dx = x(2:end)-x(1:end-1);
    dy = y(2:end)-y(1:end-1);
    S = hypot(dx,dy);
    tx = dx./S; ty = dy./S;
    nx =  ty; ny = -tx; % outward normal for CCW polygon

    xc = 0.5*(x(1:end-1)+x(2:end));
    yc = 0.5*(y(1:end-1)+y(2:end));

    % Free-stream components
    Uinf = Vinf*cos(alpha);
    Vinfv = Vinf*sin(alpha);

    % Influence coefficients for source panels (2D)
    A = zeros(N,N);
    RHS = - (Uinf*nx + Vinfv*ny); % normal velocity to cancel on surface

    for i = 1:N
        for j = 1:N
            [I, J] = panelInfluence(x(j),y(j), x(j+1),y(j+1), xc(i),yc(i), tx(j),ty(j), nx(i),ny(i));
            % Normal velocity induced by unit-strength source panel j at i
            A(i,j) = I; % I already returns normal influence
        end
    end

    % Enforce zero net source (closed body) to avoid singularity
    % Replace last equation with sum(sigma*S)=0
    A_aug = [A; S'];
    RHS_aug = [RHS; 0];

    % Add compatibility column for strength sum (no extra unknowns needed):
    % Solve least-squares with constraint via normal equations
    % Better: replace last row of A with S' and solve square system
    A2 = A_aug(1:end-1,:);
    RHS2 = RHS_aug(1:end-1);
    A2(end,:) = S';
    RHS2(end) = 0;

    sigma = A2\RHS2; % panel source strengths per unit length

    % Tangential velocity on surface: Vt = Vt_inf + induced_tangential
    Vt = (Uinf*tx + Vinfv*ty); % initialize with free-stream tangential
    for i = 1:N
        for j = 1:N
            [~, Jt] = panelInfluenceTangential(x(j),y(j), x(j+1),y(j+1), xc(i),yc(i), tx(j),ty(j), tx(i),ty(i));
            Vt(i) = Vt(i) + sigma(j)*Jt;
        end
    end

    Cp = 1 - (Vt./Vinf).^2;

    % Compute lift via Kutta-Joukowski: CL = 2*Gamma/(Vinf*c)
    % Pure source-panel on closed body gives zero net circulation (Gamma=0)
    % Numerically, approximate Gamma by integral of tangential velocity deficit
    % around body; for thickness bodies this tends to ~0.
    Gamma = trapz( (Vt - (Uinf*tx + Vinfv*ty)) .* S );

    % Reference length: chord if detectable, else projected max x-span
    c = max(x)-min(x);
    if c <= 0
        c = sum(S); % fallback
    end
    CL = 2*Gamma/(Vinf*c);

    R = struct();
    R.geom.P = P; R.geom.S = S; R.geom.tx=tx; R.geom.ty=ty; R.geom.nx=nx; R.geom.ny=ny;
    R.N=N; R.xc=xc; R.yc=yc; R.sigma=sigma; R.Vt=Vt; R.Cp=Cp; R.CL=CL; R.alpha=alpha;
end

% -----------------------------------------------------
% Panel influence: returns normal and tangential kernels
% -----------------------------------------------------
function [In, Jn] = panelInfluence(x1,y1,x2,y2, xP,yP, tx,ty, nx,ny)
    % Transform field point to panel-local coordinates
    Rx = xP - x1; Ry = yP - y1;
    % Local axes: t=(tx,ty), n=(ty,-tx) outward for this panel orientation
    t = [tx ty]; n = [ty -tx];
    x_local = Rx*t(1) + Ry*t(2);
    y_local = Rx*n(1) + Ry*n(2);
    % Panel length
    L = hypot(x2-x1, y2-y1);
    % Analytical integrals for 2D source panel (normal velocity at control)
    % Using standard formulas (Katz & Plotkin)
    eps = 1e-12;
    x2l = x_local - L; x1l = x_local;
    theta1 = atan2(y_local, x1l+eps);
    theta2 = atan2(y_local, x2l+eps);
    lnTerm = 0.5*log(((x2l).^2 + y_local.^2 + eps)/((x1l).^2 + y_local.^2 + eps));
    % Induced velocities components in local frame by unit source strength
    u_t = (theta2 - theta1)/(2*pi);
    u_n = (-lnTerm)/(2*pi);
    % Project to global normal at the control point (nx,ny)
    ug = u_t*t + u_n*n;
    In = ug(1)*nx + ug(2)*ny; % normal influence
    Jn = []; % not used here
end

function [It, Jt] = panelInfluenceTangential(x1,y1,x2,y2, xP,yP, tx,ty, tix,tiy)
    % Compute tangential induced velocity at control i due to unit source panel j
    Rx = xP - x1; Ry = yP - y1;
    t = [tx ty]; n = [ty -tx];
    x_local = Rx*t(1) + Ry*t(2);
    y_local = Rx*n(1) + Ry*n(2);
    L = hypot(x2-x1, y2-y1);
    eps = 1e-12;
    x2l = x_local - L; x1l = x_local;
    theta1 = atan2(y_local, x1l+eps);
    theta2 = atan2(y_local, x2l+eps);
    lnTerm = 0.5*log(((x2l).^2 + y_local.^2 + eps)/((x1l).^2 + y_local.^2 + eps));
    u_t = (theta2 - theta1)/(2*pi);
    u_n = (-lnTerm)/(2*pi);
    ug = u_t*t + u_n*n;
    ti = [tix tiy];
    It = []; %#ok<NASGU>
    Jt = dot(ug, ti); % tangential influence
end

% --------------------------------------------------
% Reporting, plots, comparisons
% --------------------------------------------------
function reportResults(R, rho, Vinf)
    Cp = R.Cp; s = cumulativeS(R.geom);
    fprintf('Panels: %d\n', R.N);
    fprintf('Lift coefficient (Kutta-Joukowski estimate): CL = %.6f\n', R.CL);
    fprintf('Cp range: [%.4f, %.4f]\n', min(Cp), max(Cp));

    figure('Name','Geometry'); axis equal; hold on; grid on;
    plot(R.geom.P(:,1), R.geom.P(:,2), '-k');
    quiver(R.xc, R.yc, R.geom.nx, R.geom.ny, 0.2, 'r'); title('Geometry and normals');

    figure('Name','Cp distribution'); grid on; hold on;
    plot(s/s(end), Cp, '-o'); set(gca,'YDir','reverse');
    xlabel('s/L'); ylabel('C_p'); title('Surface pressure coefficient');

    % Report circulation-based lift per unit span (KJ): L' = rho*Vinf*Gamma
    Utx = R.geom.tx; Uty = R.geom.ty;
    Vt_inf = (Vinf*cos(R.alpha)*Utx + Vinf*sin(R.alpha)*Uty);
    Gamma = trapz( (R.Vt - Vt_inf).*R.geom.S );
    Lprime = rho*Vinf*Gamma;
    fprintf('Circulation Gamma = %.6e, Lift per unit span L'' = %.6e N/m\n', Gamma, Lprime);
end

function s = cumulativeS(G)
    s = [0; cumsum(G.S(:))];
end

% Attempt analytical comparison for circular cylinder
function compareAnalyticalIfCylinder(R, Vinf, alpha_deg, rho)
    if ~isApproxCircle(R.geom)
        fprintf('No analytical Cp comparison (geometry not detected as circle).\n');
        return;
    end
    [CpA, theta] = analyticalCpCylinder(R);
    % Map numerical Cp by panel angle
    thNum = atan2(R.yc - mean(R.geom.P(1:end-1,2)), R.xc - mean(R.geom.P(1:end-1,1)));
    % Sort for plotting
    [thNumS, idx] = sort(mod(thNum, 2*pi));
    CpNumS = R.Cp(idx);

    figure('Name','Cp vs Analytical (Cylinder)'); hold on; grid on; set(gca,'YDir','reverse');
    plot(theta, CpA, 'k-', 'DisplayName','Analytical');
    plot(thNumS, CpNumS, 'ro', 'DisplayName','Numerical');
    xlabel('\theta [rad]'); ylabel('C_p'); legend; title('Cp comparison (cylinder)');

    [maxErr, L2Err] = cpErrorVsAnalytical(R, CpA);
    fprintf('Analytical Cp (cylinder) errors: max|dCp|=%.4e, L2|dCp|=%.4e\n', maxErr, L2Err);

    % Analytical lift for non-circulatory cylinder: CL = 0
    fprintf('Analytical CL (cylinder, no circulation) = 0. Numerical CL = %.6f\n', R.CL);
end

function tf = isApproxCircle(G)
    % Fit circle and test residual
    c = fitCircle(G);
    r = hypot(G.P(1:end-1,1)-c(1), G.P(1:end-1,2)-c(2));
    tf = std(r)/mean(r) < 0.02; % 2% thickness criterion
end

function c = fitCircle(G)
    X = G.P(1:end-1,1); Y = G.P(1:end-1,2);
    A = [-2*X, -2*Y, ones(size(X))]; b = -(X.^2 + Y.^2);
    sol = A\b; cx = sol(1); cy = sol(2); c0 = sol(3);
    r = sqrt(cx^2 + cy^2 - c0);
    c = [cx cy r];
end

function [CpA, theta] = analyticalCpCylinder(R)
    % Inviscid potential flow around cylinder without circulation
    % Cp(theta) = 1 - 4 sin^2(theta - alpha)
    G = R.geom; c = fitCircle(G);
    theta = linspace(0, 2*pi, max(200, R.N))';
    CpA = 1 - 4*(sin(theta - R.alpha)).^2;
end

function [maxErr, L2Err] = cpErrorVsAnalytical(R, CpA)
    % Interpolate numerical Cp by theta for comparison
    cx = mean(R.geom.P(1:end-1,1)); cy = mean(R.geom.P(1:end-1,2));
    th = mod(atan2(R.yc - cy, R.xc - cx), 2*pi);
    [thS, idx] = sort(th);
    CpN = R.Cp(idx); thS = [thS; thS(1)+2*pi]; CpN = [CpN; CpN(1)];
    thq = linspace(0,2*pi, numel(CpA))';
    CpNi = interp1(thS, CpN, thq, 'linear');
    d = CpNi - CpA(:);
    maxErr = max(abs(d)); L2Err = sqrt(trapz((d).^2)/trapz(ones(size(d))));
end

function [maxErr, L2Err] = cpErrorVsReference(R, Ref)
    % Compare Cp as function of normalized arclength s/L
    sN = [0; cumsum(R.geom.S)]; sN = sN/sN(end);
    sR = [0; cumsum(Ref.geom.S)]; sR = sR/sR(end);
    CpNi = interp1((sN(1:end-1)+sN(2:end))/2, R.Cp, linspace(0,1,200), 'linear','extrap');
    CpRi = interp1((sR(1:end-1)+sR(2:end))/2, Ref.Cp, linspace(0,1,200), 'linear','extrap');
    d = CpNi - CpRi;
    maxErr = max(abs(d)); L2Err = sqrt(trapz(linspace(0,1,200), d.^2));
end

