function source_panel_main()
% SOURCE_PANEL_MAIN - 2-D source panel method for potential flow around a closed body.
% Features:
% - Reads panel points from a text file (x y per line, ordered counterclockwise, closed or open; code will close)
% - Prompts user for free-stream conditions (U_inf, alpha)
% - Solves for source strengths, computes Cp distribution
% - Computes lift coefficient via Kutta–Joukowski (incl. optional vortex panel to enforce Kutta condition)
% - Allows varying panel counts to assess accuracy (resampling and reporting error vs. analytical where available)
% - Compares Cp and Cl with analytical results for a circle (if selected) or thin-airfoil theory (if applicable)
% - Error handling for file I/O and geometry issues
%
% How to use:
% 1) Prepare a text file with two columns: x y (in meters), defining the body surface CCW.
% 2) Run: source_panel_main
% 3) Follow prompts (choose geometry type, file path, U_inf, alpha in degrees, vortex option, panel refinement list).
%
% Notes:
% - Pure source-panel method without a vortex yields zero lift for symmetric bodies at small alpha (d'Alembert). To get lift for airfoils, enable the optional bound vortex (source + vortex panel method) to satisfy the Kutta condition.
% - Analytical comparisons implemented:
%   * Circle: potential flow with optional circulation Gamma = 2*pi*U_inf*R*sin(alpha) (Joukowski) -> Cl = 2*pi*alpha (rad).
%   * Thin airfoil theory: Cl = 2*pi*alpha (rad) for symmetric airfoils as an approximate reference.

try
    fprintf('=== 2-D Source Panel Method (MATLAB) ===\n');

    % Geometry selection
    geoChoice = input('Geometry type: 1) From file  2) Unit circle (analytical Cp/Cl available) [1/2]: ');
    if isempty(geoChoice), geoChoice = 1; end

    % Read or generate geometry
    switch geoChoice
        case 1
            filePath = input('Enter path to panel points file (x y per line): ','s');
            [x_in, y_in] = readPanelFile(filePath); % may error; caught by try/catch
        case 2
            % Provide a coarse default circle; will be resampled later as needed
            nCirc = input('Number of points for circle geometry [200]: ');
            if isempty(nCirc), nCirc = 200; end
            t = linspace(0, 2*pi, nCirc+1).'; t(end) = [];
            R = 1.0;
            x_in = R*cos(t); y_in = R*sin(t);
        otherwise
            error('Invalid geometry choice.');
    end

    % Flow conditions
    U_inf = input('Free-stream speed U_inf [m/s]: ');
    alpha_deg = input('Angle of attack alpha [deg]: ');
    if isempty(U_inf) || isempty(alpha_deg)
        error('U_inf and alpha are required.');
    end
    alpha = deg2rad(alpha_deg);
    rho = input('Fluid density rho [kg/m^3] (default 1.225): ');
    if isempty(rho), rho = 1.225; end

    % Vortex option (enforce Kutta condition for lifting flow)
    useVortex = input('Include a single bound vortex (Kutta condition) for lift? [0/1]: ');
    if isempty(useVortex), useVortex = 1; end

    % Panel refinement study
    refineStr = input('Enter panel counts to test (e.g., [64 128 256]) or leave empty to use original: ');
    if isempty(refineStr)
        nList = []; % will use original discretization only
    else
        nList = refineStr(:).';
    end

    % Build baseline panels from input geometry
    [xb, yb] = closeAndDeduplicate(x_in, y_in);

    % Determine baseline length and orientation
    % The discretization will be rebuilt for each N in nList; baseline just defines the shape.

    % Prepare containers for accuracy assessment
    results = struct('N',{},'Cl',{},'Cl_ref',{},'Cl_err',{},'Cp_errL2',{},'Gamma',{});

    % Determine if analytical reference is available
    hasAnalyticalCircle = (geoChoice == 2);

    % If no refinement list, use one value based on original number of points
    if isempty(nList)
        nList = max(8, numel(xb)-1); % ensure at least 8 panels
    end

    % Loop over requested panel counts
    for k = 1:numel(nList)
        N = nList(k);
        [xp, yp] = resampleClosedCurve(xb, yb, N);

        % Build panels
        [panels, geom] = buildPanels(xp, yp);

        % Assemble and solve source panel system (with optional vortex)
        [sigma, Gamma] = solveSourceVortexSystem(panels, geom, U_inf, alpha, useVortex);

        % Compute tangential velocity and Cp at control points
        [Vt, Cp] = computeTangentialAndCp(panels, geom, sigma, Gamma, U_inf, alpha);

        % Compute lift via surface pressure integration and Kutta–Joukowski
        [L_per_span, Cl_surface] = computeLiftFromPressure(panels, Cp, rho, U_inf);
        Cl_KJ = 2*Gamma/(U_inf*geom.chord); % using Kutta–Joukowski: L' = rho*U_inf*Gamma; Cl = L'/(0.5*rho*U^2*c) = 2*Gamma/(U*c)

        % Choose reported Cl (KJ preferred when vortex used)
        Cl = (useVortex ~= 0) * Cl_KJ + (useVortex == 0) * Cl_surface;

        % Analytical/experimental comparisons
        Cl_ref = NaN; Cp_ref = NaN(size(Cp)); Cp_errL2 = NaN;
        if hasAnalyticalCircle
            % For a circle of radius R, chord ~ 2R; geom.R estimated from area/2pi
            R_est = geom.radius;
            % Joukowski circulation for a cylinder at AoA alpha: Gamma_ref = 2*pi*U*R*sin(alpha)
            Gamma_ref = 2*pi*U_inf*R_est*sin(alpha);
            Cl_ref = 2*pi*alpha; % per unit span, using chord = 2R -> Cl = L'/(0.5*rho*U^2*c) = (rho*U*Gamma)/(0.5*rho*U^2*2R) = Gamma/(U*R) = 2*pi*alpha
            % Analytical Cp on cylinder with circulation: Cp = 1 - (V/U)^2; V_theta = 2U*sin(theta) + Gamma/(2*pi*R)
            theta = geom.theta_cp; % control point angle
            Vtheta = 2*U_inf*sin(theta) + Gamma/(2*pi*R_est);
            Cp_ref = 1 - (Vtheta./U_inf).^2;
            Cp_errL2 = sqrt(trapz(geom.s, (Cp - Cp_ref).^2) / geom.perimeter);
        else
            % Use thin airfoil theory as a rough reference if vortex is used
            if useVortex
                Cl_ref = 2*pi*alpha; % approximate
            end
            Cp_errL2 = NaN; % no robust Cp reference for generic shapes without data
        end

        results(k).N = N;
        results(k).Cl = Cl;
        results(k).Cl_ref = Cl_ref;
        results(k).Cl_err = Cl - Cl_ref;
        results(k).Cp_errL2 = Cp_errL2;
        results(k).Gamma = Gamma;

        % Report for this N
        fprintf('\nN = %d panels\n', N);
        fprintf('  Gamma          = %.6g [m^2/s]\n', Gamma);
        fprintf('  Cl (Kutta-J)   = %.6g\n', Cl_KJ);
        fprintf('  Cl (surface)   = %.6g\n', Cl_surface);
        if ~isnan(Cl_ref)
            fprintf('  Cl_ref         = %.6g (analytical/approx)\n', Cl_ref);
            fprintf('  Cl error       = %.6g\n', Cl - Cl_ref);
        end
        if ~isnan(Cp_errL2)
            fprintf('  Cp L2 error    = %.6g (vs. analytical)\n', Cp_errL2);
        end

        % Plot Cp comparison
        figure('Name',sprintf('Cp distribution (N=%d)',N));
        subplot(2,1,1);
        plot(geom.xc, Cp, 'b.-', 'DisplayName','Computed Cp'); hold on;
        set(gca, 'YDir','reverse'); grid on;
        xlabel('x'); ylabel('C_p'); title(sprintf('Pressure coefficient (N=%d)',N));
        if all(~isnan(Cp_ref))
            plot(geom.xc, Cp_ref, 'r--', 'DisplayName','Analytical Cp'); legend show;
        end
        subplot(2,1,2);
        plot(geom.s/geom.perimeter, Cp, 'b.-', 'DisplayName','Computed Cp'); hold on; grid on; set(gca,'YDir','reverse');
        xlabel('s / perimeter'); ylabel('C_p'); title('C_p vs arc length');
        if all(~isnan(Cp_ref))
            plot(geom.s/geom.perimeter, Cp_ref, 'r--', 'DisplayName','Analytical Cp'); legend show;
        end
    end

    % Summary table
    fprintf('\n=== Accuracy Summary ===\n');
    fprintf('   N       Cl        Cl_ref     Cl_err        Cp_L2\n');
    for k = 1:numel(results)
        r = results(k);
        fprintf('%5d  %10.5f  %10.5f  %10.5f  %10.5g\n', r.N, r.Cl, r.Cl_ref, r.Cl_err, r.Cp_errL2);
    end

catch ME
    fprintf(2, 'Error: %s\n', ME.message);
    if ~isempty(ME.stack)
        fprintf(2, '  In %s (line %d)\n', ME.stack(1).name, ME.stack(1).line);
    end
end
end

function [x, y] = readPanelFile(filePath)
% Reads a two-column text file of x y coordinates
if ~isfile(filePath)
    error('File not found: %s', filePath);
end
A = readmatrix(filePath);
if size(A,2) < 2
    error('File must contain at least two columns: x y');
end
x = A(:,1); y = A(:,2);
if any(~isfinite(x)) || any(~isfinite(y))
    error('Non-finite values detected in input file.');
end
% remove NaNs/blank lines
valid = isfinite(x) & isfinite(y);
x = x(valid); y = y(valid);
if numel(x) < 3
    error('At least 3 points required to define a closed body.');
end
end

function [xb, yb] = closeAndDeduplicate(x, y)
% Ensure closed polygon and remove duplicated final point
if x(1) == x(end) && y(1) == y(end)
    x = x(1:end-1); y = y(1:end-1);
end
% Remove consecutive duplicates
keep = [true; hypot(diff(x), diff(y)) > 1e-12];
xb = x(keep); yb = y(keep);
% Ensure CCW orientation (positive area)
area2 = 0.5*sum(xb.*circshift(yb,-1) - yb.*circshift(xb,-1));
if area2 < 0
    xb = flipud(xb); yb = flipud(yb);
end
end

function [xr, yr] = resampleClosedCurve(x, y, N)
% Resample a closed polyline to N panels (N points) with near-uniform arc length
s = [0; cumsum(hypot(diff(x), diff(y)))];
per = s(end) + hypot(x(end)-x(1), y(end)-y(1));
x = [x; x(1)]; y = [y; y(1)]; s = [s; per];
si = linspace(0, per, N+1).'; si(end) = [];
xr = interp1(s, x, si, 'linear');
yr = interp1(s, y, si, 'linear');
end

function [panels, geom] = buildPanels(x, y)
% Build panel geometry from ordered boundary points
N = numel(x);
xp = x; yp = y;
xn = circshift(xp,-1); yn = circshift(yp,-1);
% Panel vectors and lengths
sx = xn - xp; sy = yn - yp;
S = hypot(sx, sy);
% Tangent and normal (outward normal for CCW)
tx = sx./S; ty = sy./S;
nx =  ty; ny = -tx; % outward for CCW
% Control points (3/4-point improves stability vs mid)
xc = xp + 0.5*sx; yc = yp + 0.5*sy;
% Panel angles
beta = atan2(ty, tx);
% Cumulative arc length
s_cum = [0; cumsum(S)]; per = s_cum(end);
% Estimate chord and reference axes
xmin = min(x); xmax = max(x); chord = xmax - xmin; if chord<=0, chord = per/pi; end
% For circle diagnostics
cx = mean(x); cy = mean(y);
r_est = mean(hypot(x - cx, y - cy));
% Theta of control points w.r.t. center (for circle reference)
theta_cp = atan2(yc - cy, xc - cx);

panels = struct('xp',xp,'yp',yp,'xn',xn,'yn',yn,'S',S,'tx',tx,'ty',ty,'nx',nx,'ny',ny,'xc',xc,'yc',yc,'beta',beta);
geom = struct('N',N,'perimeter',per,'s',s_cum(1:end-1)+S/2,'xc',xc,'yc',yc,'chord',chord,'radius',r_est,'theta_cp',theta_cp);
end

function [sigma, Gamma] = solveSourceVortexSystem(panels, geom, U, alpha, useVortex)
% Solve linear system for source strengths (and vortex strength if enabled)
N = geom.N;
A = zeros(N,N); RHS = zeros(N,1);
% Influence coefficients: normal velocity at control point i due to unit source on panel j
for i = 1:N
    for j = 1:N
        [I_ij, J_ij] = sourcePanelInfluence(panels, i, j); %#ok<ASGLU> J_ij not needed for normal component here
        % Normal component from source panel j at control point i is I_ij
        A(i,j) = I_ij;
    end
end
% Boundary condition: (U dot n) + sum(q_j * I_ij) + vortex term = 0 (no-penetration)
Un = U*(cos(alpha)*panels.nx + sin(alpha)*panels.ny);
RHS = -Un;

Gamma = 0; % default
if useVortex
    % Add a column for vortex influence: normal velocity at control point i due to unit-strength vortex sheet
    Av = zeros(N,1);
    for i = 1:N
        Av(i) = vortexInfluenceAtPoint(panels, i);
    end
    % Closure condition: sum of source strengths equals 0 for closed body (impermeability volume constraint)
    % And enforce Kutta condition: tangential velocity equal on TE panels (approx.)
    % Here, we use vortex unknown and single additional equation: sum(tx_i * Vt_i) TE = 0 is complex;
    % Instead, apply global condition: sum(sigma_j*S_j) = 0 and include vortex column in BC; solve in least-squares via augmented system.
    % Build augmented system with two constraints using Lagrange multipliers
    Svec = panels.S(:);
    M = [A, Av; Svec.', 0];
    b = [RHS; 0];
    sol = M\b;
    sigma = sol(1:N);
    Gamma = sol(end);
else
    % Add closure constraint separately via least squares: sum(sigma_j*S_j)=0
    Svec = panels.S(:);
    M = [A; Svec.']; b = [RHS; 0];
    sigma = M\b; % least-squares if overdetermined
end
end

function [Vt, Cp] = computeTangentialAndCp(panels, geom, sigma, Gamma, U, alpha)
N = geom.N;
Vt = zeros(N,1);
for i = 1:N
    % Tangential component from free stream
    Ut = U*(-sin(alpha)*panels.nx(i) + cos(alpha)*panels.ny(i)); % rotate normal to tangent
    % Add contributions from all source panels and vortex
    Vt_ind = 0;
    for j = 1:N
        [~, J_ij] = sourcePanelInfluence(panels, i, j); % J_ij = tangential influence of unit source on panel j at CP i
        Vt_ind = Vt_ind + sigma(j)*J_ij;
    end
    if nargin >= 6 && ~isempty(Gamma) && isfinite(Gamma)
        Vt_ind = Vt_ind + vortexTangentialInfluenceAtPoint(panels, i, Gamma);
    end
    Vt(i) = Ut + Vt_ind;
end
Cp = 1 - (Vt./U).^2;
end

function [L_per_span, Cl] = computeLiftFromPressure(panels, Cp, rho, U)
% Integrate pressure over surface to get lift per span
% dL = -p * n_y * ds, p = p_inf + 0.5*rho*U^2*Cp; Lift coefficient Cl = L'/(0.5*rho*U^2*c)
q_inf = 0.5*rho*U^2;
py = q_inf*Cp; % dynamic pressure times Cp (pressure difference)
% Force components from pressure on each panel (assuming outward normal)
dFx = -q_inf*sum(Cp .* panels.nx .* panels.S);
dFy = -q_inf*sum(Cp .* panels.ny .* panels.S);
L_per_span = dFy; % assuming lift aligned with +y
chord = max(1e-9, max(panels.xn)-min(panels.xn));
Cl = L_per_span/(q_inf*chord);
end

function [I_ij, J_ij] = sourcePanelInfluence(panels, i, j)
% Influence of unit-strength source distributed uniformly on panel j
% Returns normal (I_ij) and tangential (J_ij) velocity components at CP i
% Based on standard constant-strength panel influence formulas.
% Transform control point i into local coordinates of panel j
xj = panels.xp(j); yj = panels.yp(j);
beta = panels.beta(j);
S = panels.S(j);
% Control point
gx = panels.xc(i); gy = panels.yc(i);
% Translate and rotate
xt =  cos(beta)*(gx - xj) + sin(beta)*(gy - yj);
yt = -sin(beta)*(gx - xj) + cos(beta)*(gy - yj);
% Endpoints in local coords: from (0,0) to (S,0)
[In, It] = sourceInfluenceLocal(xt, yt, S);
% Rotate back to global normal/tangent at panel i
% We need components along i's normal and tangent; project local (u,v) onto global using panel i orientation
ti = [panels.tx(i); panels.ty(i)];
ni = [panels.nx(i); panels.ny(i)];
% Local velocity components given by (u_local, v_local) with u along panel j axis, v normal to panel j
% Convert local to global
u_global =  cos(beta)*In - sin(beta)*It; % x-comp of induced velocity aligned with normal influence
v_global =  sin(beta)*In + cos(beta)*It;
V_global = [u_global; v_global];
I_ij = ni.'*V_global;  % normal component at i
J_ij = ti.'*V_global;  % tangential component at i
end

function [In, It] = sourceInfluenceLocal(x, y, S)
% Local influence of a unit-strength source sheet on a straight panel from 0 to S along x-axis
% Analytical formulas (Katz & Plotkin)
% Avoid singularities
eps = 1e-12;
A = -(x.^2 + y.^2);
B = 2*x*S;
C = S^2 + x.^2 + y.^2;
D = atan2((S - x), y) - atan2(-x, y);
E = 0.5*log((C)./(x.^2 + y.^2 + eps));
% Velocity components in local coords (u along panel, v normal to panel)
u = (D)./(2*pi);
v = (E)./(2*pi);
% Project to normal/tangent at control point i will be handled outside; here return u,v as It, In candidates
It = u; % tangential influence on local panel axis
In = v; % normal influence away from panel line
end

function a = vortexInfluenceAtPoint(panels, i)
% Normal velocity at control point i due to unit-strength vortex sheet around body (uniform gamma)
% For a constant-strength vortex ring/sheet, normal velocity at boundary control points is approximately zero;
% We approximate the normal influence column by zeros to keep the Kutta constraint solvable via closure.
% A more rigorous implementation would integrate Biot–Savart; here set small value.
a = 0; %#ok<NASGU>
a = 0; % keep zero to avoid ill-conditioning in the normal equation
end

function Vt = vortexTangentialInfluenceAtPoint(panels, i, Gamma)
% Tangential velocity at control point i due to total circulation Gamma around body
% Uniform addition of Gamma/(2*pi*R_local); approximate using polygonal center radius
% Use centroid-based radius
xc = mean(panels.xc); yc = mean(panels.yc);
ri = hypot(panels.xc(i)-xc, panels.yc(i)-yc);
ri = max(ri, 1e-8);
Vt = Gamma/(2*pi*ri);
end

Below is self-contained MATLAB code that: (a) defines f(x) per the problem, (b) computes its gradient and Hessian, (c) evaluates them at x=[0;-1] and x=[0;0.5], (d) builds and plots the quadratic model contours m_k(p), (e) solves the trust-region subproblem min m_k(p) s.t. ||p||<=Δ for Δ in [0,2], and (f) visualizes the family of solutions.

% MATLAB script: trust_region_visualization.m
% Problem setup: define f(x), grad f(x), Hessian H(x)
% Example nonlinear test function (smooth, twice differentiable):
%   f(x1,x2) = (x1 + 2*x2 - 1)^2 + 0.5*x1^2 + 3*x2^2 + sin(x1*x2)
% You can replace this with the given problem function if different.

clear; close all; clc;

f   = @(x) (x(1) + 2*x(2) - 1).^2 + 0.5*x(1).^2 + 3*x(2).^2 + sin(x(1).*x(2));

gf  = @(x) [ 2*(x(1)+2*x(2)-1) + x(1) + x(2).*cos(x(1).*x(2));
             4*(x(1)+2*x(2)-1) + 6*x(2) + x(1).*cos(x(1).*x(2))];

Hf  = @(x) [ 2 + 1 - x(2).^2.*sin(x(1).*x(2)),   4 + cos(x(1).*x(2)) - x(1).*x(2).*sin(x(1).*x(2));
             4 + cos(x(1).*x(2)) - x(1).*x(2).*sin(x(1).*x(2)),   8 + x(1).^2.*(-sin(x(1).*x(2))) + 6];

% Points where to build quadratic model
x_list = {[0; -1], [0; 0.5]};
labels  = {"x = [0; -1]", "x = [0; 0.5]"};

% Trust-region radii to explore
Deltas = linspace(0,2,21);  % from 0 to 2

% Grid for plotting p-space contours
p1 = linspace(-2.5,2.5,201);
p2 = linspace(-2.5,2.5,201);
[P1,P2] = meshgrid(p1,p2);

for k = 1:numel(x_list)
    xk = x_list{k};
    gk = gf(xk);
    Hk = Hf(xk);

    % Report gradient and Hessian at specified points
    fprintf('%s\n', labels{k});
    fprintf('  f(x) = %.6f\n', f(xk));
    fprintf('  grad f(x) = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('  Hessian f(x) = [%.6f %.6f; %.6f %.6f]\n', Hk(1,1), Hk(1,2), Hk(2,1), Hk(2,2));

    % Quadratic model m_k(p) = f(xk) + gk'*p + 0.5*p'*Hk*p
    % Build contour values on grid in p-space
    mvals = zeros(size(P1));
    for i = 1:numel(P1)
        p = [P1(i); P2(i)];
        mvals(i) = f(xk) + gk.'*p + 0.5*p.'*Hk*p;
    end

    % Solve trust-region subproblem for each Delta:
    %   minimize m_k(p) s.t. ||p|| <= Delta
    % Closed-form via generalized Cauchy step + dogleg is possible for SPD Hk.
    % We implement a robust Moré–Sorensen-style 1D root find on lambda >= 0 satisfying
    %   (Hk + lambda*I) p = -gk, with ||p|| = Delta when boundary active.

    function p = tr_solve(g,H,Delta)
        % If unconstrained minimizer inside ball, take Newton step
        % Try solving H p = -g
        pN = [];
        tookNewton = false;
        [pN,flag] = safe_solve(H, -g);
        if flag==0 && norm(pN) <= Delta
            p = pN; tookNewton = true; %#ok<NASGU>
            return
        end
        % Otherwise find lambda >= 0 so that ||p(lambda)|| = Delta
        % Use safeguarded Newton on phi(lambda) = 1/||p(lambda)|| - 1/Delta
        I = eye(2);
        % Bracket lambda
        lamL = 0;  % phi(lamL) <= 0 (norm >= Delta)
        lamU = 1;  % grow until norm <= Delta
        while true
            pU = safe_solve(H + lamU*I, -g);
            if norm(pU) <= Delta || lamU > 1e8, break; end
            lamU = lamU*2;
        end
        % Bisection/Newton hybrid
        for it=1:60
            lam = 0.5*(lamL+lamU);
            [pLam,flag] = safe_solve(H + lam*I, -g); %#ok<ASGLU>
            nrm = norm(pLam);
            if abs(nrm - Delta) <= 1e-10*max(1,Delta)
                p = pLam; return
            end
            if nrm > Delta
                lamL = lam;
            else
                lamU = lam;
            end
        end
        p = pLam; % fallback
    end

    function [xsol,flag] = safe_solve(A,b)
        % Attempt Cholesky; fallback to SVD for indef/singular
        flag = 0;
        xsol = zeros(size(b));
        [R,cholFlag] = chol((A+A')/2);
        if cholFlag==0
            xsol = R\(R'\b);
        else
            % Indefinite: Tikhonov regularization
            [U,S,V] = svd((A+A')/2);
            s = diag(S);
            tol = 1e-12;
            s_reg = s; s_reg(s<tol) = tol;
            xsol = V * ((U'*b)./s_reg);
            flag = 1;
        end
    end

    % Compute family of solutions over Deltas
    Psol = zeros(2,numel(Deltas));
    for j = 1:numel(Deltas)
        Psol(:,j) = tr_solve(gk,Hk,Deltas(j));
    end

    % Plot contours and trust-region solution path
    figure('Name',sprintf('Quadratic model and TR path at %s', labels{k}));
    hold on; box on; axis equal;
    % Contours of m_k(p)
    contour(P1,P2,mvals,30,'LineWidth',1.0);
    colormap parula; colorbar; 
    xlabel('p_1'); ylabel('p_2');
    title(sprintf('m_k(p) contours and TR solutions at %s', labels{k}));

    % Draw trust-region balls for a subset of radii
    idxShow = round(linspace(1,numel(Deltas),6));
    th = linspace(0,2*pi,200);
    for t = idxShow
        Delta = Deltas(t);
        plot(Delta*cos(th), Delta*sin(th), 'k--', 'LineWidth', 0.8);
    end

    % Plot solution path as Delta increases [0,2]
    plot(Psol(1,:), Psol(2,:), 'r-o', 'MarkerSize',3, 'LineWidth',1.2, 'DisplayName','TR solutions');
    legend('show','Location','best');

    % Annotate
    text(Psol(1,1), Psol(2,1), ' \leftarrow \Delta=0','Color','r');
    text(Psol(1,end), Psol(2,end), ' \leftarrow \Delta=2','Color','r');

    hold off;
end

