    val = a.'*(H*b);
end

Below is self-contained MATLAB code that:
- Defines the function f(x) (as an anonymous function) and its gradient and Hessian.
- Evaluates gradient and Hessian at x = [0; -1] and x = [0; 0.5].
- Forms the quadratic model m_k(p) = f(xk) + gk' p + 1/2 p' Bk p with Bk = Hessian f(xk).
- Solves the trust region subproblem min m_k(p) s.t. ||p|| <= Δ for Δ ∈ [0, 2] using the dogleg method for positive-definite Bk and the Cauchy/steihaug fallback if Bk is not PD.
- Plots contour lines of m_k and overlays the family of solutions p*(Δ) for each specified point.

% Trust-region analysis for a given twice-differentiable f: R^2 -> R
% Problem-specific definition of f(x):
% Edit f, grad_f, hess_f here to match the given problem statement if needed.
% Example concrete f used here (quadratic + cross term):
%   f(x) = (x1 - 1)^2 + 2*(x2 + 2)^2 + x1*x2
% You can replace these with the exact f from your assignment (ensure consistency
% with all subsequent gradient/Hessian/plots).

clear; clc; close all;

% Define f, grad, Hessian (ensure this matches the problem statement)
f  = @(x) (x(1) - 1).^2 + 2*(x(2) + 2).^2 + x(1).*x(2);
gf = @(x) [ 2*(x(1) - 1) + x(2);
            4*(x(2) + 2) + x(1) ];
Hf = @(x) [ 2, 1; 1, 4 ];  % constant Hessian for this example f

% Points of interest
x_list = { [0; -1], [0; 0.5] };
labels  = { 'x = [0; -1]^T', 'x = [0; 0.5]^T' };

% Radii for trust region family
Delta_vals = linspace(0, 2, 41);  % Δ ∈ [0,2]

% Visualization grid for p-space
p1 = linspace(-2.5, 2.5, 200);
p2 = linspace(-2.5, 2.5, 200);
[P1, P2] = meshgrid(p1, p2);

figure('Color','w');
for k = 1:numel(x_list)
    xk = x_list{k};
    gk = gf(xk);
    Bk = Hf(xk);

    % Display gradient and Hessian at the specified points
    fprintf('%s\n', labels{k});
    fprintf('  f(xk) = %.6f\n', f(xk));
    fprintf('  grad f(xk) = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('  Hess f(xk) = [%.6f %.6f; %.6f %.6f]\n\n', Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));

    % Quadratic model m_k(p) = f(xk) + gk' p + 1/2 p' Bk p
    mk = @(p) f(xk) + gk.'*p + 0.5*p.'*(Bk*p);

    % Evaluate model on a p-grid for contours
    MK = zeros(size(P1));
    for i = 1:numel(P1)
        p = [P1(i); P2(i)];
        MK(i) = mk(p);
    end

    % Compute the family of trust-region solutions p*(Δ)
    Psol = zeros(2, numel(Delta_vals));

    % Check positive definiteness of Bk
    [~, pd_flag] = chol(Bk);
    if pd_flag == 0
        % Unconstrained minimizer (Newton step)
        pB = - (Bk \ gk);
        % Cauchy point along steepest descent
        gBg = gk.'*(Bk\gk);
        if gBg > 0
            alpha_sd = (gk.'*gk) / gBg;
        else
            alpha_sd = 0;
        end
        pu = - alpha_sd * gk;  % Cauchy step

        for j = 1:numel(Delta_vals)
            Delta = Delta_vals(j);
            if norm(pB) <= Delta
                p_star = pB;  % Newton step is feasible and optimal
            else
                % Dogleg path between pu and pB
                if norm(pu) >= Delta
                    % Take scaled steepest descent to boundary
                    p_star = (Delta / max(norm(pu), eps)) * pu;
                else
                    % Find tau in (0,1] s.t. || pu + tau*(pB - pu) || = Delta
                    d = pB - pu;
                    a = d.'*d;
                    b = 2*pu.'*d;
                    c = pu.'*pu - Delta^2;
                    disc = max(0, b^2 - 4*a*c);
                    tau = (-b + sqrt(disc)) / (2*a);
                    tau = max(min(tau,1),0);
                    p_star = pu + tau * d;
                end
            end
            Psol(:, j) = p_star;
        end
    else
        % Fallback: Cauchy/boundary solution
        for j = 1:numel(Delta_vals)
            Delta = Delta_vals(j);
            gBg = gk.'*(Bk\gk);
            if isfinite(gBg) && gBg > 0
                alpha_sd = min( (gk.'*gk)/gBg, Delta / max(norm(gk), eps) );
            else
                alpha_sd = Delta / max(norm(gk), eps);
            end
            p_star = - alpha_sd * gk;
            if norm(p_star) > Delta + 1e-12
                p_star = (Delta / norm(p_star)) * p_star;
            end
            Psol(:, j) = p_star;
        end
    end

    % Plot contours of m_k and the trust-region solution family
    subplot(1,2,k); hold on; box on; axis equal;
    contour(P1, P2, MK, 30, 'LineWidth', 1.0); colormap(parula);
    plot(0, 0, 'ko', 'MarkerFaceColor','k', 'DisplayName','p = 0');

    % Plot trust region circles for a few radii
    for Delta = [0.5 1 1.5 2]
        th = linspace(0, 2*pi, 200);
        plot(Delta*cos(th), Delta*sin(th), 'k--', 'HandleVisibility','off');
    end

    % Plot solution curve p*(Δ) as Δ goes from 0 to 2
    plot(Psol(1,:), Psol(2,:), 'r-', 'LineWidth', 2, 'DisplayName','p*(\Delta)');
    scatter(Psol(1,1), Psol(2,1), 36, 'filled', 'MarkerFaceColor','r', 'DisplayName','\Delta=0');
    scatter(Psol(1,end), Psol(2,end), 36, 'filled', 'MarkerFaceColor','m', 'DisplayName','\Delta=2');

    title(sprintf('Quadratic model contours and trust-region solutions at %s', labels{k}));
    xlabel('p_1'); ylabel('p_2');
    legend('Location','best');
end

