% Define function f, its gradient, and Hessian
% Problem-specific: edit f, grad_f, hess_f if a different f is required.
% Example quadratic+quartic function to demonstrate trust-region workflow:
%   f(x) = x1^4 + x2^4 + x1^2 + 2*x2^2 + x1*x2 - 3*x1 + x2
% You can replace this with the exact f from the problem if specified.
f = @(x) x(1).^4 + x(2).^4 + x(1).^2 + 2*x(2).^2 + x(1).*x(2) - 3*x(1) + x(2);
grad_f = @(x) [4*x(1).^3 + 2*x(1) + x(2) - 3; 4*x(2).^3 + 4*x(2) + x(1) + 1];
hess_f = @(x) [12*x(1).^2 + 2, 1; 1, 12*x(2).^2 + 4];

% Points of interest
xk_list = {[0; -1], [0; 0.5]};
labels = {"x = [0; -1]", "x = [0; 0.5]"};

% Trust-region radii
Delta_vals = linspace(0,2,41);  % Δ from 0 to 2

% Helper to solve trust-region subproblem for quadratic model
% Given g, B, and Δ, solve min_p m(p) = g^T p + 1/2 p^T B p  s.t. ||p|| <= Δ
% Uses dogleg for SPD B; otherwise, generalized Cauchy point with boundary solve
function p = solve_trust_region(g,B,Delta)
    % Try Cholesky to check SPD
    isSPD = false;
    try
        chol(B);
        isSPD = true;
    catch
        isSPD = false;
    end

    if norm(g) == 0
        p = zeros(size(g));
        return;
    end

    if isSPD
        % Compute Newton step and Cauchy step
        pN = -B\g;
        pU = -(g'*g)/(g'*B*g) * g;  % Cauchy (steepest descent) step
        if norm(pN) <= Delta
            p = pN; return;
        end
        if norm(pU) >= Delta
            p = Delta * (pU / norm(pU)); return;
        end
        % Dogleg between pU and pN
        d = pN - pU;
        % Find tau in (0,1] s.t. ||pU + tau d|| = Delta
        a = d'*d; b = 2*(pU'*d); c = pU'*pU - Delta^2;
        tau = (-b + sqrt(max(b^2 - 4*a*c,0))) / (2*a);
        p = pU + tau*d;
    else
        % Non-SPD: take direction of steepest descent, then project to boundary
        pC = - (Delta / norm(g)) * g;  % boundary along -g
        % Try to improve using truncated conjugate gradient towards negative curvature
        % For simplicity and robustness, return Cauchy boundary step
        p = pC;
    end
end

% Visualization and computations for each point
