    % Build quadratic model m_k(p) = f(xk) + gk^T p + 1/2 p^T Bk p (for contours we can drop constant)
    mk = @(p1,p2) f(xk) + gk(1).*p1 + gk(2).*p2 + 0.5*(Bk(1,1).*p1.^2 + 2*Bk(1,2).*p1.*p2 + Bk(2,2).*p2.^2);

    % Determine plotting window based on unconstrained step or gradient norm
    % Try to include most trust-region steps up to Δ=2
    R = 2.5; % radius for plotting grid
    p1 = linspace(-R,R,200); p2 = linspace(-R,R,200);
    [P1,P2] = meshgrid(p1,p2);
    M = mk(P1,P2);

    % Solve the family of trust-region subproblems for Δ in [0,2]
    Psol = zeros(2,numel(Delta_vals));
    for j = 1:numel(Delta_vals)
        Psol(:,j) = solve_trust_region(gk,Bk,Delta_vals(j));
    end

    % Contour plot of quadratic model and trust-region solution path
    subplot(1,2,idx); hold on; box on; axis equal
    contour(P1,P2,M,30,'LineWidth',0.8); colormap(parula);
    % Draw a few trust-region boundaries for reference
    th = linspace(0,2*pi,300);
