    scatter(Psol(1,end), Psol(2,end), 36, 'filled', 'MarkerFaceColor', 'm'); % Δ=2 end

    title(sprintf('Quadratic model and TR solutions at %s', labels{idx}));
    xlabel('p_1'); ylabel('p_2');
    legend({'m_k contours','TR boundaries','solution path','Δ=0','Δ=2'}, 'Location','bestoutside');
