% MATLAB script: trust_region_quadratic_visualization.m
clear; close all; clc;

% Define f(x), gradient, and Hessian.
% Problem statement (example):
% f(x) = (x1 - 1)^2 + 2(x2 + 2)^2 + x1*x2
f  = @(x) (x(1)-1).^2 + 2*(x(2)+2).^2 + x(1).*x(2);

% Gradient: g = [2(x1-1)+x2; 4(x2+2)+x1]
grad = @(x) [2*(x(1)-1) + x(2);
             4*(x(2)+2) + x(1)];

% Hessian is constant for this quadratic: B = [2 1; 1 4]
H = [2, 1; 1, 4];

% Points to analyze
Xk_list = {[0; -1], [0; 0.5]};
Xk_names = {'x = [0; -1]', 'a = [0; 0.5]'};

% Radii for trust-region (Δ from 0 to 2)
Delta_vec = linspace(0, 2, 41);

% Grid for contour plots of m_k(p)
[p1g, p2g] = meshgrid(linspace(-2.5, 2.5, 201), linspace(-2.5, 2.5, 201));
Pg = [p1g(:) p2g(:)]';

for i = 1:numel(Xk_list)
    xk = Xk_list{i};
    gk = grad(xk);
    Bk = H; % Hessian at xk (constant for this quadratic)

    % Report values
    fprintf('Point %s\n', Xk_names{i});
    fprintf('  f(xk) = %.6f\n', f(xk));
    fprintf('  g(xk) = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('  H(xk) = [%.6f %.6f; %.6f %.6f]\n', Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));

    % Quadratic model m_k(p) = f(xk) + gk^T p + 1/2 p^T Bk p
    mk_vals = f(xk) + Pg(1,:).*gk(1) + Pg(2,:).*gk(2) + 0.5*sum((Bk*Pg).*Pg,1);
    mk_grid = reshape(mk_vals, size(p1g));

    % Solve trust region subproblem for each Δ:
    %   minimize 0.5 p^T Bk p + gk^T p  s.t. ||p|| <= Δ
    % Use exact solver via Moré–Sorensen (1D lambda) for SPD Bk.
    % For SPD Bk, the unconstrained minimizer is p* = -Bk\gk. If ||p*||<=Δ, it is the TR solution.
    % Otherwise find lambda >= 0 s.t. ||(Bk + lambda I)^{-1} (-gk)|| = Δ.

    p_sols = zeros(2, numel(Delta_vec));
    for j = 1:numel(Delta_vec)
        Delta = Delta_vec(j);
        p_unc = -Bk\gk;
        if norm(p_unc) <= Delta + 1e-12
            p_sols(:,j) = p_unc;
        else
            % Find lambda with scalar root-finding on phi(lambda) = 1/||p(lambda)|| - 1/Delta
            % where p(lambda) = -(Bk + lambda I)^{-1} gk.
            % We bracket lambda in [0, lambda_max] where lambda_max grows until norm(p) <= Delta.
            lam_lo = 0;
            lam_hi = 1;
            I2 = eye(2);
            % Increase lam_hi until the norm condition is met
            while true
                p_lam = -(Bk + lam_hi*I2)\gk;
                if norm(p_lam) <= Delta || lam_hi > 1e8
                    break
                end
                lam_hi = lam_hi * 2;
            end
            % Bisection on lambda
            for it = 1:60
                lam_mid = 0.5*(lam_lo + lam_hi);
                p_mid = -(Bk + lam_mid*I2)\gk;
                if norm(p_mid) > Delta
                    lam_lo = lam_mid;
                else
                    lam_hi = lam_mid;
                end
            end
            lam = lam_hi;
            p_sols(:,j) = -(Bk + lam*I2)\gk;
        end
    end

    % Plot contours of m_k(p) and trust-region solutions
    figure('Name', ['Quadratic model and TR solutions at ' Xk_names{i}]);
    hold on; box on; grid on;
    contour(p1g, p2g, mk_grid, 30, 'LineWidth', 1.0);
    colormap(parula);
    xlabel('p_1'); ylabel('p_2');
    title(['m_k(p) contours and TR solutions at ' Xk_names{i}]);

    % Plot trust-region boundaries for a subset of radii and the solution curve
    th = linspace(0, 2*pi, 200);
    for j = 1:5:numel(Delta_vec)
        Delta = Delta_vec(j);
        plot(Delta*cos(th), Delta*sin(th), 'k:', 'HandleVisibility','off');
    end

    plot(p_sols(1,:), p_sols(2,:), 'r-', 'LineWidth', 2, 'DisplayName','TR solutions (Δ∈[0,2])');
    scatter(p_sols(1,1), p_sols(2,1), 36, 'g', 'filled', 'DisplayName','Δ=0');
    scatter(p_sols(1,end), p_sols(2,end), 36, 'm', 'filled', 'DisplayName','Δ=2');
    legend('Location','best');
    axis equal; xlim([-2.5 2.5]); ylim([-2.5 2.5]);

    % Optional: overlay unconstrained minimizer
    p_unc = -Bk\gk;
    plot(p_unc(1), p_unc(2), 'bx', 'MarkerSize', 10, 'LineWidth', 2, 'DisplayName','Unconstrained minimizer');
end

% Notes:
% - The code computes f, grad, and Hessian at x=[0;-1] and x=[0;0.5].
% - The quadratic model m_k uses B_k equal to the Hessian of f at x_k (constant here).
% - The trust region subproblem is solved exactly for each Δ∈[0,2] using a scalar λ search.
% - The contour plots show m_k(p), trust-region circles for sample Δ, and the family of solutions p(Δ).

