// Maps a CSV row using header mapping; returns { ok: true, value } or { ok: false, error }
function mapAndValidateRow(row, headers, mapping, requiredColumns) {
  try {
    const mapped = {};
    // Ensure required source columns exist
    for (const col of requiredColumns) {
      if (!(col in row) || row[col] === undefined || row[col] === null || String(row[col]).trim() === '') {
        return { ok: false, error: `Missing required column: ${col}` };
      }
    }
    // Map CSV → DB fields
    for (const [dbField, csvHeader] of Object.entries(mapping)) {
      mapped[dbField] = row[csvHeader] ?? null;
    }
    return { ok: true, value: mapped };
  } catch (err) {
    return { ok: false, error: `Row mapping error: ${err.message}` };
  }
}

// Batcher with limited concurrency for DB upserts
class BatchFlusher {
  constructor({ batchSize, concurrency, upsertFn }) {
    this.batchSize = batchSize;
    this.concurrency = concurrency;
    this.upsertFn = upsertFn;
    this.current = [];
    this.active = 0;
    this.queue = [];
    this.totalFlushed = 0;
  }

  async push(row) {
    this.current.push(row);
    if (this.current.length >= this.batchSize) {
      const toFlush = this.current;
      this.current = [];
      await this.enqueueFlush(toFlush);
    }
  }

  async drain() {
    if (this.current.length > 0) {
      const toFlush = this.current;
      this.current = [];
      await this.enqueueFlush(toFlush);
    }
    await Promise.all(this.queue);
  }

  async enqueueFlush(rows) {
    const exec = async () => {
      try {
        this.active++;
        await this.upsertFn(rows);
        this.totalFlushed += rows.length;
      } finally {
        this.active--;
        this.dequeue();
      }
    };

    const run = () => {
      const p = exec();
      this.queue.push(p);
      p.finally(() => {
        const idx = this.queue.indexOf(p);
        if (idx >= 0) this.queue.splice(idx, 1);
      });
    };

    if (this.active < this.concurrency) {
      run();
    } else {
      await new Promise((resolve) => {
        const check = () => {
          if (this.active < this.concurrency) {
            run();
            resolve();
          } else {
            setTimeout(check, 5);
          }
        };
        check();
      });
    }
  }

  dequeue() {
    // noop: simple backpressure is handled via polling above
  }
}

// Main function: read and process CSV using Papa Parse with streaming
async function importCustomersFromCsv({ filePath }) {
  if (!filePath) throw new Error('filePath is required');

  const mapping = config.import.customersCsvMapping;
  const requiredColumns = config.import.requiredColumns;
  const batcher = new BatchFlusher({
    batchSize: config.import.batchSize,
    concurrency: config.import.concurrency,
    upsertFn: async (rows) => {
      try {
        await customerRepository.upsertMany(rows);
      } catch (err) {
        // Surface DB errors with context
        throw new Error(`DB upsert failed for batch of ${rows.length}: ${err.message}`);
      }
    }
  });

  let processed = 0;
  let skipped = 0;
  let headersValidated = false;
  let parseResolve, parseReject;
  const parseDone = new Promise((res, rej) => { parseResolve = res; parseReject = rej; });

  const stream = fs.createReadStream(filePath)
    .on('error', (err) => {
      parseReject(new Error(`File read error: ${err.message}`));
    });

  Papa.parse(stream, {
    header: true,
    skipEmptyLines: true,
    worker: false, // Papa's web worker is browser-only; we use Node worker_threads instead
    dynamicTyping: false,
    step: async (results, parser) => {
      const row = results.data;

      // Validate headers on first row
      if (!headersValidated) {
        headersValidated = true;
        for (const reqCol of requiredColumns) {
          if (!(reqCol in row)) {
            parser.abort();
            parseReject(new Error(`Missing required CSV header: ${reqCol}`));
            return;
          }
        }
      }

      const mapped = mapAndValidateRow(row, null, mapping, requiredColumns);
      if (!mapped.ok) {
        skipped++;
        return; // skip invalid row
      }

      let toQueue = mapped.value;

      try {
        if (config.import.useWorkers) {
          // Offload sanitation/normalization to worker
          const sanitized = await createSanitizeWorker([toQueue]);
          toQueue = sanitized[0];
        } else {
          // In-place lightweight sanitation if not using workers
          if (toQueue.email) toQueue.email = String(toQueue.email).trim().toLowerCase();
        }
        await batcher.push(toQueue);
        processed++;
      } catch (err) {
        // On batch enqueue/sanitize error, skip and continue
        skipped++;
      }
    },
    error: (err) => {
      parseReject(new Error(`Papa Parse error: ${err && err.message ? err.message : String(err)}`));
    },
    complete: async () => {
      try {
        await batcher.drain();
        parseResolve({ processed, skipped });
      } catch (err) {
        parseReject(err);
      }
    }
  });

  try {
    const summary = await parseDone;
    // Notify admin on completion
    await emailService.notifyAdmin({
      subject: 'Customer Import Completed',
      text: `Customer import finished. Processed: ${summary.processed}, Skipped: ${summary.skipped}`
    });
    return summary;
  } catch (err) {
    // Failure path: send failure email as well
    try {
      await emailService.notifyAdmin({
        subject: 'Customer Import Failed',
        text: `Customer import failed: ${err.message}`
      });
    } catch (_) { /* ignore email failure */ }
    throw err;
  } finally {
    // Best-effort cleanup of temp upload
    try { fs.unlinkSync(filePath); } catch (_) {}
  }
}

