Below is an incremental improvement of the earlier toy translator (SQL AST -> Relational Algebra AST) with focused error handling, discussion of common pitfalls, and concrete examples showing input SQL and the resulting RA. It remains Python-based and continues the iterative approach (single table -> multiple tables -> joins).

Note: We still assume you start from an existing SQL AST, not raw SQL text. For clarity in examples, we’ll display input as SQL strings alongside the equivalent SQL AST construction in Python.


Python implementation with error handling and pitfalls

```python your_code_here
from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Union

# ---------- Exceptions: explicit, precise messages ----------

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass

class DuplicateAliasError(TranslationError):
    pass

class UnknownTableError(TranslationError):
    pass

class UnknownColumnError(TranslationError):
    pass

class AmbiguousColumnError(TranslationError):
    pass

class UnsupportedFeatureError(TranslationError):
    pass


# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>'
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]  # or items including AllColumns()
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases) from SQL AST
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Helpers: expression traversal and name resolution ----------

def map_expr(e: SQLExpr, f) -> SQLExpr:
    """Post-order map over SQLExpr; applies f to each node, returns possibly transformed node."""
    if isinstance(e, Comparison):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = Comparison(e.op, left, right)
    elif isinstance(e, BooleanOp):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = BooleanOp(e.op, left, right)
    elif isinstance(e, Not):
        child = map_expr(e.expr, f)
        e = Not(child)
    elif isinstance(e, (Column, Literal, AllColumns)):
        pass
    else:
        raise UnsupportedFeatureError(f"Unsupported SQL expression node: {type(e).__name__}")
    return f(e)

class NameResolver:
    """
    Resolves unqualified columns to a unique table alias, validates existence of tables/columns,
    and catches ambiguity. If a catalog is provided, it enables strong column validation.
    """
    def __init__(self, from_tables: List[TableRef], catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True):
        self.from_tables = from_tables
        self.catalog = catalog
        self.strict = strict
        # alias_key -> table_name
        self.alias_to_table: Dict[str, str] = {}
        self._init_aliases()

    def _init_aliases(self) -> None:
        seen: Set[str] = set()
        for t in self.from_tables:
            alias_key = t.alias if t.alias else t.name
            if alias_key in seen:
                raise DuplicateAliasError(f"Duplicate table alias/name in FROM: '{alias_key}'")
            seen.add(alias_key)
            self.alias_to_table[alias_key] = t.name

    def check_tables_exist(self) -> None:
        if not self.catalog:
            return
        for tr in self.from_tables:
            if tr.name not in self.catalog:
                raise UnknownTableError(f"Unknown table '{tr.name}'")

    def _table_aliases(self) -> List[str]:
        # Return alias keys in input order (alias if present, else name)
        return [t.alias if t.alias else t.name for t in self.from_tables]

    def resolve_expr(self, e: SQLExpr) -> SQLExpr:
        def resolve(node: SQLExpr) -> SQLExpr:
            if not isinstance(node, Column):
                return node

            col = node
            # If qualified, validate qualifier and optionally column existence
            if col.table is not None:
                if col.table not in self.alias_to_table:
                    raise UnknownTableError(f"Unknown table/alias '{col.table}' in column '{col.table}.{col.name}'")
                if self.catalog and self.strict:
                    table_name = self.alias_to_table[col.table]
                    cols = self.catalog.get(table_name)
                    if cols is not None and col.name not in cols:
                        raise UnknownColumnError(f"Unknown column '{col.name}' on table '{table_name}' (alias '{col.table}')")
                return col

            # Unqualified: try to resolve uniquely across FROM tables
            candidates: List[str] = []  # alias keys
            for alias_key, table_name in self.alias_to_table.items():
                if not self.catalog or not self.strict:
                    # Without catalog, assume it could exist anywhere; track all aliases
                    candidates.append(alias_key)
                else:
                    cols = self.catalog.get(table_name)
                    if cols is None or col.name in cols:
                        candidates.append(alias_key)

            # Filter: if catalog present, keep only tables where the column exists
            if self.catalog and self.strict:
                # We already filtered above; now remove aliases where column definitely doesn't exist
                pass

            # Deduplicate, and decide
            candidates = list(dict.fromkeys(candidates))
            if len(candidates) == 0:
                raise UnknownColumnError(f"Unknown unqualified column '{col.name}'")
            if len(candidates) > 1:
                raise AmbiguousColumnError(f"Ambiguous column '{col.name}' (candidates: {', '.join(candidates)})")

            # Qualify with the single matching alias
            return Column(name=col.name, table=candidates[0])

        return map_expr(e, resolve)


# ---------- Translators ----------

class Translator:
    def __init__(self, catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True):
        self.catalog = catalog
        self.strict = strict

    def _validate_select_core(self, stmt: SelectStmt) -> None:
        if not stmt.select_list:
            raise EmptySelectListError("Empty SELECT list is not allowed")
        if not stmt.from_tables:
            raise EmptyFromError("Missing FROM clause")

    def _build_from_ra(self, from_tables: List[TableRef]) -> RAExpr:
        # Build left-deep product tree for multiple tables
        it = iter(from_tables)
        first = next(it)
        ra: RAExpr = RATable(first.name, alias=first.alias)
        for t in it:
            ra = RAProduct(ra, RATable(t.name, alias=t.alias))
        return ra

    def translate_step1_single_table(self, stmt: SelectStmt) -> RAExpr:
        self._validate_select_core(stmt)
        if len(stmt.from_tables) != 1:
            raise TranslationError("Step 1 supports exactly one table in FROM")

        resolver = NameResolver(stmt.from_tables, catalog=self.catalog, strict=self.strict)
        resolver.check_tables_exist()

        base = RATable(stmt.from_tables[0].name, alias=stmt.from_tables[0].alias)
        ra: RAExpr = base

        where_resolved = resolver.resolve_expr(stmt.where) if stmt.where is not None else None
        if where_resolved is not None:
            ra = RASelection(predicate=where_resolved, child=ra)

        # Projection: if SELECT * only, you may skip RAProjection
        star_only = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
        items_resolved = [SelectItem(resolver.resolve_expr(si.expr), si.alias) for si in stmt.select_list]
        if star_only:
            return ra
        else:
            return RAProjection(items=items_resolved, child=ra)

    def translate_step2_multi_from(self, stmt: SelectStmt) -> RAExpr:
        self._validate_select_core(stmt)
        if len(stmt.from_tables) < 1:
            raise EmptyFromError("Missing FROM clause")
        resolver = NameResolver(stmt.from_tables, catalog=self.catalog, strict=self.strict)
        resolver.check_tables_exist()

        ra: RAExpr = self._build_from_ra(stmt.from_tables)
        where_resolved = resolver.resolve_expr(stmt.where) if stmt.where is not None else None
        if where_resolved is not None:
            ra = RASelection(predicate=where_resolved, child=ra)

        star_only = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
        items_resolved = [SelectItem(resolver.resolve_expr(si.expr), si.alias) for si in stmt.select_list]
        if star_only:
            return ra
        else:
            return RAProjection(items=items_resolved, child=ra)

    # A simple JOIN-capable variant: treat explicit joins as products + pushed selection.
    # For brevity, we assume JOINs are already normalized into from_tables + where predicate.
    # In a fuller AST, you'd have JoinRef nodes with join_type and on.
    def translate_step3_with_joins(self, stmt: SelectStmt) -> RAExpr:
        # Here we reuse step2; in a real system, you'd detect join conditions and place them as selections.
        return self.translate_step2_multi_from(stmt)


# ---------- Common pitfalls (discussed via checks above) ----------
# 1) Ambiguous unqualified columns when multiple tables are in FROM.
# 2) Duplicate table aliases or reusing a base table name as another alias.
# 3) Referencing tables or columns that don't exist in the catalog.
# 4) Empty SELECT lists or missing FROM clause.
# 5) Forgetting to qualify columns in JOINs, leading to ambiguity.
# 6) Assuming SELECT * is always safe; with overlapping column names it becomes ambiguous later.
# 7) Boolean precedence in WHERE (ensure SQL AST captures parentheses to avoid mis-translation).


# ---------- Examples: SQL -> RA (or errors) ----------
if __name__ == "__main__":
    # Define a tiny catalog for validation
    catalog = {
        "users": {"id", "name", "age", "dept_id"},
        "depts": {"id", "name"},
    }

    tr = Translator(catalog=catalog, strict=True)

    def show_case(title: str, sql: str, build_stmt):
        print("\n== ", title)
        print("SQL:", sql)
        try:
            stmt = build_stmt()
            ra = tr.translate_step2_multi_from(stmt)
            print("RA:\n" + ra_to_str(ra))
        except TranslationError as e:
            print("Error:", type(e).__name__, str(e))

    # Case A: Single table basic select
    # SQL: SELECT id, name FROM users WHERE age > 18;
    show_case(
        "Single table basic",
        "SELECT id, name FROM users WHERE age > 18;",
        lambda: SelectStmt(
            select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
            from_tables=[TableRef("users")],
            where=Comparison(">", Column("age"), Literal(18)),
        ),
    )

    # Case B: SELECT * with aliasing
    # SQL: SELECT * FROM users u WHERE u.age >= 21;
    show_case(
        "Star with alias",
        "SELECT * FROM users u WHERE u.age >= 21;",
        lambda: SelectStmt(
            select_list=[SelectItem(AllColumns())],
            from_tables=[TableRef("users", alias="u")],
            where=Comparison(">=", Column("age"), Literal(21)),
        ),
    )

    # Case C: Two-table query with qualified predicate
    # SQL: SELECT u.id, d.name FROM users u, depts d WHERE u.dept_id = d.id;
    show_case(
        "Two-table join via WHERE",
        "SELECT u.id, d.name FROM users u, depts d WHERE u.dept_id = d.id;",
        lambda: SelectStmt(
            select_list=[SelectItem(Column("id", "u")), SelectItem(Column("name", "d"))],
            from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="d")],
            where=Comparison("=", Column("dept_id", "u"), Column("id", "d")),
        ),
    )

    # Case D (Ambiguity error): Unqualified column present in multiple tables
    # SQL: SELECT id FROM users u, depts d;   -- 'id' exists in both tables
    show_case(
        "Ambiguous unqualified column",
        "SELECT id FROM users u, depts d;",
        lambda: SelectStmt(
            select_list=[SelectItem(Column("id"))],
            from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="d")],
            where=None,
        ),
    )

    # Case E (Unknown column): Typo in column name
    # SQL: SELECT u.idx FROM users u;
    show_case(
        "Unknown column",
        "SELECT u.idx FROM users u;",
        lambda: SelectStmt(
            select_list=[SelectItem(Column("idx", "u"))],
            from_tables=[TableRef("users", alias="u")],
            where=None,
        ),
    )

    # Case F (Duplicate alias): Same alias used twice
    # SQL: SELECT * FROM users u, depts u;
    try:
        _ = tr.translate_step2_multi_from(
            SelectStmt(
                select_list=[SelectItem(AllColumns())],
                from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="u")],
            )
        )
    except TranslationError as e:
        print("\n== Duplicate alias example")
        print("SQL: SELECT * FROM users u, depts u;")
        print("Error:", type(e).__name__, str(e))
```


How examples map to Relational Algebra
- Single table basic: Project[id, name] over Select[age > 18] over Table(users)
- Star with alias: Select[u.age >= 21] over Table(users AS u)
- Two-table join via WHERE: Project[u.id, d.name] over Select[u.dept_id = d.id] over Product(Table(users AS u), Table(depts AS d))

Common pitfalls and handling
- Ambiguous columns: Always qualify columns when multiple tables are present; our NameResolver raises AmbiguousColumnError.
- Unknown identifiers: With a catalog, we detect UnknownTableError and UnknownColumnError early.
- Duplicate aliases: We guard against reusing alias or base table names via DuplicateAliasError.
- SELECT * over multiple tables: Downstream ambiguity; consider expanding to qualified columns during later planning.
- Boolean precedence: Ensure the SQL AST preserves parentheses; translator assumes AST is already disambiguated.
- Missing FROM or empty select list: Raises EmptyFromError and EmptySelectListError.

