Here’s a concise, hands-on introduction to a toy “query parser” that converts a pre-parsed SQL AST (Abstract Syntax Tree) into a relational algebra (RA) expression tree, with step-by-step guidance starting from simple SELECT statements and expanding to multiple tables/joins. All examples are in Python.

Overview
- We start from a SQL AST (already parsed SQL represented as Python objects).
- We map it to a relational algebra AST using operators: Table, Selection (WHERE), Projection (SELECT), and Product (for multiple tables / joins-as-selections).
- We build iteratively: first a single-table SELECT, then multiple tables (implicit cross-product), and show example SQL inputs (for readability), the AST objects you would construct, and the resulting RA expressions.

Step 0 — Define minimal ASTs and pretty-printing

```python rom __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # e.g., Column(name="id", table="users")

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # '=', '<', '>', '<=', '>='
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    pass  # SELECT *

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"


def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"
```

Step 1 — Single-table SELECT-FROM-[WHERE]
Mapping rules:
- FROM t -> RATable(t)
- WHERE p -> RASelection(p, child)
- SELECT a,b -> RAProjection([a,b], child); SELECT * -> omit projection

```python
class TranslationError(Exception):
    pass

def translate_select_single_table(stmt: SelectStmt) -> RAExpr:
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if len(stmt.from_tables) != 1:
        raise TranslationError("This step supports exactly one table in FROM.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    base = stmt.from_tables[0]
    ra: RAExpr = RATable(name=base.name, alias=base.alias)

    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    return ra if only_star else RAProjection(items=stmt.select_list, child=ra)
```

Example inputs and outputs (Step 1)
- SQL: SELECT id, name FROM users WHERE age > 18;
  RA:
  Project[id, name]
    Select[(age > 18)]
      Table(users)

- SQL: SELECT * FROM users;
  RA:
  Table(users)

Code to construct AST and run:

```python
# Example 1: SELECT id, name FROM users WHERE age > 18;
stmt1 = SelectStmt(
    select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
    from_tables=[TableRef("users")],
    where=Comparison(">", Column("age"), Literal(18)),
)
ra1 = translate_select_single_table(stmt1)
print(ra_to_str(ra1))

# Example 2: SELECT * FROM users;
stmt2 = SelectStmt(
    select_list=[SelectItem(AllColumns())],
    from_tables=[TableRef("users")],
)
ra2 = translate_select_single_table(stmt2)
print(ra_to_str(ra2))
```

Step 2 — Multiple tables in FROM (implicit cross-product) and joins-as-selections
Mapping rules:
- FROM t1, t2, ... -> left-deep RAProduct chain
- WHERE join/filter -> RASelection over that product
- SELECT -> RAProjection unless SELECT *

```python
def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra


def translate_select(stmt: SelectStmt) -> RAExpr:
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    ra = fold_product(stmt.from_tables)

    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    return ra if only_star else RAProjection(items=stmt.select_list, child=ra)
```

Example inputs and outputs (Step 2)
- SQL: SELECT u.id, o.total FROM users AS u, orders AS o WHERE u.id = o.user_id AND o.total > 100;
  RA:
  Project[u.id, o.total]
    Select[((u.id = o.user_id) AND (o.total > 100))]
      Product
        Table(users AS u)
        Table(orders AS o)

Code to construct AST and run:

```python
stmt3 = SelectStmt(
    select_list=[SelectItem(Column("id", table="u")), SelectItem(Column("total", table="o"))],
    from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
    where=BooleanOp(
        "AND",
        left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
        right=Comparison(">", Column("total", "o"), Literal(100)),
    ),
)
ra3 = translate_select(stmt3)
print(ra_to_str(ra3))
```

How the conversion works (summary)
- Build base RA from FROM (Table or Product of Tables).
- Wrap with Selection if WHERE exists.
- Wrap with Projection for SELECT items (omit if SELECT *).

Common pitfalls and tips
- Ambiguous columns: unqualified Column("id") with multiple tables may be ambiguous; add name resolution or require qualification.
- SELECT * with aliases: ensure downstream pretty-printer or executor knows column origins.
- Boolean precedence: encode parentheses in the AST (BooleanOp/Not) to avoid misinterpretation.
- Validation: check empty SELECT list or missing FROM early and raise clear errors.

