% MATLAB code (wrapped in a python block as requested)

%-----------------------------------------------------------
% Periodic-noise restoration with discussion-ready scaffolding:
% - Synthetic degradation (as in the question)
% - Automatic spike detection on the log-spectrum
% - Butterworth notch-reject filtering (Hermitian-safe)
% - Optional residual denoising (Wiener, NLM, Wavelet)
% - Metrics and spectra
%-----------------------------------------------------------
function periodic_restoration_with_discussion()
    close all; clc;

    % 0) Load and degrade (same pattern as the question)
    im = im2double(imread('saturn.tif'));
    if size(im,3) > 1, im = rgb2gray(im); end
    [M, N] = size(im);

    X = fft2(im);
    nn = 1e6;
    X(10,10) = X(10,10) + nn;
    X(10,11) = X(10,11) + nn;
    X(11,10) = X(11,10) + nn;
    X(11,11) = X(11,11) + nn;
    y = real(ifft2(X));    % degraded image

    % 1) Spike detection on y's spectrum (auto), or use known indices
    params.kSigma      = 6.0;   % threshold strength on log-spectrum
    params.centerBlock = 25;    % exclude DC neighborhood (shifted coords)
    params.minDist     = 3;     % min separation between peaks (pixels)
    params.maxPeaks    = 20;    % safety cap
    params.smoothSigma = 1.0;   % Gaussian smoothing of log-spectrum
    params.applyApodization = false; % window edges before FFT (leakage control)

    useAutoDetect = true;
    if useAutoDetect
        spikeIdx = detectPeriodicSpikesAuto(y, params);  % returns unshifted [row col]
    else
        spikeIdx = [10 10; 10 11; 11 10; 11 11];         % manual (from degradation)
    end

    % 2) Build Butterworth notch-reject filter (Hermitian-safe)
    notch.radius = 2;
    notch.order  = 4;
    H = buildButterworthNotchReject(M, N, spikeIdx, notch.radius, notch.order);

    % 3) Filter in Fourier domain
    Y  = fft2(y);
    Yf = H .* Y;
    y_notched = real(ifft2(Yf));

    % 4) Residual denoising option
    post.method = 'wiener2';
    switch lower(post.method)
        case 'wiener2'
            restored = wiener2(y_notched, [5 5]);
        case 'nlm'
            restored = imnlmfilt(y_notched, 'ComparisonWindowSize', 9, 'SearchWindowSize', 21, 'DegreeOfSmoothing', 8);
        case 'wavelet'
            restored = wdenoise2(y_notched, 2, 'Wavelet', 'sym4', 'DenoisingMethod', 'Bayes', 'NoiseEstimate', 'LevelIndependent');
        case 'none'
            restored = y_notched;
        otherwise
            restored = y_notched;
    end

    % 5) Metrics and visualization
    figure; montage({im, y, restored}, 'Size', [1 3]); title('Original | Degraded | Restored');
    fprintf('PSNR(y_notched vs im): %.2f dB\n', psnr(y_notched, im));
    fprintf('PSNR(restored vs im):  %.2f dB\n', psnr(restored, im));

    figure; subplot(1,3,1); imshow(log1p(abs(fftshift(fft2(im)))),[]); title('log|F(im)|');
    subplot(1,3,2); imshow(log1p(abs(fftshift(fft2(y)))),[]); title('log|F(y)|');
    subplot(1,3,3); imshow(log1p(abs(fftshift(fft2(restored)))),[]); title('log|F(restored)|');
end

%--- Helpers ---
function idx = detectPeriodicSpikesAuto(y, params)
    Y = fft2(y);
    L = log1p(abs(fftshift(Y)));
    if params.smoothSigma > 0
        L = imgaussfilt(L, params.smoothSigma);
    end
    % mask out DC neighborhood
    [M,N] = size(L);
    cx = floor(M/2)+1; cy = floor(N/2)+1;
    CB = params.centerBlock;
    L(cx-CB:cx+CB, cy-CB:cy+CB) = median(L(:));
    T = mean(L(:)) + params.kSigma*std(L(:));
    BW = L > T;
    BW = bwareaopen(BW, 2);
    % map back to unshifted indices
    [r,c] = find(BW);
    r = mod(r-1 - floor(M/2), M) + 1;
    c = mod(c-1 - floor(N/2), N) + 1;
    P = [r c];
    % merge nearby peaks
    if ~isempty(P)
        P = unique(round(P), 'rows');
        P = reduceClosePoints(P, params.minDist, [M N]);
        if size(P,1) > params.maxPeaks
            P = P(1:params.maxPeaks,:);
        end
    end
    % enforce Hermitian pairs
    idx = enforceHermitianPairs(P, [M N]);
end

function P2 = reduceClosePoints(P, minDist, sz)
    if isempty(P), P2 = P; return; end
    keep = true(size(P,1),1);
    for i=1:size(P,1)
        if ~keep(i), continue; end
        d = hypot(circDist(P(:,1),P(i,1),sz(1)), circDist(P(:,2),P(i,2),sz(2)));
        closeIdx = find(d<=minDist & (1:numel(d))'~=i);
        keep(closeIdx) = false;
    end
    P2 = P(keep,:);
end

function d = circDist(a,b,modv)
    d = abs(a-b); d = min(d, modv-d);
end

function idx = enforceHermitianPairs(P, sz)
    if isempty(P), idx = P; return; end
    conjP = [mod(sz(1)-P(:,1)+2-1, sz(1))+1, mod(sz(2)-P(:,2)+2-1, sz(2))+1];
    idx = unique([P; conjP], 'rows');
end

function H = buildButterworthNotchReject(M, N, spikeIdx, r0, n)
    if isempty(spikeIdx)
        H = ones(M,N); return;
    end
    [U,V] = ndgrid(0:M-1, 0:N-1);
    H = ones(M,N);
    for k=1:size(spikeIdx,1)
        uk = spikeIdx(k,1)-1; vk = spikeIdx(k,2)-1;
        Dk  = hypot(mod(U-uk+M/2,M)-M/2, mod(V-vk+N/2,N)-N/2);
        Dck = hypot(mod(U-(M-uk)+M/2,M)-M/2, mod(V-(N-vk)+N/2,N)-N/2);
        H = H .* (1./(1+(r0./(Dk+eps)).^(2*n))) .* (1./(1+(r0./(Dck+eps)).^(2*n)));
    end
    H = max(min(H,1),0);
end

%-----------------------------------------------------------
% Discussion: limitations, trade-offs, and best practices
%-----------------------------------------------------------
% Limitations / trade-offs
% - Notch width vs detail loss: Larger radius/order removes more periodic noise
%   but can suppress genuine textures near the notches and introduce ringing.
% - Missed or extra spikes: Auto-detection can miss low-contrast peaks or flag
%   false positives; verify spikeIdx visually on the log-spectrum.
% - Spatial artifacts: Sharp frequency notches may cause Gibbs-like ripples.
%   Prefer soft (Butterworth) notches and minimal necessary radius.
% - Residual random noise: Notch filtering won’t remove non-periodic noise;
%   follow with spatial/transform denoising (e.g., wiener2, NLM, wavelets).
% - Parameter sensitivity: kSigma, radius, and order need tuning per image;
%   over-aggressive settings reduce fine details and edges.
% - Ground-truth absence: Without original im, rely on no-reference metrics and
%   visual inspection; PSNR/SSIM require a reference.
% - Computation: Peak detection and large FFTs are O(MN log MN); consider GPU.
%
% Additional tips / best practices in MATLAB
% - Inspect spectra: Use fftshift and log1p(abs(FFT)) to manually validate peaks.
% - Hermitian safety: Always notch both a spike and its conjugate to keep output real.
% - Apodize edges: try windowing (hann) before FFT to reduce leakage if content allows.
% - Work in double, keep ranges consistent; clip after inverse FFT if needed.
% - Start conservative: small radius/order; increment gradually while monitoring details.
% - Combine methods: light notch + mild denoiser often outperforms heavy notch alone.
% - Parameter sweeps: script loops over kSigma/radius/order and record PSNR/SSIM.
% - Reproducibility: fix RNG seeds, save parameters and spectra for audit.
% - GPU acceleration: gpuArray for fft2/ifft2 on large images.
% - Visualization: montage before/after; improfile or edge maps to inspect detail loss.
% - Boundary handling: for spatial filters (wiener2), consider padarray to reduce edge bias.
% - Save intermediates: keep y_notched to compare the impact of post-denoising.

Below is a compact but complete C++ implementation of a dynamically connectable Izhikevich neuron with synaptic plasticity (additive STDP), excitatory/inhibitory types, and optional conduction delays. It includes utilities to build a random network, step the simulation, and dynamically connect/disconnect neurons at runtime. Comments explain how this maps to primitive animal nervous systems (spiking units, synapses, plasticity driving adaptation).

Key features:
- Izhikevich neuron model with presets (RS/FS) and configurable parameters; tonic input and noise.
- Synapse with additive STDP (pre/post traces, clamped weights), optional delays via ring buffer; O(1) connect/disconnect.
- Network utilities to build random E/I networks, run steps, and probe spikes.
- Clear interfaces for integration into larger simulations; basic validation and attention to performance.

Note: Uses only the C++ standard library. Single-header style for ease of integration. Compile with: g++ -O3 -std=c++17 izhi.cpp -o izhi

#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstdint>
#include <functional>
#include <iostream>
#include <limits>
#include <memory>
#include <optional>
#include <random>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

// Forward declarations
struct Synapse;

struct Neuron {
    // Izhikevich parameters
    float a{0.02f};
    float b{0.2f};
    float c{-65.0f};
    float d{8.0f};

    // State variables
    float v{-65.0f};
    float u{b * v};

    // Inputs and identity
    float tonic_current{0.0f};
    float noise_std{0.0f};
    bool is_excitatory{true};
    std::string name;

    // Connectivity
    std::vector<Synapse*> incoming;  // owned by Network
    std::vector<Synapse*> outgoing;  // owned by Network

    // Integration helpers
    float I_syn{0.0f};
    bool spiked{false};
    std::optional<float> last_spike_time_ms;

    // Ring buffer for delayed inputs (post-synaptic current)
    std::vector<float> delay_buffer; // size = delay_slots
    std::size_t delay_index{0};

    Neuron() = default;

    static Neuron RegularSpiking(const std::string& n = "RS", bool excit = true) {
        Neuron neu;
        neu.a = 0.02f; neu.b = 0.2f; neu.c = -65.0f; neu.d = 8.0f;
        neu.v = -65.0f; neu.u = neu.b * neu.v; neu.is_excitatory = excit; neu.name = n;
        return neu;
    }

    static Neuron FastSpiking(const std::string& n = "FS") {
        Neuron neu;
        neu.a = 0.1f; neu.b = 0.2f; neu.c = -65.0f; neu.d = 2.0f;
        neu.v = -65.0f; neu.u = neu.b * neu.v; neu.is_excitatory = false; neu.name = n;
        return neu;
    }

    void set_delay_slots(std::size_t slots) {
        delay_buffer.assign(slots, 0.0f);
        delay_index = 0;
    }

    void reset_step_state() {
        I_syn = 0.0f;
        spiked = false;
    }

    void enqueue_current(float I) {
        // Current delivered to current delay slot (already delayed by synapse)
        if (!delay_buffer.empty()) delay_buffer[delay_index] += I;
        else I_syn += I; // if no delay ring, inject immediately
    }

    void apply_delayed_input_advance() {
        // Called once per step to retrieve delayed current and advance ring
        if (!delay_buffer.empty()) {
            I_syn += delay_buffer[delay_index];
            delay_buffer[delay_index] = 0.0f;
            delay_index = (delay_index + 1) % delay_buffer.size();
        }
    }

    bool step(float dt_ms, float t_ms, std::mt19937& rng) {
        // Euler with two half-steps for stability and threshold handling
        spiked = false;
        std::normal_distribution<float> norm(0.0f, noise_std);
        float Iext = tonic_current + I_syn + (noise_std > 0 ? norm(rng) : 0.0f);

        auto euler_half = [&](float h){
            float dv = 0.04f * v * v + 5.0f * v + 140.0f - u + Iext;
            float du = a * (b * v - u);
            v += h * dv;
            u += h * du;
        };

        euler_half(0.5f * dt_ms);
        if (v >= 30.0f) {
            v = c; u += d; spiked = true; last_spike_time_ms = t_ms; return true;
        }
        euler_half(0.5f * dt_ms);
        if (v >= 30.0f) {
            v = c; u += d; spiked = true; last_spike_time_ms = t_ms; return true;
        }
        return false;
    }
};

struct Synapse {
    // Connectivity
    Neuron* pre{nullptr};
    Neuron* post{nullptr};

    // Weight and type
    float w{0.01f};           // synaptic efficacy (current units)
    bool inhibitory{false};   // convenience flag (usually pre.is_excitatory == !inhibitory)

    // Delay implemented via post neuron's ring buffer index offset
    // We store delay in integer slots for dt-sized steps (managed by Network)
    std::size_t delay_slots{0};

    // STDP parameters (additive with exponential traces)
    float A_plus{0.01f};
    float A_minus{0.012f};
    float tau_plus_ms{20.0f};
    float tau_minus_ms{20.0f};

    // Clamping for stability
    float w_min{0.0f};
    float w_max{0.5f};

    // Traces
    float x_pre{0.0f};
    float y_post{0.0f};

    // Cached for efficiency (decay factors per step)
    float pre_decay{1.0f};
    float post_decay{1.0f};

    // Index of this synapse in pre/outgoing and post/incoming vectors for O(1) erase
    std::size_t pre_idx{std::numeric_limits<std::size_t>::max()};
    std::size_t post_idx{std::numeric_limits<std::size_t>::max()};

    void configure_dt(float dt_ms) {
        pre_decay = std::exp(-dt_ms / tau_plus_ms);
        post_decay = std::exp(-dt_ms / tau_minus_ms);
    }

    void decay_traces() {
        x_pre *= pre_decay;
        y_post *= post_decay;
    }

    void on_pre_spike(float /*t_ms*/) {
        // STDP: pre before post -> LTP proportional to y_post
        w += A_plus * y_post;
        w = std::clamp(w, w_min, w_max);
        x_pre += 1.0f;
    }

    void on_post_spike(float /*t_ms*/) {
        // STDP: post after pre -> LTD proportional to x_pre
        w -= A_minus * x_pre;
        w = std::clamp(w, w_min, w_max);
        y_post += 1.0f;
    }
};

struct Network {
    float dt_ms{1.0f};
    float t_ms{0.0f};

    // Ownership of neurons and synapses
    std::vector<std::unique_ptr<Neuron>> neurons;
    std::vector<std::unique_ptr<Synapse>> synapses;

    // RNG
    std::mt19937 rng{std::random_device{}()};

    // Maximum delay slots supported by neurons' ring buffers
    std::size_t max_delay_slots{1};

    Neuron* add_neuron(const Neuron& proto) {
        neurons.emplace_back(std::make_unique<Neuron>(proto));
        neurons.back()->set_delay_slots(max_delay_slots);
        return neurons.back().get();
    }

    Synapse* connect(Neuron* pre, Neuron* post, float w, std::size_t delay_slots = 0, bool inhibitory = false) {
        assert(pre && post);
        auto s = std::make_unique<Synapse>();
        s->pre = pre; s->post = post; s->w = w; s->inhibitory = inhibitory; s->delay_slots = delay_slots;
        s->configure_dt(dt_ms);
        // Register in adjacency lists
        s->pre_idx = pre->outgoing.size();
        s->post_idx = post->incoming.size();
        pre->outgoing.push_back(s.get());
        post->incoming.push_back(s.get());
        synapses.push_back(std::move(s));
        return synapses.back().get();
    }

    void disconnect(Synapse* s) {
        if (!s) return;
        // O(1) removal from pre->outgoing
        auto& out = s->pre->outgoing;
        if (s->pre_idx < out.size() && out[s->pre_idx] == s) {
            std::swap(out[s->pre_idx], out.back());
            out.back()->pre_idx = s->pre_idx;
            out.pop_back();
        } else {
            // Fallback search if indices got out of sync
            auto it = std::find(out.begin(), out.end(), s);
            if (it != out.end()) {
                std::swap(*it, out.back());
                out.back()->pre_idx = static_cast<std::size_t>(it - out.begin());
                out.pop_back();
            }
        }
        // O(1) removal from post->incoming
        auto& in = s->post->incoming;
        if (s->post_idx < in.size() && in[s->post_idx] == s) {
            std::swap(in[s->post_idx], in.back());
            in.back()->post_idx = s->post_idx;
            in.pop_back();
        } else {
            auto it = std::find(in.begin(), in.end(), s);
            if (it != in.end()) {
                std::swap(*it, in.back());
                in.back()->post_idx = static_cast<std::size_t>(it - in.begin());
                in.pop_back();
            }
        }
        // Remove from ownership vector
        auto it = std::find_if(synapses.begin(), synapses.end(), [&](const std::unique_ptr<Synapse>& p){ return p.get() == s; });
        if (it != synapses.end()) synapses.erase(it);
    }

    void set_dt(float new_dt_ms) {
        dt_ms = new_dt_ms;
        for (auto& s : synapses) s->configure_dt(dt_ms);
    }

    void set_max_delay_ms(float max_delay_ms) {
        max_delay_slots = std::max<std::size_t>(1, static_cast<std::size_t>(std::round(max_delay_ms / dt_ms)) + 1);
        for (auto& n : neurons) n->set_delay_slots(max_delay_slots);
    }

    // Deliver synaptic currents for spikes that occurred this step, honoring delays
    void deliver_spikes() {
        for (auto& s_ptr : synapses) {
            Synapse* s = s_ptr.get();
            if (!s->pre->spiked) continue;
            // sign of weight: inhibitory synapses pass negative current
            float I = (s->inhibitory ? -1.0f : 1.0f) * s->w;
            // enqueue to post's delay buffer at (current_index + delay) slot
            if (s->post->delay_buffer.empty() || s->delay_slots == 0) {
                s->post->enqueue_current(I);
            } else {
                std::size_t idx = (s->post->delay_index + s->delay_slots) % s->post->delay_buffer.size();
                s->post->delay_buffer[idx] += I;
            }
            // STDP pre event
            s->on_pre_spike(t_ms);
        }
    }

    void apply_post_spike_stdp() {
        for (auto& s_ptr : synapses) {
            if (s_ptr->post->spiked) {
                s_ptr->on_post_spike(t_ms);
            }
        }
    }

    void decay_all_traces() {
        for (auto& s_ptr : synapses) s_ptr->decay_traces();
    }

    // One simulation step: order matters for causality
    void step() {
        // 1) Advance delayed input buffers and clear per-step accumulators
        for (auto& n : neurons) {
            n->reset_step_state();
            n->apply_delayed_input_advance();
        }

        // 2) Integrate neuron dynamics; record spikes
        for (auto& n : neurons) {
            n->step(dt_ms, t_ms, rng);
        }

        // 3) Deliver synaptic currents for spikes (arriving now or scheduled via delay)
        deliver_spikes();

        // 4) Apply post-spike STDP (posts that spiked this step)
        apply_post_spike_stdp();

        // 5) Decay traces for all synapses
        decay_all_traces();

        // 6) Advance time
        t_ms += dt_ms;
    }

    // Utility: build a random network with given E/I ratio and connection probability
    void build_random_network(std::size_t N, float p_connect, float frac_excitatory,
                              float w_exc = 0.02f, float w_inh = 0.02f,
                              std::size_t max_delay_slots_ = 1, unsigned seed = 0) {
        rng.seed(seed);
        max_delay_slots = std::max<std::size_t>(1, max_delay_slots_);
        // Create neurons
        std::size_t Ne = static_cast<std::size_t>(std::round(frac_excitatory * N));
        for (std::size_t i = 0; i < N; ++i) {
            bool excit = (i < Ne);
            Neuron proto = excit ? Neuron::RegularSpiking("E" + std::to_string(i), true)
                                 : Neuron::FastSpiking("I" + std::to_string(i));
            proto.set_delay_slots(max_delay_slots);
            add_neuron(proto);
        }
        std::bernoulli_distribution coin(p_connect);
        std::uniform_int_distribution<std::size_t> delay_dist(0, max_delay_slots - 1);
        for (std::size_t i = 0; i < N; ++i) {
            for (std::size_t j = 0; j < N; ++j) {
                if (i == j) continue;
                if (coin(rng)) {
                    bool inhib = !neurons[i]->is_excitatory;
                    float w = inhib ? w_inh : w_exc;
                    connect(neurons[i].get(), neurons[j].get(), w, delay_dist(rng), inhib);
                }
            }
        }
    }
};

// Example usage demonstrating dynamic connect/disconnect and network stepping
int main() {
    Network net;
    net.set_dt(1.0f);        // ms
    net.set_max_delay_ms(5); // optional ring buffer size

    // Create a small primitive circuit: sensory (E), interneuron (E), motor (E), and inhibitory (I)
    Neuron sensory = Neuron::RegularSpiking("sensory", true); sensory.tonic_current = 5.0f; // tonic drive
    Neuron inter   = Neuron::RegularSpiking("inter", true);
    Neuron motor   = Neuron::RegularSpiking("motor", true);
    Neuron inhibit = Neuron::FastSpiking("inhib");

    Neuron* n_sens = net.add_neuron(sensory);
    Neuron* n_int  = net.add_neuron(inter);
    Neuron* n_motor= net.add_neuron(motor);
    Neuron* n_inh  = net.add_neuron(inhibit);

    // Dynamically connect
    Synapse* s1 = net.connect(n_sens, n_int,   0.05f, 1, false); // E -> E
    Synapse* s2 = net.connect(n_int,  n_motor, 0.05f, 2, false); // E -> E with delay
    Synapse* s3 = net.connect(n_inh,  n_motor, 0.03f, 1, true ); // I -> E

    // Run a short simulation and then rewire
    for (int t = 0; t < 200; ++t) {
        // After 100 ms, disconnect inhibitory synapse to emulate disinhibition
        if (t == 100) {
            net.disconnect(s3);
            // Connect sensory directly to motor
            net.connect(n_sens, n_motor, 0.04f, 1, false);
        }
        net.step();
        // Simple probe: print spikes
        for (auto& n : net.neurons) {
            if (n->spiked) std::cout << net.t_ms << "," << n->name << "\n";
        }
    }

    return 0;
}

Notes on biological relevance and performance:
- Relation to primitive nervous systems: Each Neuron approximates a spiking cell with membrane potential v and recovery variable u capturing ion-channel dynamics. Synapses transmit pulses (currents) with delays; STDP adjusts weights based on relative spike timing, enabling reflex-like learning and adaptation seen in simple animals.
- Accuracy: Implements canonical Izhikevich equations with reset v<-c, u<-u+d and supports RS/FS presets. dt=1 ms is common; reduce dt for higher fidelity if needed.
- Dynamic connectivity: connect/disconnect operate in O(1) by tracking indices; safe in running simulations (avoid modifying while iterating if you extend stepping loops).
- Error handling: asserts for basic invariants; in production, replace with exceptions and checks (e.g., null pointers, bounds on weights and delays).
- Scalability: Vectors and contiguous ownership minimize overhead. For large networks, consider: reserving capacities, event-driven spike queues, partitioned loops, and OpenMP/TBB for parallel neuron updates.
- Memory/compute efficiency: Per-neuron ring buffers avoid per-synapse queues; STDP tracks two scalars per synapse. Compile with -O3 and prefer structure-of-arrays if profiling indicates cache bottlenecks.

Below is a complete, self-contained Go program that compiles and runs. It implements a genetic algorithm (GA) for weight budgeting (e.g., portfolio allocation). It enforces per-asset min/max bounds and the simplex constraint that weights sum to 1, while maximizing expected return minus a risk penalty on variance.

You can save this as main.go and run with: go run main.go

```go
// main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"sort"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Create a random feasible weight vector summing to 1 within bounds.
func randomFeasibleWeights(n int, minW, maxW []float64) []float64 {
	w := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		w[i] = rand.Float64() + 1e-12
		sum += w[i]
	}
	for i := 0; i < n; i++ {
		w[i] /= sum
	}
	projectToSimplexWithBounds(w, minW, maxW)
	return w
}

// Projects a vector w onto the bounded simplex: sum=1, minW[i] <= w[i] <= maxW[i].
// Uses bisection on a Lagrange multiplier tau: y_i = clip(w_i - tau, [minW_i,maxW_i]) so that sum y_i = 1.
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Feasibility checks
	sumMin, sumMax := 0.0, 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		copy(w, maxW)
		return
	}

	// Compute tau bounds
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]
		high := w[i] - minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	for iter := 0; iter < 60; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		s := 0.0
		for i := 0; i < n; i++ {
			val := w[i] - tau
			if val < minW[i] {
				val = minW[i]
			}
			if val > maxW[i] {
				val = maxW[i]
			}
			s += val
		}
		if s > 1.0 {
			// Decrease sum -> increase tau
			tauLow = tau
		} else {
			// Increase sum -> decrease tau
			tauHigh = tau
		}
	}

	tau := 0.5 * (tauLow + tauHigh)
	sum := 0.0
	for i := 0; i < n; i++ {
		val := w[i] - tau
		if val < minW[i] {
			val = minW[i]
		}
		if val > maxW[i] {
			val = maxW[i]
		}
		w[i] = val
		sum += val
	}
	// Normalize (numeric safeguard)
	if sum != 0 {
		for i := 0; i < n; i++ {
			w[i] /= sum
		}
	}
}

// Tournament selection (maximization): pick 'k' random individuals, return the best
func tournamentSelect(pop []Individual, k int) Individual {
	best := pop[rand.Intn(len(pop))]
	for i := 1; i < k; i++ {
		cand := pop[rand.Intn(len(pop))]
		if cand.Fitness > best.Fitness {
			best = cand
		}
	}
	return best
}

// Uniform crossover: for each gene, pick from parent1 or parent2 with p=0.5
func uniformCrossover(p1, p2 Individual) (Individual, Individual) {
	n := len(p1.Weights)
	c1 := Individual{Weights: make([]float64, n)}
	c2 := Individual{Weights: make([]float64, n)}
	for i := 0; i < n; i++ {
		if rand.Intn(2) == 0 {
			c1.Weights[i] = p1.Weights[i]
			c2.Weights[i] = p2.Weights[i]
		} else {
			c1.Weights[i] = p2.Weights[i]
			c2.Weights[i] = p1.Weights[i]
		}
	}
	return c1, c2
}

// Gaussian mutation with probability 'rate' per gene, then clip to bounds later by projection
func mutate(ind *Individual, rate, sigma float64) {
	for i := range ind.Weights {
		if rand.Float64() < rate {
			ind.Weights[i] += rand.NormFloat64() * sigma
		}
	}
}

// Population utilities
func copyIndividual(ind Individual) Individual {
	w := make([]float64, len(ind.Weights))
	copy(w, ind.Weights)
	return Individual{Weights: w, Fitness: ind.Fitness}
}

func sortByFitness(pop []Individual) []Individual {
	sorted := make([]Individual, len(pop))
	copy(sorted, pop)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Fitness > sorted[j].Fitness })
	return sorted
}

func bestIndividual(pop []Individual) Individual {
	best := pop[0]
	for i := 1; i < len(pop); i++ {
		if pop[i].Fitness > best.Fitness {
			best = pop[i]
		}
	}
	return best
}

// Math helpers
func dot(a, b []float64) float64 {
	s := 0.0
	for i := range a {
		s += a[i] * b[i]
	}
	return s
}

func quadForm(w []float64, cov [][]float64) float64 {
	s := 0.0
	for i := 0; i < len(w); i++ {
		for j := 0; j < len(w); j++ {
			s += w[i] * cov[i][j] * w[j]
		}
	}
	return s
}

func pretty(w []float64) string {
	out := "["
	for i, v := range w {
		if i > 0 {
			out += ", "
		}
		out += fmt.Sprintf("%.3f", v)
	}
	out += "]"
	return out
}
