intSLPercentage  = (intStopLoss * 100.0) / acctEquity
allocPercent     = enterLong ? math.max(intSLPercentage, brokerCommissionFrac * 100.0) : na
qtyContracts     = na(allocPercent) ? na : ((allocPercent / 100.0) * acctEquity) / close

strategy.entry(
