    if (out.empty()) {
        // Provide at least one stub entry so later steps can continue
        RelayMicrodescRef r; r.fingerprint = "FAKEFPR"; r.address = "1.1.1.1"; r.orport = 9001; out.push_back(r);
    }
    return out;
}

// HSv3 address parsing helpers
// A v3 onion address is base32 of: PUBKEY(32) || CHECKSUM(2) || VERSION(1) where version=3, then ".onion"
static bool parse_onion_address_v3(const std::string& onion, std::vector<unsigned char>& ed25519_pubkey_out) {
    std::string s = onion;
    if (s.size() > 6 && s.substr(s.size()-6) == ".onion") s.resize(s.size()-6);
    if (s.size() != 56) return false; // v3 host length (no suffix)
    auto decoded = base32_decode(s);
    if (decoded.size() != 35) return false;
    // Verify version byte == 3
    if (decoded[34] != 0x03) return false;
    // Verify checksum = truncated SHA3 of ("onion checksum" || pubkey || version)
    // Tor spec uses SHA3-256 and takes first 2 bytes. We'll compute and check.
    const unsigned char prefix[] = {'o','n','i','o','n',' ','c','h','e','c','k','s','u','m'};
    std::vector<unsigned char> buf; buf.insert(buf.end(), prefix, prefix+15);
    buf.insert(buf.end(), decoded.begin(), decoded.begin()+32); // pubkey
    buf.push_back(0x03);

    // Use OpenSSL SHA3-256
    unsigned char md[EVP_MAX_MD_SIZE]; unsigned int mdlen=0;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new(); if (!ctx) throw OpenSslLastError("EVP_MD_CTX_new");
    bool ok=true;
    do {
        if (EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) != 1) { ok=false; break; }
        if (EVP_DigestUpdate(ctx, buf.data(), buf.size()) != 1) { ok=false; break; }
        if (EVP_DigestFinal_ex(ctx, md, &mdlen) != 1) { ok=false; break; }
    } while (0);
    EVP_MD_CTX_free(ctx);
    if (!ok || mdlen < 2) return false;
    if (md[0] != decoded[32] || md[1] != decoded[33]) return false;

    ed25519_pubkey_out.assign(decoded.begin(), decoded.begin()+32);
    return true;
}

// Descriptor ID calculation (illustrative only). Real HSDir selection requires blinding and time periods.
static std::string compute_descriptor_id_demo(const std::vector<unsigned char>& ed25519_pubkey) {
    // For demonstration, compute SHA3-256(pubkey) and base32 it to resemble an ID.
    unsigned char md[EVP_MAX_MD_SIZE]; unsigned int mdlen=0;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new(); if (!ctx) throw OpenSslLastError("EVP_MD_CTX_new");
    if (EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) != 1) { EVP_MD_CTX_free(ctx); throw OpenSslLastError("EVP_DigestInit_ex"); }
    if (EVP_DigestUpdate(ctx, ed25519_pubkey.data(), ed25519_pubkey.size()) != 1) { EVP_MD_CTX_free(ctx); throw OpenSslLastError("EVP_DigestUpdate"); }
    if (EVP_DigestFinal_ex(ctx, md, &mdlen) != 1) { EVP_MD_CTX_free(ctx); throw OpenSslLastError("EVP_DigestFinal_ex"); }
    EVP_MD_CTX_free(ctx);
    std::vector<unsigned char> v(md, md+mdlen);
    return base32_encode(v);
}

// Download a v3 HS descriptor (illustrative): In reality, you'd pick HSDirs from the consensus ring and use
// Tor directory protocol over HTTPS to hsdir:443/tor/hs/3/<desc-id>. Here we show an HTTPS GET pattern only.
static std::string download_hs_descriptor_demo(const std::string& desc_id_b32) {
    // Use a non-authoritative placeholder host; in reality HSDirs are Tor relays that serve descriptors.
    // We demonstrate URL construction and robust error handling only.
    const std::wstring host = L"example.com"; // placeholder; no real descriptor will be served
    std::wstring path = L"/tor/hs/3/";
    // Convert desc_id to wide
    std::wstring descw(desc_id_b32.begin(), desc_id_b32.end());
    path += descw;
    try {
        return WinHttpRequest(host, INTERNET_DEFAULT_HTTPS_PORT, path, L"GET", L"", "", true);
    } catch (const std::exception&) {
        // Return empty to simulate 'not found' and allow parser to run with guard rails
        return std::string();
    }
}

// Minimal descriptor parser stub: extract introduction points, auth keys, etc. Here we only demonstrate structure.
struct HSDescriptorDemo { bool valid=false; std::vector<std::string> intro_points; };

static HSDescriptorDemo parse_hs_descriptor_demo(const std::string& text) {
    HSDescriptorDemo d; if (text.empty()) return d;
    std::istringstream iss(text); std::string line;
    while (std::getline(iss, line)) {
        if (line.find("introduction-point") != std::string::npos) {
            d.intro_points.push_back("ip-placeholder");
        }
    }
    d.valid = !d.intro_points.empty();
    return d;
}

// Demonstrate GET/POST to a .onion using WinHTTP. Without Tor, DNS will fail. We therefore show the mechanics
// and robust error handling. Real operation requires routing via Tor (e.g., SOCKS5 to Tor) which WinHTTP alone
// cannot provide.
static void demo_onion_get_post(const std::string& onion_host_no_suffix) {
    // Convert to wide
    std::wstring hostw(onion_host_no_suffix.begin(), onion_host_no_suffix.end());
    hostw += L".onion"; // Show intent; this will not resolve without Tor

    try {
        std::string resp = WinHttpRequest(hostw, INTERNET_DEFAULT_HTTPS_PORT, L"/", L"GET", L"", "", true, 10000);
        std::cout << "GET to .onion response size: " << resp.size() << "\n";
    } catch (const std::exception& e) {
        std::cerr << "GET to .onion failed (expected without Tor): " << e.what() << "\n";
    }

    try {
        std::string body = "{""ping"":""pong""}";
        std::wstring hdrs = L"Content-Type: application/json\r\n";
        std::string resp = WinHttpRequest(hostw, INTERNET_DEFAULT_HTTPS_PORT, L"/echo", L"POST", hdrs, body, true, 10000);
        std::cout << "POST to .onion response size: " << resp.size() << "\n";
    } catch (const std::exception& e) {
        std::cerr << "POST to .onion failed (expected without Tor): " << e.what() << "\n";
    }
}

