    // Initialize OpenSSL
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();
    EVP_default_properties_enable_fips(nullptr, 0); // ensure default properties; not enabling FIPS here

    try {
        // 1) Download consensus (illustrative) and parse
        std::cout << "Downloading consensus (demo)...\n";
        std::string consensus = download_consensus_example();
        std::cout << "Consensus bytes: " << consensus.size() << "\n";
        auto relays = parse_consensus_minimal(consensus);
        std::cout << "Parsed relays (demo): " << relays.size() << "\n";

        // 2) Parse onion address
        const std::string onion = (argc > 1) ? argv[1] : "exampleexampleexampleexampleexampleexampleexample.onion";
        std::vector<unsigned char> ed25519_pk;
        if (!parse_onion_address_v3(onion, ed25519_pk)) {
            std::cerr << "Invalid v3 onion address: " << onion << "\n";
        } else {
            std::cout << "Parsed onion v3 pubkey (32 bytes).\n";
        }

        // 3) Compute descriptor ID (demo) and attempt to download descriptor
        std::string desc_id_b32 = ed25519_pk.empty() ? std::string("") : compute_descriptor_id_demo(ed25519_pk);
        if (!desc_id_b32.empty()) {
            std::cout << "Descriptor ID (demo, base32): " << desc_id_b32.substr(0, 16) << "...\n";
            std::string desc_text = download_hs_descriptor_demo(desc_id_b32);
            HSDescriptorDemo d = parse_hs_descriptor_demo(desc_text);
            std::cout << "Descriptor valid (demo): " << (d.valid ? "yes" : "no") << ", intro points: " << d.intro_points.size() << "\n";
        } else {
            std::cout << "Skipping descriptor download (no pubkey).\n";
        }

        // 4) Demonstrate GET/POST mechanics to a .onion host using WinHTTP (will fail without Tor)
        std::string onion_host = onion;
        if (onion_host.size() > 6 && onion_host.substr(onion_host.size()-6)==".onion") onion_host.resize(onion_host.size()-6);
        demo_onion_get_post(onion_host);

    } catch (const std::exception& e) {
        std::cerr << "Fatal error: " << e.what() << "\n";
        EVP_cleanup();
        ERR_free_strings();
        return EXIT_FAILURE;
    }

    EVP_cleanup();
    ERR_free_strings();
    return EXIT_SUCCESS;
}

