// -------------------- Base64 helpers (OpenSSL) --------------------
static std::vector<unsigned char> Base64Decode(const std::string& b64) {
    std::vector<unsigned char> out;
    BIO* b64bio = BIO_new(BIO_f_base64());
    BIO* membio = BIO_new_mem_buf(b64.data(), (int)b64.size());
    if (!b64bio || !membio) {
        if (b64bio) BIO_free(b64bio);
        if (membio) BIO_free(membio);
        return out;
    }
    BIO_set_flags(b64bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_push(b64bio, membio);

    out.resize(b64.size());
    int n = BIO_read(b64bio, out.data(), (int)out.size());
    if (n <= 0) {
        out.clear();
    } else {
        out.resize((size_t)n);
    }
    BIO_free_all(b64bio);
    return out;
}

// -------------------- URL parsing --------------------
struct ParsedUrl {
    std::wstring scheme;   // L"http" or L"https"
    std::wstring host;     // domain or .onion
    INTERNET_PORT port{0};
    std::wstring path;     // starts with '/'
};

static bool ParseUrl(const std::wstring& url, ParsedUrl& out) {
    out = {};
    const std::wstring http = L"http://";
    const std::wstring https = L"https://";
    size_t pos = std::wstring::npos;
    bool is_https = false;
    if (url.rfind(https, 0) == 0) { is_https = true; pos = https.size(); out.scheme = L"https"; out.port = 443; }
    else if (url.rfind(http, 0) == 0) { is_https = false; pos = http.size(); out.scheme = L"http"; out.port = 80; }
    else return false;

    size_t slash = url.find(L'/', pos);
    std::wstring hostport = (slash == std::wstring::npos) ? url.substr(pos) : url.substr(pos, slash - pos);
    out.path = (slash == std::wstring::npos) ? L"/" : url.substr(slash);

    size_t colon = hostport.rfind(L':');
    if (colon != std::wstring::npos) {
        out.host = hostport.substr(0, colon);
        std::wstring p = hostport.substr(colon + 1);
        out.port = (INTERNET_PORT)std::stoi(p);
    } else {
        out.host = hostport;
    }
    return true;
}

// -------------------- WinHTTP request helpers --------------------
static bool HttpRequest(const std::wstring& method,
                        const std::wstring& url,
                        const std::wstring& headers,
                        const std::string& body,
                        std::wstring& o_status,
                        std::map<std::wstring, std::wstring>& o_headers,
                        std::string& o_body) {
    o_status.clear();
    o_headers.clear();
    o_body.clear();

    ParsedUrl u;
    if (!ParseUrl(url, u)) {
        std::wcerr << L"Invalid URL: " << url << L"\n";
        return false;
    }

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP Tor Client/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) {
        std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n";
        return false;
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, u.host.c_str(), u.port, 0));
    if (!hConnect) {
        std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n";
        return false;
    }

    DWORD flags = (u.scheme == L"https") ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), u.path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) {
        std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    if (!headers.empty()) {
        if (!WinHttpAddRequestHeaders(hRequest, headers.c_str(), (ULONG)-1L, WINHTTP_ADDREQ_FLAG_ADD)) {
            std::wcerr << L"WinHttpAddRequestHeaders failed: " << FormatLastError() << L"\n";
            return false;
        }
    }

    LPCVOID optBody = body.empty() ? WINHTTP_NO_REQUEST_DATA : body.data();
    DWORD bodyLen = static_cast<DWORD>(body.size());

    if (!WinHttpSendRequest(hRequest,
                            headers.empty() ? WINHTTP_NO_ADDITIONAL_HEADERS : headers.c_str(),
                            headers.empty() ? 0 : (DWORD)-1,
                            (LPVOID)optBody,
                            bodyLen,
                            bodyLen,
                            0)) {
        DWORD err = GetLastError();
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n";
        if (err == ERROR_WINHTTP_NAME_NOT_RESOLVED)
            std::wcerr << L"Name not resolved (host: " << u.host << L")\n";
        return false;
    }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n";
        return false;
    }

    // Status code and reason
    DWORD statusCode = 0; DWORD size = sizeof(statusCode);
    if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                            WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &size, WINHTTP_NO_HEADER_INDEX)) {
        o_status = std::to_wstring(statusCode);
    }

    // Read headers block
    DWORD dwSize = 0;
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX,
                        WINHTTP_NO_OUTPUT_BUFFER, &dwSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::wstring headerBlock; headerBlock.resize(dwSize / sizeof(wchar_t));
        if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX,
                                &headerBlock[0], &dwSize, WINHTTP_NO_HEADER_INDEX)) {
            // Parse headers into map
            std::wstringstream ss(headerBlock);
            std::wstring line;
            bool first = true;
            while (std::getline(ss, line)) {
                if (first) { first = false; continue; }
                if (line.empty()) continue;
                size_t c = line.find(L':');
                if (c != std::wstring::npos) {
                    std::wstring name = line.substr(0, c);
                    std::wstring val = line.substr(c + 1);
                    while (!val.empty() && (val[0] == L' ' || val[0] == L'\t')) val.erase(val.begin());
                    if (!name.empty() && !val.empty()) o_headers[name] = val;
                }
            }
        }
    }

    // Read body
    std::string result;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (avail == 0) break;
        std::vector<char> buf(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, buf.data(), avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        result.append(buf.data(), buf.data() + read);
    }
    o_body.swap(result);
    return true;
}

static bool HttpGet(const std::wstring& url, std::string& bodyOut) {
    std::wstring status; std::map<std::wstring, std::wstring> hdrs; std::string body;
    bool ok = HttpRequest(L"GET", url, L"", "", status, hdrs, body);
    if (!ok) return false;
    bodyOut = std::move(body);
    return true;
}

static bool HttpPost(const std::wstring& url, const std::string& data, std::string& bodyOut) {
    std::wstring status; std::map<std::wstring, std::wstring> hdrs; std::string body;
    std::wstring headers = L"Content-Type: application/x-www-form-urlencoded\r\n";
    bool ok = HttpRequest(L"POST", url, headers, data, status, hdrs, body);
    if (!ok) return false;
    bodyOut = std::move(body);
    return true;
}

// -------------------- Tor consensus minimal parser --------------------
struct RelayEntry { std::string nickname; std::string fingerprint; std::string address; };
struct ConsensusSummary { std::string valid_after; std::string fresh_until; std::vector<RelayEntry> relays; };

static ConsensusSummary ParseConsensus(const std::string& text) {
    ConsensusSummary s;
    std::istringstream in(text);
    std::string line;
    RelayEntry current;
    while (std::getline(in, line)) {
        if (line.rfind("valid-after ", 0) == 0) {
            s.valid_after = line.substr(strlen("valid-after "));
        } else if (line.rfind("fresh-until ", 0) == 0) {
            s.fresh_until = line.substr(strlen("fresh-until "));
        } else if (line.rfind("r ", 0) == 0) {
            // r nickname identity digest publication IP ORPort DirPort
            std::istringstream ls(line);
            std::string rtag; ls >> rtag;
            RelayEntry re; ls >> re.nickname; std::string idb64, pub; ls >> idb64 >> pub; ls >> re.address; // ignore rest
            s.relays.push_back(re);
        }
    }
    return s;
}

// -------------------- Tor HSv3 descriptor minimal parser --------------------
struct HSv3Descriptor {
    std::string hs_desc; // version line
    std::string create2_formats;
    std::string intro_points_b64;
};

static HSv3Descriptor ParseHSv3Descriptor(const std::string& text) {
    HSv3Descriptor d;
    std::istringstream in(text);
    std::string line;
    bool in_intro = false;
    std::string intro_b64;
    while (std::getline(in, line)) {
        if (line.rfind("hs-descriptor ", 0) == 0) d.hs_desc = line.substr(strlen("hs-descriptor "));
        else if (line.rfind("create2-formats ", 0) == 0) d.create2_formats = line.substr(strlen("create2-formats "));
        else if (line == "introduction-points") { in_intro = true; intro_b64.clear(); }
        else if (in_intro && line == "-----END MESSAGE-----") { in_intro = false; d.intro_points_b64 = intro_b64; }
        else if (in_intro) { if (!line.empty()) { if (line.find("BEGIN") == std::string::npos) { intro_b64 += line; } } }
    }
    return d;
}

// -------------------- Main demonstrating required actions --------------------
int wmain(int argc, wchar_t* argv[]) {
    OpenSSLGlobalInit _ssl_init;

    // Minimal CLI:
    //  --consensus <url>
    //  --descriptor <url>
    //  --get <url>
    //  --post <url> <data>

    std::wstring consensusUrl;
    std::wstring descriptorUrl;
    std::wstring getUrl;
    std::wstring postUrl; std::string postData;

    for (int i = 1; i < argc; ++i) {
        std::wstring a = argv[i];
        if (a == L"--consensus" && i + 1 < argc) { consensusUrl = argv[++i]; }
        else if (a == L"--descriptor" && i + 1 < argc) { descriptorUrl = argv[++i]; }
        else if (a == L"--get" && i + 1 < argc) { getUrl = argv[++i]; }
        else if (a == L"--post" && i + 2 < argc) { postUrl = argv[++i];
            // Convert wide to UTF-8 for data
            std::wstring wd = argv[++i];
            int len = WideCharToMultiByte(CP_UTF8, 0, wd.c_str(), -1, nullptr, 0, nullptr, nullptr);
            std::string utf8(len ? (size_t)len - 1 : 0, '\0');
            if (len) WideCharToMultiByte(CP_UTF8, 0, wd.c_str(), -1, utf8.data(), len, nullptr, nullptr);
            postData = std::move(utf8);
        }
    }

    bool any = false;

    if (!consensusUrl.empty()) {
        any = true;
        std::wcout << L"Downloading consensus from: " << consensusUrl << L"\n";
        std::string body;
        if (!HttpGet(consensusUrl, body)) {
            std::wcerr << L"Failed to download consensus." << L"\n";
            return 1;
        }
        auto cons = ParseConsensus(body);
        std::wcout << L"Consensus valid-after: " << std::wstring(cons.valid_after.begin(), cons.valid_after.end()) << L"\n";
        std::wcout << L"Consensus fresh-until: " << std::wstring(cons.fresh_until.begin(), cons.fresh_until.end()) << L"\n";
        std::wcout << L"Relays parsed: " << cons.relays.size() << L"\n";
        if (!cons.relays.empty()) {
            const auto& r = cons.relays.front();
            std::wcout << L"Example relay: " << std::wstring(r.nickname.begin(), r.nickname.end())
                       << L" IP: " << std::wstring(r.address.begin(), r.address.end()) << L"\n";
        }
    }

    if (!descriptorUrl.empty()) {
        any = true;
        std::wcout << L"Downloading v3 descriptor from: " << descriptorUrl << L"\n";
        std::string body;
        if (!HttpGet(descriptorUrl, body)) {
            std::wcerr << L"Failed to download descriptor." << L"\n";
            return 1;
        }
        auto d = ParseHSv3Descriptor(body);
        std::wcout << L"Descriptor hs-descriptor: " << std::wstring(d.hs_desc.begin(), d.hs_desc.end()) << L"\n";
        std::wcout << L"Descriptor create2-formats: " << std::wstring(d.create2_formats.begin(), d.create2_formats.end()) << L"\n";
        if (!d.intro_points_b64.empty()) {
            auto decoded = Base64Decode(d.intro_points_b64);
            std::wcout << L"Introduction points decoded bytes: " << decoded.size() << L"\n";
        } else {
            std::wcout << L"No introduction-points block found." << L"\n";
        }
    }

    if (!getUrl.empty()) {
        any = true;
        std::wcout << L"GET: " << getUrl << L"\n";
        std::string body;
        if (!HttpGet(getUrl, body)) {
            std::wcerr << L"GET failed." << L"\n";
            return 1;
        }
        std::wcout << L"GET bytes: " << body.size() << L"\n";
    }

    if (!postUrl.empty()) {
        any = true;
        std::wcout << L"POST: " << postUrl << L"\n";
        std::string body;
        if (!HttpPost(postUrl, postData, body)) {
            std::wcerr << L"POST failed." << L"\n";
            return 1;
        }
        std::wcout << L"POST response bytes: " << body.size() << L"\n";
    }

    if (!any) {
        std::wcout << L"Usage:\n"
                   << L"  --consensus <http(s) URL to Tor consensus>\n"
                   << L"  --descriptor <http(s) URL to HSv3 descriptor>\n"
                   << L"  --get <http(s) URL (including .onion if resolvable in your env)>\n"
                   << L"  --post <http(s) URL> <data>\n";
    }

    return 0;
}

