// -------------------- High-level helpers --------------------
static bool DownloadAndParseConsensus(const std::string& url) {
    auto wurl = Utf8ToWide(url);
    auto r = HttpRequest(L"GET", wurl);
    if (r.status != 200) {
        std::cerr << "Consensus download failed, HTTP " << r.status << "\n";
        return false;
    }
    auto ci = ParseConsensus(r.body);
    std::cout << "Consensus: valid-after=" << ci.valid_after
              << ", fresh-until=" << ci.fresh_until
              << ", valid-until=" << ci.valid_until
              << ", routers=" << ci.router_count << "\n";
    return true;
}

static bool DownloadAndParseDescriptor(const std::string& url) {
    auto wurl = Utf8ToWide(url);
    auto r = HttpRequest(L"GET", wurl);
    if (r.status != 200) {
        std::cerr << "Descriptor download failed, HTTP " << r.status << "\n";
        return false;
    }
    auto di = ParseDescriptor(r.body);
    std::cout << "Descriptor: id=" << di.desc_id << ", create-time=" << di.create_time << "\n";
    std::cout << "Intro points detected: " << di.intro_points_b64.size() << "\n";
    return true;
}

static void DoHttpGet(const std::string& url) {
    auto r = HttpRequest(L"GET", Utf8ToWide(url));
    std::cout << "GET status=" << r.status << ", bytes=" << r.body.size() << "\n";
}

static void DoHttpPost(const std::string& url, const std::string& payload) {
    auto r = HttpRequest(L"POST", Utf8ToWide(url), payload, L"application/x-www-form-urlencoded");
    std::cout << "POST status=" << r.status << ", bytes=" << r.body.size() << "\n";
}

// -------------------- main --------------------
int wmain(int argc, wchar_t* argv[]) {
    OpenSSLInit ossl;

    std::vector<std::wstring> args(argv+1, argv+argc);
    auto nextArg = [&](const std::wstring& flag)->std::optional<std::wstring>{
        for (size_t i=0;i<args.size();++i){ if (args[i]==flag && i+1<args.size()) return args[i+1]; }
        return std::nullopt;
    };

    bool did=false;

    if (auto v = nextArg(L"--validate-onion")) {
        std::string h = WideToUtf8(*v);
        auto inf = ParseOnionV3(h);
        if (!inf) {
            std::cout << "Invalid v3 .onion: " << h << "\n";
        } else {
            std::cout << "Valid v3 .onion: " << h << "; version=" << (int)inf->version << "\n";
        }
        did=true;
    }

    if (auto v = nextArg(L"--consensus-url")) {
        did = DownloadAndParseConsensus(WideToUtf8(*v)) || did;
    }

    if (auto v = nextArg(L"--descriptor-url")) {
        did = DownloadAndParseDescriptor(WideToUtf8(*v)) || did;
    }

    if (auto v = nextArg(L"--get")) {
        DoHttpGet(WideToUtf8(*v)); did=true;
    }

    if (auto v = nextArg(L"--post")) {
        // Expect payload next
        std::string url = WideToUtf8(*v);
        std::string payload;
        for (size_t i=0;i<args.size();++i) if (args[i]==L"--post" && i+2<args.size()) { payload = WideToUtf8(args[i+2]); break; }
        DoHttpPost(url, payload); did=true;
    }

    if (!did) {
        std::cout << "Usage:\n"
                  << "  --consensus-url <https-url>\n"
                  << "  --descriptor-url <https-url>\n"
                  << "  --validate-onion <host.onion>\n"
                  << "  --get <url>\n"
                  << "  --post <url> <payload>\n";
    }

    return 0;
}

