// -------------------- Error formatters --------------------
static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

// -------------------- RAII handles --------------------
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept {
        if (this != &o) { if (h) WinHttpCloseHandle(h); h = o.h; o.h = nullptr; }
        return *this;
    }
    operator HINTERNET() const { return h; }
};

// -------------------- URL parser --------------------
struct ParsedUrl {
    std::wstring host;
    std::wstring path;
    INTERNET_PORT port{0};
    bool https{false};
};
static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTS uc{};
    wchar_t host[512]{};
    wchar_t path[4096]{};
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    uc.dwSchemeLength = (DWORD)-1;
    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    out.path.clear();
    if (uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    out.port = uc.nPort;
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    if (out.path.empty()) out.path = L"/";
    return true;
}

// -------------------- WinHTTP client --------------------
struct HttpResponse { DWORD status{0}; std::string headers; std::string body; };

static bool HttpRequestWinHttp(const std::wstring& url, const std::wstring& method, const std::string* body,
                               const std::vector<std::pair<std::wstring,std::wstring>>* extra_headers,
                               HttpResponse& out,
                               const std::wstring& proxy = L"",
                               INTERNET_PORT proxy_port = 0) {
    ParsedUrl pu{};
    if (!CrackUrl(url, pu)) return false;

    DWORD access = WINHTTP_ACCESS_TYPE_DEFAULT_PROXY;
    WINHTTP_PROXY_INFO proxyInfo{};
    WINHTTP_AUTOPROXY_OPTIONS autoProxy{};

    WinHttpHandle hSession(WinHttpOpen(L"tor_onion_tool/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    if (!proxy.empty()) {
        std::wstring proxyStr = proxy + L":" + std::to_wstring(proxy_port);
        proxyInfo.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY;
        proxyInfo.lpszProxy = (LPWSTR)proxyStr.c_str();
        proxyInfo.lpszProxyBypass = (LPWSTR)L"<local>";
        if (!WinHttpSetOption(hSession, WINHTTP_OPTION_PROXY, &proxyInfo, sizeof(proxyInfo))) {
            std::wcerr << L"WinHttpSetOption(PROXY) failed: " << FormatLastError() << L"\n";
            return false;
        }
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, pu.host.c_str(), pu.port ? pu.port : (pu.https ? INTERNET_DEFAULT_HTTPS_PORT : INTERNET_DEFAULT_HTTP_PORT), 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), pu.path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              pu.https ? WINHTTP_FLAG_SECURE : 0));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID;
    WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &flags, sizeof(flags));

    std::wstringstream hdrs;
    if (extra_headers) {
        for (auto& kv : *extra_headers) {
            hdrs << kv.first << L": " << kv.second << L"\r\n";
        }
    }
    std::wstring hdrStr = hdrs.str();

    BOOL sent = FALSE;
    if (body) {
        sent = WinHttpSendRequest(hRequest, hdrStr.empty()? WINHTTP_NO_ADDITIONAL_HEADERS : hdrStr.c_str(), (DWORD)-1,
                                  (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
    } else {
        sent = WinHttpSendRequest(hRequest, hdrStr.empty()? WINHTTP_NO_ADDITIONAL_HEADERS : hdrStr.c_str(), (DWORD)-1,
                                  WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!sent) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD statusCode = 0; DWORD len = sizeof(statusCode);
    if (!WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX)) {
        std::wcerr << L"WinHttpQueryHeaders(status) failed: " << FormatLastError() << L"\n"; return false; }
    out.status = statusCode;

    std::string headers;
    DWORD dwSize = 0;
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &dwSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER && dwSize) {
        std::wstring hbuf; hbuf.resize(dwSize/sizeof(wchar_t));
        if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &hbuf[0], &dwSize, WINHTTP_NO_HEADER_INDEX)) {
            headers = WideToUtf8(hbuf);
        }
    }
    out.headers = headers;

    std::string bodyBuf;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) { std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (!avail) break;
        std::string chunk; chunk.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, &chunk[0], avail, &read)) { std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        chunk.resize(read);
        bodyBuf.append(chunk);
    }
    out.body = std::move(bodyBuf);
    return true;
}

// -------------------- Base32 (RFC4648, lowercase) for .onion --------------------
static int Base32Val(int c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}
static bool Base32Decode(const std::string& in, std::vector<uint8_t>& out) {
    int buffer = 0, bitsLeft = 0; out.clear(); out.reserve(in.size()*5/8+8);
    for (char ch : in) {
        if (ch == '=' || ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' || ch == '-') continue;
        int v = Base32Val(ch);
        if (v < 0) return false;
        buffer = (buffer << 5) | v; bitsLeft += 5;
        if (bitsLeft >= 8) { bitsLeft -= 8; out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF)); }
    }
    return true;
}
static std::string ToLower(std::string s) { std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){return (char)std::tolower(c);}); return s; }

// -------------------- v3 .onion validation --------------------
// v3 address: base32(lowercase) of pubkey(32) || checksum(2) || version(1), total 35 bytes -> 56 chars
// checksum = HsId = truncated SHA3-256(".onion checksum" || pubkey || version) first 2 bytes
static bool ValidateOnionV3(const std::string& onionHost, std::array<uint8_t,32>& pubkeyOut) {
    std::string host = onionHost;
    if (host.size() > 6 && host.substr(host.size()-6) == ".onion") host.resize(host.size()-6);
    host = ToLower(host);
    if (host.size() != 56) return false;
    std::vector<uint8_t> decoded;
    if (!Base32Decode(host, decoded)) return false;
    if (decoded.size() != 35) return false;
    std::array<uint8_t,32> pk{}; memcpy(pk.data(), decoded.data(), 32);
    uint8_t c0 = decoded[32], c1 = decoded[33];
    uint8_t ver = decoded[34];
    if (ver != 3) return false;

    static const uint8_t prefix[] = {'.','o','n','i','o','n',' ','c','h','e','c','k','s','u','m'};
    uint8_t input[sizeof(prefix)+32+1];
    memcpy(input, prefix, sizeof(prefix));
    memcpy(input+sizeof(prefix), pk.data(), 32);
    input[sizeof(prefix)+32] = ver;

    uint8_t digest[32];
    EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
    if (!mdctx) return false;
    bool ok = EVP_DigestInit_ex(mdctx, EVP_sha3_256(), nullptr) == 1 &&
              EVP_DigestUpdate(mdctx, input, sizeof(input)) == 1 &&
              EVP_DigestFinal_ex(mdctx, digest, nullptr) == 1;
    EVP_MD_CTX_free(mdctx);
    if (!ok) return false;
    if (digest[0] != c0 || digest[1] != c1) return false;
    pubkeyOut = pk;
    return true;
}

// -------------------- Simple Tor consensus parsing --------------------
// We extract: valid-after, fresh-until, and a handful of relays lines (r, s, a, v)
static void ParseConsensus(const std::string& txt) {
    std::istringstream iss(txt);
    std::string line;
    std::string valid_after, fresh_until;
    size_t relays = 0;
    while (std::getline(iss, line)) {
        if (line.rfind("valid-after ", 0) == 0) valid_after = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) fresh_until = line.substr(12);
        else if (line.size() && (line[0] == 'r' && (line.size()==1 || line[1]==' '))) {
            relays++;
        }
    }
    std::cout << "Consensus: valid-after=" << valid_after << ", fresh-until=" << fresh_until << ", relays~" << relays << "\n";
}

// -------------------- Hidden service descriptor parsing (v3) --------------------
// We parse header fields and extract base64 sections like signing-key, hs-descriptor, superencrypted, etc.
static void ParseDescriptorV3(const std::string& txt) {
    std::istringstream iss(txt);
    std::string line;
    std::map<std::string,std::string> headers;
    auto trim = [](std::string s){ while(!s.empty() && (s.back()=='\r' || s.back()=='\n' || std::isspace((unsigned char)s.back()))) s.pop_back(); return s; };

    auto readBlock = [&](const std::string& beginTag) -> std::string {
        std::string accum;
        std::string endTag = "-----END "+beginTag.substr(11);
        std::string l;
        while (std::getline(iss, l)) {
            if (trim(l) == endTag) break;
            accum += l + "\n";
        }
        return accum;
    };

    iss.clear(); iss.seekg(0);
    std::vector<std::string> blocksFound;
    while (std::getline(iss, line)) {
        std::string t = trim(line);
        if (t.empty()) continue;
        if (t.rfind("hs-descriptor ", 0) == 0 ||
            t.rfind("descriptor-signing-key ", 0) == 0 ||
            t.rfind("revision-counter ", 0) == 0 ||
            t.rfind("superencrypted ", 0) == 0 ||
            t.rfind("encrypted ", 0) == 0 ||
            t.rfind("signature ", 0) == 0) {
            size_t sp = t.find(' ');
            std::string k = (sp==std::string::npos)? t : t.substr(0, sp);
            headers[k] = t;
        } else if (t.rfind("-----BEGIN ", 0) == 0) {
            std::string block = t;
            std::string data = readBlock(t);
            blocksFound.push_back(block);
        }
    }
    std::cout << "Descriptor headers: " << headers.size() << ", blocks: " << blocksFound.size() << "\n";
}

// -------------------- Helper to download text via WinHTTP --------------------
static bool DownloadText(const std::wstring& url, std::string& out) {
    HttpResponse r;
    std::vector<std::pair<std::wstring,std::wstring>> hdrs = {
        {L"User-Agent", L"tor_onion_tool/1.0"},
        {L"Accept", L"*/*"}
    };
    if (!HttpRequestWinHttp(url, L"GET", nullptr, &hdrs, r)) return false;
    if (r.status < 200 || r.status >= 300) {
        std::wcerr << L"HTTP error: " << r.status << L" from " << url << L"\n";
        return false;
    }
    out = std::move(r.body);
    return true;
}

// -------------------- SOCKS5 CONNECT through WinHTTP proxy option --------------------
// WinHTTP supports named proxy; for .onion we provide http://<host> and supply a SOCKS5 proxy (127.0.0.1:9050).
// The Tor client must be running locally to service SOCKS, but we do not link or call Tor directly.

static bool HttpRequestToOnionViaSocks(const std::wstring& onionUrl, const std::wstring& method, const std::string* body,
                                       HttpResponse& out, const std::wstring& socksHost, INTERNET_PORT socksPort) {
    std::vector<std::pair<std::wstring,std::wstring>> hdrs = {
        {L"User-Agent", L"tor_onion_tool/1.0"},
        {L"Accept", L"*/*"}
    };
    return HttpRequestWinHttp(onionUrl, method, body, &hdrs, out, socksHost, socksPort);
}

// -------------------- CLI --------------------
static void PrintHelp() {
    std::cout << "Usage:\n"
                 "  --consensus-url <url>\n"
                 "  --descriptor-url <url>\n"
                 "  --onion-check <v3.onion>\n"
                 "  --get <url>\n"
                 "  --post <url> <data>\n"
                 "  --get-onion <onion-url> --proxy <host:port>\n"
                 "  --post-onion <onion-url> --data <formencoded> --proxy <host:port>\n";
}

int wmain(int argc, wchar_t** wargv) {
    std::vector<std::wstring> args(wargv, wargv + argc);
    auto arg = [&](const std::wstring& key)->std::wstring {
        for (size_t i=1;i+1<args.size();++i) if (args[i]==key) return args[i+1];
        return L"";
    };

    // OpenSSL init (modern OpenSSL initializes automatically, but keep for clarity)
    ERR_load_CRYPTO_strings(); OpenSSL_add_all_algorithms();

    bool did = false;

    // 1) Download and parse consensus
    if (!arg(L"--consensus-url").empty()) {
        std::wstring url = arg(L"--consensus-url");
        std::string txt;
        if (!DownloadText(url, txt)) return 1;
        ParseConsensus(txt);
        did = true;
    }

    // 2) Download and parse hidden service descriptor
    if (!arg(L"--descriptor-url").empty()) {
        std::wstring url = arg(L"--descriptor-url");
        std::string txt;
        if (!DownloadText(url, txt)) return 1;
        ParseDescriptorV3(txt);
        did = true;
    }

    // 3) Validate a v3 .onion address
    if (!arg(L"--onion-check").empty()) {
        std::string host = WideToUtf8(arg(L"--onion-check"));
        std::array<uint8_t,32> pk{};
        bool ok = ValidateOnionV3(host, pk);
        std::cout << host << ": v3=" << (ok?"ok":"invalid") << "\n";
        did = true;
    }

    // 4) Plain GET/POST via WinHTTP
    if (!arg(L"--get").empty()) {
        std::wstring url = arg(L"--get");
        HttpResponse r;
        if (!HttpRequestWinHttp(url, L"GET", nullptr, nullptr, r)) return 1;
        std::cout << "Status: " << r.status << "\n" << r.body << "\n";
        did = true;
    }
    if (!arg(L"--post").empty()) {
        std::wstring url = arg(L"--post");
        size_t pos = 0; for (size_t i=1;i+2<args.size();++i) if (args[i]==L"--post") { pos = i+2; break; }
        std::string data = (pos<args.size()? WideToUtf8(args[pos]) : std::string());
        HttpResponse r;
        std::vector<std::pair<std::wstring,std::wstring>> hdrs = {{L"Content-Type", L"application/x-www-form-urlencoded"}};
        if (!HttpRequestWinHttp(url, L"POST", &data, &hdrs, r)) return 1;
        std::cout << "Status: " << r.status << "\n" << r.body << "\n";
        did = true;
    }

    // 5) Real GET/POST to .onion via SOCKS proxy (Tor running locally)
    if (!arg(L"--get-onion").empty()) {
        std::wstring url = arg(L"--get-onion");
        std::wstring proxy = arg(L"--proxy");
        if (proxy.empty()) { std::wcerr << L"--proxy host:port required for --get-onion\n"; return 1; }
        size_t c = proxy.find(L':');
        if (c==std::wstring::npos) { std::wcerr << L"--proxy must be host:port\n"; return 1; }
        std::wstring ph = proxy.substr(0,c);
        INTERNET_PORT pp = (INTERNET_PORT)std::stoi(proxy.substr(c+1));
        HttpResponse r;
        if (!HttpRequestToOnionViaSocks(url, L"GET", nullptr, r, ph, pp)) return 1;
        std::cout << "Status: " << r.status << "\n" << r.body << "\n";
        did = true;
    }
    if (!arg(L"--post-onion").empty()) {
        std::wstring url = arg(L"--post-onion");
        std::wstring proxy = arg(L"--proxy");
        if (proxy.empty()) { std::wcerr << L"--proxy host:port required for --post-onion\n"; return 1; }
        size_t c = proxy.find(L':');
        if (c==std::wstring::npos) { std::wcerr << L"--proxy must be host:port\n"; return 1; }
        std::wstring ph = proxy.substr(0,c);
        INTERNET_PORT pp = (INTERNET_PORT)std::stoi(proxy.substr(c+1));
        std::wstring dataW = arg(L"--data");
        if (dataW.empty()) { std::wcerr << L"--data required for --post-onion\n"; return 1; }
        std::string data = WideToUtf8(dataW);
        HttpResponse r;
        std::vector<std::pair<std::wstring,std::wstring>> hdrs = {{L"Content-Type", L"application/x-www-form-urlencoded"}};
        if (!HttpRequestWinHttp(url, L"POST", &data, &hdrs, r, ph, pp)) return 1;
        std::cout << "Status: " << r.status << "\n" << r.body << "\n";
        did = true;
    }

    if (!did) { PrintHelp(); }
    EVP_cleanup(); ERR_free_strings();
    return did ? 0 : 1;
}

// tor_onion_tool.cpp
//
// Single-file C++ (Windows) that:
// - Uses WinHTTP for HTTP/HTTPS GET/POST with robust error handling.
// - Routes requests through a Tor SOCKS5 proxy using WinHTTP's "socks=" proxy syntax (no tor2web).
// - Downloads the Tor consensus and parses key relay fields.
// - Resolves and downloads a Tor v3 hidden service descriptor and parses key sections.
// - Validates and decodes a v3 .onion address using RFC4648 base32 (lowercase, no padding) and OpenSSL (SHA3-256) for checksum verification.
// - Demonstrates real GET/POST to a .onion via Tor SOCKS5.
//
// Build (MSVC example):
//   cl /std:c++17 /O2 /EHsc tor_onion_tool.cpp winhttp.lib crypt32.lib
//
// Example usage:
//   tor_onion_tool.exe --socks 127.0.0.1:9050 --get http://expyuzz4wqqyqhjn.onion/
//   tor_onion_tool.exe --socks 127.0.0.1:9050 --post http://expyuzz4wqqyqhjn.onion/ "name=value"
//   tor_onion_tool.exe --consensus-url https://collector.torproject.org/recent/relay-descriptors/consensuses/2024-01-01-00-00-00-consensus
//   tor_onion_tool.exe --desc-resolve zlal32teyptf4tvi.onion --socks 127.0.0.1:9050
//
