// UTF-8/UTF-16 helpers
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &out[0], len);
    return out;
}
static std::string WideToUtf8(const std::wstring& ws) {
    if (ws.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), &out[0], len, nullptr, nullptr);
    return out;
}

static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

struct WinHttpHandle { HINTERNET h{nullptr}; WinHttpHandle()=default; explicit WinHttpHandle(HINTERNET x):h(x){} ~WinHttpHandle(){ if(h) WinHttpCloseHandle(h);} operator HINTERNET()const{return h;} };

struct ParsedUrl {
    std::wstring host;
    std::wstring path;
    INTERNET_PORT port{0};
    bool https{false};
};

static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTS uc{};
    wchar_t host[512]{}; wchar_t path[4096]{};
    uc.dwStructSize = sizeof(uc);
    uc.dwSchemeLength = (DWORD)-1;
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    out.port = uc.nPort ? uc.nPort : (out.https ? 443 : 80);
    if (uc.dwUrlPathLength) out.path.assign(uc.lpszUrlPath, uc.dwUrlPathLength); else out.path = L"/";
    return true;
}

// Simple RFC4648 base32 (lowercase, no padding) for onion v3
static bool Base32DecodeLowerNoPad(const std::string& in, std::vector<uint8_t>& out) {
    static bool inited=false; static int8_t loc[256];
    if(!inited){
        std::fill(std::begin(loc), std::end(loc), -1);
        const std::string alpha = "abcdefghijklmnopqrstuvwxyz234567";
        for (size_t i=0;i<alpha.size();++i) loc[(uint8_t)alpha[i]] = (int8_t)i;
        inited=true;
    }
    out.clear(); int val=0, valb=-5;
    for (unsigned char c: in) {
        int8_t v = loc[(uint8_t)std::tolower(c)];
        if (v<0) return false;
        val = (val<<5) | v; valb += 5;
        if (valb >= 0) { out.push_back((uint8_t)((val>>valb)&0xFF)); valb -= 8; }
    }
    return true;
}

// Tor v3 address: base32 of 35 bytes: [ED25519_PUBKEY(32)] [CHECKSUM(2)] [VERSION(1)=3]
static bool DecodeOnionV3(const std::string& host, std::array<uint8_t,32>& pubkey) {
    std::string h = host;
    if (h.size()>6 && h.substr(h.size()-6)==".onion") h.resize(h.size()-6);
    if (h.size()!=56) return false;
    std::vector<uint8_t> dec;
    if (!Base32DecodeLowerNoPad(h, dec)) return false;
    if (dec.size()!=35) return false;
    std::copy(dec.begin(), dec.begin()+32, pubkey.begin());
    uint8_t checksum[2] = { dec[32], dec[33] };
    uint8_t ver = dec[34];
    if (ver != 3) return false;
    static const uint8_t prefix[] = {'.','o','n','i','o','n',' ','c','h','e','c','k','s','u','m'};
    std::vector<uint8_t> m; m.insert(m.end(), std::begin(prefix), std::end(prefix));
    m.insert(m.end(), pubkey.begin(), pubkey.end());
    m.push_back(ver);
    std::array<uint8_t, 32> digest{};
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if(!ctx) return false;
    bool ok = EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr)==1 &&
              EVP_DigestUpdate(ctx, m.data(), m.size())==1 &&
              EVP_DigestFinal_ex(ctx, digest.data(), nullptr)==1;
    EVP_MD_CTX_free(ctx);
    if(!ok) return false;
    return digest[0]==checksum[0] && digest[1]==checksum[1];
}

static bool IsOnionHost(const std::wstring& host) {
    if (host.size()>=6) {
        std::wstring l = host; std::transform(l.begin(), l.end(), l.begin(), ::towlower);
        return l.rfind(L".onion") == l.size()-6;
    }
    return false;
}

struct HttpClient {
    std::wstring socksProxy; // e.g., L"socks=127.0.0.1:9050"

    bool Request(const std::wstring& url, const std::wstring& method, const std::string* body,
                 std::wstring& statusLine, std::map<std::wstring,std::wstring>& headers, std::string& resp) {
        ParsedUrl pu{}; if(!CrackUrl(url, pu)) return false;
        WinHttpHandle hSession(WinHttpOpen(L"tor_onion_tool/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
        if (!hSession.h) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }
        if (!socksProxy.empty()) {
            WINHTTP_PROXY_INFO pi{}; pi.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY; pi.lpszProxy = (LPWSTR)socksProxy.c_str();
            if (!WinHttpSetOption(hSession.h, WINHTTP_OPTION_PROXY, &pi, sizeof(pi))) {
                std::wcerr << L"WinHttpSetOption(PROXY) failed: " << FormatLastError() << L"\n"; return false;
            }
        }
        WinHttpHandle hConnect(WinHttpConnect(hSession.h, pu.host.c_str(), pu.port, 0));
        if (!hConnect.h) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }
        DWORD flags = pu.https ? WINHTTP_FLAG_SECURE : 0;
        WinHttpHandle hRequest(WinHttpOpenRequest(hConnect.h, method.c_str(), pu.path.c_str(), nullptr,
                                                  WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
        if (!hRequest.h) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }
        if (pu.https && IsOnionHost(pu.host)) {
            DWORD opt = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID |
                        SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_WRONG_USAGE;
            WinHttpSetOption(hRequest.h, WINHTTP_OPTION_SECURITY_FLAGS, &opt, sizeof(opt));
        }
        std::wstring hdrs = L"Accept: */*\r\nUser-Agent: tor_onion_tool/1.0\r\n";
        BOOL sent = FALSE;
        if (body) {
            std::wstring h2 = hdrs + L"Content-Type: application/x-www-form-urlencoded\r\n";
            sent = WinHttpSendRequest(hRequest.h, h2.c_str(), (DWORD)-1L, (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
        } else {
            sent = WinHttpSendRequest(hRequest.h, hdrs.c_str(), (DWORD)-1L, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
        }
        if (!sent) { std::wcerr << L"WinHttpSendRequest failed: " << FormatWinHttpError(GetLastError()) << L"\n"; return false; }
        if (!WinHttpReceiveResponse(hRequest.h, nullptr)) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatWinHttpError(GetLastError()) << L"\n"; return false; }

        DWORD statusCode=0, len=sizeof(statusCode);
        WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX);
        wchar_t statusText[256]{}; DWORD stlen = sizeof(statusText);
        WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_STATUS_TEXT, WINHTTP_HEADER_NAME_BY_INDEX, statusText, &stlen, WINHTTP_NO_HEADER_INDEX);
        statusLine = L"HTTP " + std::to_wstring(statusCode) + L" " + std::wstring(statusText);

        resp.clear();
        for(;;){ DWORD avail=0; if(!WinHttpQueryDataAvailable(hRequest.h,&avail)) { std::wcerr<<L"WinHttpQueryDataAvailable failed\n"; break; }
            if(avail==0) break; std::string chunk; chunk.resize(avail);
            DWORD read=0; if(!WinHttpReadData(hRequest.h, chunk.data(), avail, &read)) { std::wcerr<<L"WinHttpReadData failed\n"; break; }
            chunk.resize(read); resp += chunk; }
        return true;
    }
};

// Minimal consensus parser: extracts relay fingerprints and flags
static void ParseConsensus(const std::string& text) {
    std::istringstream iss(text);
    std::string line; size_t relays=0, guards=0, exits=0;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back()=='\r') line.pop_back();
        if (line.rfind("r ",0)==0) { relays++; }
        else if (line.rfind("s ",0)==0) {
            if (line.find(" Guard")!=std::string::npos || line.find(" Guard ")!=std::string::npos) guards++;
            if (line.find(" Exit")!=std::string::npos || line.find(" Exit ")!=std::string::npos) exits++;
        }
    }
    std::cout << "Consensus relays: "<<relays<<", Guards: "<<guards<<", Exits: "<<exits<<"\n";
}

// Descriptor parsing (v3 HSDir format): parse header blocks and ciphertext sections
static void ParseV3Descriptor(const std::string& text) {
    std::istringstream iss(text); std::string line; std::string cur;
    std::map<std::string,std::string> fields; std::map<std::string,std::string> blocks;
    auto trim=[&](std::string s){ while(!s.empty() && (s.back()=='\r' || s.back()=='\n')) s.pop_back(); return s; };
    while(std::getline(iss,line)){
        line=trim(line);
        if(line.empty()) continue;
        if(line.find("-----BEGIN ")==0){ cur=line.substr(11); blocks[cur]=""; }
        else if(line.find("-----END ")==0){ cur.clear(); }
        else if(!cur.empty()){ blocks[cur] += line + "\n"; }
        else {
            auto sp = line.find(' '); if (sp!=std::string::npos) fields[line.substr(0,sp)] = line.substr(sp+1);
        }
    }
    std::cout << "Descriptor fields: \n";
    for (auto& kv: fields) std::cout << "  "<<kv.first<<": "<<kv.second<<"\n";
    std::cout << "PEM-like blocks: \n";
    for (auto& kv: blocks) std::cout << "  "<<kv.first<<" ("<<kv.second.size()<<" bytes b64)\n";
}

static bool HttpGetAll(HttpClient& cli, const std::wstring& url, std::string& bodyOut) {
    std::wstring status; std::map<std::wstring,std::wstring> hdrs; std::string resp;
    if(!cli.Request(url, L"GET", nullptr, status, hdrs, resp)) return false;
    std::wcout << L"GET "<< url << L" => " << status << L"\n";
    bodyOut.swap(resp);
    return true;
}
static bool HttpPostAll(HttpClient& cli, const std::wstring& url, const std::string& body, std::string& bodyOut) {
    std::wstring status; std::map<std::wstring,std::wstring> hdrs; std::string resp;
    if(!cli.Request(url, L"POST", &body, status, hdrs, resp)) return false;
    std::wcout << L"POST "<< url << L" => " << status << L"\n";
    bodyOut.swap(resp);
    return true;
}

int wmain(int argc, wchar_t* argv[]) {
    std::wstring socksArg; std::wstring getUrl; std::wstring postUrl; std::string postData;
    std::wstring consensusUrl; std::wstring descriptorUrl; std::wstring onionCheck;
    std::wstring descResolveOnion;

    for (int i=1;i<argc;i++) {
        std::wstring a = argv[i];
        if (a==L"--socks" && i+1<argc) { socksArg = L"socks=" + std::wstring(argv[++i]); }
        else if (a==L"--get" && i+1<argc) { getUrl = argv[++i]; }
        else if (a==L"--post" && i+2<argc) { postUrl = argv[++i]; postData = WideToUtf8(argv[++i]); }
        else if (a==L"--consensus-url" && i+1<argc) { consensusUrl = argv[++i]; }
        else if (a==L"--descriptor-url" && i+1<argc) { descriptorUrl = argv[++i]; }
        else if (a==L"--onion-check" && i+1<argc) { onionCheck = argv[++i]; }
        else if (a==L"--desc-resolve" && i+1<argc) { descResolveOnion = argv[++i]; }
    }

    HttpClient client; client.socksProxy = socksArg;

    if (!onionCheck.empty()) {
        std::array<uint8_t,32> pk{}; bool ok = DecodeOnionV3(WideToUtf8(onionCheck), pk);
        std::wcout << L"onion check for "<< onionCheck << L": " << (ok?L"valid":L"invalid") << L"\n";
    }

    if (!consensusUrl.empty()) {
        std::string body;
        if (HttpGetAll(client, consensusUrl, body)) {
            std::cout << "Downloaded consensus: " << body.size() << " bytes\n";
            ParseConsensus(body);
        }
    }

    if (!descriptorUrl.empty()) {
        std::string body;
        if (HttpGetAll(client, descriptorUrl, body)) {
            std::cout << "Downloaded descriptor: " << body.size() << " bytes\n";
            ParseV3Descriptor(body);
        }
    }

    if (!descResolveOnion.empty()) {
        std::array<uint8_t,32> pk{}; if (DecodeOnionV3(WideToUtf8(descResolveOnion), pk)) {
            std::wcout << L"Valid onion; attempting descriptor fetch via Tor directory mirror (if provided with --descriptor-url).\n";
        } else {
            std::wcout << L"Invalid onion; cannot resolve descriptor.\n";
        }
    }

    if (!getUrl.empty()) {
        std::string body;
        if (HttpGetAll(client, getUrl, body)) {
            std::cout << "GET response (first 1024 bytes):\n" << body.substr(0,1024) << "\n";
        }
    }
    if (!postUrl.empty()) {
        std::string body;
        if (HttpPostAll(client, postUrl, postData, body)) {
            std::cout << "POST response (first 1024 bytes):\n" << body.substr(0,1024) << "\n";
        }
    }

    if (consensusUrl.empty() && descriptorUrl.empty() && getUrl.empty() && postUrl.empty() && onionCheck.empty()) {
        std::wcout << L"Usage:\n"
                    L"  --socks host:port                Route via Tor SOCKS5 (e.g., 127.0.0.1:9050)\n"
                    L"  --get URL                        Perform GET (supports .onion via SOCKS)\n"
                    L"  --post URL DATA                  Perform POST (supports .onion via SOCKS)\n"
                    L"  --consensus-url URL              Download and parse Tor consensus\n"
                    L"  --descriptor-url URL             Download and parse v3 descriptor\n"
                    L"  --onion-check HOST               Validate v3 .onion address\n"
                    L"  --desc-resolve HOST.onion        Validate and prepare descriptor resolution demo\n";
    }
    return 0;
}

