// RFC4648 base32 (lowercase) – custom
static std::vector<unsigned char> Base32DecodeLower(const std::string& s) {
    static const int8_t tbl[256] = [](){
        std::array<int8_t,256> a{}; a.fill(-1);
        const std::string alph = "abcdefghijklmnopqrstuvwxyz234567";
        for (size_t i=0;i<alph.size();++i) a[(uint8_t)alph[i]] = (int)i;
        return a;
    }();
    std::vector<unsigned char> out;
    int buffer = 0, bitsLeft = 0;
    for (char ch : s) {
        if (ch=='=') break;
        int8_t v = tbl[(uint8_t)std::tolower((unsigned char)ch)];
        if (v < 0) continue;
        buffer = (buffer << 5) | v;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((unsigned char)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return out;
}

static bool Sha3_256(const unsigned char* data, size_t len, unsigned char out[32]) {
#if defined(EVP_MD_fetch)
    EVP_MD* md = EVP_MD_fetch(nullptr, "SHA3-256", nullptr);
    if (!md) return false;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) { EVP_MD_free(md); return false; }
    bool ok = EVP_DigestInit_ex(ctx, md, nullptr) == 1 &&
              EVP_DigestUpdate(ctx, data, len) == 1 &&
              EVP_DigestFinal_ex(ctx, out, nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    EVP_MD_free(md);
    return ok;
#else
    const EVP_MD* md = EVP_sha3_256();
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return false;
    bool ok = EVP_DigestInit_ex(ctx, md, nullptr) == 1 &&
              EVP_DigestUpdate(ctx, data, len) == 1 &&
              EVP_DigestFinal_ex(ctx, out, nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    return ok;
#endif
}

// Base64 decode via OpenSSL EVP
static bool Base64Decode(const std::string& in, std::vector<unsigned char>& out) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    bio = BIO_push(b64, bio);
    out.resize(in.size());
    int n = BIO_read(bio, out.data(), (int)out.size());
    if (n < 0) { BIO_free_all(bio); out.clear(); return false; }
    out.resize((size_t)n);
    BIO_free_all(bio);
    return true;
}

// ---------------- URL parsing ----------------
struct ParsedUrl { std::wstring scheme; std::wstring host; INTERNET_PORT port{0}; std::wstring path; bool https{false}; };

static bool ParseUrl(const std::wstring& url, ParsedUrl& pu) {
    URL_COMPONENTS uc{}; uc.dwStructSize = sizeof(uc);
    wchar_t host[512]{}; wchar_t path[2048]{}; wchar_t scheme[16]{};
    uc.lpszHostName = host; uc.dwHostNameLength = _countof(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = _countof(path);
    uc.lpszScheme = scheme; uc.dwSchemeLength = _countof(scheme);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return false;
    pu.scheme.assign(uc.lpszScheme, uc.dwSchemeLength);
    pu.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    pu.port = uc.nPort ? uc.nPort : ((uc.nScheme == INTERNET_SCHEME_HTTPS) ? 443 : 80);
    pu.path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (pu.path.empty()) pu.path = L"/";
    pu.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    return true;
}

// ---------------- WinHTTP client (supports socks= proxy) ----------------
struct HttpResponse { DWORD status{0}; std::string body; std::map<std::string,std::string> headers; };

static bool WinHttpRequest(const std::wstring& url, const std::wstring& method, const std::wstring& proxy, const std::string* postBody, HttpResponse& resp) {
    ParsedUrl pu{}; if (!ParseUrl(url, pu)) { std::wcerr << L"Invalid URL: " << url << L"\n"; return false; }
    WinHttpHandle hSession(WinHttpOpen(L"tor-onion-tool/1.0", WINHTTP_ACCESS_TYPE_NO_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession.h) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    if (!proxy.empty()) {
        WINHTTP_PROXY_INFO p{}; p.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY; p.lpszProxy = const_cast<LPWSTR>(proxy.c_str());
        if (!WinHttpSetOption(hSession.h, WINHTTP_OPTION_PROXY, &p, sizeof(p))) {
            std::wcerr << L"WinHttpSetOption(PROXY) failed: " << FormatLastError() << L"\n"; return false;
        }
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession.h, pu.host.c_str(), pu.port, 0));
    if (!hConnect.h) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = pu.https ? (WINHTTP_FLAG_SECURE) : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect.h, method.c_str(), pu.path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest.h) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (pu.https) {
        DWORD secFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_REVOCATION;
        WinHttpSetOption(hRequest.h, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));
    }

    std::wstring headers = L"Accept: */*\r\nConnection: close\r\n";
    LPCVOID pBody = WINHTTP_NO_REQUEST_DATA; DWORD cbBody = 0;
    if (postBody) { pBody = postBody->data(); cbBody = (DWORD)postBody->size(); headers += L"Content-Type: application/x-www-form-urlencoded\r\n"; }

    if (!WinHttpSendRequest(hRequest.h, headers.c_str(), (DWORD)-1L, const_cast<LPVOID>(pBody), cbBody, cbBody, 0)) {
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false;
    }

    if (!WinHttpReceiveResponse(hRequest.h, nullptr)) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD statusCode = 0; DWORD len = sizeof(statusCode);
    WinHttpQueryHeaders(hRequest.h, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX);
    resp.status = statusCode;

    std::string body; DWORD avail = 0;
    do {
        avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest.h, &avail)) { std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (!avail) break;
        std::string chunk; chunk.resize(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest.h, &chunk[0], avail, &read)) { std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        chunk.resize(read);
        body += chunk;
    } while (avail > 0);
    resp.body = std::move(body);
    return true;
}

// ---------------- Tor consensus parsing (minimal fields) ----------------
struct ConsensusInfo {
    std::string validAfter;
    std::string freshUntil;
    std::string validUntil;
    size_t routerCount{0};
};

static ConsensusInfo ParseConsensus(const std::string& text) {
    ConsensusInfo ci{};
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.rfind("valid-after ", 0) == 0) ci.validAfter = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) ci.freshUntil = line.substr(12);
        else if (line.rfind("valid-until ", 0) == 0) ci.validUntil = line.substr(12);
        else if (line.rfind("r ", 0) == 0) ci.routerCount++;
    }
    return ci;
}

// ---------------- Onion v3 address validation ----------------
// v3 address = base32(lower) of: PUBKEY(32) || CHECKSUM(2) || VERSION(1) with checksum = first2 bytes of SHA3-256(".onion checksum" || PUBKEY || VERSION)
static bool ValidateOnionV3(const std::string& onionHostLower) {
    std::string host = onionHostLower;
    if (host.size() > 6 && host.substr(host.size()-6) == ".onion") host = host.substr(0, host.size()-6);
    if (host.size() != 56) return false;
    auto dec = Base32DecodeLower(host);
    if (dec.size() != 35) return false;
    const unsigned char* pub = dec.data();
    const unsigned char* checksum = dec.data()+32;
    unsigned char version = dec[34];
    if (version != 3) return false;
    const char prefix[] = ".onion checksum";
    unsigned char data[sizeof(prefix)-1 + 32 + 1];
    memcpy(data, prefix, sizeof(prefix)-1);
    memcpy(data + sizeof(prefix)-1, pub, 32);
    data[sizeof(prefix)-1 + 32] = version;
    unsigned char h[32];
    if (!Sha3_256(data, sizeof(data), h)) return false;
    return (h[0] == checksum[0] && h[1] == checksum[1]);
}

// ---------------- Descriptor parsing (minimal) ----------------
struct DescriptorInfo {
    std::string hsDescriptor;
    std::string descriptorSignature;
    std::string introPointsEnc; // base64
    std::vector<unsigned char> introPoints; // decoded
};

static DescriptorInfo ParseDescriptor(const std::string& text) {
    DescriptorInfo di{};
    std::istringstream iss(text);
    std::string line;
    auto trim = [](std::string s){ s.erase(s.find_last_not_of("\r\n ") + 1); s.erase(0, s.find_first_not_of(" \t")); return s; };
    std::string currentKey;
    std::string base64Buf;
    while (std::getline(iss, line)) {
        if (line.rfind("hs-descriptor ", 0) == 0) di.hsDescriptor = trim(line.substr(13));
        else if (line.rfind("signature ", 0) == 0) di.descriptorSignature = trim(line.substr(10));
        else if (line.rfind("introduction-points ", 0) == 0) { currentKey = "intro"; base64Buf.clear(); }
        else if (line.rfind("-----END MESSAGE-----", 0) == 0 && currentKey == "intro") { currentKey.clear(); di.introPointsEnc = base64Buf; }
        else if (currentKey == "intro") { base64Buf += trim(line); }
    }
    if (!di.introPointsEnc.empty()) Base64Decode(di.introPointsEnc, di.introPoints);
    return di;
}

// ---------------- High-level helpers ----------------
static bool DownloadText(const std::wstring& url, const std::wstring& proxy, std::string& out, DWORD* status=nullptr) {
    HttpResponse r{};
    if (!WinHttpRequest(url, L"GET", proxy, nullptr, r)) return false;
    if (status) *status = r.status;
    out = std::move(r.body);
    return (r.status >= 200 && r.status < 300);
}

static bool HttpGet(const std::wstring& url, const std::wstring& proxy, std::string& body, DWORD& status) {
    HttpResponse r{}; if (!WinHttpRequest(url, L"GET", proxy, nullptr, r)) return false; status = r.status; body = r.body; return true;
}
static bool HttpPost(const std::wstring& url, const std::wstring& proxy, const std::string& data, std::string& body, DWORD& status) {
    HttpResponse r{}; if (!WinHttpRequest(url, L"POST", proxy, &data, r)) return false; status = r.status; body = r.body; return true;
}

// ---------------- CLI ----------------
struct Args {
    std::wstring socks; // e.g., L"socks=127.0.0.1:9050"
    std::wstring getUrl;
    std::wstring postUrl; std::string postData;
    std::wstring consensusUrl;
    std::wstring descriptorUrl;
    std::string onionCheck;
};

static Args ParseArgs(int argc, wchar_t** argv) {
    Args a{};
    for (int i=1;i<argc;++i) {
        std::wstring k = argv[i];
        auto next = [&](std::wstring& out){ if (i+1<argc) { out = argv[++i]; return true; } return false; };
        auto nextA = [&](std::string& out){ if (i+1<argc) { out = WideToUtf8(argv[++i]); return true; } return false; };
        if (k == L"--socks") { next(a.socks); }
        else if (k == L"--get") { next(a.getUrl); }
        else if (k == L"--post") { next(a.postUrl); nextA(a.postData); }
        else if (k == L"--consensus-url") { next(a.consensusUrl); }
        else if (k == L"--descriptor-url") { next(a.descriptorUrl); }
        else if (k == L"--onion-check") { a.onionCheck = WideToUtf8(argv[++i]); std::transform(a.onionCheck.begin(), a.onionCheck.end(), a.onionCheck.begin(), ::tolower); }
    }
    return a;
}

static void PrintUsage() {
    std::wcout << L"Usage:\n"
               << L"  --socks socks=127.0.0.1:9050   (Tor SOCKS5)\n"
               << L"  --get URL                      (GET request)\n"
               << L"  --post URL DATA                (POST request)\n"
               << L"  --consensus-url URL            (Download Tor consensus)\n"
               << L"  --descriptor-url URL           (Download v3 descriptor)\n"
               << L"  --onion-check HOST.onion       (Validate v3 address)\n";
}

int wmain(int argc, wchar_t** argv) {
    OpenSSLOnce _ssl;
    Args args = ParseArgs(argc, argv);

    if (argc == 1) { PrintUsage(); return 0; }

    if (!args.onionCheck.empty()) {
        bool ok = ValidateOnionV3(args.onionCheck);
        std::wcout << L"Onion v3 validation for " << Utf8ToWide(args.onionCheck) << L": " << (ok?L"OK":L"FAIL") << L"\n";
    }

    if (!args.consensusUrl.empty()) {
        std::string text; DWORD st=0;
        if (DownloadText(args.consensusUrl, args.socks, text, &st)) {
            auto ci = ParseConsensus(text);
            std::wcout << L"Consensus: valid-after=" << Utf8ToWide(ci.validAfter) << L" fresh-until=" << Utf8ToWide(ci.freshUntil)
                       << L" valid-until=" << Utf8ToWide(ci.validUntil) << L" routers=" << ci.routerCount << L"\n";
        } else {
            std::wcout << L"Failed to download consensus (HTTP " << st << L")\n";
        }
    }

    if (!args.descriptorUrl.empty()) {
        std::string text; DWORD st=0;
        if (DownloadText(args.descriptorUrl, args.socks, text, &st)) {
            auto di = ParseDescriptor(text);
            std::wcout << L"Descriptor fields: hs-descriptor='" << Utf8ToWide(di.hsDescriptor) << L"' sig='" << Utf8ToWide(di.descriptorSignature)
                       << L"' intro-bytes=" << di.introPoints.size() << L"\n";
        } else {
            std::wcout << L"Failed to download descriptor (HTTP " << st << L")\n";
        }
    }

    if (!args.getUrl.empty()) {
        std::string body; DWORD st=0;
        if (HttpGet(args.getUrl, args.socks, body, st)) {
            std::wcout << L"GET status=" << st << L" bytes=" << body.size() << L"\n";
            std::wcout << Utf8ToWide(body.substr(0, std::min<size_t>(body.size(), 1024))) << L"\n";
        } else {
            std::wcout << L"GET failed\n";
        }
    }

    if (!args.postUrl.empty()) {
        std::string body; DWORD st=0;
        if (HttpPost(args.postUrl, args.socks, args.postData, body, st)) {
            std::wcout << L"POST status=" << st << L" bytes=" << body.size() << L"\n";
            std::wcout << Utf8ToWide(body.substr(0, std::min<size_t>(body.size(), 1024))) << L"\n";
        } else {
            std::wcout << L"POST failed\n";
        }
    }

    return 0;
}

