// C# (put this in Assets/Scripts). This file contains:
// - IChunkDataProvider + VistaGraphAdapter (with concrete Vista 2023 integration)
// - TerrainChunkStreamer: minimal scene controller that streams chunks around the player

using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

// Vista 2023 namespaces (Pinwheel.Vista.*)
using Pinwheel.Vista;                  // Core graph types
using Pinwheel.Vista.Graph;            // Graph asset types
using Pinwheel.Vista.Runtime;          // Runtime runner/evaluator
using Pinwheel.Vista.Runtime.Readback; // Readback helpers

#region Data contracts

public interface IChunkDataProvider
{
    Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct);
}

[Serializable]
public struct ChunkCoord
{
    public int x;               // chunk index in grid (not world units)
    public int z;
    public float chunkSize;     // world size of a chunk in meters
}

public sealed class ChunkData
{
    // Terrain height array: size [heightResolution, heightResolution], normalized [0..1]
    public float[,] heights;

    // Alphamap array: size [alphaResolution, alphaResolution, numLayers] (optional)
    public float[,,] alphamaps;

    public int heightResolution;    // e.g., 257
    public int alphaResolution;     // e.g., 512
    public int layerCount;          // number of splat layers
}

#endregion

#region Vista adapter with concrete integration

public class VistaGraphAdapter : MonoBehaviour, IChunkDataProvider
{
    [Header("Vista 2023")]
    [Tooltip("Reference to your Vista 2023 graph asset (ScriptableObject)")]
    public GGraph vistaGraphAsset; // Vista 2023 graph asset type

    [Header("Resolutions")]
    public int heightResolution = 257;    // power of two + 1
    public int alphaResolution = 512;     // splat/alphamap resolution; 0 to skip
    public int bleedPixels = 2;           // extra border to ensure seamless edges

    [Header("Terrain Settings")]
    public float terrainHeight = 300f;    // vertical scale
    public Vector2 worldOffset = Vector2.zero;
    public int seed = 12345;

    [Header("Execution")]
    public bool preferGPU = true;         // if supported by your graph/nodes
    public int maxConcurrent = 2;         // throttle parallel chunk evals

    private SemaphoreSlim _gate;
    private SynchronizationContext _unityContext;

    void Awake()
    {
        _gate = new SemaphoreSlim(Mathf.Max(1, maxConcurrent), Mathf.Max(1, maxConcurrent));
        _unityContext = SynchronizationContext.Current;
    }

    public async Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            float wx = coord.x * coord.chunkSize + worldOffset.x;
            float wz = coord.z * coord.chunkSize + worldOffset.y;
            var bounds = new Rect(wx, wz, coord.chunkSize, coord.chunkSize);

            var eval = await EvaluateVistaGraphAsync(bounds, heightResolution, alphaResolution, bleedPixels, ct)
                .ConfigureAwait(false);

            var heightsNoBleed = TrimBleed(eval.heights, bleedPixels);
            float[,,] alphamapsNoBleed = eval.alphamaps;
            if (alphamapsNoBleed != null && bleedPixels > 0)
            {
                alphamapsNoBleed = TrimBleedAlpha(eval.alphamaps, bleedPixels);
            }

            return new ChunkData
            {
                heights = heightsNoBleed,
                alphamaps = alphamapsNoBleed,
                heightResolution = heightResolution,
                alphaResolution = alphaResolution,
                layerCount = alphamapsNoBleed != null ? alphamapsNoBleed.GetLength(2) : 0
            };
        }
        finally
        {
            _gate.Release();
        }
    }

    private float[,] TrimBleed(float[,] src, int bleed)
    {
        if (src == null || bleed <= 0) return src;
        int srcW = src.GetLength(0);
        int srcH = src.GetLength(1);
        int dstW = srcW - 2 * bleed;
        int dstH = srcH - 2 * bleed;
        var dst = new float[dstW, dstH];
        for (int y = 0; y < dstH; y++)
        {
            for (int x = 0; x < dstW; x++)
            {
                dst[x, y] = src[x + bleed, y + bleed];
            }
        }
        return dst;
    }

    private float[,,] TrimBleedAlpha(float[,,] src, int bleed)
    {
        if (src == null || bleed <= 0) return src;
        int srcW = src.GetLength(0);
        int srcH = src.GetLength(1);
        int layers = src.GetLength(2);
        int dstW = srcW - 2 * bleed;
        int dstH = srcH - 2 * bleed;
        var dst = new float[dstW, dstH, layers];
        for (int y = 0; y < dstH; y++)
        {
            for (int x = 0; x < dstW; x++)
            {
                for (int l = 0; l < layers; l++)
                {
                    dst[x, y, l] = src[x + bleed, y + bleed, l];
                }
            }
        }
        return dst;
    }

    private struct VistaEvalResult
    {
        public float[,] heights;     // (heightRes + 2*bleed) squared
        public float[,,] alphamaps;  // (alphaRes + 2*bleed)^2 x layers
    }

    private Task SwitchToUnityMainThread(CancellationToken ct)
    {
        var tcs = new TaskCompletionSource<bool>();
        _unityContext.Post(_ =>
        {
            if (ct.IsCancellationRequested)
            {
                tcs.TrySetCanceled(ct);
            }
            else
            {
                tcs.TrySetResult(true);
            }
        }, null);
        return tcs.Task;
    }

    private async Task<VistaEvalResult> EvaluateVistaGraphAsync(
        Rect worldBounds,
        int heightRes,
        int alphaRes,
        int bleed,
        CancellationToken ct)
    {
        // Vista runtime evaluation must happen on the main thread.
        await SwitchToUnityMainThread(ct);

        // Create a runtime runner from the graph
        // GRuntime is Vista's runtime executor for GGraph assets.
        var runtime = new GRuntime();
        runtime.Graph = vistaGraphAsset;           // bind graph asset
        runtime.Seed = seed;                       // optional seed if graph uses it
        runtime.UseGPU = preferGPU;                // prefer GPU path if nodes support it

        // Configure per-chunk domain (XZ world rect) and per-output resolutions
        // Vista uses GDomain to define the evaluation space in world units.
        var domain = new GDomain
        {
            Origin = new Vector2(worldBounds.xMin, worldBounds.yMin),
            Size = new Vector2(worldBounds.width, worldBounds.height)
        };
        runtime.Domain = domain;

        // Height output: request a heightmap with bleed padding
        int heightResWithBleed = heightRes + 2 * bleed;
        var heightRequest = new GHeightmapRequest
        {
            Resolution = heightResWithBleed,
            Normalize = true
        };
        runtime.Requests.Heightmap = heightRequest;

        // Alphamap output (optional)
        int alphaResWithBleed = Mathf.Max(0, alphaRes > 0 ? alphaRes + 2 * bleed : 0);
        if (alphaResWithBleed > 0)
        {
            var splatRequest = new GAlphamapRequest
            {
                Resolution = alphaResWithBleed,
                NormalizeLayers = true
            };
            runtime.Requests.Alphamap = splatRequest;
        }
        else
        {
            runtime.Requests.Alphamap = null;
        }

        // Evaluate asynchronously (Vista provides async graph evaluation)
        // EvaluateAsync returns a GTask that can be awaited via ToTask().
        var gtask = runtime.EvaluateAsync();
        await gtask.ToTask(ct); // extension to await Vista's async handle with CancellationToken

        // Read back results
        // Height readback as float[] (row-major), then convert to float[,]
        GHeightmapResult hResult = runtime.Results.Heightmap; // contains Texture/Buffer and utilities
        float[] hLinear = GReadback.ReadHeightFloatArray(hResult); // 1D array length = res*res, values 0..1
        float[,] heights = new float[heightResWithBleed, heightResWithBleed];
        for (int y = 0; y < heightResWithBleed; y++)
        {
            int row = y * heightResWithBleed;
            for (int x = 0; x < heightResWithBleed; x++)
            {
                heights[x, y] = hLinear[row + x];
            }
        }

        float[,,] alphamaps = null;
        if (alphaResWithBleed > 0 && runtime.Results.Alphamap != null)
        {
            GAlphamapResult aResult = runtime.Results.Alphamap;
            // Returns [w*h*layers] linear floats (0..1), layer-major interleaved or per-pixel layered
            var aRead = GReadback.ReadAlphamapFloatArray(aResult, out int layers);
            alphamaps = new float[alphaResWithBleed, alphaResWithBleed, layers];

            int idx = 0;
            for (int y = 0; y < alphaResWithBleed; y++)
            {
                for (int x = 0; x < alphaResWithBleed; x++)
                {
                    for (int l = 0; l < layers; l++)
                    {
                        alphamaps[x, y, l] = aRead[idx++];
                    }
                }
            }
        }

        // Cleanup runtime (optional if you reuse instances)
        runtime.Dispose();

        return new VistaEvalResult
        {
            heights = heights,
            alphamaps = alphamaps
        };
    }
}

#endregion

#region Minimal scene controller: streaming, spawning, unloading

public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public VistaGraphAdapter dataProvider;

    [Header("Chunk Settings")]
    public float chunkSize = 256f;              // meters per chunk (XZ)
    public int heightResolution = 257;          // TerrainData.heightmapResolution
    public int alphaResolution = 512;           // TerrainData.alphamapResolution
    public float terrainHeight = 300f;          // Terrain vertical scale (matches adapter)

    [Header("Streaming")]
    public int renderRadiusInChunks = 3;        // Manhattan or Chebyshev radius; we use Chebyshev
    public int maxActiveChunks = 400;           // safety cap

    private readonly Dictionary<Vector2Int, Terrain> _active = new();
    private readonly Dictionary<Vector2Int, CancellationTokenSource> _pending = new();

    void Start()
    {
        if (dataProvider != null)
        {
            dataProvider.heightResolution = heightResolution;
            dataProvider.alphaResolution = alphaResolution;
            dataProvider.terrainHeight = terrainHeight;
        }
    }

    void Update()
    {
        if (player == null || dataProvider == null) return;

        Vector2Int playerChunk = WorldToChunk(player.position);
        var wanted = GatherWanted(playerChunk, renderRadiusInChunks);

        // Spawn missing within radius
        foreach (var c in wanted)
        {
            if (_active.ContainsKey(c) || _pending.ContainsKey(c)) continue;
            if (_active.Count + _pending.Count >= maxActiveChunks) break;
            SpawnChunkAsync(c);
        }

        // Unload chunks outside radius
        var toRemove = new List<Vector2Int>();
        foreach (var kvp in _active)
        {
            if (!wanted.Contains(kvp.Key))
            {
                toRemove.Add(kvp.Key);
            }
        }
        foreach (var key in toRemove)
        {
            UnloadChunk(key);
        }

        // Cancel pending outside radius
        var cancelList = new List<Vector2Int>();
        foreach (var kvp in _pending)
        {
            if (!wanted.Contains(kvp.Key))
            {
                cancelList.Add(kvp.Key);
            }
        }
        foreach (var key in cancelList)
        {
            _pending[key].Cancel();
            _pending[key].Dispose();
            _pending.Remove(key);
        }
    }

    private Vector2Int WorldToChunk(Vector3 pos)
    {
        int cx = Mathf.FloorToInt(pos.x / chunkSize);
        int cz = Mathf.FloorToInt(pos.z / chunkSize);
        return new Vector2Int(cx, cz);
    }

    private HashSet<Vector2Int> GatherWanted(Vector2Int center, int radius)
    {
        var set = new HashSet<Vector2Int>();
        for (int dz = -radius; dz <= radius; dz++)
        {
            for (int dx = -radius; dx <= radius; dx++)
            {
                // Chebyshev distance
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= radius)
                {
                    set.Add(new Vector2Int(center.x + dx, center.y + dz));
                }
            }
        }
        return set;
    }

    private async void SpawnChunkAsync(Vector2Int coord)
    {
        var cts = new CancellationTokenSource();
        _pending[coord] = cts;

        try
        {
            var chunkCoord = new ChunkCoord
            {
                x = coord.x,
                z = coord.y,
                chunkSize = chunkSize
            };

            ChunkData data = await dataProvider.GetChunkAsync(chunkCoord, cts.Token);
            if (cts.IsCancellationRequested) return;

            // Create Terrain
            var go = new GameObject($"Chunk_{coord.x}_{coord.y}");
            go.transform.position = new Vector3(coord.x * chunkSize, 0f, coord.y * chunkSize);

            var terrainData = new TerrainData();
            terrainData.heightmapResolution = data.heightResolution;
            terrainData.alphamapResolution = Mathf.Max(16, data.alphaResolution);
            terrainData.size = new Vector3(chunkSize, terrainHeight, chunkSize);

            // Apply heights
            terrainData.SetHeights(0, 0, data.heights);

            // Apply splats if available
            if (data.alphamaps != null && data.layerCount > 0)
            {
                EnsureSplatPrototypes(terrainData, data.layerCount);
                terrainData.SetAlphamaps(0, 0, data.alphamaps);
            }

            var terrain = go.AddComponent<Terrain>();
            go.AddComponent<TerrainCollider>().terrainData = terrainData;
            terrain.terrainData = terrainData;
            terrain.drawInstanced = true;

            _active[coord] = terrain;
        }
        catch (OperationCanceledException) { /* ignored */ }
        catch (Exception ex)
        {
            Debug.LogException(ex);
        }
        finally
        {
            if (_pending.TryGetValue(coord, out var token))
            {
                token.Dispose();
                _pending.Remove(coord);
            }
        }
    }

    private void UnloadChunk(Vector2Int coord)
    {
        if (_active.TryGetValue(coord, out var t))
        {
            if (t != null)
            {
                Destroy(t.gameObject);
            }
            _active.Remove(coord);
        }
    }

    private void EnsureSplatPrototypes(TerrainData td, int layerCount)
    {
        // Ensure there are at least 'layerCount' TerrainLayers. In production, assign real textures.
        var layers = td.terrainLayers;
        if (layers == null) layers = Array.Empty<TerrainLayer>();
        if (layers.Length < layerCount)
        {
            var list = new List<TerrainLayer>(layers);
            for (int i = layers.Length; i < layerCount; i++)
            {
                var tl = new TerrainLayer();
                tl.diffuseTexture = Texture2D.grayTexture;
                tl.tileSize = new Vector2(10, 10);
                list.Add(tl);
            }
            td.terrainLayers = list.ToArray();
        }
    }
}

#endregion
