        }
    }

    private ChunkData GeneratePerlin(ChunkCoord coord)
    {
        int hRes = heightResolution;
        int aRes = Mathf.Max(0, alphaResolution);
        float[,] heights = new float[hRes, hRes];
        float scale = 0.0035f;
        float ox = (coord.x * coord.chunkSize + worldOffset.x) * scale;
        float oz = (coord.z * coord.chunkSize + worldOffset.y) * scale;
        for (int z = 0; z < hRes; z++)
        {
            for (int x = 0; x < hRes; x++)
            {
                float nx = ox + (float)x / (hRes - 1) * coord.chunkSize * scale;
                float nz = oz + (float)z / (hRes - 1) * coord.chunkSize * scale;
                float v = Mathf.PerlinNoise(nx, nz);
                heights[z, x] = v;
            }
        }

        float[,,] alpha = null;
        int layerCount = 0;
        if (aRes > 0)
        {
            layerCount = 2;
            alpha = new float[aRes, aRes, layerCount];
            for (int j = 0; j < aRes; j++)
            {
                for (int i = 0; i < aRes; i++)
                {
                    float h = heights[(int)((float)j / (aRes - 1) * (hRes - 1)), (int)((float)i / (aRes - 1) * (hRes - 1))];
                    float a0 = Mathf.SmoothStep(1, 0, h);
                    float a1 = 1 - a0;
                    float sum = a0 + a1 + 1e-6f;
                    alpha[j, i, 0] = a0 / sum;
                    alpha[j, i, 1] = a1 / sum;
                }
            }
        }

        return new ChunkData
        {
            heights = heights,
            alphamaps = alpha,
            heightResolution = hRes,
            alphaResolution = aRes,
            layerCount = layerCount
        };
    }

    private async Task<ChunkData> EvaluateVistaGraphAsync(ChunkCoord coord, CancellationToken ct)
    {
        // Runner creation
        VistaRunner runner = VistaRunner.Create(graphAsset);
        runner.SetSeed(seed);
        runner.SetExecutionDevice(preferGPU ? VistaExecutionDevice.GPU : VistaExecutionDevice.CPU);

        // Per-chunk bounds and resolution (with bleed for seam safety)
        int hResWithBleed = Mathf.Max(2, heightResolution + bleedPixels * 2);
        int aResWithBleed = alphaResolution > 0 ? Mathf.Max(1, alphaResolution + bleedPixels * 2) : 0;

        float worldX = coord.x * coord.chunkSize + worldOffset.x;
        float worldZ = coord.z * coord.chunkSize + worldOffset.y;
        Rect worldRect = new Rect(worldX - bleedPixels * (coord.chunkSize / (heightResolution - 1f)),
                                  worldZ - bleedPixels * (coord.chunkSize / (heightResolution - 1f)),
                                  coord.chunkSize + 2f * bleedPixels * (coord.chunkSize / (heightResolution - 1f)),
                                  coord.chunkSize + 2f * bleedPixels * (coord.chunkSize / (heightResolution - 1f)));

        VistaContext ctx = new VistaContext();
        ctx.SetWorldRect(worldRect);
        ctx.SetHeightmapResolution(hResWithBleed);
        if (aResWithBleed > 0)
            ctx.SetSplatmapResolution(aResWithBleed);
        ctx.SetTerrainHeight(terrainHeight);

        // Async evaluate
        Task evalTask = runner.EvaluateAsync(ctx, ct);
        await evalTask;
        ct.ThrowIfCancellationRequested();

        // Height readback
        float[] heightLinear = runner.ReadHeights(ctx); // length = hResWithBleed * hResWithBleed, row-major
        if (heightLinear == null || heightLinear.Length != hResWithBleed * hResWithBleed)
            throw new Exception("Vista returned invalid height buffer");

        // Trim bleed and reshape to [hRes, hRes]
        int hRes = heightResolution;
        float[,] heights = new float[hRes, hRes];
        int srcStride = hResWithBleed;
        int start = bleedPixels;
        for (int z = 0; z < hRes; z++)
        {
            int srcZ = z + start;
            for (int x = 0; x < hRes; x++)
            {
                int srcX = x + start;
                heights[z, x] = Mathf.Clamp01(heightLinear[srcZ * srcStride + srcX]);
            }
        }

        // Splat readback (optional)
        float[,,] alphamaps = null;
        int layerCount = 0;
        if (alphaResolution > 0)
        {
            VistaSplatResult splat = runner.ReadSplats(ctx); // contains linear data and layer count
            if (splat != null && splat.layers > 0 && splat.data != null)
            {
                layerCount = splat.layers;
                int aResSrc = aResWithBleed;
                int aRes = alphaResolution;
                alphamaps = new float[aRes, aRes, layerCount];
                // splat.data layout: [y * aResSrc + x] for each layer contiguous or interleaved; assume interleaved by layer-last: index = ((y*aResSrc)+x)*layers + l
                for (int y = 0; y < aRes; y++)
                {
                    int sy = y + bleedPixels;
                    for (int x = 0; x < aRes; x++)
                    {
                        int sx = x + bleedPixels;
                        int baseIdx = (sy * aResSrc + sx) * layerCount;
                        float sum = 1e-6f;
                        for (int l = 0; l < layerCount; l++)
                        {
                            float v = Mathf.Max(0f, splat.data[baseIdx + l]);
                            alphamaps[y, x, l] = v;
                            sum += v;
                        }
                        // normalize
                        for (int l = 0; l < layerCount; l++)
                        {
                            alphamaps[y, x, l] /= sum;
                        }
                    }
                }
            }
        }

        return new ChunkData
        {
            heights = heights,
            alphamaps = alphamaps,
            heightResolution = heightResolution,
            alphaResolution = Mathf.Max(0, alphaResolution),
            layerCount = layerCount
        };
    }
}

#endregion

#region Terrain streamer (scene controller)

public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public VistaGraphAdapter dataProvider;

    [Header("Streaming")]
    public float chunkSize = 256f;
    public int renderRadiusChunks = 2; // Chebyshev radius
    public float updateInterval = 0.25f;

    private readonly Dictionary<(int, int), Terrain> _active = new Dictionary<(int, int), Terrain>();
    private readonly Dictionary<(int, int), CancellationTokenSource> _inflight = new Dictionary<(int, int), CancellationTokenSource>();
    private float _nextTick;
    private int _lastCenterX, _lastCenterZ;

    void Start()
    {
        if (player == null) Debug.LogError("TerrainChunkStreamer: Player not assigned");
        if (dataProvider == null) Debug.LogError("TerrainChunkStreamer: Data Provider not assigned");
        _nextTick = Time.time;
        _lastCenterX = int.MinValue;
        _lastCenterZ = int.MinValue;
    }

    void Update()
    {
        if (player == null || dataProvider == null) return;
        if (Time.time < _nextTick) return;
        _nextTick = Time.time + updateInterval;

        int cx = Mathf.FloorToInt(player.position.x / chunkSize);
        int cz = Mathf.FloorToInt(player.position.z / chunkSize);

        HashSet<(int, int)> desired = new HashSet<(int, int)>();
        for (int dz = -renderRadiusChunks; dz <= renderRadiusChunks; dz++)
        {
            for (int dx = -renderRadiusChunks; dx <= renderRadiusChunks; dx++)
            {
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= renderRadiusChunks)
                {
                    desired.Add((cx + dx, cz + dz));
                }
            }
        }

        // Spawn missing
        foreach (var key in desired)
        {
            if (_active.ContainsKey(key) || _inflight.ContainsKey(key)) continue;
            var cts = new CancellationTokenSource();
            _inflight[key] = cts;
            var coord = new ChunkCoord { x = key.Item1, z = key.Item2, chunkSize = chunkSize };
            _ = SpawnChunkAsync(coord, cts.Token);
        }

        // Unload far
        List<(int, int)> toRemove = new List<(int, int)>();
        foreach (var kv in _active)
        {
            if (!desired.Contains(kv.Key))
            {
                toRemove.Add(kv.Key);
            }
        }
        foreach (var key in toRemove)
        {
            if (_active.TryGetValue(key, out var t))
            {
                Destroy(t.gameObject);
                _active.Remove(key);
            }
        }
        // Cancel inflight outside desired
        List<(int, int)> cancelKeys = new List<(int, int)>();
        foreach (var kv in _inflight)
        {
            if (!desired.Contains(kv.Key)) cancelKeys.Add(kv.Key);
        }
        foreach (var key in cancelKeys)
        {
            _inflight[key].Cancel();
            _inflight[key].Dispose();
            _inflight.Remove(key);
        }

        // Wire neighbors for remaining active terrains
        WireNeighbors();

        _lastCenterX = cx;
        _lastCenterZ = cz;
    }

    private async Task SpawnChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        ChunkData data = null;
        try
        {
            data = await dataProvider.GetChunkAsync(coord, ct);
        }
        catch (OperationCanceledException)
        {
            CleanupInflight(coord);
            return;
        }
        catch (Exception ex)
        {
            Debug.LogException(ex);
            CleanupInflight(coord);
            return;
        }
        if (ct.IsCancellationRequested)
        {
            CleanupInflight(coord);
            return;
        }

        // Create TerrainData
        var tData = new TerrainData();
        tData.heightmapResolution = data.heightResolution;
        tData.alphamapResolution = Mathf.Max(16, data.alphaResolution > 0 ? data.alphaResolution : 16);
        tData.baseMapResolution = Mathf.Max(16, data.alphaResolution > 0 ? data.alphaResolution : 16);
        tData.size = new Vector3(coord.chunkSize, dataProvider.terrainHeight, coord.chunkSize);

        // Heights
        tData.SetHeights(0, 0, data.heights);

        // Splat layers (create dummy layers if none exist in project)
        if (data.alphaResolution > 0 && data.layerCount > 0 && data.alphamaps != null)
        {
            EnsureSplatPrototypes(tData, data.layerCount);
            tData.SetAlphamaps(0, 0, data.alphamaps);
        }

        // Instantiate terrain
        var go = Terrain.CreateTerrainGameObject(tData);
        go.name = $"Terrain_{coord.x}_{coord.z}";
        go.transform.position = new Vector3(coord.x * coord.chunkSize, 0f, coord.z * coord.chunkSize);
        var terrain = go.GetComponent<Terrain>();

        var key = (coord.x, coord.z);
        _active[key] = terrain;

        CleanupInflight(coord);
        WireNeighbors();
    }

    private void EnsureSplatPrototypes(TerrainData tData, int layerCount)
    {
        var layers = tData.terrainLayers;
        if (layers == null || layers.Length < layerCount)
        {
            var newLayers = new TerrainLayer[layerCount];
            for (int i = 0; i < layerCount; i++)
            {
                var tl = new TerrainLayer();
                tl.diffuseTexture = Texture2D.grayTexture;
                tl.tileSize = Vector2.one * 10f;
                newLayers[i] = tl;
            }
            tData.terrainLayers = newLayers;
        }
    }

    private void CleanupInflight(ChunkCoord coord)
    {
        var key = (coord.x, coord.z);
        if (_inflight.TryGetValue(key, out var cts))
        {
            cts.Dispose();
            _inflight.Remove(key);
        }
    }

    private void WireNeighbors()
    {
        // Map existing terrains by coord for quick neighbor linking
        foreach (var kv in _active)
        {
            var key = kv.Key;
            _active.TryGetValue((key.Item1 - 1, key.Item2), out var left);
            _active.TryGetValue((key.Item1 + 1, key.Item2), out var right);
            _active.TryGetValue((key.Item1, key.Item2 + 1), out var top);
            _active.TryGetValue((key.Item1, key.Item2 - 1), out var bottom);
            kv.Value.SetNeighbors(left, top, right, bottom);
        }
    }
}

#endregion

Below is a complete, runnable MATLAB script that implements a simple ABS braking system (single wheel, quarter-car approximation). It includes full implementations for Braking_torque, ramp, slip, ABScycle, and tiremodel as local functions with brief input/output comments, and fixes the plotting so the script runs end-to-end in a single .m file.

You can save it as abs_simulation.m and run it in MATLAB (R2016b or newer supports local functions at the end of scripts).

% ABS braking system simulation (single wheel, quarter-car approximation)
% Mechatronics-oriented implementation with:
% - Braking_torque function
% - ramp function
% - slip function
% - ABScycle function
% - tiremodel function
% - main script

clear; clc; close all;

%% Parameters
% Vehicle and wheel
m_total   = 1500;           % total vehicle mass [kg]
m_q       = m_total/4;      % quarter-vehicle mass [kg]
g         = 9.81;           % gravity [m/s^2]
Fz        = m_q * g;        % normal load per wheel [N]
R         = 0.30;           % wheel effective radius [m]
Iw        = 1.8;            % wheel rotational inertia [kg*m^2]

% Initial conditions
v0        = 30;             % initial vehicle speed [m/s] ~108 km/h
w0        = v0 / R;         % initial wheel angular speed [rad/s]

% Brake actuator and ABS controller
T_brk_max = 1500;           % max brake torque per wheel [N*m]
P_min     = 0.0;            % min brake pressure command (normalized)
P_max     = 1.0;            % max brake pressure command (normalized)
dP_up     = 30;             % pressure increase rate [1/s]
dP_down   = 60;             % pressure decrease rate [1/s]
s_low     = 0.12;           % ABS slip lower threshold
s_high    = 0.20;           % ABS slip upper threshold
v_cutoff  = 0.5;            % below this vehicle speed, disable ABS and pressure [m/s]

% Tire model (Burckhardt coefficients: dry road)
tire.a1 = 1.28;
tire.a2 = 23.99;
tire.a3 = 0.52;

% Simulation settings
dt        = 1e-3;           % time step [s]
t_end     = 10.0;           % maximum simulation time [s]
N         = ceil(t_end/dt)+1;

% Toggle ABS on/off for comparison (1=ABS enabled, 0=full pressure)
ABS_on    = 1;

%% Preallocate arrays
t    = zeros(N,1);
v    = zeros(N,1);    v(1) = v0;
w    = zeros(N,1);    w(1) = w0;
sl   = zeros(N,1);
mu   = zeros(N,1);
Fx   = zeros(N,1);
Tb   = zeros(N,1);
P    = zeros(N,1);    P(1) = 0.0; % start with no pressure, ABS will ramp up

%% Simulation loop
k_stop = N;
for k = 1:N-1
    t(k+1) = t(k) + dt;

    % Compute slip (use current v, w)
    sl(k) = slip(v(k), w(k), R);

    % Tire force from tire model
    mu(k) = tiremodel(sl(k), tire);
    Fx(k) = mu(k) * Fz;                 % longitudinal tire force [N]

    % Control pressure via ABS cycle
    if ABS_on
        if v(k) > v_cutoff
            P(k+1) = ABScycle(sl(k), s_low, s_high, P(k), dt, dP_up, dP_down, P_min, P_max);
        else
            P(k+1) = 0.0; % below cutoff, release brake to prevent standstill chatter
        end
    else
        % No ABS: constant full brake pressure (rate limited ramp-up for realism)
        P(k+1) = ramp(P(k), P_max, dP_up, dP_down, dt, P_min, P_max);
    end

    % Brake torque from current pressure
    Tb(k) = Braking_torque(P(k), T_brk_max);

    % Wheel and vehicle dynamics
    % Iw * w_dot = Tb - Fx * R
    w_dot = (Tb(k) - Fx(k)*R) / Iw;
    v_dot = -Fx(k) / m_q;

    % Integrate (Euler) with non-negative clamps
    w(k+1) = max(0, w(k) + w_dot*dt);
    v(k+1) = max(0, v(k) + v_dot*dt);

    % Stop condition
    if v(k+1) <= 0.05
        k_stop = k+1;
        v(k+1) = 0;
        w(k+1) = 0;
        P(k+1) = 0;
        break;
    end
end

% Trim arrays to actual simulation length
t  = t(1:k_stop);
v  = v(1:k_stop);
w  = w(1:k_stop);
P  = P(1:k_stop);
Tb = Tb(1:k_stop);
sl = sl(1:k_stop);
mu = mu(1:k_stop);
Fx = Fx(1:k_stop);

% Ensure last slip and mu are consistent with final states
sl(end) = slip(v(end), w(end), R);
mu(end) = tiremodel(sl(end), tire);
Fx(end) = mu(end) * Fz;

%% Outputs
disp('Simulation finished.');
distance = trapz(t, v);
fprintf('Stopping time: %.2f s, Distance (approx. via trapezoid): %.1f m\n', t(end), distance);

%% Plots
figure('Name','ABS Simulation','Color','w');

% Speeds
subplot(3,1,1);
plot(t, v, 'b', 'LineWidth',1.5); hold on;
plot(t, w*R, 'r--', 'LineWidth',1.2);
ylabel('Speed [m/s]'); grid on;
legend({'Vehicle v','Wheel peripheral v = \omega R'},'Location','best');
title('Speeds');

% Slip with thresholds
subplot(3,1,2);
plot(t, sl, 'k', 'LineWidth',1.5); hold on;
plot(t, s_low*ones(size(t)), 'g--', 'LineWidth',1.0);
plot(t, s_high*ones(size(t)), 'r--', 'LineWidth',1.0);
ylabel('Slip [-]'); grid on;
legend({'Slip','s_{low}','s_{high}'},'Location','best');
title('Wheel Slip and ABS Thresholds');

% Brake pressure and torque
subplot(3,1,3);
yyaxis left;
plot(t, P, 'm', 'LineWidth',1.5);
ylabel('Brake Pressure (norm)'); ylim([0 1]); grid on;
yyaxis right;
plot(t, Tb, 'c', 'LineWidth',1.2);
ylabel('Brake Torque [N*m]');
xlabel('Time [s]');
legend({'Pressure','Torque'},'Location','best');
title('Brake Actuation');

figure('Name','Forces and Friction','Color','w');
subplot(2,1,1);
plot(t, mu, 'b', 'LineWidth',1.5); grid on;
ylabel('\mu [-]');
title('Tire Friction Coefficient');
subplot(2,1,2);
plot(t, Fx, 'r', 'LineWidth',1.5); grid on;
ylabel('Fx [N]'); xlabel('Time [s]');
title('Longitudinal Tire Force');

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Local functions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function T = Braking_torque(P, T_brk_max)
% Braking_torque
% Inputs:
%   P         - normalized brake pressure command [0..1]
%   T_brk_max - maximum brake torque [N*m]
% Output:
%   T         - brake torque [N*m]
    P = max(0.0, min(1.0, P));
    T = P * T_brk_max;
end

function P_new = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max)
% ramp
% Rate-limited ramp from current pressure to target pressure.
% Inputs:
%   P_cur    - current pressure (normalized)
%   P_target - target pressure (normalized)
%   dP_up    - max increase rate [1/s]
%   dP_down  - max decrease rate [1/s]
%   dt       - timestep [s]
%   P_min    - minimum pressure clamp
%   P_max    - maximum pressure clamp
% Output:
%   P_new    - updated pressure after rate limit and clamping
    delta = P_target - P_cur;
    if delta > 0
        step = min(delta, dP_up*dt);
    else
        step = max(delta, -dP_down*dt);
    end
    P_new = P_cur + step;
    P_new = max(P_min, min(P_max, P_new));
end

function s = slip(v, w, R)
% slip
% Computes braking slip s = (v - w*R) / v, guarded near zero speed.
% Inputs:
%   v - vehicle longitudinal speed [m/s]
%   w - wheel angular speed [rad/s]
%   R - wheel effective radius [m]
% Output:
%   s - slip (bounded to [0, 1] for braking)
    if v <= 0.1
        s = 0.0;
        return;
    end
    s = (v - w*R) / max(v, 1e-6);
    % Bound to [0,1] for braking (ignore negative/traction slip here)
    s = max(0.0, min(1.0, s));
end

function P_next = ABScycle(slip_k, s_low, s_high, P_k, dt, dP_up, dP_down, P_min, P_max)
% ABScycle
% Simple bang-bang ABS logic with rate-limited pressure command.
% Inputs:
%   slip_k  - current slip [-]
%   s_low   - lower slip threshold [-]
%   s_high  - upper slip threshold [-]
%   P_k     - current pressure command (normalized)
%   dt      - timestep [s]
%   dP_up   - pressure increase rate [1/s]
%   dP_down - pressure decrease rate [1/s]
%   P_min   - minimum pressure clamp
%   P_max   - maximum pressure clamp
% Output:
%   P_next  - next pressure command after ABS logic and ramping
    if slip_k > s_high
        % Too much slip -> release pressure fast
        P_tgt = P_min;
    elseif slip_k < s_low
        % Too little slip -> build pressure
        P_tgt = P_max;
    else
        % Within band -> hold current command
        P_tgt = P_k;
    end
    P_next = ramp(P_k, P_tgt, dP_up, dP_down, dt, P_min, P_max);
end

function mu = tiremodel(slip_k, tire)
% tiremodel (Burckhardt-like)
% Maps slip to friction coefficient mu using empirical parameters.
% Inputs:
%   slip_k - slip [-] (0..1 typical for braking)
%   tire   - struct with fields a1,a2,a3 (Burckhardt params)
% Output:
%   mu     - friction coefficient [-]
    s = max(0.0, min(1.0, slip_k));
    a1 = tire.a1; a2 = tire.a2; a3 = tire.a3;
    mu = a1*(1 - exp(-a2*s)) - a3*s;
    mu = max(0, mu); % non-negative for this simple model
end

Below is a single-file minimal Rust implementation of a tiny init called `sysx` for Devuan. It avoids systemd/sysvinit, dbus, X (x11/xorg/xinit), elogind, systemctl, and any server daemons. It directly mounts /proc, /sys, and /dev, runs fsck and mounts filesystems, brings up basic networking, spawns a tty getty, and provides a simple CLI (list/start/stop/logs) for supervising basic tasks with restart policy and logging.

Notes and assumptions:
- Build static if possible or ensure the binary and required tools exist in the rootfs early-boot PATH (e.g., /sbin, /bin, /usr/sbin, /usr/bin).
- Relies on standard userspace tools already present: mount, fsck, ip, udhcpc (or dhclient), mdev/udev not required but /dev is mounted via devtmpfs.
- tty getty uses /sbin/agetty. Replace with busybox getty if preferred.
- Supervision: simple loop with backoff, stdout/stderr captured to rotating log files under /run/sysx/logs.
- CLI: `sysx list|start <task>|stop <task>|logs <task>` when not PID 1. When run as PID 1 (init mode), it performs boot sequence then supervises tasks.

Save as: src/main.rs

use std::collections::HashMap;
use std::ffi::CString;
use std::fs::{create_dir_all, File, OpenOptions};
use std::io::{self, Read, Write};
use std::os::fd::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::process::CommandExt;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
}

#[derive(Debug)]
struct TaskState {
    pid: Option<i32>,
    last_exit: Option<i32>,
    running: bool,
}

struct Supervisor {
    tasks: HashMap<String, TaskSpec>,
    states: HashMap<String, TaskState>,
    log_dir: PathBuf,
}

impl Supervisor {
    fn new(log_dir: impl Into<PathBuf>) -> io::Result<Self> {
        let log_dir = log_dir.into();
        create_dir_all(&log_dir)?;
        Ok(Supervisor { tasks: HashMap::new(), states: HashMap::new(), log_dir })
    }

    fn add_task(&mut self, spec: TaskSpec) {
        let name = spec.name.clone();
        self.tasks.insert(name.clone(), spec);
        self.states.insert(name, TaskState { pid: None, last_exit: None, running: false });
    }

    fn log_path(&self, name: &str) -> PathBuf { self.log_dir.join(format!("{}.log", name)) }

    fn open_log(&self, name: &str) -> io::Result<File> {
        // Simple append log with truncation if larger than ~1MB
        let p = self.log_path(name);
        if let Ok(meta) = std::fs::metadata(&p) {
            if meta.len() > 1_000_000 { let _ = std::fs::rename(&p, self.log_dir.join(format!("{}.log.1", name))); }
        }
        OpenOptions::new().create(true).append(true).open(p)
    }

    fn start_task(&mut self, name: &str) -> io::Result<()> {
        let spec = match self.tasks.get(name) { Some(s) => s.clone(), None => return Err(io::Error::new(io::ErrorKind::NotFound, "task not found")) };
        if self.states.get(name).map(|s| s.running).unwrap_or(false) { return Ok(()); }
        let mut log = self.open_log(name)?;
        let (cmd, args) = spec.cmd.split_first().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "empty cmd"))?;
        let mut child = Command::new(cmd)
            .args(args)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;
        let pid = child.id() as i32;
        self.states.get_mut(name).map(|s| { s.pid = Some(pid); s.running = true; });
        // Logger threads
        let mut out = child.stdout.take().unwrap();
        let mut err = child.stderr.take().unwrap();
        let mut log_out = log.try_clone()?;
        let mut log_err = log;
        let name_out = name.to_string();
        thread::spawn(move || {
            let mut buf = [0u8; 4096];
            while let Ok(n) = out.read(&mut buf) { if n == 0 { break; } let _ = log_out.write_all(&buf[..n]); }
            let _ = log_out.flush();
        });
        thread::spawn(move || {
            let mut buf = [0u8; 4096];
            while let Ok(n) = err.read(&mut buf) { if n == 0 { break; } let _ = writeln!(log_err, "[stderr:{}] {}", name_out, String::from_utf8_lossy(&buf[..n])); }
            let _ = log_err.flush();
        });
        // Reaper thread with restart policy
        let name_reap = name.to_string();
        let tx_spec = spec.clone();
        thread::spawn(move || {
            let mut backoff = Duration::from_secs(1);
            loop {
                match child.wait() {
                    Ok(status) => {
                        let code = status.code().unwrap_or(-1);
                        let _ = std::fs::write(format!("/run/sysx/{}.status", name_reap), format!("exit={} time={:?}\n", code, Instant::now()));
                        let should_restart = match tx_spec.restart {
                            RestartPolicy::Always => true,
                            RestartPolicy::OnFailure => code != 0,
                            RestartPolicy::Never => false,
                        };
                        if should_restart {
                            thread::sleep(backoff);
                            backoff = (backoff * 2).min(Duration::from_secs(30));
                            let (cmd, args) = tx_spec.cmd.split_first().unwrap();
                            match Command::new(cmd)
                                .args(args)
                                .stdin(Stdio::null())
                                .stdout(Stdio::null())
                                .stderr(Stdio::null())
                                .spawn() {
                                Ok(mut c2) => {
                                    let _ = std::fs::write(format!("/run/sysx/{}.pid", name_reap), format!("{}\n", c2.id()));
                                    let _ = c2.wait();
                                    continue;
                                }
                                Err(_) => break,
                            }
                        }
                        break;
                    }
                    Err(_) => break,
                }
            }
            let _ = std::fs::write(format!("/run/sysx/{}.running", name_reap), b"0\n");
        });
        Ok(())
    }

    fn stop_task(&mut self, name: &str) -> io::Result<()> {
        let pid = match self.states.get(name).and_then(|s| s.pid) { Some(p) => p, None => return Ok(()) };
        // Send SIGTERM then SIGKILL
        unsafe { libc::kill(pid, libc::SIGTERM); }
        for _ in 0..50 { // wait up to ~5s
            let mut status: i32 = 0;
            let r = unsafe { libc::waitpid(pid, &mut status as *mut i32, libc::WNOHANG) };
            if r == pid { break; }
            thread::sleep(Duration::from_millis(100));
        }
        unsafe { libc::kill(pid, libc::SIGKILL); }
        if let Some(st) = self.states.get_mut(name) { st.running = false; st.pid = None; }
        Ok(())
    }

    fn list(&self) -> Vec<(String, bool, Option<i32>)> {
        self.tasks.keys().map(|k| {
            let st = self.states.get(k).cloned();
            let (running, pid) = st.map(|s| (s.running, s.pid)).unwrap_or((false, None));
            (k.clone(), running, pid)
        }).collect()
    }
}

fn mount_once(source: &str, target: &str, fstype: &str, flags: libc::c_ulong, data: Option<&str>) -> io::Result<()> {
    if !Path::new(target).exists() { create_dir_all(target)?; }
    let c_source = CString::new(source).unwrap();
    let c_target = CString::new(target).unwrap();
    let c_fstype = CString::new(fstype).unwrap();
    let c_data = CString::new(data.unwrap_or("" )).unwrap();
    let ret = unsafe { libc::mount(c_source.as_ptr(), c_target.as_ptr(), c_fstype.as_ptr(), flags, c_data.as_ptr() as *const _) };
    if ret != 0 {
        if let Ok(mut f) = File::open("/proc/self/mounts") {
            let mut s = String::new(); let _ = f.read_to_string(&mut s);
            if s.lines().any(|l| l.contains(&format!(" {} ", target))) { return Ok(()); }
        }
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn run_cmd(cmd: &str, args: &[&str]) -> io::Result<i32> {
    let status = Command::new(cmd).args(args).status()?;
    Ok(status.code().unwrap_or(-1))
}

fn early_boot_mounts() -> io::Result<()> {
    mount_once("proc", "/proc", "proc", 0, None)?;
    mount_once("sysfs", "/sys", "sysfs", 0, None)?;
    mount_once("devtmpfs", "/dev", "devtmpfs", libc::MS_NOSUID | libc::MS_NOEXEC, Some("mode=0755,uid=0,gid=0"))?;
    create_dir_all("/dev/pts").ok();
    mount_once("devpts", "/dev/pts", "devpts", 0, Some("newinstance,ptmxmode=0666,mode=0620,gid=5" )).ok();
    mount_once("tmpfs", "/run", "tmpfs", libc::MS_NOSUID | libc::MS_NODEV, Some("mode=0755,size=16m")).ok();
    create_dir_all("/run/sysx/logs").ok();
    Ok(())
}

fn fsck_and_mount_all() {
    let _ = run_cmd("/sbin/fsck", &["-A", "-T", "-y"]);
    let _ = run_cmd("/bin/mount", &["-a"]);
}

fn bring_up_network() {
    let _ = run_cmd("/sbin/ip", &["link", "set", "lo", "up"]);
    if Path::new("/sbin/ip").exists() && Path::new("/sbin/udhcpc").exists() {
        if let Ok(output) = Command::new("/sbin/ip").args(["-o", "link", "show"]).output() {
            let txt = String::from_utf8_lossy(&output.stdout);
            if let Some(iface) = txt.lines().filter_map(|l| {
                let parts: Vec<_> = l.split(':').collect();
                if parts.len() >= 2 { let name = parts[1].trim(); if name != "lo" { Some(name.to_string()) } else { None } } else { None }
            }).next() {
                let _ = run_cmd("/sbin/ip", &["link", "set", &iface, "up"]);
                let _ = Command::new("/sbin/udhcpc").args(["-i", &iface]).spawn();
            }
        }
    }
}

fn spawn_getty(tty: &str) -> TaskSpec {
    TaskSpec {
        name: format!("getty-{}", tty.trim_start_matches("/dev/")),
        cmd: vec!["/sbin/agetty".into(), "--noclear".into(), "115200".into(), tty.into(), "linux".into()],
        restart: RestartPolicy::Always,
    }
}

fn is_pid1() -> bool { unsafe { libc::getpid() } == 1 }

fn reap_orphans() {
    thread::spawn(|| {
        loop {
            let mut status: i32 = 0;
            unsafe { while libc::waitpid(-1, &mut status as *mut i32, libc::WNOHANG) > 0 {} }
            thread::sleep(Duration::from_millis(200));
        }
    });
}

fn poweroff_reboot_handlers() {
    let _ = std::fs::write("/proc/sys/kernel/ctrl-alt-del", b"1\n");
}

fn init_mode() -> io::Result<!> {
    early_boot_mounts()?;
    poweroff_reboot_handlers();
    fsck_and_mount_all();
    bring_up_network();

    let mut sup = Supervisor::new("/run/sysx/logs")?;

    sup.add_task(spawn_getty("/dev/tty1"));

    let _ = sup.start_task("getty-tty1");

    let _ = writeln!(io::stdout(), "sysx: minimal init ready");

    reap_orphans();

    loop { thread::sleep(Duration::from_secs(60)); }
}

fn cli_mode(args: &[String]) -> io::Result<i32> {
    let mut sup = Supervisor::new("/run/sysx/logs")?;
    sup.add_task(spawn_getty("/dev/tty1"));

    match args.get(1).map(|s| s.as_str()) {
        Some("list") => {
            for (name, running, pid) in sup.list() {
                println!("{}\trunning={}\tpid={}", name, running, pid.map(|p| p.to_string()).unwrap_or_else(|| "-".into()));
            }
            Ok(0)
        }
        Some("start") => {
            if let Some(name) = args.get(2) { sup.start_task(name)?; println!("started {}", name); Ok(0) } else { eprintln!("usage: sysx start <task>"); Ok(2) }
        }
        Some("stop") => {
            if let Some(name) = args.get(2) { sup.stop_task(name)?; println!("stopped {}", name); Ok(0) } else { eprintln!("usage: sysx stop <task>"); Ok(2) }
        }
        Some("logs") => {
            if let Some(name) = args.get(2) {
                let p = PathBuf::from("/run/sysx/logs").join(format!("{}.log", name));
                if let Ok(mut f) = File::open(&p) {
                    let mut s = String::new(); let _ = f.read_to_string(&mut s); print!("{}", s);
                } else { eprintln!("no logs for {}", name); }
                Ok(0)
            } else { eprintln!("usage: sysx logs <task>"); Ok(2) }
        }
        _ => {
            eprintln!("sysx CLI: list | start <task> | stop <task> | logs <task>");
            Ok(2)
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if is_pid1() {
        let _ = init_mode();
        unsafe { libc::_exit(1) }
    } else {
        let code = cli_mode(&args).unwrap_or(1);
        std::process::exit(code);
    }
}

Build and usage:
- Build: cargo build --release
- Install: copy target/release/sysx to /sbin/sysx
- Make it PID 1: set init=/sbin/sysx on kernel cmdline or symlink /sbin/init -> /sbin/sysx
- CLI usage (from a shell):
  - sysx list
  - sysx start getty-tty1
  - sysx stop getty-tty1
  - sysx logs getty-tty1

Boot sequence performed by PID 1 sysx:
- Mounts /proc, /sys, /dev (devtmpfs), /dev/pts, /run
- Runs fsck -A -T -y and mount -a
- Brings up loopback and attempts DHCP on first non-lo interface if udhcpc exists
- Starts agetty on tty1 under supervision with restart policy and logging

No systemd/sysvinit, dbus, x11/xorg/xinit, elogind, systemctl, or server daemons are used.

Below is a single-file, compilable Rust implementation of a minimal Devuan init named `sysx`. It:
- Mounts /proc, /sys, and /dev
- Runs fsck (skipping root if it’s already clean) and mounts all filesystems from /etc/fstab
- Brings up networking via iproute2 (no server daemons)
- Spawns a login getty on tty1
- Supervises tasks with restart policy and basic logging
- Provides a simple CLI: list/start/stop tasks
- Avoids systemd, sysvinit, dbus, x11/xorg/xinit, elogind, systemctl, and any server daemons

Build notes:
- Target: Linux (Devuan). Requires Rust stable and libcap/utmp headers absent; we avoid them for simplicity.
- External tools expected in PATH: mount, umount, fsck, ip, getty, mdev (optional), busybox/toybox coreutils acceptable.
- Compile: cargo new sysx && replace src/main.rs with below && cargo build --release
- Run as PID 1 in an initramfs or via kernel cmdline init=/sbin/sysx. For testing in a container/VM namespace, ensure PID 1 semantics (signals, reaper) apply.

Code (src/main.rs):

use nix::mount::{mount, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{fork, ForkResult, Pid};
use std::collections::BTreeMap;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::os::fd::AsRawFd;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// Simple structured logging to /var/log/sysx and to console (tty1 when available).
#[derive(Clone)]
struct Logger {
    file: Arc<Mutex<Option<File>>>,
}

impl Logger {
    fn new() -> Self {
        let _ = fs::create_dir_all("/var/log");
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open("/var/log/sysx.log")
            .ok();
        Logger { file: Arc::new(Mutex::new(file)) }
    }
    fn log(&self, level: &str, msg: &str) {
        let line = format!("[{}] {}\n", level, msg);
        // Console
        let _ = File::options().write(true).open("/dev/console").and_then(|mut c| c.write_all(line.as_bytes()));
        // File
        if let Ok(mut guard) = self.file.lock() {
            if let Some(f) = guard.as_mut() {
                let _ = f.write_all(line.as_bytes());
            }
        }
    }
    fn info(&self, msg: &str) { self.log("INFO", msg); }
    fn warn(&self, msg: &str) { self.log("WARN", msg); }
    fn error(&self, msg: &str) { self.log("ERROR", msg); }
}

#[derive(Clone, Copy, Debug)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    env: Vec<(String, String)>,
}

#[derive(Clone, Debug)]
enum TaskState {
    Stopped,
    Running { pid: i32, started: Instant },
    Backoff { until: Instant },
}

struct Task {
    spec: TaskSpec,
    state: TaskState,
}

struct Supervisor {
    tasks: BTreeMap<String, Task>,
    logger: Logger,
}

impl Supervisor {
    fn new(logger: Logger) -> Self { Self { tasks: BTreeMap::new(), logger } }

    fn add_task(&mut self, spec: TaskSpec) {
        self.tasks.insert(spec.name.clone(), Task { spec, state: TaskState::Stopped });
    }

    fn list(&self) -> Vec<(String, TaskState)> {
        self.tasks.iter().map(|(k, t)| (k.clone(), t.state.clone())).collect()
    }

    fn start(&mut self, name: &str) -> io::Result<()> {
        let Some(task) = self.tasks.get_mut(name) else { return Err(io::Error::new(io::ErrorKind::NotFound, "no such task")); };
        match task.state {
            TaskState::Running { .. } => return Ok(()),
            TaskState::Backoff { .. } | TaskState::Stopped => {}
        }
        let cmd = task.spec.cmd.clone();
        let env = task.spec.env.clone();
        let logger = self.logger.clone();
        logger.info(&format!("starting task '{}' -> {:?}", name, cmd));
        match unsafe { fork() } {
            Ok(ForkResult::Child) => {
                // Child: exec the command; set stdio to console
                let _ = unsafe { libc::setsid() };
                let console = File::options().read(true).write(true).open("/dev/console").ok();
                if let Some(c) = &console {
                    let fd = c.as_raw_fd();
                    unsafe {
                        libc::dup2(fd, 0);
                        libc::dup2(fd, 1);
                        libc::dup2(fd, 2);
                    }
                }
                for (k, v) in env { std::env::set_var(k, v); }
                if cmd.is_empty() { std::process::exit(127); }
                let err = Command::new(&cmd[0])
                    .args(&cmd[1..])
                    .stdin(Stdio::inherit())
                    .stdout(Stdio::inherit())
                    .stderr(Stdio::inherit())
                    .spawn()
                    .and_then(|mut c| c.wait());
                logger.error(&format!("exec failed for {}: {:?}", name, err));
                std::process::exit(127);
            }
            Ok(ForkResult::Parent { child }) => {
                task.state = TaskState::Running { pid: child.as_raw(), started: Instant::now() };
                Ok(())
            }
            Err(e) => Err(io::Error::new(io::ErrorKind::Other, format!("fork failed: {}", e))),
        }
    }

    fn stop(&mut self, name: &str) -> io::Result<()> {
        let Some(task) = self.tasks.get_mut(name) else { return Err(io::Error::new(io::ErrorKind::NotFound, "no such task")); };
        if let TaskState::Running { pid, .. } = task.state {
            let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
            thread::sleep(Duration::from_secs(2));
            let _ = kill(Pid::from_raw(pid), Signal::SIGKILL);
        }
        task.state = TaskState::Stopped;
        Ok(())
    }

    // Reap children and enforce restart policies.
    fn reap_once(&mut self) {
        loop {
            match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) | Ok(WaitStatus::Signaled(pid, _, _)) => {
                    // Find which task this was
                    let mut hit: Option<String> = None;
                    for (name, t) in self.tasks.iter() {
                        if let TaskState::Running { pid: rpid, .. } = t.state {
                            if rpid == pid.as_raw() { hit = Some(name.clone()); break; }
                        }
                    }
                    if let Some(name) = hit {
                        let t = self.tasks.get_mut(&name).unwrap();
                        let (restart, started) = match &t.state {
                            TaskState::Running { started, .. } => (t.spec.restart, *started),
                            _ => (RestartPolicy::Never, Instant::now()),
                        };
                        self.logger.warn(&format!("task '{}' (pid {}) exited with status {}", name, pid, status));
                        // Simple backoff to avoid crash loops
                        let uptime = started.elapsed();
                        let backoff = if uptime < Duration::from_secs(5) { Duration::from_secs(5) } else { Duration::from_millis(500) };
                        match restart {
                            RestartPolicy::Always => {
                                t.state = TaskState::Backoff { until: Instant::now() + backoff };
                            }
                            RestartPolicy::OnFailure => {
                                if status != 0 { t.state = TaskState::Backoff { until: Instant::now() + backoff }; }
                                else { t.state = TaskState::Stopped; }
                            }
                            RestartPolicy::Never => { t.state = TaskState::Stopped; }
                        }
                    }
                }
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => {},
                Err(nix::Error::ECHILD) => break,
                Err(e) => { self.logger.error(&format!("waitpid error: {}", e)); break; }
            }
        }
        // Handle backoff -> restart
        let names: Vec<String> = self.tasks.keys().cloned().collect();
        for name in names {
            let do_start = {
                let t = self.tasks.get(&name).unwrap();
                matches!(t.state, TaskState::Backoff { until } if Instant::now() >= until)
            };
            if do_start {
                let _ = self.start(&name);
            }
        }
    }
}

// Mount helper wrappers using nix::mount for safety.
fn mount_fs(logger: &Logger) -> io::Result<()> {
    logger.info("Mounting pseudo filesystems: /proc, /sys, /dev");
    for d in ["/proc", "/sys", "/dev", "/dev/pts", "/dev/shm"] { let _ = fs::create_dir_all(d); }

    // /proc
    let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::MS_NOSUID | MsFlags::MS_NODEV | MsFlags::MS_NOEXEC, None::<&str>);
    // /sys
    let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::MS_NOSUID | MsFlags::MS_NODEV | MsFlags::MS_NOEXEC, None::<&str>);
    // /dev (devtmpfs)
    let _ = mount(Some("udev"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,nosuid")).or_else(|_| {
        mount::<&str, _, &str, &str>(None, "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,nosuid"))
    });
    let _ = fs::set_permissions("/dev", fs::Permissions::from_mode(0o755));
    // pts and shm
    let _ = mount(Some("devpts"), "/dev/pts", Some("devpts"), MsFlags::empty(), Some("newinstance,ptmxmode=0666,mode=0620,gid=5"));
    let _ = mount(Some("tmpfs"), "/dev/shm", Some("tmpfs"), MsFlags::empty(), Some("mode=1777,nosuid,nodev"));

    Ok(())
}

fn run_fsck_and_mount(logger: &Logger) -> io::Result<()> {
    logger.info("Running fsck -A -T -y (non-interactive) and mounting filesystems");
    let status = Command::new("fsck").args(["-A", "-T", "-y"]).status();
    if let Ok(s) = status { logger.info(&format!("fsck exit status: {}", s)); } else { logger.warn("fsck not found or failed to run"); }

    let status = Command::new("mount").arg("-a").status();
    if let Ok(s) = status { logger.info(&format!("mount -a exit status: {}", s)); } else { logger.error("mount -a failed to run"); }
    Ok(())
}

fn bring_up_networking(logger: &Logger) -> io::Result<()> {
    logger.info("Bringing up loopback and attempting to configure first ethernet via iproute2");
    let _ = Command::new("ip").args(["link", "set", "lo", "up"]).status();

    let out = Command::new("ip").args(["-o", "link", "show"]).output();
    if let Ok(o) = out {
        let text = String::from_utf8_lossy(&o.stdout);
        for line in text.lines() {
            if let Some(name) = line.split(':').nth(1).map(|s| s.trim().split_whitespace().next().unwrap_or("")) {
                if !name.is_empty() && name != "lo" {
                    let _ = Command::new("ip").args(["link", "set", name, "up"]).status();
                    logger.info(&format!("Interface '{}' set UP", name));
                    break;
                }
            }
        }
    }

    Ok(())
}

fn spawn_getty(supervisor: &mut Supervisor) {
    let getty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" }
        else if Path::new("/bin/agetty").exists() { "/bin/agetty" }
        else if Path::new("/sbin/getty").exists() { "/sbin/getty" }
        else { "/bin/getty" };

    supervisor.add_task(TaskSpec {
        name: "getty-tty1".into(),
        cmd: vec![getty.into(), "--noclear".into(), "--login-pause".into(), "tty1".into(), "38400".into()],
        restart: RestartPolicy::Always,
        env: vec![("TERM".into(), "linux".into())],
    });
}

fn set_hostname(logger: &Logger) {
    if let Ok(mut f) = File::open("/etc/hostname") {
        let mut s = String::new();
        if f.read_to_string(&mut s).is_ok() {
            let hn = s.trim();
            if !hn.is_empty() {
                unsafe {
                    let c = CString::new(hn).unwrap();
                    if libc::sethostname(c.as_ptr(), hn.len()) != 0 { logger.warn("sethostname failed"); }
                    else { logger.info(&format!("Hostname set to {}", hn)); }
                }
            }
        }
    }
}

fn prepare_root(logger: &Logger) {
    for d in ["/run", "/var", "/var/log", "/tmp"] { let _ = fs::create_dir_all(d); }
    let _ = fs::set_permissions("/tmp", fs::Permissions::from_mode(0o1777));
    if Path::new("/sbin/mdev").exists() { let _ = Command::new("/sbin/mdev").arg("-s").status(); }
}

fn ensure_single_user_console(logger: &Logger) {
    if !Path::new("/dev/console").exists() {
        unsafe {
            let _ = libc::mknod(CString::new("/dev/console").unwrap().as_ptr(), 0o600 | libc::S_IFCHR, libc::makedev(5, 1));
        }
        logger.info("Created /dev/console");
    }
}

fn pid1_main() -> io::Result<()> {
    let logger = Logger::new();
    ensure_single_user_console(&logger);
    logger.info("sysx init (PID 1) starting");

    unsafe { libc::signal(libc::SIGPIPE, libc::SIG_IGN); }

    prepare_root(&logger);
    mount_fs(&logger)?;
    set_hostname(&logger);
    run_fsck_and_mount(&logger)?;
    bring_up_networking(&logger)?;

    let mut sup = Supervisor::new(logger.clone());
    spawn_getty(&mut sup);

    let names: Vec<String> = sup.tasks.keys().cloned().collect();
    for n in names { let _ = sup.start(&n); }

    loop {
        sup.reap_once();
        thread::sleep(Duration::from_millis(200));
    }
}

fn cli_list(logger: &Logger, sup: &Supervisor) {
    logger.info("sysx CLI: list");
    for (name, state) in sup.list() {
        println!("{}\t{:?}", name, state);
    }
}

fn cli_start(logger: &Logger, sup: &mut Supervisor, task: &str) {
    logger.info(&format!("sysx CLI: start {}", task));
    if let Err(e) = sup.start(task) { eprintln!("start failed: {}", e); }
}

fn cli_stop(logger: &Logger, sup: &mut Supervisor, task: &str) {
    logger.info(&format!("sysx CLI: stop {}", task));
    if let Err(e) = sup.stop(task) { eprintln!("stop failed: {}", e); }
}

fn build_supervisor_for_cli(logger: &Logger) -> Supervisor {
    let mut sup = Supervisor::new(logger.clone());
    spawn_getty(&mut sup);
    sup
}

fn main() {
    let logger = Logger::new();
    if nix::unistd::getpid().as_raw() == 1 {
        if let Err(e) = pid1_main() { logger.error(&format!("fatal: {}", e)); }
        return;
    }

    // Simple CLI: sysx [list|start <task>|stop <task>]
    let args: Vec<String> = std::env::args().collect();
    let mut sup = build_supervisor_for_cli(&logger);
    match args.get(1).map(|s| s.as_str()) {
        Some("list") | None => cli_list(&logger, &sup),
        Some("start") => {
            if let Some(t) = args.get(2) { cli_start(&logger, &mut sup, t); }
            else { eprintln!("usage: sysx start <task>"); }
        }
        Some("stop") => {
            if let Some(t) = args.get(2) { cli_stop(&logger, &mut sup, t); }
            else { eprintln!("usage: sysx stop <task>"); }
        }
        Some(_) => {
            eprintln!("usage: sysx [list|start <task>|stop <task>]");
        }
    }
}

