use nix::errno::Errno;
use nix::libc;
use nix::mount::{mount, umount2, MsFlags, MntFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::stat::{mknod, Mode, SFlag};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, chroot, execv, fork, ForkResult, Pid};
use std::collections::HashMap;
use std::env;
use std::ffi::CString;
use std::fs::{create_dir_all, File, OpenOptions};
use std::io::{Read, Write};
use std::os::unix::io::IntoRawFd;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use std::{thread};

// Simple logging to console and to /var/log/sysx/<task>.log (once /var is mounted)
fn log(msg: &str) {
    let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    eprintln!("[sysx {}] {}", ts, msg);
}

#[derive(Clone, Copy, Debug)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    // backoff parameters for restart supervision
    min_backoff: Duration,
    max_backoff: Duration,
}

#[derive(Clone, Debug)]
struct TaskState {
    pid: Option<Pid>,
    last_start: Option<Instant>,
    backoff: Duration,
    log_path: Option<String>,
}

struct Supervisor {
    tasks: HashMap<String, TaskSpec>,
    state: HashMap<String, TaskState>,
}

impl Supervisor {
    fn new() -> Self {
        Supervisor { tasks: HashMap::new(), state: HashMap::new() }
    }

    fn add_task(&mut self, spec: TaskSpec) {
        self.state.insert(spec.name.clone(), TaskState { pid: None, last_start: None, backoff: spec.min_backoff, log_path: Some(format!("/var/log/sysx/{}.log", spec.name)) });
        self.tasks.insert(spec.name.clone(), spec);
    }

    fn list(&self) -> Vec<(String, Option<i32>)> {
        let mut out = Vec::new();
        for (name, st) in &self.state {
            out.push((name.clone(), st.pid.map(|p| p.as_raw())));
        }
        out.sort_by(|a, b| a.0.cmp(&b.0));
        out
    }

    fn start(&mut self, name: &str) -> Result<(), String> {
        let spec = self.tasks.get(name).ok_or_else(|| format!("unknown task: {}", name))?.clone();
        let st = self.state.get_mut(name).unwrap();
        if st.pid.is_some() {
            return Ok(()); // already running
        }
        let pid = spawn_task(&spec, st.log_path.clone());
        match pid {
            Ok(p) => {
                st.pid = Some(p);
                st.last_start = Some(Instant::now());
                st.backoff = spec.min_backoff;
                log(&format!("started task '{}' pid={} ", name, p));
                Ok(())
            }
            Err(e) => Err(format!("failed to start {}: {}", name, e)),
        }
    }

    fn stop(&mut self, name: &str) -> Result<(), String> {
        let st = self.state.get_mut(name).ok_or_else(|| format!("unknown task: {}", name))?;
        if let Some(pid) = st.pid {
            let _ = kill(pid, Signal::TERM);
            // give it a moment, then KILL if still around
            thread::sleep(Duration::from_millis(800));
            let _ = kill(pid, Signal::KILL);
            st.pid = None;
        }
        Ok(())
    }

    // Supervision loop; call from PID 1 main loop
    fn supervise_once(&mut self) {
        // Reap any children and react to exits
        loop {
            match waitpid(None, Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) => {
                    self.handle_exit(pid, Some(status));
                }
                Ok(WaitStatus::Signaled(pid, sig, _)) => {
                    log(&format!("pid {} terminated by signal {:?}", pid, sig));
                    self.handle_exit(pid, None);
                }
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => {},
                Err(nix::Error::ECHILD) => break,
                Err(e) => {
                    log(&format!("waitpid error: {}", e));
                    break;
                }
            }
        }

        // Attempt restarts per policy if not running
        let keys: Vec<String> = self.tasks.keys().cloned().collect();
        for name in keys {
            let spec = self.tasks.get(&name).unwrap().clone();
            let st = self.state.get_mut(&name).unwrap();
            if st.pid.is_none() {
                match spec.restart {
                    RestartPolicy::Never => {},
                    RestartPolicy::OnFailure | RestartPolicy::Always => {
                        // backoff to avoid rapid crash loops
                        thread::sleep(st.backoff);
                        match spawn_task(&spec, st.log_path.clone()) {
                            Ok(p) => {
                                log(&format!("restarted '{}' pid={}", name, p));
                                st.pid = Some(p);
                                st.last_start = Some(Instant::now());
                                st.backoff = spec.min_backoff; // reset
                            }
                            Err(e) => {
                                log(&format!("restart '{}' failed: {}", name, e));
                                // exponential backoff up to max
                                let mut next = st.backoff * 2;
                                if next > spec.max_backoff { next = spec.max_backoff; }
                                st.backoff = next;
                            }
                        }
                    }
                }
            }
        }
    }

    fn handle_exit(&mut self, pid: Pid, status: Option<i32>) {
        for (name, st) in self.state.iter_mut() {
            if st.pid == Some(pid) {
                log(&format!("task '{}' pid {} exited status {:?}", name, pid, status));
                st.pid = None;
            }
        }
    }
}

fn spawn_task(spec: &TaskSpec, log_path: Option<String>) -> Result<Pid, String> {
    // Open log file if available; fallback to console
    let (stdout_fd, stderr_fd) = if let Some(path) = log_path {
        // Ensure directory exists
        if let Some(dir) = Path::new(&path).parent() { let _ = create_dir_all(dir); }
        let file = OpenOptions::new().create(true).append(true).open(&path)
            .map_err(|e| format!("open log {}: {}", path, e))?;
        let fd = file.into_raw_fd();
        // dup fd for stderr too
        let fd2 = unsafe { libc::dup(fd) };
        (fd, fd2)
    } else {
        (libc::STDOUT_FILENO, libc::STDERR_FILENO)
    };

    unsafe {
        match fork().map_err(|e| e.to_string())? {
            ForkResult::Child => {
                // redirect stdout/stderr
                libc::dup2(stdout_fd, libc::STDOUT_FILENO);
                libc::dup2(stderr_fd, libc::STDERR_FILENO);
                // exec the command
                let prog = CString::new(spec.cmd[0].as_str()).unwrap();
                let mut args_c: Vec<CString> = spec.cmd.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
                // execv requires argv[0] to be program name
                if args_c.is_empty() { args_c.push(prog.clone()); }
                let argv: Vec<&CString> = args_c.iter().collect();
                let _ = execv(&prog, &argv);
                // If exec fails
                let _ = eprintln!("exec failed: {}", spec.cmd[0]);
                libc::_exit(127);
            }
            ForkResult::Parent { child } => Ok(child),
        }
    }
}

// Utility: run a command, capture status only
fn run_cmd(cmd: &[&str]) -> i32 {
    if cmd.is_empty() { return 1; }
    log(&format!("run: {}", cmd.join(" ")));
    match Command::new(cmd[0]).args(&cmd[1..]).stdin(Stdio::null()).stdout(Stdio::inherit()).stderr(Stdio::inherit()).status() {
        Ok(status) => status.code().unwrap_or(1),
        Err(e) => { log(&format!("failed to exec {}: {}", cmd[0], e)); 1 }
    }
}

fn ensure_dev_nodes() {
    // Create minimal device nodes if missing, since we're not using udev/dbus.
    let _ = create_dir_all("/dev");
    let _ = create_dir_all("/dev/pts");
    let _ = create_dir_all("/dev/shm");
    let nodes = vec![
        ("/dev/console", SFlag::S_CHR, 5, 1, 0o600),
        ("/dev/null",    SFlag::S_CHR, 1, 3, 0o666),
        ("/dev/tty",     SFlag::S_CHR, 5, 0, 0o666),
        ("/dev/ptmx",    SFlag::S_CHR, 5, 2, 0o666),
        ("/dev/random",  SFlag::S_CHR, 1, 8, 0o444),
        ("/dev/urandom", SFlag::S_CHR, 1, 9, 0o444),
    ];
    for (path, kind, maj, min, mode) in nodes {
        if !Path::new(path).exists() {
            let dev = nix::sys::stat::makedev(maj, min);
            let _ = mknod(Path::new(path), kind, Mode::from_bits_truncate(mode), dev);
        }
    }
}

fn mount_early_fs() {
    // Mount proc, sysfs, devtmpfs (or tmpfs on /dev if devtmpfs is not available), and devpts.
    let _ = create_dir_all("/proc");
    let _ = create_dir_all("/sys");
    let _ = create_dir_all("/dev");

    unsafe {
        let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>);
        let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>);
    }

    // Try devtmpfs first
    let dev_res = unsafe { mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,size=8m")) };
    if dev_res.is_err() {
        // Fallback to tmpfs and manually create nodes
        let _ = unsafe { mount(Some("tmpfs"), "/dev", Some("tmpfs"), MsFlags::empty(), Some("mode=0755,size=8m")) };
        ensure_dev_nodes();
    }

    // devpts for PTYs
    let _ = unsafe { mount(Some("devpts"), "/dev/pts", Some("devpts"), MsFlags::empty(), Some("mode=0620,ptmxmode=0666,newinstance")) };
}

fn run_fsck_and_mount_all() {
    // Run fsck -A -T -t noopts=tmpfs,devpts,proc,sysfs
    let _ = run_cmd(&["/sbin/fsck", "-A", "-T", "-t", "noopts=tmpfs,devpts,proc,sysfs", "-a"]);

    // Mount all filesystems from /etc/fstab (except those handled above)
    let _ = run_cmd(&["/bin/mount", "-a"]); // relies on fstab
}

fn bring_up_networking(iface_opt: Option<String>) {
    // Very simple: ip link set IFACE up; optional DHCP via busybox udhcpc if available
    // We avoid any dbus/systemd components.
    let iface = iface_opt.or_else(|| detect_first_iface()).unwrap_or_else(|| "eth0".to_string());
    let _ = run_cmd(&["/sbin/ip", "link", "set", &iface, "up"]);

    // If a static config is desired, user can add a task below. Try DHCP if udhcpc exists.
    if Path::new("/sbin/udhcpc").exists() || Path::new("/usr/sbin/udhcpc").exists() {
        let udhcpc = if Path::new("/sbin/udhcpc").exists() { "/sbin/udhcpc" } else { "/usr/sbin/udhcpc" };
        let _ = run_cmd(&[udhcpc, "-i", &iface, "-q", "-t", "3", "-T", "3"]);
    }
}

fn detect_first_iface() -> Option<String> {
    // Pick first non-loopback from /sys/class/net
    if let Ok(entries) = std::fs::read_dir("/sys/class/net") {
        for e in entries.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            if name != "lo" { return Some(name); }
        }
    }
    None
}

fn spawn_getty_tty1() -> TaskSpec {
    // Use agetty if available, else getty. Devuan systems typically provide agetty.
    let getty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" } else if Path::new("/bin/agetty").exists() { "/bin/agetty" } else { "/sbin/getty" };
    TaskSpec {
        name: "getty-tty1".into(),
        cmd: vec![getty.into(), "--noclear".into(), "38400".into(), "tty1".into()],
        restart: RestartPolicy::Always,
        min_backoff: Duration::from_secs(1),
        max_backoff: Duration::from_secs(60),
    }
}

fn parse_kernel_cmdline() -> HashMap<String, String> {
    let mut map = HashMap::new();
    if let Ok(mut f) = File::open("/proc/cmdline") {
        let mut s = String::new();
        let _ = f.read_to_string(&mut s);
        for tok in s.split_whitespace() {
            if let Some((k, v)) = tok.split_once('=') {
                map.insert(k.into(), v.into());
            } else {
                map.insert(tok.into(), String::new());
            }
        }
    }
    map
}

fn is_pid1() -> bool {
    unsafe { libc::getpid() == 1 }
}

fn setup_console() {
    // Ensure we have a controlling TTY for basic logging if possible
    let _ = OpenOptions::new().write(true).open("/dev/console").and_then(|mut f| f.write_all(b"sysx init starting\n"));
}

fn init_main() -> ! {
    setup_console();
    log("mounting early filesystems (/proc, /sys, /dev)");
    mount_early_fs();

    log("running fsck and mounting all filesystems");
    run_fsck_and_mount_all();

    // Bring up networking
    let kcmd = parse_kernel_cmdline();
    let iface = kcmd.get("sysx.iface").cloned();
    log("bringing up networking");
    bring_up_networking(iface);

    // Prepare logging dir now that filesystems are mounted
    let _ = create_dir_all("/var/log/sysx");

    // Define tasks to supervise
    let mut sup = Supervisor::new();

    // Example: syslog (optional): if you have busybox syslogd; comment out if undesired
    if Path::new("/sbin/syslogd").exists() || Path::new("/usr/sbin/syslogd").exists() {
        let bin = if Path::new("/sbin/syslogd").exists() { "/sbin/syslogd" } else { "/usr/sbin/syslogd" };
        sup.add_task(TaskSpec { name: "syslogd".into(), cmd: vec![bin.into(), "-n".into()], restart: RestartPolicy::Always, min_backoff: Duration::from_secs(1), max_backoff: Duration::from_secs(30) });
    }

    // Add getty on tty1
    sup.add_task(spawn_getty_tty1());

    // Start all tasks
    for name in sup.tasks.keys().cloned().collect::<Vec<_>>() { let _ = sup.start(&name); }

    log("sysx init entering supervision loop (PID 1)");

    // Main loop for PID 1: supervise tasks, reap zombies, and provide a minimal control socket/CLI via signals and a control file.
    // For simplicity, we implement a FIFO at /run/sysx.ctl that the CLI writes commands to.
    let ctl_path = "/run/sysx.ctl";
    let _ = create_dir_all("/run");
    if !Path::new(ctl_path).exists() {
        let _ = nix::unistd::mkfifo(Path::new(ctl_path), Mode::from_bits_truncate(0o600));
    }

    loop {
        // Non-blocking supervise
        sup.supervise_once();

        // Process one CLI command if available
        if let Ok(mut f) = OpenOptions::new().read(true).open(ctl_path) {
            let mut buf = String::new();
            if f.read_to_string(&mut buf).is_ok() {
                for line in buf.lines() {
                    handle_cli_line(line.trim(), &mut sup);
                }
            }
        }

        // Small sleep to avoid busy loop
        thread::sleep(Duration::from_millis(200));
    }
}

fn handle_cli_line(line: &str, sup: &mut Supervisor) {
    if line.is_empty() { return; }
    let mut it = line.split_whitespace();
    match it.next() {
        Some("list") => {
            for (name, pid) in sup.list() {
                log(&format!("task {} pid={}", name, pid.map(|p| p.to_string()).unwrap_or_else(|| "-".into())));
            }
        }
        Some("start") => {
            if let Some(t) = it.next() { let _ = sup.start(t); } else { log("usage: start <task>"); }
        }
        Some("stop") => {
            if let Some(t) = it.next() { let _ = sup.stop(t); } else { log("usage: stop <task>"); }
        }
        _ => log(&format!("unknown cmd: {}", line)),
    }
}

fn cli_main(args: &[String]) {
    // Simple CLI that talks to PID 1 via FIFO at /run/sysx.ctl
    // Commands: list | start <task> | stop <task>
    let ctl_path = "/run/sysx.ctl";
    if !Path::new(ctl_path).exists() {
        eprintln!("sysx: control FIFO not found (is sysx running as PID 1?)");
        std::process::exit(1);
    }
    let cmdline = args.join(" ");
    if cmdline.is_empty() { eprintln!("usage: sysx <list|start <task>|stop <task>>"); std::process::exit(2); }
    if let Ok(mut f) = OpenOptions::new().write(true).open(ctl_path) {
        let _ = writeln!(f, "{}", cmdline);
    } else {
        eprintln!("sysx: failed to open control FIFO");
        std::process::exit(1);
    }
}

fn main() {
    // If PID 1, behave as init. Otherwise behave as CLI.
    if is_pid1() {
        init_main();
    } else {
        let mut args: Vec<String> = env::args().skip(1).collect();
        if args.is_empty() { eprintln!("usage: sysx <list|start <task>|stop <task>>"); std::process::exit(2); }
        cli_main(&args);
    }
}

