// Simple restart policy
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize)]
enum TaskRunState {
    Starting,
    Running(i32),
    Stopped,
    Crashed(Option<i32>), // exit code or None if signaled
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    child: Option<Child>,
    last_start: Option<Instant>,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self { spec, state: TaskRunState::Stopped, child: None, last_start: None }
    }
}

static TASKS: Lazy<Arc<Mutex<HashMap<String, TaskRuntime>>>> = Lazy::new(|| Arc::new(Mutex::new(HashMap::new())));

// Utility: open a log file for a task
fn open_log(path: &Path) -> std::io::Result<File> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let f = OpenOptions::new().create(true).append(true).open(path)?;
    let mut perms = f.metadata()?.permissions();
    perms.set_mode(0o640);
    fs::set_permissions(path, perms)?;
    Ok(f)
}

fn run_cmd_log(name: &str, log_path: &Path, mut cmd: Command) -> std::io::Result<Child> {
    let mut log = open_log(log_path)?;
    writeln!(log, "==== [{}] starting at {:?} ====", name, std::time::SystemTime::now()).ok();
    let log_file = OpenOptions::new().create(true).append(true).open(log_path)?;
    let child = cmd.stdout(Stdio::from(log_file.try_clone()?))
        .stderr(Stdio::from(log_file))
        .spawn()?;
    Ok(child)
}

fn start_task(name: &str) -> std::io::Result<()> {
    let mut tasks = TASKS.lock().unwrap();
    let rt = tasks.get_mut(name).ok_or_else(|| std::io::Error::new(std::io::ErrorKind::NotFound, "task not found"))?;
    if matches!(rt.state, TaskRunState::Running(_)|TaskRunState::Starting) {
        return Ok(());
    }
    let mut cmd = Command::new(&rt.spec.cmd[0]);
    if rt.spec.cmd.len() > 1 { cmd.args(&rt.spec.cmd[1..]); }
    cmd.env_clear().env("PATH", "/usr/sbin:/usr/bin:/sbin:/bin");
    cmd.stdin(Stdio::null());
    rt.state = TaskRunState::Starting;
    match run_cmd_log(&rt.spec.name, &rt.spec.log_path, cmd) {
        Ok(child) => {
            let pid = child.id() as i32;
            rt.child = Some(child);
            rt.state = TaskRunState::Running(pid);
            rt.last_start = Some(Instant::now());
        }
        Err(e) => {
            rt.state = TaskRunState::Crashed(None);
            return Err(e);
        }
    }
    Ok(())
}

fn stop_task(name: &str) -> std::io::Result<()> {
    let mut tasks = TASKS.lock().unwrap();
    let rt = tasks.get_mut(name).ok_or_else(|| std::io::Error::new(std::io::ErrorKind::NotFound, "task not found"))?;
    if let Some(child) = rt.child.as_mut() {
        let pid = Pid::from_raw(child.id() as i32);
        let _ = kill(pid, Signal::SIGTERM);
    }
    Ok(())
}

fn reaper_loop() {
    loop {
        match waitpid(None, Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, code)) => handle_exit(pid, Some(code)),
            Ok(WaitStatus::Signaled(pid, _sig, _)) => handle_exit(pid, None),
            Ok(WaitStatus::StillAlive) => thread::sleep(Duration::from_millis(100)),
            Ok(_) => {}
            Err(_) => thread::sleep(Duration::from_millis(100)),
        }
    }
}

fn handle_exit(pid: Pid, code: Option<i32>) {
    let mut to_restart: Option<(String, RestartPolicy)> = None;
    let mut tasks = TASKS.lock().unwrap();
    for (name, rt) in tasks.iter_mut() {
        if let Some(child) = rt.child.as_ref() {
            if child.id() as i32 == pid.as_raw() {
                rt.child = None;
                rt.state = if code.is_some() { TaskRunState::Crashed(code) } else { TaskRunState::Crashed(None) };
                to_restart = Some((name.clone(), rt.spec.restart));
                break;
            }
        }
    }
    drop(tasks);
    if let Some((name, policy)) = to_restart {
        match policy {
            RestartPolicy::Never => {}
            RestartPolicy::OnFailure => {
                // We treat any exit here as failure; refine as needed.
                let _ = start_task(&name);
            }
            RestartPolicy::Always => {
                thread::sleep(Duration::from_secs(1));
                let _ = start_task(&name);
            }
        }
    }
}

fn ensure_dir_mode(p: &Path, mode: u32) {
    if let Err(_)= fs::create_dir_all(p) {}
    if let Ok(md) = fs::metadata(p) {
        let mut perms = md.permissions();
        perms.set_mode(mode);
        let _ = fs::set_permissions(p, perms);
    }
}

fn mount_fs() {
    // Mount devtmpfs, proc, sysfs
    let _ = mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), None::<&str>);
    ensure_dir_mode(Path::new("/dev/pts"), 0o755);
    let _ = mount(Some("devpts"), "/dev/pts", Some("devpts"), MsFlags::empty(), Some("newinstance,ptmxmode=0666,mode=0620,gid=5"));
    let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>);
    let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>);
}

fn run_fsck_and_mount() {
    // Remount root read-only first (in case it isn't)
    let _ = mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT | MsFlags::MS_RDONLY, None);

    // fsck -A -T -y (ignore errors, continue boot)
    let _ = Command::new("/sbin/fsck").args(["-A", "-T", "-y"]).status();

    // Remount root read-write and mount all
    let _ = mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT, None);
    let _ = Command::new("/bin/mount").args(["-a"]).status();
}

fn bring_up_networking() {
    // Ensure loopback is up
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    let _ = Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();
    let _ = Command::new("/sbin/ip").args(["route", "add", "127.0.0.0/8", "dev", "lo"]).status();

    // If ifupdown is installed on Devuan, bring up all interfaces per /etc/network/interfaces
    if Path::new("/sbin/ifup").exists() {
        let _ = Command::new("/sbin/ifup").arg("-a").status();
    }
}

fn spawn_getty() {
    let spec = TaskSpec {
        name: "getty-tty1".to_string(),
        cmd: vec!["/sbin/agetty".to_string(), "--login-program".to_string(), "/bin/login".to_string(), "--noclear".to_string(), "tty1".to_string(), "115200".to_string()],
        restart: RestartPolicy::Always,
        autostart: true,
        log_path: PathBuf::from("/var/log/sysx/getty-tty1.log"),
    };
    TASKS.lock().unwrap().insert(spec.name.clone(), TaskRuntime::new(spec));
}

fn setup_default_tasks() {
    // Example supervised service: syslogd (if present) — optional; not required if unavailable
    if Path::new("/sbin/busybox").exists() {
        let spec = TaskSpec {
            name: "klogd".to_string(),
            cmd: vec!["/sbin/busybox".to_string(), "klogd".to_string(), "-n".to_string()],
            restart: RestartPolicy::Always,
            autostart: true,
            log_path: PathBuf::from("/var/log/sysx/klogd.log"),
        };
        TASKS.lock().unwrap().insert(spec.name.clone(), TaskRuntime::new(spec));
    }
}

// Simple control protocol over a Unix socket: JSON lines
// Requests: {"cmd":"list"} | {"cmd":"start","task":"name"} | {"cmd":"stop","task":"name"}
// Responses: JSON objects per request
#[derive(Deserialize)]
struct CtrlReq { cmd: String, task: Option<String> }

#[derive(Serialize)]
struct TaskInfo { name: String, state: TaskRunState }

#[derive(Serialize)]
struct CtrlResp { ok: bool, message: String, tasks: Option<Vec<TaskInfo>> }

fn handle_client(mut stream: UnixStream) {
    let mut buf = String::new();
    if let Ok(_) = BufReader::new(stream.try_clone().unwrap()).read_line(&mut buf) {
        let resp = if let Ok(req) = serde_json::from_str::<CtrlReq>(&buf) {
            match req.cmd.as_str() {
                "list" => {
                    let tasks = TASKS.lock().unwrap().iter().map(|(n, rt)| TaskInfo { name: n.clone(), state: rt.state.clone() }).collect();
                    CtrlResp { ok: true, message: "ok".into(), tasks: Some(tasks) }
                }
                "start" => {
                    if let Some(t) = req.task {
                        match start_task(&t) {
                            Ok(()) => CtrlResp { ok: true, message: format!("started {}", t), tasks: None },
                            Err(e) => CtrlResp { ok: false, message: format!("start failed: {}", e), tasks: None },
                        }
                    } else {
                        CtrlResp { ok: false, message: "missing task".into(), tasks: None }
                    }
                }
                "stop" => {
                    if let Some(t) = req.task {
                        match stop_task(&t) {
                            Ok(()) => CtrlResp { ok: true, message: format!("stopped {} (SIGTERM)", t), tasks: None },
                            Err(e) => CtrlResp { ok: false, message: format!("stop failed: {}", e), tasks: None },
                        }
                    } else {
                        CtrlResp { ok: false, message: "missing task".into(), tasks: None }
                    }
                }
                _ => CtrlResp { ok: false, message: "unknown cmd".into(), tasks: None },
            }
        } else {
            CtrlResp { ok: false, message: "bad json".into(), tasks: None }
        };
        let _ = serde_json::to_writer(&mut stream, &resp);
        let _ = stream.write_all(b"\n");
    }
}

fn run_ctrl_socket() {
    let sock_dir = Path::new("/run/sysx");
    ensure_dir_mode(sock_dir, 0o755);
    let sock_path = sock_dir.join("sysx.sock");
    let _ = fs::remove_file(&sock_path);
    let listener = UnixListener::bind(&sock_path).expect("bind ctrl socket");
    // Restrict permissions
    let mut perms = fs::metadata(&sock_path).unwrap().permissions();
    perms.set_mode(0o660);
    fs::set_permissions(&sock_path, perms).ok();

    for stream in listener.incoming() {
        if let Ok(stream) = stream {
            handle_client(stream);
        }
    }
}

fn run_cli(args: &[String]) -> i32 {
    // CLI client: connects to /run/sysx/sysx.sock and sends one JSON line
    if args.len() < 2 {
        eprintln!("Usage: sysx <list|start|stop> [task]");
        return 2;
    }
    let cmd = args[1].as_str();
    let req = match cmd {
        "list" => serde_json::json!({"cmd":"list"}),
        "start" => {
            let t = args.get(2).cloned().unwrap_or_default();
            if t.is_empty() { eprintln!("missing task name"); return 2; }
            serde_json::json!({"cmd":"start","task":t})
        }
        "stop" => {
            let t = args.get(2).cloned().unwrap_or_default();
            if t.is_empty() { eprintln!("missing task name"); return 2; }
            serde_json::json!({"cmd":"stop","task":t})
        }
        _ => { eprintln!("unknown command"); return 2; }
    };
    let sock_path = "/run/sysx/sysx.sock";
    match UnixStream::connect(sock_path) {
        Ok(mut s) => {
            let line = serde_json::to_string(&req).unwrap() + "\n";
            let _ = s.write_all(line.as_bytes());
            let mut resp = String::new();
            let _ = BufReader::new(s).read_line(&mut resp);
            println!("{}", resp.trim());
            0
        }
        Err(e) => {
            eprintln!("cannot connect to sysx: {}", e);
            1
        }
    }
}

fn is_pid1() -> bool { nix::unistd::getpid().as_raw() == 1 }

fn main() {
    let args: Vec<String> = env::args().collect();

    // If not PID 1, behave as CLI client
    if !is_pid1() && args.len() > 1 {
        std::process::exit(run_cli(&args));
    }

    // PID 1 flow: init responsibilities
    eprintln!("sysx: starting as init (PID 1)");

    // Basic mounts and filesystems
    mount_fs();
    run_fsck_and_mount();

    // Bring up minimal networking
    bring_up_networking();

    // Prepare tasks (getty and optional ones)
    spawn_getty();
    setup_default_tasks();

    // Autostart tasks
    {
        let names: Vec<String> = TASKS.lock().unwrap().iter().filter_map(|(n, rt)| if rt.spec.autostart { Some(n.clone()) } else { None }).collect();
        for n in names { let _ = start_task(&n); }
    }

    // Start control socket in background thread
    thread::spawn(move || run_ctrl_socket());

    // Reaper loop in main thread to adopt zombies
    reaper_loop();
}

// Safety & concurrency notes:
// - All shared task state is guarded by a Mutex; interactions are short to avoid contention.
// - Child IO is redirected to per-task log files; the reaper_loop avoids blocking by using WNOHANG.
// - PID 1 must not exit; reaper_loop runs forever.
// - No systemd/sysvinit/dbus/x11/xorg/elogind/xinit/systemctl are used; only direct syscalls and classic userland tools available on Devuan.

Below is a complete, compilable Rust project for a minimal "sysx" init and CLI for Devuan that:

- Mounts /proc, /sys, and /dev (devtmpfs)
- Runs fsck, remounts root rw, mounts filesystems from /etc/fstab
- Brings up basic networking (loopback and, if available, ifup -a)
- Supervises tasks with restart policies and per-task logging
- Spawns a login getty on tty1
- Exposes a simple Unix-socket CLI: sysx list | start <task> | stop <task>
- Avoids systemd, sysvinit, dbus, X/x11/xorg, elogind, xinit, systemctl

