// ---------------------- Task model and supervision ----------------------
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum TaskRunState {
    Starting,
    Running(i32), // pid
    Stopped,
    Crashed(Option<i32>), // exit code or None if by signal
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    last_start: Option<Instant>,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        TaskRuntime {
            spec,
            state: TaskRunState::Stopped,
            last_start: None,
        }
    }
}

// Global task table guarded by a Mutex for simplicity.
struct State {
    tasks: HashMap<String, TaskRuntime>,
}

impl State {
    fn new() -> Self {
        State { tasks: HashMap::new() }
    }
}

// ---------------------- Utility helpers ----------------------
fn log_to_console(msg: &str) {
    eprintln!("[sysx] {msg}");
}

fn run_and_log(cmd: &mut Command, log: Option<&mut File>) -> std::io::Result<i32> {
    let output = cmd.output()?;
    if let Some(l) = log {
        let _ = l.write_all(&output.stdout);
        let _ = l.write_all(&output.stderr);
        let _ = l.flush();
    }
    Ok(output.status.code().unwrap_or(0))
}

fn open_append_log(path: &Path) -> std::io::Result<File> {
    if let Some(parent) = path.parent() { create_dir_all(parent)?; }
    OpenOptions::new().create(true).append(true).open(path)
}

fn safe_mount<F: AsRef<Path>>(src: Option<&str>, target: F, fstype: Option<&str>, flags: MsFlags, data: Option<&str>) {
    let t = target.as_ref();
    if let Err(e) = create_dir_all(t) { log_to_console(&format!("mkdir {:?}: {e}", t)); }
    let src_c = src.map(|s| CString::new(s).unwrap());
    let fstype_c = fstype.map(|s| CString::new(s).unwrap());
    let data_c = data.map(|s| CString::new(s).unwrap());
    let res = unsafe {
        mount(
            src_c.as_ref().map(|c| c.as_c_str()),
            &CString::new(t.as_os_str().as_bytes()).unwrap(),
            fstype_c.as_ref().map(|c| c.as_c_str()),
            flags,
            data_c.as_ref().map(|c| c.as_c_str()),
        )
    };
    if let Err(e) = res { log_to_console(&format!("mount {:?} on {:?}: {e}", fstype, t)); }
}

fn remount_root_rw() {
    let target = CString::new("/").unwrap();
    if let Err(e) = unsafe { mount::<CString, CString, CString, CString>(
        None, &target, None, MsFlags::MS_REMOUNT, None,
    ) } {
        log_to_console(&format!("remount / rw failed: {e}"));
    }
}

fn run_fsck_all() {
    // Prefer fsck -A -T -a (non-interactive). On errors, allow boot to continue.
    let mut cmd = Command::new("/sbin/fsck");
    cmd.arg("-A").arg("-T").arg("-a");
    match cmd.status() {
        Ok(st) => log_to_console(&format!("fsck exited with: {st}")),
        Err(e) => log_to_console(&format!("fsck not run: {e}")),
    }
}

fn mount_base_fs() {
    // Mount proc, sysfs, devtmpfs
    safe_mount(None, "/proc", Some("proc"), MsFlags::empty(), None);
    safe_mount(None, "/sys", Some("sysfs"), MsFlags::empty(), None);
    safe_mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,uid=0,gid=0"));
    // Basic device nodes if missing (useful in some container/early boot cases)
    let _ = fs::create_dir_all("/dev/pts");
    safe_mount(None, "/dev/pts", Some("devpts"), MsFlags::empty(), Some("newinstance,ptmxmode=0666,mode=0620,gid=5"));
    safe_mount(None, "/dev/shm", Some("tmpfs"), MsFlags::empty(), Some("mode=1777,size=64m"));
}

fn mount_fstab() {
    // Mount fstab entries: mount -a
    match Command::new("/bin/mount").arg("-a").status() {
        Ok(st) => log_to_console(&format!("mount -a exited with: {st}")),
        Err(e) => log_to_console(&format!("mount -a failed to execute: {e}")),
    }
}

fn bring_up_networking() {
    // lo up
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    let _ = Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();
    // If ifupdown is present on Devuan: ifup -a
    if Path::new("/sbin/ifup").exists() {
        let _ = Command::new("/sbin/ifup").arg("-a").status();
    }
}

// ---------------------- Supervision ----------------------
fn spawn_task(spec: &TaskSpec) -> Option<Pid> {
    // Open task log
    let mut logf = match open_append_log(&spec.log_path) { Ok(f) => f, Err(e) => { log_to_console(&format!("log open failed for {}: {e}", spec.name)); return None; } };

    if spec.cmd.is_empty() { return None; }
    let mut cmd = Command::new(&spec.cmd[0]);
    if spec.cmd.len() > 1 { cmd.args(&spec.cmd[1..]); }
    cmd.stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .env("PATH", "/usr/sbin:/usr/bin:/sbin:/bin");

    match cmd.spawn() {
        Ok(mut child) => {
            let pid = Pid::from_raw(child.id() as i32);
            log_to_console(&format!("started task {} pid {}", spec.name, pid));
            // Tee child's stdout/stderr to log file
            let mut out = child.stdout.take();
            let mut err = child.stderr.take();
            let log_path = spec.log_path.clone();
            if let Some(mut o) = out.take() {
                thread::spawn(move || {
                    if let Ok(mut lf) = open_append_log(&log_path) {
                        let mut buf = [0u8; 4096];
                        loop {
                            match o.read(&mut buf) { Ok(0) | Err(_) => break, Ok(n) => { let _ = lf.write_all(&buf[..n]); } }
                        }
                    }
                });
            }
            if let Some(mut e) = err.take() {
                thread::spawn(move || {
                    if let Ok(mut lf) = open_append_log(&log_path) {
                        let mut buf = [0u8; 4096];
                        loop {
                            match e.read(&mut buf) { Ok(0) | Err(_) => break, Ok(n) => { let _ = lf.write_all(&buf[..n]); } }
                        }
                    }
                });
            }
            Some(pid)
        }
        Err(e) => {
            let _ = writeln!(logf, "spawn failed: {e}");
            None
        }
    }
}

fn supervise_loop(state: Arc<Mutex<State>>) {
    // Reap children; restart per policy.
    loop {
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, code)) | Ok(WaitStatus::Signaled(pid, _, _)) => {
                let mut st = state.lock().unwrap();
                let mut to_restart: Option<String> = None;
                for (name, tr) in st.tasks.iter_mut() {
                    if let TaskRunState::Running(p) = tr.state {
                        if p == pid.as_raw() {
                            // Update state
                            tr.state = if let Ok(WaitStatus::Exited(_, c)) = Ok(WaitStatus::Exited(pid, code)) {
                                if c == 0 { TaskRunState::Stopped } else { TaskRunState::Crashed(Some(c)) }
                            } else {
                                TaskRunState::Crashed(None)
                            };
                            // Decide restart
                            let restart = match tr.spec.restart {
                                RestartPolicy::Always => true,
                                RestartPolicy::OnFailure => !matches!(tr.state, TaskRunState::Stopped),
                                RestartPolicy::Never => false,
                            };
                            if restart { to_restart = Some(name.clone()); }
                            break;
                        }
                    }
                }
                drop(st);
                if let Some(name) = to_restart {
                    thread::sleep(Duration::from_secs(1));
                    let mut st2 = state.lock().unwrap();
                    if let Some(tr) = st2.tasks.get_mut(&name) {
                        if let Some(pid) = spawn_task(&tr.spec) {
                            tr.state = TaskRunState::Running(pid.as_raw());
                            tr.last_start = Some(Instant::now());
                        } else {
                            tr.state = TaskRunState::Crashed(None);
                        }
                    }
                }
            }
            Ok(WaitStatus::StillAlive) => {
                thread::sleep(Duration::from_millis(200));
            }
            Ok(_) => { /* ignore other statuses */ }
            Err(_) => {
                thread::sleep(Duration::from_millis(500));
            }
        }
    }
}

// ---------------------- Control socket CLI ----------------------
// Simple line protocol over Unix socket: one JSON per request/response.
// Request: {"cmd":"list"} | {"cmd":"start","task":"name"} | {"cmd":"stop","task":"name"}
// Response: JSON objects with "ok":true/false and payload.

#[derive(Serialize, Deserialize, Debug)]
struct CliReq { cmd: String, task: Option<String> }

#[derive(Serialize, Deserialize, Debug)]
struct CliResp { ok: bool, msg: String, tasks: Option<Vec<(String, TaskRunState)>> }

const SOCK_PATH: &str = "/run/sysx/sysx.sock";

fn remove_stale_socket() {
    if Path::new(SOCK_PATH).exists() { let _ = fs::remove_file(SOCK_PATH); }
}

fn serve_control_socket(state: Arc<Mutex<State>>) {
    let _ = fs::create_dir_all("/run/sysx");
    remove_stale_socket();
    let listener = UnixListener::bind(SOCK_PATH).expect("bind control socket");
    let _ = fs::set_permissions(SOCK_PATH, fs::Permissions::from_mode(0o660));
    log_to_console(&format!("control socket at {}", SOCK_PATH));

    for conn in listener.incoming() {
        match conn {
            Ok(mut stream) => {
                let st = state.clone();
                thread::spawn(move || handle_client(st, &mut stream));
            }
            Err(e) => log_to_console(&format!("socket accept error: {e}")),
        }
    }
}

fn handle_client(state: Arc<Mutex<State>>, stream: &mut UnixStream) {
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut line = String::new();
    if reader.read_line(&mut line).is_err() { return; }
    let req: Result<CliReq, _> = serde_json::from_str(line.trim());
    let mut resp = match req {
        Ok(r) => match r.cmd.as_str() {
            "list" => {
                let st = state.lock().unwrap();
                let mut v = Vec::new();
                for (k, tr) in &st.tasks { v.push((k.clone(), tr.state.clone())); }
                CliResp { ok: true, msg: "ok".into(), tasks: Some(v) }
            }
            "start" => {
                if let Some(name) = r.task {
                    let mut st = state.lock().unwrap();
                    if let Some(tr) = st.tasks.get_mut(&name) {
                        if let TaskRunState::Running(_) = tr.state {
                            CliResp { ok: true, msg: format!("{} already running", name), tasks: None }
                        } else {
                            if let Some(pid) = spawn_task(&tr.spec) {
                                tr.state = TaskRunState::Running(pid.as_raw());
                                tr.last_start = Some(Instant::now());
                                CliResp { ok: true, msg: format!("{} started", name), tasks: None }
                            } else {
                                CliResp { ok: false, msg: format!("{} failed to start", name), tasks: None }
                            }
                        }
                    } else { CliResp { ok: false, msg: "unknown task".into(), tasks: None } }
                } else { CliResp { ok: false, msg: "missing task".into(), tasks: None } }
            }
            "stop" => {
                if let Some(name) = r.task {
                    let mut st = state.lock().unwrap();
                    if let Some(tr) = st.tasks.get_mut(&name) {
                        if let TaskRunState::Running(pid) = tr.state.clone() {
                            let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
                            tr.state = TaskRunState::Stopped;
                            CliResp { ok: true, msg: format!("{} stopped", name), tasks: None }
                        } else {
                            CliResp { ok: true, msg: format!("{} not running", name), tasks: None }
                        }
                    } else { CliResp { ok: false, msg: "unknown task".into(), tasks: None } }
                } else { CliResp { ok: false, msg: "missing task".into(), tasks: None } }
            }
            _ => CliResp { ok: false, msg: "unknown command".into(), tasks: None },
        },
        Err(e) => CliResp { ok: false, msg: format!("bad request: {e}"), tasks: None },
    };

    let _ = writeln!(stream, "{}", serde_json::to_string(&resp).unwrap());
}

// Simple CLI when invoked not as PID 1: connect to socket and send request.
fn run_cli(args: &[String]) -> i32 {
    let req = if args.len() == 1 && args[0] == "list" {
        CliReq { cmd: "list".into(), task: None }
    } else if args.len() == 2 && args[0] == "start" {
        CliReq { cmd: "start".into(), task: Some(args[1].clone()) }
    } else if args.len() == 2 && args[0] == "stop" {
        CliReq { cmd: "stop".into(), task: Some(args[1].clone()) }
    } else {
        eprintln!("Usage: sysx [list|start <task>|stop <task>]");
        return 2;
    };

    match UnixStream::connect(SOCK_PATH) {
        Ok(mut s) => {
            let _ = writeln!(s, "{}", serde_json::to_string(&req).unwrap());
            let mut resp = String::new();
            let mut r = BufReader::new(s);
            if r.read_line(&mut resp).is_ok() {
                println!("{}", resp.trim());
                0
            } else { eprintln!("no response from sysx"); 1 }
        }
        Err(e) => { eprintln!("cannot connect to {}: {}", SOCK_PATH, e); 1 }
    }
}

// ---------------------- Getty (login) ----------------------
fn spawn_getty_tty1_task() -> TaskSpec {
    // Prefer /sbin/agetty common on Devuan. Fallback to /bin/login directly if needed.
    let (cmd, args) = if Path::new("/sbin/agetty").exists() {
        ("/sbin/agetty", vec!["--noclear", "--login-pause", "38400", "tty1", "linux"])
    } else {
        ("/bin/login", vec!["-f", "root"]) // extremely minimal fallback
    };
    TaskSpec {
        name: "getty-tty1".into(),
        cmd: std::iter::once(cmd.to_string()).chain(args.into_iter().map(|s| s.to_string())).collect(),
        restart: RestartPolicy::Always,
        autostart: true,
        log_path: PathBuf::from("/var/log/sysx/getty-tty1.log"),
    }
}

// ---------------------- PID 1 main ----------------------
fn pid1_main() -> i32 {
    log_to_console("sysx init starting as PID 1");

    // Create essential dirs
    let _ = create_dir_all("/run");
    let _ = create_dir_all("/run/sysx");
    let _ = create_dir_all("/var/log/sysx");

    // Mount base virtual filesystems early
    mount_base_fs();

    // Ensure we are session leader (avoid controlling tty surprises)
    let _ = unsafe { setsid() };

    // Run filesystem checks, then remount root rw and mount fstab
    run_fsck_all();
    remount_root_rw();
    mount_fstab();

    // Minimal networking
    bring_up_networking();

    // Initialize tasks
    let mut state = State::new();

    // Example of a supervised service task (customize via editing source or future config)
    // Here we demonstrate supervising a simple syslog daemon if present without using systemd.
    if Path::new("/sbin/rsyslogd").exists() {
        let spec = TaskSpec {
            name: "rsyslogd".into(),
            cmd: vec!["/sbin/rsyslogd".into(), "-n".into()], // -n foreground
            restart: RestartPolicy::OnFailure,
            autostart: true,
            log_path: PathBuf::from("/var/log/sysx/rsyslogd.log"),
        };
        state.tasks.insert(spec.name.clone(), TaskRuntime::new(spec));
    }

    // Getty on tty1
    let getty = spawn_getty_tty1_task();
    state.tasks.insert(getty.name.clone(), TaskRuntime::new(getty));

    let shared = Arc::new(Mutex::new(state));

    // Start autostart tasks
    {
        let mut st = shared.lock().unwrap();
        for (_name, tr) in st.tasks.iter_mut() {
            if tr.spec.autostart {
                if let Some(pid) = spawn_task(&tr.spec) {
                    tr.state = TaskRunState::Running(pid.as_raw());
                    tr.last_start = Some(Instant::now());
                }
            }
        }
    }

    // Start control socket server
    {
        let st = shared.clone();
        thread::spawn(move || serve_control_socket(st));
    }

    // Supervision + reap loop (blocking)
    supervise_loop(shared);
    // never returns
}

fn not_pid1_main(args: Vec<String>) -> i32 {
    // Act as CLI tool to communicate with the running sysx over Unix socket.
    if args.len() <= 1 {
        eprintln!("Usage: sysx [list|start <task>|stop <task>]");
        return 2;
    }
    run_cli(&args[1..])
}

fn main() {
    // If PID == 1 act as init; else act as CLI client.
    if getpid().as_raw() == 1 {
        std::process::exit(pid1_main());
    } else {
        let args: Vec<String> = env::args().collect();
        std::process::exit(not_pid1_main(args));
    }
}

Build and run notes
- Build: cargo build --release
- Install: copy target/release/sysx to /sbin/sysx and chmod 0755
- Kernel cmdline: init=/sbin/sysx
- CLI examples (from a running system with sysx as init):
  - sysx list
  - sysx start getty-tty1
  - sysx stop getty-tty1

Security and safety notes
- Rust ensures memory safety; supervision loop is simple and uses Mutex for concurrency.
- No use of systemd/sysvinit/dbus/x11/xorg/elogind/xinit/systemctl.
- Designed for Devuan’s traditional userspace (ifupdown, agetty, mount, fsck).

Below is a complete, compilable Rust project for a minimal 'sysx' init and CLI. It avoids systemd, sysvinit, dbus, x11/xorg, elogind, xinit, and systemctl. It is intended to run as PID 1 on Devuan. Project layout:

- Cargo.toml
- src/main.rs

