src/main.rs:

use anyhow::{anyhow, Context, Result};
use log::{error, info, warn};
use nix::errno::Errno;
use nix::libc;
use nix::mount::{mount, MntFlags, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::socket::{accept, bind, listen, recv, send, socket, AddressFamily, MsgFlags, SockAddr, SockFlag, SockType, UnixAddr};
use nix::sys::stat::Mode;
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{close, dup2, execv, fork, getpid, mkdir, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use simplelog::{Config as LogConfig, LevelFilter, WriteLogger};
use std::collections::HashMap;
use std::ffi::CString;
use std::fs::{self, OpenOptions};
use std::io::Write as IoWrite;
use std::os::fd::{AsRawFd, RawFd};
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::thread;
use std::time::{Duration, Instant};

// -----------------------------
// Config and task supervision
// -----------------------------

#[derive(Clone, Debug, Serialize, Deserialize)]
struct Task {
    name: String,
    cmd: Vec<String>,
    restart: bool,
    env: Vec<(String, String)>,
    stdout_log: PathBuf,
    stderr_log: PathBuf,
}

#[derive(Debug, Default)]
struct RuntimeTask {
    pid: Option<Pid>,
    last_start: Option<Instant>,
}

struct Supervisor {
    tasks: HashMap<String, Task>,
    runtime: HashMap<String, RuntimeTask>,
}

impl Supervisor {
    fn new() -> Self {
        Supervisor { tasks: HashMap::new(), runtime: HashMap::new() }
    }

    fn add_task(&mut self, t: Task) {
        self.runtime.insert(t.name.clone(), RuntimeTask::default());
        self.tasks.insert(t.name.clone(), t);
    }

    fn start_task(&mut self, name: &str) -> Result<()> {
        let task = self.tasks.get(name).ok_or_else(|| anyhow!("task not found: {}", name))?.clone();
        let rt = self.runtime.get_mut(name).unwrap();
        if rt.pid.is_some() {
            return Ok(()); // already running
        }
        let (stdout_fd, stderr_fd) = open_logs(&task.stdout_log, &task.stderr_log)?;
        match unsafe { fork() }? {
            ForkResult::Parent { child } => {
                rt.pid = Some(child);
                rt.last_start = Some(Instant::now());
                info!("started task '{}' as pid {}", name, child);
                // Close in parent
                let _ = close(stdout_fd);
                let _ = close(stderr_fd);
                Ok(())
            }
            ForkResult::Child => {
                let _ = setsid();
                let _ = dup2(stdout_fd, libc::STDOUT_FILENO);
                let _ = dup2(stderr_fd, libc::STDERR_FILENO);
                // Open /dev/null for stdin
                if let Ok(f) = OpenOptions::new().read(true).open("/dev/null") { let _ = dup2(f.as_raw_fd(), libc::STDIN_FILENO); }
                let _ = close(stdout_fd);
                let _ = close(stderr_fd);
                if task.cmd.is_empty() { std::process::exit(127); }
                let prog = CString::new(task.cmd[0].as_str()).unwrap();
                let argv: Vec<CString> = task.cmd.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
                for (k, v) in task.env.iter() { std::env::set_var(k, v); }
                if let Err(e) = execv(&prog, &argv) { eprintln!("exec failed for {}: {}", task.name, e); }
                std::process::exit(127);
            }
        }
    }

    fn stop_task(&mut self, name: &str) -> Result<()> {
        let rt = self.runtime.get_mut(name).ok_or_else(|| anyhow!("task not found: {}", name))?;
        if let Some(pid) = rt.pid {
            let _ = kill(pid, Signal::SIGTERM);
            for _ in 0..50 {
                match waitpid(pid, Some(WaitPidFlag::WNOHANG)) {
                    Ok(WaitStatus::StillAlive) | Err(_) => thread::sleep(Duration::from_millis(50)),
                    _ => { rt.pid = None; return Ok(()); }
                }
            }
            let _ = kill(pid, Signal::SIGKILL);
            rt.pid = None;
        }
        Ok(())
    }

    fn reaper(&mut self) {
        loop {
            match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) | Ok(WaitStatus::Signaled(pid, _, _)) => {
                    self.on_exit(pid, status);
                }
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => (),
                Err(nix::Error::Sys(Errno::ECHILD)) => break,
                Err(e) => { warn!("waitpid error: {}", e); break; }
            }
        }
    }

    fn on_exit(&mut self, pid: Pid, status: i32) {
        let mut found: Option<String> = None;
        for (name, rt) in self.runtime.iter() {
            if rt.pid == Some(pid) { found = Some(name.clone()); break; }
        }
        if let Some(name) = found {
            info!("task '{}' exited pid {} status {}", name, pid, status);
            if let Some(rt) = self.runtime.get_mut(&name) { rt.pid = None; }
            if let Some(t) = self.tasks.get(&name).cloned() { if t.restart { let _ = self.start_task(&name); } }
        }
    }

    fn list(&self) -> Vec<(String, Option<i32>)> {
        let mut v = Vec::new();
        for (name, rt) in self.runtime.iter() { v.push((name.clone(), rt.pid.map(|p| p.as_raw()))); }
        v
    }
}

fn open_logs(out: &Path, err: &Path) -> Result<(RawFd, RawFd)> {
    if let Some(p) = out.parent() { fs::create_dir_all(p).ok(); }
    if let Some(p) = err.parent() { fs::create_dir_all(p).ok(); }
    let f_out = OpenOptions::new().create(true).append(true).open(out)?;
    let f_err = OpenOptions::new().create(true).append(true).open(err)?;
    Ok((f_out.as_raw_fd(), f_err.as_raw_fd()))
}

// -----------------------------
// Minimal CLI over Unix socket
// -----------------------------

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum CliReq { List, Start { name: String }, Stop { name: String } }

#[derive(Serialize, Deserialize, Debug)]
struct CliResp { ok: bool, msg: String, tasks: Option<Vec<(String, Option<i32>)>> }

const CLI_SOCK: &str = "/run/sysx.sock";

fn run_cli_server(supervisor: *mut Supervisor) -> Result<()> {
    let _ = fs::create_dir_all("/run");
    let _ = fs::remove_file(CLI_SOCK);
    let fd = socket(AddressFamily::Unix, SockType::Stream, SockFlag::empty(), None)?;
    let addr = UnixAddr::new(CLI_SOCK).unwrap();
    bind(fd, &SockAddr::Unix(addr))?;
    listen(fd, 10)?;
    let _ = nix::sys::stat::fchmod(fd, Mode::from_bits_truncate(0o660));
    loop {
        let client = match accept(fd) { Ok(c) => c, Err(e) => { warn!("accept error: {}", e); continue; } };
        let mut buf = [0u8; 4096];
        let n = match recv(client, &mut buf, MsgFlags::empty()) { Ok(n) => n, Err(_) => { let _=close(client); continue; } };
        let req: Result<CliReq, _> = serde_json::from_slice(&buf[..n]);
        let mut resp = CliResp { ok: false, msg: String::new(), tasks: None };
        unsafe {
            if let Some(sv) = supervisor.as_mut() {
                match req {
                    Ok(CliReq::List) => { resp.tasks = Some(sv.list()); resp.ok = true; resp.msg = "ok".into(); }
                    Ok(CliReq::Start { name }) => { match sv.start_task(&name) { Ok(_) => { resp.ok = true; resp.msg = format!("started {}", name); }, Err(e) => { resp.msg = e.to_string(); } } }
                    Ok(CliReq::Stop { name }) => { match sv.stop_task(&name) { Ok(_) => { resp.ok = true; resp.msg = format!("stopped {}", name); }, Err(e) => { resp.msg = e.to_string(); } } }
                    Err(e) => { resp.msg = format!("invalid request: {}", e); }
                }
            }
        }
        let body = serde_json::to_vec(&resp).unwrap_or_else(|_| b"{\"ok\":false,\"msg\":\"encode error\"}".to_vec());
        let _ = send(client, &body, MsgFlags::empty());
        let _ = close(client);
    }
}

// -----------------------------
// System setup (mounts, fsck, fstab, networking, getty)
// -----------------------------

fn ensure_dirs() {
    let _ = fs::create_dir_all("/proc");
    let _ = fs::create_dir_all("/sys");
    let _ = fs::create_dir_all("/dev");
    let _ = fs::create_dir_all("/run");
    let _ = fs::create_dir_all("/var/log/sysx");
}

fn mount_essential() -> Result<()> {
    let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>);
    let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>);
    // devtmpfs is usually mounted by kernel. Attempt if available via alias name "devtmpfs".
    let _ = mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,size=50m"));
    Ok(())
}

fn remount_root_rw() {
    // Fallback to shell command since direct remount flags can be finicky across kernels
    let _ = Command::new("/bin/mount").args(["-o","remount,rw","/"]).status();
}

fn run_fsck_and_fstab() {
    let _ = Command::new("/sbin/fsck").args(["-A", "-T", "-a"]).status();
    let _ = Command::new("/bin/mount").arg("-a").status();
}

fn bring_up_network() {
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    let _ = Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();
    if Path::new("/sbin/ifup").exists() { let _ = Command::new("/sbin/ifup").arg("-a").status(); }
}

fn spawn_getty() {
    if Path::new("/sbin/agetty").exists() {
        if let Ok(ForkResult::Child) = unsafe { fork() } {
            let _ = setsid();
            let _ = execv(&CString::new("/sbin/agetty").unwrap(), &[
                CString::new("agetty").unwrap(),
                CString::new("--noclear").unwrap(),
                CString::new("tty1").unwrap(),
                CString::new("115200").unwrap(),
                CString::new("linux").unwrap(),
            ]);
            std::process::exit(127);
        }
    } else if Path::new("/bin/login").exists() {
        if let Ok(ForkResult::Child) = unsafe { fork() } {
            let _ = setsid();
            let _ = execv(&CString::new("/bin/sh").unwrap(), &[
                CString::new("sh").unwrap(),
                CString::new("-c").unwrap(),
                CString::new("exec /bin/login < /dev/tty1 > /dev/tty1 2>&1").unwrap(),
            ]);
            std::process::exit(127);
        }
    }
}

// -----------------------------
// PID 1 main loop
// -----------------------------

fn setup_logging() -> Result<()> {
    let log_path = "/var/log/sysx/init.log";
    if let Some(p) = Path::new(log_path).parent() { fs::create_dir_all(p)?; }
    let file = OpenOptions::new().create(true).append(true).open(log_path)?;
    WriteLogger::init(LevelFilter::Info, LogConfig::default(), file)?;
    Ok(())
}

fn is_pid1() -> bool { getpid().as_raw() == 1 }

fn main() -> Result<()> {
    unsafe { libc::signal(libc::SIGPIPE, libc::SIG_IGN); }

    if !is_pid1() {
        eprintln!("This binary is intended to run as PID 1. For CLI, use: echo '{\"cmd\":\"list\"}' | socat - UNIX-CONNECT:/run/sysx.sock");
    }

    ensure_dirs();
    let _ = setup_logging();
    info!("sysx starting (pid={})", getpid());

    mount_essential().ok();
    remount_root_rw();
    run_fsck_and_fstab();
    bring_up_network();

    let mut sup = Supervisor::new();
    // Example supervised tasks (optional, non-GUI, non-systemd)
    if Path::new("/sbin/klogd").exists() {
        sup.add_task(Task { name: "klogd".into(), cmd: vec!["/sbin/klogd".into(), "-n".into()], restart: true, env: vec![], stdout_log: "/var/log/sysx/klogd.out".into(), stderr_log: "/var/log/sysx/klogd.err".into() });
    }
    if Path::new("/sbin/dhclient").exists() {
        sup.add_task(Task { name: "dhclient".into(), cmd: vec!["/sbin/dhclient".into(), "-v".into()], restart: true, env: vec![], stdout_log: "/var/log/sysx/dhclient.out".into(), stderr_log: "/var/log/sysx/dhclient.err".into() });
    }

    for name in sup.tasks.clone().keys() { let _ = sup.start_task(name); }

    spawn_getty();

    let sup_ptr: *mut Supervisor = &mut sup;
    thread::spawn(move || { let _ = run_cli_server(sup_ptr); });

    loop {
        sup.reaper();
        thread::sleep(Duration::from_millis(200));
    }
}

// CLI usage (from another shell):
//   echo '{"cmd":"list"}' | socat - UNIX-CONNECT:/run/sysx.sock
//   echo '{"cmd":"start","name":"dhclient"}' | socat - UNIX-CONNECT:/run/sysx.sock
//   echo '{"cmd":"stop","name":"dhclient"}' | socat - UNIX-CONNECT:/run/sysx.sock

Below is a complete, compilable Rust project for a minimal sysx init and CLI designed for Devuan. It avoids systemd, sysvinit, dbus, X/X11/xorg, elogind, xinit, and systemctl. It mounts /proc, /sys, /dev, runs fsck, remounts root rw, mounts fstab, brings up networking, reaps zombies, supervises tasks with restart policies and logging, exposes a Unix domain socket CLI (list/start/stop), and starts a getty on tty1.

---
Cargo.toml

[package]
name = "sysx"
version = "0.1.0"
