src/main.rs

use nix::errno::Errno;
use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{kill, SigHandler, SigSet, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, dup2, execvp, fork, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::ffi::CString;
use std::fs::{self, create_dir_all, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::fd::AsRawFd;
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::process::{exit, Command};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// -------------------------------
// Data structures for supervision
// -------------------------------

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize)]
enum TaskRunState {
    Starting,
    Running { pid: i32 },
    Stopped,
    Crashed { code: Option<i32> },
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    pid: Option<Pid>,
    last_start: Option<Instant>,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self { spec, state: TaskRunState::Stopped, pid: None, last_start: None }
    }
}

// -------------------------------
// Global state
// -------------------------------

struct State {
    tasks: HashMap<String, TaskRuntime>,
}

impl State {
    fn new() -> Self { Self { tasks: HashMap::new() } }
}

// -------------------------------
// Utility helpers
// -------------------------------

fn log_to_console(msg: &str) {
    let _ = File::create("/dev/console").and_then(|mut f| writeln!(f, "[sysx] {msg}"));
}

fn run_cmd(mut cmd: Command, desc: &str) -> std::io::Result<i32> {
    log_to_console(&format!("run: {desc}: {:?}", cmd));
    let status = cmd.status()?;
    Ok(status.code().unwrap_or_default())
}

fn open_append_log(path: &Path) -> std::io::Result<File> {
    if let Some(dir) = path.parent() { create_dir_all(dir)?; }
    OpenOptions::new().create(true).append(true).open(path)
}

fn ensure_dir_mode<P: AsRef<Path>>(p: P, mode: u32) {
    if let Err(e) = create_dir_all(&p) { log_to_console(&format!("mkdir {:?}: {e}", p.as_ref())); }
    if let Err(e) = fs::set_permissions(&p, fs::Permissions::from_mode(mode)) {
        log_to_console(&format!("chmod {:?}: {e}", p.as_ref()));
    }
}

// -------------------------------
// Mounting and early boot
// -------------------------------

fn mount_essential() {
    ensure_dir_mode("/proc", 0o555);
    ensure_dir_mode("/sys", 0o555);
    ensure_dir_mode("/dev", 0o755);
    ensure_dir_mode("/run", 0o755);

    // Mount devtmpfs early so device nodes exist
    if let Err(e) = mount::<str, str, str, str>(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,nosuid")) {
        log_to_console(&format!("mount devtmpfs: {e}"));
    }
    // proc and sysfs
    if let Err(e) = mount::<str, str, str, str>(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None) {
        log_to_console(&format!("mount proc: {e}"));
    }
    if let Err(e) = mount::<str, str, str, str>(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None) {
        log_to_console(&format!("mount sysfs: {e}"));
    }
}

fn remount_root_rw() {
    if let Err(e) = mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT, Some("rw")) {
        log_to_console(&format!("remount / rw: {e}"));
    }
}

fn run_fsck_all() {
    // Prefer util-linux fsck -A -T -a (non-interactive)
    let mut cmd = Command::new("/sbin/fsck");
    if !Path::new("/sbin/fsck").exists() { cmd = Command::new("/bin/fsck"); }
    if Path::new("/sbin/fsck").exists() || Path::new("/bin/fsck").exists() {
        let _ = run_cmd(cmd.arg("-AT").arg("-a"), "fsck -AT -a");
    } else {
        log_to_console("fsck not found; skipping");
    }
}

fn mount_fstab() {
    // Use mount -a to honor /etc/fstab
    let bin = if Path::new("/bin/mount").exists() { "/bin/mount" } else { "/sbin/mount" };
    let _ = run_cmd(Command::new(bin).arg("-a"), "mount -a");
}

// -------------------------------
// Networking
// -------------------------------

fn bringup_networking() {
    // Loopback
    if Path::new("/sbin/ip").exists() {
        let _ = run_cmd(Command::new("/sbin/ip").args(["link", "set", "lo", "up"]), "ip link set lo up");
        let _ = run_cmd(Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]), "ip addr add lo");
    } else if Path::new("/bin/ip").exists() {
        let _ = run_cmd(Command::new("/bin/ip").args(["link", "set", "lo", "up"]), "ip link set lo up");
        let _ = run_cmd(Command::new("/bin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]), "ip addr add lo");
    }

    // If ifupdown is present on Devuan, bring all configured interfaces
    if Path::new("/sbin/ifup").exists() {
        let _ = run_cmd(Command::new("/sbin/ifup").arg("-a"), "ifup -a");
    } else if Path::new("/bin/ifup").exists() {
        let _ = run_cmd(Command::new("/bin/ifup").arg("-a"), "ifup -a");
    } else {
        // Fallback: attempt DHCP on first non-lo interface via busybox udhcpc if available
        if Path::new("/sbin/udhcpc").exists() {
            let _ = run_cmd(Command::new("/sbin/udhcpc").args(["-q"]), "udhcpc -q");
        }
    }
}

// -------------------------------
// Getty spawn (tty1)
// -------------------------------

fn spawn_getty_task(state: &mut State) {
    // On Devuan, util-linux agetty is typical
    let getty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" } else if Path::new("/bin/agetty").exists() { "/bin/agetty" } else { "/sbin/getty" };
    let spec = TaskSpec {
        name: "getty-tty1".to_string(),
        cmd: vec![getty.to_string(), "--noclear".into(), "tty1".into(), "38400".into(), "linux".into()],
        restart: RestartPolicy::Always,
        autostart: true,
        log_path: PathBuf::from("/var/log/sysx/getty-tty1.log"),
    };
    state.tasks.insert(spec.name.clone(), TaskRuntime::new(spec));
}

// -------------------------------
// Supervision engine
// -------------------------------

fn spawn_task(rt: &mut TaskRuntime) {
    let argv = rt.spec.cmd.clone();
    if argv.is_empty() { return; }

    let log_path = rt.spec.log_path.clone();
    let mut log = match open_append_log(&log_path) {
        Ok(f) => f,
        Err(e) => {
            log_to_console(&format!("log open {:?}: {e}", log_path));
            return;
        }
    };

    match unsafe { fork() } {
        Ok(ForkResult::Child) => {
            // New session for the service
            let _ = setsid();

            // Redirect stdout/stderr to log file
            let fd = log.as_raw_fd();
            let _ = dup2(fd, 1);
            let _ = dup2(fd, 2);

            // Prepare exec
            let cprog = CString::new(argv[0].clone()).unwrap();
            let cargs: Vec<CString> = argv.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
            // Exec
            let _ = execvp(&cprog, &cargs);
            // If exec fails
            let _ = writeln!(log, "exec failed for {:?}", argv);
            unsafe { libc::_exit(127) };
        }
        Ok(ForkResult::Parent { child }) => {
            rt.pid = Some(child);
            rt.state = TaskRunState::Running { pid: child.as_raw() };
            rt.last_start = Some(Instant::now());
            let _ = writeln!(log, "started pid {}: {:?}", child, argv);
        }
        Err(e) => {
            let _ = writeln!(log, "fork failed: {e}");
            rt.state = TaskRunState::Crashed { code: None };
        }
    }
}

fn supervise_tick(state: &mut State) {
    // Reap any children, update states, and restart if policy demands
    loop {
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::StillAlive) => break,
            Ok(WaitStatus::Exited(pid, code)) => {
                // find which task
                for rt in state.tasks.values_mut() {
                    if rt.pid == Some(pid) {
                        rt.pid = None;
                        if code == 0 {
                            rt.state = TaskRunState::Stopped;
                        } else {
                            rt.state = TaskRunState::Crashed { code: Some(code) };
                        }
                        // restart per policy
                        match rt.spec.restart {
                            RestartPolicy::Always => spawn_task(rt),
                            RestartPolicy::OnFailure => if code != 0 { spawn_task(rt) },
                            RestartPolicy::Never => {}
                        }
                        break;
                    }
                }
            }
            Ok(WaitStatus::Signaled(pid, _sig, _)) => {
                for rt in state.tasks.values_mut() {
                    if rt.pid == Some(pid) {
                        rt.pid = None;
                        rt.state = TaskRunState::Crashed { code: None };
                        match rt.spec.restart {
                            RestartPolicy::Always | RestartPolicy::OnFailure => spawn_task(rt),
                            RestartPolicy::Never => {}
                        }
                        break;
                    }
                }
            }
            Ok(_) => {}
            Err(nix::Error::Sys(Errno::ECHILD)) => break,
            Err(e) => { log_to_console(&format!("waitpid err: {e}")); break; }
        }
    }
}

fn autostart_tasks(state: &mut State) {
    for rt in state.tasks.values_mut() {
        if rt.spec.autostart && rt.pid.is_none() {
            rt.state = TaskRunState::Starting;
            spawn_task(rt);
        }
    }
}

// -------------------------------
// CLI protocol over Unix socket
// -------------------------------

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum CliRequest {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize, Debug)]
struct TaskView {
    name: String,
    state: TaskRunState,
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "status", rename_all = "lowercase")]
enum CliResponse {
    Ok,
    Tasks { tasks: Vec<TaskView> },
    Error { message: String },
}

fn handle_cli_conn(mut stream: UnixStream, state: &Arc<Mutex<State>>) {
    let mut buf = String::new();
    if let Err(e) = BufReader::new(stream.try_clone().unwrap()).read_line(&mut buf) {
        let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Error { message: format!("read: {e}") }).unwrap());
        return;
    }
    let req: Result<CliRequest, _> = serde_json::from_str(&buf);
    match req {
        Ok(CliRequest::List) => {
            let state = state.lock().unwrap();
            let mut tasks = Vec::new();
            for (name, rt) in state.tasks.iter() {
                tasks.push(TaskView { name: name.clone(), state: rt.state.clone() });
            }
            let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Tasks { tasks }).unwrap());
        }
        Ok(CliRequest::Start { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if rt.pid.is_none() {
                    rt.state = TaskRunState::Starting;
                    spawn_task(rt);
                }
                let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Ok).unwrap());
            } else {
                let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Error { message: "unknown task".into() }).unwrap());
            }
        }
        Ok(CliRequest::Stop { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if let Some(pid) = rt.pid {
                    let _ = kill(pid, Signal::SIGTERM);
                }
                rt.state = TaskRunState::Stopped;
                let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Ok).unwrap());
            } else {
                let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Error { message: "unknown task".into() }).unwrap());
            }
        }
        Err(e) => {
            let _ = writeln!(stream, "{}", serde_json::to_string(&CliResponse::Error { message: format!("decode: {e}") }).unwrap());
        }
    }
}

fn cli_server(state: Arc<Mutex<State>>) {
    ensure_dir_mode("/run/sysx", 0o755);
    let sock_path = "/run/sysx/sysx.sock";
    let _ = fs::remove_file(sock_path);
    let listener = UnixListener::bind(sock_path).expect("bind sysx socket");
    if let Err(e) = fs::set_permissions(sock_path, fs::Permissions::from_mode(0o660)) {
        log_to_console(&format!("chmod socket: {e}"));
    }
    log_to_console("sysx CLI listening on /run/sysx/sysx.sock (JSON lines). Use: sysx list|start <name>|stop <name>");

    for conn in listener.incoming() {
        match conn {
            Ok(stream) => {
                let st = state.clone();
                thread::spawn(move || handle_cli_conn(stream, &st));
            }
            Err(e) => log_to_console(&format!("socket accept: {e}")),
        }
    }
}

// Simple CLI client when invoked not as PID 1
fn run_cli_client(args: &[String]) {
    // Commands:
    // sysx list
    // sysx start <name>
    // sysx stop <name>
    let req = if args.len() == 2 && args[1] == "list" {
        CliRequest::List
    } else if args.len() == 3 && args[1] == "start" {
        CliRequest::Start { name: args[2].clone() }
    } else if args.len() == 3 && args[1] == "stop" {
        CliRequest::Stop { name: args[2].clone() }
    } else {
        eprintln!("Usage: sysx [list|start <name>|stop <name>]");
        exit(2);
    };

    let mut stream = UnixStream::connect("/run/sysx/sysx.sock").expect("connect to sysx");
    let line = format!("{}\n", serde_json::to_string(&req).unwrap());
    stream.write_all(line.as_bytes()).unwrap();
    let mut resp = String::new();
    BufReader::new(stream).read_line(&mut resp).unwrap();
    println!("{}", resp.trim_end());
}

// -------------------------------
// PID 1 setup and main loop
// -------------------------------

extern "C" fn sigchld_handler(_sig: i32) { /* nothing: main loop uses waitpid(WNOHANG) */ }

fn setup_signals_pid1() {
    unsafe {
        let handler = SigHandler::Handler(sigchld_handler);
        let _ = nix::sys::signal::signal(Signal::SIGCHLD, handler);
        let _ = nix::sys::signal::signal(Signal::SIGTERM, SigHandler::SigIgn);
        let _ = nix::sys::signal::signal(Signal::SIGINT, SigHandler::SigIgn);
    }
}

fn is_pid1() -> bool { unsafe { libc::getpid() } == 1 }

fn pid1_main() -> ! {
    log_to_console("sysx: starting as PID 1");

    // Early mounts and boot steps
    mount_essential();
    remount_root_rw();
    run_fsck_all();
    mount_fstab();

    bringup_networking();

    // Init state and tasks
    let mut state = State::new();

    // Getty on tty1
    spawn_getty_task(&mut state);

    // Autostart
    autostart_tasks(&mut state);

    // Share state with CLI thread
    let shared = Arc::new(Mutex::new(state));
    let cli_state = shared.clone();
    thread::spawn(move || cli_server(cli_state));

    // Main supervision + reap loop
    loop {
        {
            let mut st = shared.lock().unwrap();
            supervise_tick(&mut st);
        }
        // Sleep a bit to avoid busy-looping
        thread::sleep(Duration::from_millis(200));
    }
}

fn main() {
    // If not PID 1, act as CLI client
    if !is_pid1() {
        let args: Vec<String> = std::env::args().collect();
        run_cli_client(&args);
        return;
    }

    setup_signals_pid1();

    // Ensure we have a working console
    if let Err(e) = OpenOptions::new().read(true).write(true).open("/dev/console") { eprintln!("console open: {e}"); }

    // Change to root dir
    let _ = chdir("/");

    // Launch PID 1 main
    pid1_main();
}

// -------------------------------
// Notes:
// - To use as init: add kernel cmdline init=/sbin/sysx and place this binary at /sbin/sysx (0755).
// - CLI examples (on running system):
//     echo '{"cmd":"list"}' | socat - UNIX-CONNECT:/run/sysx/sysx.sock
//     echo '{"cmd":"start","name":"getty-tty1"}' | socat - UNIX-CONNECT:/run/sysx/sysx.sock
//     echo '{"cmd":"stop","name":"getty-tty1"}' | socat - UNIX-CONNECT:/run/sysx/sysx.sock
// - Logging: per-task logs at /var/log/sysx/<task>.log. sysx also logs short events to /dev/console.
// - Safety: avoids unsafe except for fork/exec signal setup typical for init; supervises and reaps children; avoids server managers like systemd.

Below is a complete, self-contained Flask app you can deploy (Render, Railway, Fly.io, Heroku, etc.) and then embed on your Square.com site via an iframe. It includes:

- A working /embed UI with paste and .txt/.pdf upload
- Ingredient extraction and external lookups (Wikipedia, Wikidata, Datamuse) with timeouts and error handling
- A playful “spell” generator that uses the extracted ingredients and lookup results
- Clear error states and a compact, embeddable layout

How to embed on Square:
1) Deploy this app to a public URL (e.g., https://your-spell-app.example.com)
2) In Square Online > Website > Edit site > Add section > Embed code, paste this exact snippet:
   <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>
3) Publish.

Notes:
- For PDFs, install PyPDF2: pip install PyPDF2
- Public endpoints only; no API keys
- Default network timeout is 4 seconds per call
- This is for creative/entertainment purposes

```python
# app.py
import io
import re
import html
import logging
import json
from typing import List, Dict, Optional

from flask import Flask, request, jsonify, Response
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0

def normalize_ingredient_line(line: str) -> Optional[str]:
    line = re.sub(r"\([^)]*\)", "", line)
    line = line.strip().lstrip("-•*").strip()
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)
    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []
    if not cleaned:
        return None
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]
    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]
    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()
    pieces = ing.split()
    if len(pieces) > 5:
        ing = " ".join(pieces[-3:])
    ing = re.sub(r"\s+", " ", ing).strip().lower()
    if not ing or len(ing) < 2:
        return None
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None

def extract_ingredients_from_text(text: str, limit: int = 20) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line or
                any(b in low for b in SECTION_BREAKERS if b != "ingredients") or
                re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)
    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped

def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None

def truncate(text: str, max_len: int = 300) -> str:
