# --------- Spell Generation ---------

def build_spell(ingredients: List[str], knowledge: Dict[str, Dict]) -> str:
    if not ingredients:
        return "No ingredients found — please paste a recipe or upload a .txt/.pdf."
    lines = [
        "By moonlit measure and sunlit spoon,",
        "Combine these gifts and chant this tune:",
        ""
    ]
    for ing in ingredients:
        k = knowledge.get(ing, {})
        desc = k.get("wikidata_description") or k.get("wikipedia_summary") or "a mysterious essence"
        adjs = k.get("adjectives") or []
        flair = ", ".join(adjs[:2]) if adjs else "enchanted"
        lines.append(f"- {ing.title()} — {flair}; {truncate(desc, 140)}")
    lines += [
        "",
        "Stir thrice widdershins, speak soft and well,",
        "Let flavor awaken this humble spell."
    ]
    return "\n".join(lines)

