def embed():
    return Response(EMBED_HTML, mimetype="text/html")

@app.route("/api/process", methods=["POST"])
def api_process():
    try:
        text = (request.form.get("recipe") or "").strip()
        file = request.files.get("file")
        if file and file.filename:
            fname = (file.filename or "").lower()
            b = file.read()
            if len(b) > app.config["MAX_CONTENT_LENGTH"]:
                return jsonify({"error": "File too large (max 2MB)."}), 413
            if fname.endswith(".txt"):
                try:
                    text = b.decode("utf-8", errors="ignore")
                except Exception:
                    text = b.decode("latin-1", errors="ignore")
            elif fname.endswith(".pdf"):
                try:
                    text = extract_text_from_pdf(b)
                except Exception as e:
                    return jsonify({"error": f"PDF error: {str(e)}"}), 400
            else:
                return jsonify({"error": "Unsupported file type. Use .txt or .pdf"}), 400
        if not text:
            return jsonify({"error": "Empty input. Paste recipe text or upload a .txt/.pdf."}), 400

        ingredients = extract_ingredients_from_text(text, limit=20)
        knowledge: Dict[str, Dict] = {}
        for ing in ingredients:
            try:
                knowledge[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"Lookup failed for {ing}: {e}")
                knowledge[ing] = {
                    "ingredient": ing,
                    "wikipedia_summary": "",
                    "wikidata_description": "",
                    "adjectives": [],
                    "related": [],
                    "sources": {}
                }
        spell = build_spell(ingredients, knowledge)
        return jsonify({
            "message": "Processed successfully",
            "ingredients": ingredients,
            "knowledge": knowledge,
            "spell": spell
        })
    except Exception as e:
        logger.exception("/api/process error")
        return jsonify({"error": "Server error. Please try again later."}), 500

# --------- Main ---------

if __name__ == "__main__":
