# --------- Spell Generation ---------

def craft_spell(ingredients: List[str], knowledge: Dict[str, Dict]) -> str:
    if not ingredients:
        return "No ingredients found — the cauldron stays still."
    lines = ["By moonlit measure and careful art,"]
    for ing in ingredients:
        info = knowledge.get(ing, {})
        adj = (info.get("adjectives") or ["mystic"])[:1][0]
        desc = info.get("wikidata_description") or info.get("wikipedia_summary") or "an enigmatic essence"
        lines.append(f"• Stir in {adj} {ing}, {desc}.")
    lines.extend([
        "Whisper the names thrice, let aromas swell,",
        "From humble recipe, awaken spell!"
    ])
    return "\n".join(lines)

