label { font-weight: 600; }
textarea { width: 100%; min-height: 140px; padding: 10px; border: 1px solid #d1d5db; border-radius: 8px; resize: vertical; }
input[type=file] { width: 100%; }
button { appearance: none; border: 0; background: #111827; color: #fff; padding: 10px 14px; border-radius: 8px; cursor: pointer; }
button:disabled { opacity: .6; cursor: not-allowed; }
.row { display: grid; grid-template-columns: 1fr; gap: 12px; }
@media (min-width: 720px) { .row-2 { grid-template-columns: 1fr 1fr; } }
