footer { margin-top: 12px; font-size: .85rem; color: #6b7280; }
"""

# Minimal escaping to avoid injection in results pane

def esc(s: str) -> str:
    return html.escape(s or "")

# --------- Routes ---------

@app.get("/")
def index():
    return redirect(url_for('embed'))

@app.get("/healthz")
def healthz():
    return {"ok": True}

@app.get("/embed")
def embed():
    html_doc = f"""
<!doctype html>
<html lang=\"en\">
<head>
  <meta charset=\"utf-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
  <title>Recipe to Spell</title>
  <style>{esc(BASE_CSS)}</style>
</head>
<body>
  <div class=\"container\">
    <div class=\"card\">
      <h1>Recipe to Spell Converter</h1>
      <form class=\"row\" action=\"/process\" method=\"post\" enctype=\"multipart/form-data\">
        <div>
          <label for=\"recipe_text\">Paste recipe text</label>
          <textarea id=\"recipe_text\" name=\"recipe_text\" placeholder=\"Paste your recipe here...\"></textarea>
          <div class=\"small\">Tip: Include an Ingredients section for better results.</div>
        </div>
        <div>
          <label for=\"recipe_file\">Or upload .txt or .pdf</label>
          <input id=\"recipe_file\" name=\"recipe_file\" type=\"file\" accept=\".txt,application/pdf\">
        </div>
        <div>
          <button type=\"submit\">Conjure Spell</button>
        </div>
      </form>
      <hr>
      <div class=\"small\">This widget parses ingredients, looks up facts (Wikipedia/Wikidata/Datamuse), and crafts a playful spell. No data is stored.</div>
    </div>
    <footer>Works best when embedded via iframe on Square Online. Max upload 2 MB.</footer>
  </div>
</body>
</html>
"""
    resp = make_response(html_doc)
    resp.headers['Content-Security-Policy'] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; script-src 'self'; frame-ancestors *; connect-src 'self' https://en.wikipedia.org https://www.wikidata.org https://api.datamuse.com"
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['Referrer-Policy'] = 'no-referrer'
    return resp

@app.post("/process")
def process():
    error = None
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")
    if file and file.filename:
        filename = file.filename.lower()
        try:
            if filename.endswith(".txt"):
                file_bytes = file.read()
                if len(file_bytes) > app.config["MAX_CONTENT_LENGTH"]:
                    raise RuntimeError("File too large")
                text_from_file = file_bytes.decode("utf-8", errors="replace")
                text = (text + "\n" + text_from_file).strip() if text else text_from_file
            elif filename.endswith(".pdf"):
                try:
                    file_bytes = file.read()
                    if len(file_bytes) > app.config["MAX_CONTENT_LENGTH"]:
                        raise RuntimeError("File too large")
                    text_from_file = extract_text_from_pdf(file_bytes)
                except RuntimeError as e:
                    error = str(e)
                    text_from_file = ""
                text = (text + "\n" + text_from_file).strip() if text_from_file else text
            else:
                error = "Unsupported file type. Please upload .txt or .pdf"
        except Exception as e:
            error = f"Failed to read file: {e}"
    if not text and not error:
        error = "Please paste a recipe or upload a .txt/.pdf file."

    ingredients: List[str] = []
    if text:
        ingredients = extract_ingredients_from_text(text)
        if not ingredients and not error:
            error = "No ingredients could be extracted. Try adding an Ingredients section or bullet list."

    knowledge: Dict[str, Dict] = {}
    if ingredients:
        for ing in ingredients:
            try:
                knowledge[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"Lookup failed for {ing}: {e}")
                knowledge[ing] = {"ingredient": ing, "wikipedia_summary": "", "wikidata_description": "", "adjectives": [], "related": [], "sources": {}}

    spell_text = craft_spell(ingredients, knowledge) if ingredients else ""

    # Build results HTML
    ing_list_html = "".join(f"<li>{esc(i)}</li>" for i in ingredients)

    sources_html_parts = []
    for ing, info in knowledge.items():
        src = info.get("sources", {})
        wp = src.get("wikipedia")
        wd = src.get("wikidata_search")
        dm = src.get("datamuse")
        links = []
        if wp: links.append(f"<a href='{esc(wp)}' target='_blank' rel='noopener'>Wikipedia</a>")
        if wd: links.append(f"<a href='{esc(wd)}' target='_blank' rel='noopener'>Wikidata</a>")
        if dm: links.append(f"<a href='{esc(dm)}' target='_blank' rel='noopener'>Datamuse</a>")
        if links:
            sources_html_parts.append(f"<li><span class='mono'>{esc(ing)}</span>: " + ", ".join(links) + "</li>")
    sources_html = "".join(sources_html_parts) if sources_html_parts else "<li>No external info available.</li>"

    status_banner = f"<div class='error'>⚠️ {esc(error)}</div>" if error else "<div class='ok'>✅ Spell conjured successfully.</div>"

    result_html = f"""
<!doctype html>
<html lang=\"en\">
<head>
  <meta charset=\"utf-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
  <title>Recipe to Spell — Result</title>
  <style>{esc(BASE_CSS)}</style>
</head>
<body>
  <div class=\"container\">
    <div class=\"card\">
      <h1>Recipe to Spell — Result</h1>
      {status_banner}
      <div class=\"row row-2\">
        <div>
          <h2 class=\"small\">Ingredients</h2>
          <ul>{ing_list_html or '<li>None</li>'}</ul>
          <h2 class=\"small\">Sources</h2>
          <ul>{sources_html}</ul>
        </div>
        <div>
          <h2 class=\"small\">Your Spell</h2>
          <div class=\"spell\">{esc(spell_text) if not error else esc('No spell generated due to input errors.')}</div>
        </div>
      </div>
      <hr>
      <form action=\"/embed\" method=\"get\">
        <button type=\"submit\">Back</button>
      </form>
    </div>
  </div>
</body>
</html>
"""
    resp = make_response(result_html)
    resp.headers['Content-Security-Policy'] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; script-src 'self'; frame-ancestors *; connect-src 'self' https://en.wikipedia.org https://www.wikidata.org https://api.datamuse.com"
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['Referrer-Policy'] = 'no-referrer'
    return resp

if __name__ == "__main__":
    # Bind to all interfaces for container platforms
