.error{background:#1f2937;border:1px solid var(--bad);color:#fecaca;padding:10px;border-radius:8px}
.result{white-space:pre-wrap;background:#0f172a;border:1px solid #243244;border-radius:10px;padding:12px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;background:#0b3; color:#041}
ul.sources{margin:8px 0 0;padding-left:18px;color:#cbd5e1}
footer{margin-top:14px;color:#94a3b8;font-size:12px}
"""


def render_embed_page(error: Optional[str] = None, spell: Optional[str] = None, ings: Optional[List[str]] = None, info: Optional[Dict] = None) -> str:
    # Basic, self-contained HTML suitable for iframe embedding
    err_html = f'<div class="error">{html.escape(error)}</div>' if error else ''
    spell_html = ''
    if spell:
        # Sources list (first ingredient sources shown compactly)
        src_blocks = []
        if info and ings:
            shown = 0
            for ing in ings:
                meta = info.get(ing, {})
                src = meta.get("sources", {})
                if src:
                    block = f"<li><strong>{html.escape(ing)}</strong>: " \
                            f"<a target=_blank rel=noopener href='{html.escape(src.get('wikipedia',''))}'>Wikipedia</a> · " \
                            f"<a target=_blank rel=noopener href='{html.escape(src.get('wikidata_search',''))}'>Wikidata</a>" \
                            f" · <a target=_blank rel=noopener href='https://api.datamuse.com/words?ml={html.escape(ing)}'>Datamuse</a></li>"
                    src_blocks.append(block)
                    shown += 1
                if shown >= 6:
                    break
        spell_html = f"""
        <div class=card>
          <h2 style="margin:0 0 8px">Your Conjured Spell</h2>
          <div class=result>{html.escape(spell)}</div>
          <details style="margin-top:10px"><summary style="cursor:pointer">Sources & Links</summary>
            <ul class=sources>{''.join(src_blocks) or '<li>No external details found; used defaults.</li>'}</ul>
          </details>
        </div>
        """

    return f"""
<!doctype html>
<html lang=en>
<meta charset=utf-8>
<meta name=viewport content="width=device-width,initial-scale=1">
<title>Recipe-to-Spell Widget</title>
<style>{BASE_CSS}</style>
<body>
  <div class=wrapper>
    <div class=card>
      <h1>Recipe → Spell</h1>
      <p class=lead>Paste a recipe or upload a .txt/.pdf. We will extract ingredients and weave a playful spell.</p>
      {err_html}
      <form method=post action="/process" enctype="multipart/form-data">
        <label for=recipe>Paste recipe text</label>
        <textarea id=recipe name=recipe placeholder="Ingredients\n- 2 cups flour\n- 1 tsp salt\n\nInstructions..." ></textarea>
        <div class=controls>
          <input type=file name=file accept=".txt,application/pdf,.pdf,text/plain">
          <button type=submit>Conjure Spell</button>
        </div>
        <small class=hint>We ignore personal data; only ingredients are used. Max file size 2MB. PDFs require PyPDF2 on the server.</small>
      </form>
    </div>
    {spell_html}
    <footer>Timeouts keep lookups snappy. Entertainment only.</footer>
  </div>
</body>
</html>
"""

# --------- Routes ---------

@app.route("/health")
def health():
    return {"ok": True}


@app.route("/")
def index():
    # Redirect root to /embed for convenience
    return redirect("/embed", code=302)


@app.route("/embed", methods=["GET"])
def embed():
    html_doc = render_embed_page()
    resp = make_response(html_doc)
    # Security headers for embedding
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "ALLOWALL"  # Needed to be embedded across origins
    resp.headers["Referrer-Policy"] = "no-referrer"
    resp.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; frame-ancestors *; connect-src *;"
    return resp


@app.route("/process", methods=["POST"])
def process():
    # Get text either from textarea or uploaded file
    text = (request.form.get("recipe") or "").strip()
    uploaded = request.files.get("file")

    if uploaded and uploaded.filename:
        try:
            data = uploaded.read()
            if not data:
                raise ValueError("Uploaded file was empty.")
            name = (uploaded.filename or "").lower()
            if name.endswith(".txt") or (uploaded.mimetype or "").startswith("text/"):
                try:
                    text = data.decode("utf-8", errors="ignore")
                except Exception:
                    text = data.decode("latin-1", errors="ignore")
            elif name.endswith(".pdf") or (uploaded.mimetype or "") == "application/pdf":
                try:
                    text = extract_text_from_pdf(data)
                except Exception as e:
                    return _render_error(f"PDF error: {e}")
            else:
                return _render_error("Unsupported file type. Please upload .txt or .pdf.")
        except Exception as e:
            return _render_error(f"File processing failed: {e}")

    if not text:
        return _render_error("Please paste a recipe or upload a .txt/.pdf file.")

    ingredients = extract_ingredients_from_text(text, limit=12)
    if not ingredients:
        return _render_error("No ingredients could be extracted. Try a clearer recipe list.")

    # Fetch lightweight knowledge for each ingredient (with basic caching)
    info: Dict[str, Dict] = {}
    for ing in ingredients:
        try:
            info[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception as e:
            logger.warning(f"lookup failed for {ing}: {e}")
            info[ing] = {"ingredient": ing, "adjectives": [], "related": [], "wikipedia_summary": "", "wikidata_description": "", "sources": {}}

    spell = make_spell(ingredients, info)
    if not spell:
        return _render_error("Spell generation failed. Please try different text.")

    html_doc = render_embed_page(None, spell, ingredients, info)
    resp = make_response(html_doc)
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "ALLOWALL"
    resp.headers["Referrer-Policy"] = "no-referrer"
    resp.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; frame-ancestors *; connect-src *;"
    return resp


def _render_error(msg: str):
    html_doc = render_embed_page(error=msg)
    resp = make_response(html_doc, 400)
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "ALLOWALL"
    resp.headers["Referrer-Policy"] = "no-referrer"
    resp.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; frame-ancestors *; connect-src *;"
    return resp


if __name__ == "__main__":
    # For local testing: python app.py
    # In production, use a WSGI server (gunicorn, waitress, uwsgi)
    app.run(host="0.0.0.0", port=8000, debug=False)
```

Below is a complete, runnable Flask app that delivers a working /embed UI for pasting recipe text or uploading .txt/.pdf files, extracts ingredients, fetches playful knowledge from Wikipedia/Wikidata/Datamuse with timeouts and error handling, generates a whimsical spell, and renders clear success/error pages.

How to use:
- Run locally: pip install flask requests PyPDF2 (PyPDF2 is optional; PDFs will show a clear error if not installed)
- Start: python app.py (defaults to port 8000)
- Deploy to a public URL (Render, Railway, Fly.io, Heroku, etc.)
- Embed in Square: paste this exact snippet (replacing the domain with yours)
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

```python
# app.py
import io
import os
import re
import html
import random
import logging
from typing import List, Dict, Optional

from flask import Flask, request, make_response, redirect
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB upload limit

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    # Remove parenthetical notes
    line = re.sub(r"\([^)]*\)", "", line)
    # Normalize and trim bullets
    line = line.strip().lstrip("-•*").strip()
    # Remove leading quantities like "1 1/2", "2", "2-3", "200 g", etc.
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    # Remove unicode fractions like "½"
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)

    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    # Skip initial unit tokens
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []

    if not cleaned:
        return None

    # Remove stopwords
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]

    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()

    pieces = ing.split()
    if len(pieces) > 5:
        # Keep likely core, e.g., "brown sugar"
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()

    if not ing or len(ing) < 2:
        return None

    # Exclude section headers and non-ingredient lines
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    # Avoid lines that are likely headings with non-alpha characters
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    # Trim trailing descriptors like "to taste" or "as needed"
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 12) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    # Try to find an "Ingredients" section
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line
                or any(b in low for b in SECTION_BREAKERS if b != "ingredients")
                or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                # End on blank or another section header
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        # Fallback: scan all lines, prefer bullets or lines with quantities
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    # Deduplicate while preserving order, limit count
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")


# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    # Try REST summary first
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    # Action API search fallback
    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generator ---------

def build_spell(ingredients: List[str], knowledge: List[Dict]) -> str:
    if not ingredients:
        return ""
    invocations = [
        "By whisk and will,",
        "By flame and fame,",
        "By salt of earth and spark of sky,",
        "Hark the hidden kitchen sprites,",
        "With gentle stir and lunar light,",
    ]
    closers = [
        "So mote it taste.",
        "Let savor rise.",
        "Thus the charm is cast.",
        "Feast and be bright.",
        "Bon appetit, bewitched!",
    ]

    lines = []
    lines.append(random.choice(invocations))

    for i, ing in enumerate(ingredients[:8]):
        info = next((k for k in knowledge if k.get("ingredient") == ing), {})
        adjs = info.get("adjectives") or []
        rel = info.get("related") or []
        desc = info.get("wikidata_description") or info.get("wikipedia_summary") or ""
        flair = ", ".join(adjs[:2]) if adjs else "mystic"
        alt = rel[0] if rel else "essence"
        snippet = truncate(desc, 120)
        part = f"- Add {flair} {ing} (akin to {alt}). {snippet}" if snippet else f"- Add {flair} {ing}."
        lines.append(part)

    lines.append(random.choice(closers))
    return "\n".join(lines)


