def render_embed_form(error: Optional[str] = None):
    err_html = f"<div class='error'>{html.escape(error)}</div>" if error else ""
    body = f"""
    <div class='card'>
      <p class='muted'>Paste your recipe text or upload a .txt/.pdf file. We'll extract ingredients and conjure a playful spell.</p>
