        <input id="recipe_file" name="recipe_file" type="file" accept=".txt,application/pdf" />
        <div class='hint'>Max 2 MB. PDFs require PyPDF2 on server.</div>
        <div style="margin-top:8px"><button class="btn" type="submit">Make Spell from File</button></div>
      </form>
    </div>
    <p class='muted' style='margin-top:10px'>Having trouble? This widget relies on public info sources and may take a few seconds.</p>
    """
    return page("Embed - Recipe to Spell", body)


def render_result(ingredients: List[str], spell_text: str, details: List[Dict]):
    if not ingredients:
        return page("No ingredients found", "<div class='error'>We couldn't detect any ingredients. Please check your recipe formatting and try again.</div>" + render_embed_form().get_data(as_text=True), 200)

    ing_list = "\n".join(f"<li>{html.escape(ing)}</li>" for ing in ingredients)

    src_blocks = []
    for k in details:
        wsum = html.escape(truncate(k.get("wikipedia_summary") or "", 180))
        wdd = html.escape(truncate(k.get("wikidata_description") or "", 120))
        lines = []
        if wsum:
            lines.append(f"<div><strong>Wikipedia:</strong> {wsum}</div>")
        if wdd:
            lines.append(f"<div><strong>Wikidata:</strong> {wdd}</div>")
        if not lines:
            lines.append("<div class='muted'>No external notes found.</div>")
        src = f"<details><summary style='cursor:pointer'>Notes for {html.escape(k.get('ingredient',''))}</summary>{''.join(lines)}</details>"
        src_blocks.append(src)

    body = f"""
    <div class='card'>
      <div class='success'><strong>Spell conjured!</strong> Based on your detected ingredients.</div>
      <h3>Ingredients</h3>
      <ul class='ingredients'>
        {ing_list}
      </ul>
      <h3>Your Spell</h3>
      <pre class='spell'>{html.escape(spell_text)}</pre>
      <details style='margin-top:10px'>
        <summary style='cursor:pointer'>How this was made</summary>
        <p class='muted'>We parse likely ingredient lines, then fetch short, public facts/related words from Wikipedia, Wikidata, and Datamuse to add flavor. This is just for fun and not medically or nutritionally authoritative.</p>
      </details>
      <div style='margin-top:12px'>
        <a class='small' href='/embed'>Back</a>
      </div>
      <div style='margin-top:12px'>
        {''.join(src_blocks)}
      </div>
    </div>
    """
    return page("Spell Result", body)


# --------- Request Handling ---------

def read_text_field(max_len: int = 20000) -> str:
    text = (request.form.get("recipe_text") or "").strip()
    if not text:
        raise ValueError("Please paste your recipe text.")
    if len(text) > max_len:
        raise ValueError("Text is too long. Please limit to 20KB.")
    return text


def read_uploaded_file() -> str:
    if "recipe_file" not in request.files:
        raise ValueError("No file part in request.")
    f = request.files.get("recipe_file")
    if not f or f.filename is None or f.filename.strip() == "":
        raise ValueError("Please choose a .txt or .pdf file to upload.")

    filename = f.filename.lower()
    data = f.read()
    if not data:
        raise ValueError("Uploaded file is empty.")

    if filename.endswith(".txt"):
        try:
            return data.decode("utf-8", errors="ignore")
        except Exception:
            raise ValueError("Could not decode text file. Please ensure it's UTF-8.")
    elif filename.endswith(".pdf"):
        try:
            return extract_text_from_pdf(data)
        except RuntimeError as e:
            raise ValueError(str(e))
        except Exception:
            raise ValueError("Failed to parse the PDF. Please try a different file.")
    else:
        raise ValueError("Unsupported file type. Please upload .txt or .pdf only.")


def process_recipe_text(raw_text: str) -> Dict:
    ings = extract_ingredients_from_text(raw_text, limit=12)
    details = [fetch_knowledge_for_ingredient(ing) for ing in ings]
    spell = build_spell(ings, details)
    return {"ingredients": ings, "details": details, "spell": spell}


# --------- Routes ---------

@app.route("/", methods=["GET"])
def index():
    return redirect("/embed", code=302)


@app.route("/embed", methods=["GET"])
def embed():
    return render_embed_form()


@app.route("/process_text", methods=["POST"])
def process_text():
    try:
        raw = read_text_field()
        result = process_recipe_text(raw)
        if not result["ingredients"]:
            return render_embed_form("We couldn't detect ingredients. Please ensure your list has lines like '- 2 cups flour'.")
        if not result["spell"]:
            return render_embed_form("Spell generation failed unexpectedly. Please try again.")
        return render_result(result["ingredients"], result["spell"], result["details"])
    except ValueError as e:
        return render_embed_form(str(e))
    except Exception as e:
        logger.exception("process_text failed")
        return render_embed_form("An unexpected error occurred while processing your text.")


@app.route("/process_upload", methods=["POST"])
def process_upload():
    try:
        raw = read_uploaded_file()
        result = process_recipe_text(raw)
        if not result["ingredients"]:
            return render_embed_form("We couldn't detect ingredients in your file. Try a clearer list or use pasted text.")
        if not result["spell"]:
            return render_embed_form("Spell generation failed unexpectedly. Please try again.")
        return render_result(result["ingredients"], result["spell"], result["details"])
    except ValueError as e:
        return render_embed_form(str(e))
    except Exception as e:
        logger.exception("process_upload failed")
        return render_embed_form("An unexpected error occurred while processing your file.")


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False)
