"""
    resp = make_response(html_doc, status)
    # Security headers for embedding
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['X-Frame-Options'] = 'ALLOWALL'  # allow embedding in Square iframe
    resp.headers['Content-Security-Policy'] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; script-src 'self'; frame-ancestors *"
    return resp


# --------- Routes ---------

@app.get("/embed")
def embed_form():
    err = request.args.get("error")
    ok = request.args.get("ok")
    err_html = f"<div class=\"err\">{html.escape(err)}</div>" if err else ""
    ok_html = f"<div class=\"ok\">{html.escape(ok)}</div>" if ok else ""

    body = f"""
<h1>Recipe to Spell</h1>
<p class=\"muted\">Paste your recipe or upload a .txt/.pdf. We will extract ingredients, gather lore, and weave a whimsical spell.</p>
{err_html}
{ok_html}
<form action=\"/process\" method=\"post\" enctype=\"multipart/form-data\">
  <label for=\"recipe_text\" class=\"mono\">Paste recipe text (optional if you upload a file)</label>
  <textarea name=\"recipe_text\" id=\"recipe_text\" placeholder=\"Ingredients\n- 2 cups flour\n- 1 tsp salt\n...\"></textarea>

  <div class=\"row\">
    <div>
      <label for=\"recipe_file\" class=\"mono\">Or upload .txt or .pdf (max 2 MB)</label><br>
      <input type=\"file\" name=\"recipe_file\" id=\"recipe_file\" accept=\".txt,application/pdf\">
    </div>
  </div>

  <div class=\"row\">
    <button class=\"btn\" type=\"submit\">Weave Spell</button>
  </div>
</form>
<p class=\"small\">By submitting, you agree not to upload sensitive or copyrighted content. We fetch public info from Wikipedia/Wikidata/Datamuse.</p>
"""
    return render_page("Recipe to Spell", body)


@app.post("/process")
def process_input():
    # Server-side validation
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")

    if not text and (not file or file.filename.strip() == ""):
        return _error("Please paste some recipe text or choose a .txt/.pdf file.")

    extracted_text = text

    if file and file.filename:
        filename = file.filename
        # Basic filename sanitation (no path traversal)
        if os.path.sep in filename or os.path.altsep and os.path.altsep in filename:
            return _error("Invalid file name.")

        # Read small buffer into memory (limited by MAX_CONTENT_LENGTH)
        try:
            data = file.read()
        except Exception:
            return _error("Could not read the uploaded file.")

        if not data:
            return _error("Uploaded file is empty.")
        if len(data) > app.config["MAX_CONTENT_LENGTH"]:
            return _error("File is too large (max 2 MB).")

        ctype = (file.mimetype or "").lower()
        ext = os.path.splitext(filename)[1].lower()

        if ext == ".txt" or ctype in {"text/plain", "text/markdown"}:
            try:
                extracted_text = (data.decode("utf-8", errors="ignore").strip())
            except Exception:
                return _error("Could not decode text file as UTF-8.")
        elif ext == ".pdf" or ctype == "application/pdf":
            if not HAS_PDF:
                return _error("PDF uploaded but PDF support is not installed on the server.")
            try:
                extracted_text = extract_text_from_pdf(data)
            except Exception as e:
                return _error(str(e))
        else:
            return _error("Unsupported file type. Please upload a .txt or .pdf file.")

    if not extracted_text:
        return _error("No text content found to analyze.")

    # Extract ingredients
    ingredients = extract_ingredients_from_text(extracted_text, limit=12)
    if not ingredients:
        return _error("We couldn’t find ingredients. Please include a clear ingredients list or bullet points.")

    # Gather knowledge for each ingredient with caching
    lore: Dict[str, Dict] = {}
    for ing in ingredients:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception:
            # Continue even if lookups fail; we’ll still build a spell
            lore[ing] = {"ingredient": ing, "adjectives": [], "wikidata_description": "", "wikipedia_summary": "", "related": []}

    # Build the spell
    spell_text = build_spell(ingredients, lore)

    # Render result
    items_html = "".join(
        f"<li><strong>{html.escape(ing)}</strong> — "
        f"{html.escape((lore.get(ing) or {}).get('wikidata_description') or (lore.get(ing) or {}).get('wikipedia_summary') or 'No lore found.')}</li>"
        for ing in ingredients
    )

    sources_html = "".join(
        f"<li class=\"small\"><a href=\"{html.escape((lore.get(ing) or {}).get('sources', {}).get('wikipedia', '#'))}\" target=\"_blank\" rel=\"noopener\">Wikipedia: {html.escape(ing)}</a></li>"
        for ing in ingredients
    )

    body = f"""
<h1>Your Spell</h1>
<p class=\"muted\">Born from your ingredients and stitched with public lore.</p>
<div class=\"ok\"><strong>Ingredients detected:</strong>
  <ul>{items_html}</ul>
</div>
<h2>Incantation</h2>
<pre class=\"mono\">{html.escape(spell_text)}</pre>

<h2>Sources</h2>
<ul>{sources_html}</ul>

<form action=\"/embed\" method=\"get\" class=\"row\" style=\"margin-top:16px\"> 
  <button class=\"btn\" type=\"submit\">Create Another</button>
</form>
"""
    return render_page("Your Spell", body)


def _error(message: str):
    # Re-render the /embed page with an error message
    err_body = f"""
<h1>Recipe to Spell</h1>
<div class=\"err\">{html.escape(message)}</div>
<form action=\"/process\" method=\"post\" enctype=\"multipart/form-data\">
  <label for=\"recipe_text\" class=\"mono\">Paste recipe text</label>
