// C# code (placed in a Python code fence per request) that embeds drawing primitives
// into a nanoCAD McTable cell using the MultiCAD .NET API.
//
// The function below:
//   1) Creates (or recreates) a dedicated block definition for the target cell.
//   2) Converts input geometry to McDbEntity instances and appends them to that block.
//   3) Computes a fitting scale for the block so it fits inside the cell with optional padding.
//   4) Assigns the block reference to the specified McTable cell [row, col] and commits the transaction.
//
using System;
using System.Collections.Generic;
using Multicad.ApplicationServices;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

namespace YourCompany.YourPlugin
{
    // Example geometry abstraction; each concrete type must return a valid McEntity for MultiCAD.
    public abstract class EntityGeometry
    {
        public abstract McEntity ToEntity();
    }

    public static class TableCellGeometryEmbedder
    {
        // Embeds primitives into a table cell by placing them into a per-cell block and setting it as cell content.
        // Parameters:
        //  - table: target McTable already added to the database
        //  - row, col: zero-based indices of the target cell
        //  - entityGeometry: list of geometry descriptors convertible to McEntity
        //  - padding: optional padding inside the cell (drawing units)
        //  - blockNamePrefix: prefix used to create a unique block name per cell
        public static void EmbedGeometryIntoCell(
            McTable table,
            int row,
            int col,
            IList<EntityGeometry> entityGeometry,
            double padding = 0.0,
            string blockNamePrefix = "_CellGeom_")
        {
            if (table == null) throw new ArgumentNullException(nameof(table));
            if (entityGeometry == null || entityGeometry.Count == 0)
                throw new ArgumentException("entityGeometry must contain at least one item.", nameof(entityGeometry));
            if (row < 0 || row >= table.Rows)
                throw new ArgumentOutOfRangeException(nameof(row));
            if (col < 0 || col >= table.Columns)
                throw new ArgumentOutOfRangeException(nameof(col));

            var db = HostMgdApp.Database; // Access current database in nanoCAD MultiCAD
            if (db == null)
                throw new InvalidOperationException("No active database.");

            // Create a unique block name for the cell
            string blockName = $"{blockNamePrefix}{table.Handle}_{row}_{col}";

            try
            {
                using (var tr = db.TransactionManager.StartTransaction())
                {
                    // Open block table for read/write
                    var btId = db.BlockTableId;
                    var bt = (McBlockTable)tr.GetObject(btId, OpenMode.ForRead);

                    // If block exists, erase and recreate to reflect latest geometry
                    McObjectId btrId;
                    McBlockTableRecord btr = null;
                    if (bt.Has(blockName))
                    {
                        bt.UpgradeOpen();
                        btrId = bt[blockName];
                        btr = (McBlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                        // Erase existing contents
                        var idsToErase = new List<McObjectId>(btr);
                        foreach (var id in idsToErase)
                        {
                            var ent = (McEntity)tr.GetObject(id, OpenMode.ForWrite);
                            ent.Erase();
                        }
                    }
                    else
                    {
                        bt.UpgradeOpen();
                        btr = new McBlockTableRecord { Name = blockName };
                        btrId = bt.Add(btr);
                        tr.AddNewlyCreatedDBObject(btr, true);
                    }

                    // Append converted entities into the block definition and compute bounds
                    Extents3d? ext = null;
                    foreach (var eg in entityGeometry)
                    {
                        var ent = eg?.ToEntity();
                        if (ent == null) continue;

                        btr.UpgradeOpen();
                        var entId = btr.AppendEntity(ent);
                        tr.AddNewlyCreatedDBObject(ent, true);

                        // Update extents
                        try
                        {
                            var eext = ent.GeometricExtents; // Extents3d
                            ext = ext.HasValue ? Union(ext.Value, eext) : eext;
                        }
                        catch { /* Some entities may not have extents initially */ }
                    }

                    // Fallback extents to a tiny box if nothing computed
                    if (!ext.HasValue)
                    {
                        ext = new Extents3d(new Point3d(0, 0, 0), new Point3d(1, 1, 0));
                    }

                    // Get target cell size
                    var cell = table.GetCell(row, col);
                    double cellW = cell.Width;
                    double cellH = cell.Height;

                    // Compute scale to fit with padding
                    var bb = ext.Value;
                    double geomW = Math.Max(1e-9, bb.MaxPoint.X - bb.MinPoint.X);
                    double geomH = Math.Max(1e-9, bb.MaxPoint.Y - bb.MinPoint.Y);
                    double fitW = Math.Max(0.0, cellW - 2.0 * padding);
                    double fitH = Math.Max(0.0, cellH - 2.0 * padding);
                    double sx = fitW > 0 ? fitW / geomW : 1.0;
                    double sy = fitH > 0 ? fitH / geomH : 1.0;
                    double s = Math.Min(sx, sy);
                    if (double.IsInfinity(s) || double.IsNaN(s) || s <= 0) s = 1.0;

                    // Create a block reference centered in the cell
                    var cellCenter = new Point3d(cell.Origin.X + cellW / 2.0, cell.Origin.Y + cellH / 2.0, 0.0);
                    var geomCenter = new Point3d((bb.MinPoint.X + bb.MaxPoint.X) / 2.0, (bb.MinPoint.Y + bb.MaxPoint.Y) / 2.0, 0.0);

                    // Insert block reference into model space (or table owner space) and then assign to cell content
                    var msId = db.CurrentSpaceId;
                    var ms = (McBlockTableRecord)tr.GetObject(msId, OpenMode.ForWrite);

                    var br = new McBlockReference
                    {
                        BlockTableRecord = btr.ObjectId,
                        Position = cellCenter,
                        ScaleFactors = new Scale3d(s, s, 1.0),
                        Rotation = 0.0
                    };

                    // Apply translation to keep geometry centered after scaling
                    var displacement = (Vector3d)(cellCenter - geomCenter);
                    br.TransformBy(Matrix3d.Displacement(displacement));

                    var brId = ms.AppendEntity(br);
                    tr.AddNewlyCreatedDBObject(br, true);

                    // Assign block reference to the cell content
                    cell.SetContentAsBlockReference(brId);

                    // Commit all changes
                    tr.Commit();
                }
            }
            catch (System.Exception ex)
            {
                // Basic error reporting; in a real plugin, consider logging framework integration
                HostMgdApp.ShowAlert("Failed to embed geometry into table cell: " + ex.Message);
                throw;
            }
        }

        // Helper to union two extents
        private static Extents3d Union(Extents3d a, Extents3d b)
        {
            var min = new Point3d(Math.Min(a.MinPoint.X, b.MinPoint.X), Math.Min(a.MinPoint.Y, b.MinPoint.Y), Math.Min(a.MinPoint.Z, b.MinPoint.Z));
            var max = new Point3d(Math.Max(a.MaxPoint.X, b.MaxPoint.X), Math.Max(a.MaxPoint.Y, b.MaxPoint.Y), Math.Max(a.MaxPoint.Z, b.MaxPoint.Z));
            return new Extents3d(min, max);
        }
    }
}

public static void EmbedPrimitivesIntoTableCell(List<EntityGeometry> geometries, McTable table, int rowIndex, int colIndex, string blockName)
{
    // Purpose: Convert input primitives to McDbEntity objects, create/update a block,
    // fit it to the specified McTable cell, assign it, and commit the transaction with basic validation and error handling.

    // Minimal input validation
    if (table == null) throw new ArgumentNullException(nameof(table));
    if (rowIndex < 0 || colIndex < 0) throw new ArgumentOutOfRangeException("Row and column indices must be non-negative.");
    if (geometries == null) throw new ArgumentNullException(nameof(geometries));
    if (geometries.Count == 0) throw new ArgumentException("Geometries list must not be empty.", nameof(geometries));
    if (string.IsNullOrWhiteSpace(blockName)) throw new ArgumentException("Block name is required.", nameof(blockName));

    try
    {
        // Ensure the table has the requested cell
        if (rowIndex >= table.RowsCount || colIndex >= table.ColumnsCount)
            throw new ArgumentOutOfRangeException("Target cell is outside the table bounds.");

        // Start a database transaction
        using (var tr = Db.StartTransaction())
        {
            // Get or create the block definition in the current database
            McBlockRef existingRef = null;
            McBlock blockDef = McBlock.GetBlock(blockName);
            if (blockDef == null)
            {
                blockDef = new McBlock(blockName);
                blockDef.AddToDb();
            }
            else
            {
                // Clear existing contents to update the block definition
                var idsToErase = blockDef.GetEntities();
                foreach (var id in idsToErase)
                {
                    var ent = McObjectManager.GetObject<McDbEntity>(id, DbEntityOpenMode.ForWrite);
                    ent?.Erase();
                }
            }

            // Convert custom geometries to real McDbEntity objects and add to the block definition
            var addedIds = new List<McObjectId>();
            foreach (var g in geometries)
            {
                if (g == null) continue;
                McDbEntity ent = null;
                // Example mapping: adapt cases to your EntityGeometry types and data
                switch (g.Type)
                {
                    case EntityGeometryType.Line:
                        // expects: g.Start, g.End as McGe.Point3d
                        ent = new DbLine(g.Start, g.End);
                        break;
                    case EntityGeometryType.Circle:
                        // expects: g.Center as Point3d, g.Radius as double
                        ent = new DbCircle(g.Center, g.Radius);
                        break;
                    case EntityGeometryType.Arc:
                        // expects: g.Center, g.Radius, g.StartAngle, g.EndAngle
                        ent = new DbArc(g.Center, g.Radius, g.StartAngle, g.EndAngle);
                        break;
                    case EntityGeometryType.Polyline:
                        // expects: g.Points as IEnumerable<Point3d>, g.Closed as bool
                        var pl = new DbPolyline();
                        foreach (var p in g.Points)
                            pl.AddVertexAt(pl.NumberOfVertices, new Point2d(p.X, p.Y), 0.0, 0.0, 0.0);
                        pl.Closed = g.Closed;
                        ent = pl;
                        break;
                    default:
                        // Skip unsupported geometry types
                        continue;
                }

                if (ent != null)
                {
                    ent.AddToDb(blockDef);
                    addedIds.Add(ent.Id);
                }
            }

            if (addedIds.Count == 0)
                throw new InvalidOperationException("No supported geometry was converted to entities.");

            // Compute block content extents to fit into the target cell
            Extents3d ext = default;
            bool hasExt = false;
            foreach (var id in addedIds)
            {
                var e = McObjectManager.GetObject<McDbEntity>(id, DbEntityOpenMode.ForRead);
                if (e == null) continue;
                if (!hasExt)
                {
                    ext = e.GeometricExtents;
                    hasExt = true;
                }
                else
                {
                    ext.AddExtents(e.GeometricExtents);
                }
            }

            if (!hasExt)
                throw new InvalidOperationException("Failed to compute extents for the block content.");

            // Determine target cell geometry (position and size)
            var cellRect = table.GetCellRect(rowIndex, colIndex); // assumes returns a rectangle with origin and size in drawing units
            var cellCenter = new Point3d(
                (cellRect.Left + cellRect.Right) * 0.5,
                (cellRect.Bottom + cellRect.Top) * 0.5,
                0.0);
            double cellW = Math.Abs(cellRect.Right - cellRect.Left);
            double cellH = Math.Abs(cellRect.Top - cellRect.Bottom);

            // Compute scale to fit extents into cell with small margin
            var size = new Vector3d(ext.MaxPoint.X - ext.MinPoint.X, ext.MaxPoint.Y - ext.MinPoint.Y, 0);
            if (size.X <= 1e-9 || size.Y <= 1e-9)
                throw new InvalidOperationException("Block content has degenerate extents.");

            const double margin = 0.9; // 90% of cell size
            double sx = (cellW * margin) / size.X;
            double sy = (cellH * margin) / size.Y;
            double uniformScale = Math.Min(sx, sy);
            if (uniformScale <= 0 || double.IsInfinity(uniformScale) || double.IsNaN(uniformScale))
                throw new InvalidOperationException("Invalid scale computed for fitting block into cell.");

            // Create or update a block reference positioned and scaled to the cell
            // Remove existing content in the cell if a block ref is already assigned
            var currentContent = table.GetCellContent(rowIndex, colIndex);
            if (currentContent is McBlockRef oldRef)
            {
                existingRef = oldRef;
            }

            // Compute transform: translate block extents center to origin, scale, then move to cell center
            var contentCenter = new Point3d((ext.MinPoint.X + ext.MaxPoint.X) * 0.5, (ext.MinPoint.Y + ext.MaxPoint.Y) * 0.5, 0.0);
            var toOrigin = Matrix3d.Displacement(Point3d.Origin - contentCenter);
            var scale = Matrix3d.Scaling(uniformScale, Point3d.Origin);
            var toCell = Matrix3d.Displacement(cellCenter - Point3d.Origin);
            var transform = toOrigin * scale * toCell;

            if (existingRef == null)
            {
                var br = new McBlockRef(blockDef);
                br.TransformBy(transform);
                br.AddToDb();
                // Assign block reference to the table cell
                table.SetCellContent(rowIndex, colIndex, br);
            }
            else
            {
                existingRef.UpgradeOpen();
                existingRef.Block = blockDef;
                existingRef.TransformBy(transform);
                table.SetCellContent(rowIndex, colIndex, existingRef);
            }

            // Commit transaction to persist all changes
            tr.Commit();
        }
    }
    catch (Exception ex)
    {
        // Basic error reporting; in production, route to logger/UI as appropriate
        throw new InvalidOperationException("Failed to embed primitives into the specified table cell.", ex);
    }
}

// Note: The following placeholder types and API calls (EntityGeometry, EntityGeometryType, Db*, McTable APIs like GetCellRect/SetCellContent) are expected to exist in the MultiCAD .NET/nanoCAD environment or your project wrappers. Adjust mappings and property names to your actual SDK versions.

using System;
using System.Collections.Generic;
using System.Linq;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.DatabaseServices.Tables;
using Multicad.Geometry;
using Multicad.Runtime;

public static class TableEmbedder
{
    // Embeds primitives into a McTable cell by creating/updating a block built from the given geometries.
    // Parameters:
    //   table: Target McTable instance where the block reference will be placed.
    //   row, col: Target cell indices (zero-based) identifying the destination cell in the table.
    //   geometries: List of EntityGeometry primitives to convert into McDbEntity objects for the block definition.
    // Behavior:
    //   - Validates inputs
    //   - Builds/updates a block definition named based on the table and cell
    //   - Inserts a block reference into the specified table cell and fits it to the cell bounds
    //   - Commits the changes within a transaction; catches and reports errors
    public static void EmbedPrimitivesIntoTableCell(McTable table, int row, int col, List<EntityGeometry> geometries)
    {
        // Minimal input validation
        if (table == null) throw new ArgumentNullException(nameof(table));
        if (row < 0 || col < 0 || row >= table.RowsCount || col >= table.ColumnsCount)
            throw new ArgumentOutOfRangeException($"Invalid table cell indices: row={row}, col={col}");
        if (geometries == null || geometries.Count == 0)
            throw new ArgumentException("Geometries list must not be null or empty.", nameof(geometries));

        // Start a transaction for robustness
        using (var tr = new Transaction())
        {
            try
            {
                Database db = HostMgd.ApplicationServices.Application.ActiveDocument.Database;

                // Resolve or create a block table record for our content
                string blockName = $"_TABLE_CELL_{table.Id.Handle}_{row}_{col}";
                ObjectId btrId;
                var bt = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
                if (!bt.Has(blockName))
                {
                    // Create new block definition
                    bt.UpgradeOpen();
                    var newBtr = new BlockTableRecord { Name = blockName };
                    btrId = bt.Add(newBtr);
                    tr.AddNewlyCreatedDBObject(newBtr, true);

                    // Convert geometries to entities and append to new block
                    var ents = ConvertToEntities(geometries);
                    AppendEntitiesToBlock(tr, newBtr, ents);
                }
                else
                {
                    // Update existing block definition: erase previous contents and add new
                    btrId = bt[blockName];
                    var btr = (BlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                    // Erase existing entities inside the block
                    var toErase = btr.Cast<ObjectId>().ToList();
                    foreach (var id in toErase)
                    {
                        var dbo = tr.GetObject(id, OpenMode.ForWrite, false);
                        dbo.Erase(true);
                    }

                    // Rebuild with current geometry set
                    var ents = ConvertToEntities(geometries);
                    AppendEntitiesToBlock(tr, btr, ents);
                }

                // Insert block reference into the specified table cell and fit
                var cellRect = table.GetCellRect(row, col); // returns rectangle in WCS
                var cellCenter = new Point3d((cellRect.Left + cellRect.Right) * 0.5, (cellRect.Top + cellRect.Bottom) * 0.5, 0.0);

                // Compute block extents to scale it to cell
                var btrForExt = (BlockTableRecord)tr.GetObject(btrId, OpenMode.ForRead);
                var ext = GetBlockExtents(tr, btrForExt);
                double sx = 1.0, sy = 1.0;
                if (!ext.IsEmpty)
                {
                    double blockW = Math.Max(1e-9, ext.MaxPoint.X - ext.MinPoint.X);
                    double blockH = Math.Max(1e-9, ext.MaxPoint.Y - ext.MinPoint.Y);
                    double cellW = Math.Abs(cellRect.Right - cellRect.Left);
                    double cellH = Math.Abs(cellRect.Top - cellRect.Bottom);
                    sx = cellW / blockW;
                    sy = cellH / blockH;
                    // keep aspect ratio: fit inside
                    double s = Math.Min(sx, sy);
                    sx = sy = s;
                }

                // Create the block reference on current space
                var curSpace = (BlockTableRecord)tr.GetObject(db.CurrentSpaceId, OpenMode.ForWrite);
                var br = new BlockReference(cellCenter, btrId)
                {
                    ScaleFactors = new Scale3d(sx, sy, 1.0),
                    Rotation = 0.0
                };
                var brId = curSpace.AppendEntity(br);
                tr.AddNewlyCreatedDBObject(br, true);

                // If the table supports embedding a reference per cell, assign entity to cell
                // Otherwise, we keep geometric placement centered in the cell
                try
                {
                    table.SetCellContent(row, col, brId);
                }
                catch
                {
                    // Fallback: leave the inserted reference in place if direct assignment is not supported
                }

                tr.Commit();
            }
            catch
            {
                // Rollback happens on dispose if not committed
                throw;
            }
        }
    }

    // Converts a list of EntityGeometry primitives into database entities.
    private static List<Entity> ConvertToEntities(List<EntityGeometry> geometries)
    {
        var result = new List<Entity>(geometries.Count);
        foreach (var g in geometries)
        {
            switch (g)
            {
                case LineGeometry lg:
                    var ln = new Line(new Point3d(lg.Start.X, lg.Start.Y, lg.Start.Z), new Point3d(lg.End.X, lg.End.Y, lg.End.Z));
                    result.Add(ln);
                    break;
                case PolylineGeometry pg:
                    var pl = new Polyline();
                    for (int i = 0; i < pg.Vertices.Count; i++)
                        pl.AddVertexAt(i, new Point2d(pg.Vertices[i].X, pg.Vertices[i].Y), 0, 0, 0);
                    pl.Closed = pg.Closed;
                    result.Add(pl);
                    break;
                case CircleGeometry cg:
                    var cir = new Circle(new Point3d(cg.Center.X, cg.Center.Y, cg.Center.Z), Vector3d.ZAxis, cg.Radius);
                    result.Add(cir);
                    break;
                case ArcGeometry ag:
                    var arc = new Arc(new Point3d(ag.Center.X, ag.Center.Y, ag.Center.Z), ag.Radius, ag.StartAngle, ag.EndAngle);
                    result.Add(arc);
                    break;
                default:
                    // Unsupported type is ignored; could be extended as needed
                    break;
            }
        }
        return result;
    }

    // Appends the given entities to the specified block definition
    private static void AppendEntitiesToBlock(Transaction tr, BlockTableRecord btr, IEnumerable<Entity> entities)
    {
        foreach (var e in entities)
        {
            btr.AppendEntity(e);
            tr.AddNewlyCreatedDBObject(e, true);
        }
    }

    // Computes the extents of a block definition by aggregating contained entity bounds
    private static Extents3d GetBlockExtents(Transaction tr, BlockTableRecord btr)
    {
        bool inited = false;
        Extents3d total = new Extents3d();
        foreach (ObjectId id in btr)
        {
            var ent = tr.GetObject(id, OpenMode.ForRead) as Entity;
            if (ent == null) continue;
            try
            {
                var ext = ent.GeometricExtents;
                if (!inited)
                {
                    total = ext;
                    inited = true;
                }
                else
                {
                    total.AddExtents(ext);
                }
            }
            catch
            {
                // Some entities may not provide extents until database resident; best-effort
            }
        }
        return inited ? total : new Extents3d(new Point3d(0, 0, 0), new Point3d(0, 0, 0));
    }
}

