    rng = ta.tr(true)
    thr = math.max(level * proximityPct * 0.01, nz(rng))
    // close enough if (level - high) within threshold but still below level
    (level - high) <= thr and high < level

f_closeEnoughToLowLevel(level, proximityPct) =>
    rng = ta.tr(true)
    thr = math.max(level * proximityPct * 0.01, nz(rng))
    // close enough if (low - level) within threshold but still above level
    (low - level) <= thr and low > level

