    array.push(activePHIndex, phBarIndex)

if not na(pl)
    array.push(activePL, pl)
    array.push(activePLIndex, plBarIndex)

// Prune very old entries
f_prune(arrF, arrI, maxBars) =>
    for i = array.size(arrI) - 1 to 0
        if bar_index - array.get(arrI, i) > maxBars
            array.remove(arrF, i)
            array.remove(arrI, i)

f_prune(activePH, activePHIndex, lookbackBars)
f_prune(activePL, activePLIndex, lookbackBars)

// Check hits/misses for High pivots
for i = array.size(activePH) - 1 to 0
    lvl = array.get(activePH, i)
    idx = array.get(activePHIndex, i)
    // Hit condition: price trades to/through the pivot level
    isHit = high >= lvl
    // Miss condition heuristic: price moved away enough on downside (close enough but never hit) AND an opposite pivot confirmed after it
    oppPivotAfter = not na(pl) and plBarIndex > idx
    closeEnough = f_closeEnoughToHighLevel(lvl, missThresholdPct)
    isMiss = oppPivotAfter and closeEnough and not isHit
    if isHit or isMiss
        array.remove(activePH, i)
        array.remove(activePHIndex, i)
        if isMiss
            missedPH := true
            missedMsg := "Missed Pivot High @ " + str.tostring(lvl, format.mintick)

// Check hits/misses for Low pivots
for i = array.size(activePL) - 1 to 0
    lvl = array.get(activePL, i)
    idx = array.get(activePLIndex, i)
    isHit = low <= lvl
    oppPivotAfter = not na(ph) and phBarIndex > idx
    closeEnough = f_closeEnoughToLowLevel(lvl, missThresholdPct)
    isMiss = oppPivotAfter and closeEnough and not isHit
    if isHit or isMiss
        array.remove(activePL, i)
        array.remove(activePLIndex, i)
        if isMiss
            missedPL := true
            missedMsg := "Missed Pivot Low @ " + str.tostring(lvl, format.mintick)

//========================
// Plot regular pivots
//========================
plotshape(showRegular and not na(ph), title="Pivot High", style=shape.triangledown, location=location.abovebar, color=colPH, size=size.tiny, text="PH", textcolor=color.white, offset=-right)
plotshape(showRegular and not na(pl), title="Pivot Low",  style=shape.triangleup,   location=location.belowbar, color=colPL, size=size.tiny, text="PL", textcolor=color.white, offset=-right)

// Optional alerts on regular pivots
if alertOnRegular and not na(ph)
    alert("Pivot High confirmed", alert.freq_once_per_bar_close)
if alertOnRegular and not na(pl)
    alert("Pivot Low confirmed", alert.freq_once_per_bar_close)

//========================
// Missed pivot warnings (on-chart) and alerts
//========================
// Show label once at bar close when detected
if warnOnChart and barstate.isconfirmed and (missedPH or missedPL)
    lblTxt = missedMsg + " (bar " + str.tostring(bar_index) + ")"
    label.new(bar_index, close, text=lblTxt, style=label.style_label_down, color=color.new(colMiss, 10), textcolor=color.black)

// Fire alerts when missed events occur
if alertOnMissed and barstate.isconfirmed and missedPH
    alert(missedMsg, alert.freq_once_per_bar_close)
if alertOnMissed and barstate.isconfirmed and missedPL
    alert(missedMsg, alert.freq_once_per_bar_close)

//========================
// Create alertconditions so users can make custom alerts
//========================
alertcondition(not na(ph), title="Pivot High Confirmed", message="Pivot High confirmed")
alertcondition(not na(pl), title="Pivot Low Confirmed",  message="Pivot Low confirmed")
alertcondition(missedPH,   title="Missed Pivot High",    message="Missed Pivot High detected")
alertcondition(missedPL,   title="Missed Pivot Low",     message="Missed Pivot Low detected")

//========================
// Notes:
// - Use Left/Right to control pivot sensitivity.
// - Missed logic is heuristic: considers an opposite pivot confirmation after the original pivot and that price came close without tagging the level.
// - Use the alert conditions in TradingView to create popups, sounds, or webhooks.
//========================

//@version=5
indicator("Pivot High/Low with Missed Pivot Alerts", overlay=true, timeframe="", timeframe_gaps=true)

//==== Inputs ====
leftLen  = input.int(5,  "Left bars",  minval=1)
rightLen = input.int(5,  "Right bars", minval=1)

// Missed pivot settings
missedLookbackBars = input.int(500, "Bars to track missed pivots", minval=50)
maxResolveBars     = input.int(50,  "Max bars to wait for price to touch pivot", minval=1)

// Alert behavior
enableAlerts       = input.bool(true,  "Enable alerts")
alertOnMissedHigh  = input.bool(true,  "Alert on missed pivot highs")
alertOnMissedLow   = input.bool(true,  "Alert on missed pivot lows")

// Plot styling
phColor = input.color(color.new(color.red, 0),   "Pivot High color")
plColor = input.color(color.new(color.lime, 0),  "Pivot Low color")
missedHighColor = input.color(color.new(color.red, 60),  "Missed High line color")
missedLowColor  = input.color(color.new(color.lime, 60), "Missed Low line color")
showLabels = input.bool(true, "Show pivot labels on chart")

//==== Core pivot detection ====
ph = ta.pivothigh(high, leftLen, rightLen)
pl = ta.pivotlow(low,  leftLen, rightLen)

// Bar index helper
var int bi = na
bi := bar_index

//==== Plot regular pivots visibly on the chart ====
// We use plotshape for clear on-bar markers and plot to connect optional series
plotshape(not na(ph), title="Pivot High", style=shape.triangledown, color=phColor, size=size.tiny, location=location.abovebar, offset=-rightLen, text=showLabels ? "PH" : "")
plotshape(not na(pl), title="Pivot Low",  style=shape.triangleup,   color=plColor, size=size.tiny, location=location.belowbar, offset=-rightLen, text=showLabels ? "PL" : "")

//==== Track potential "missed" pivots ====
// Definition used: A pivot is "missed" if, after confirmation (rightLen bars), price has not revisited/touched the pivot price within maxResolveBars bars.
// We will:
// 1) Record confirmed pivot price and the bar it confirmed.
// 2) Over subsequent bars, check if price reaches (>= for lows, <= for highs) the pivot price.
// 3) If not reached within maxResolveBars, raise a missed-pivot alert and draw a warning line.

// Structures to track open (unresolved) pivots
var float[] openHighPrices = array.new_float()
var int[]   openHighBars   = array.new_int()
var line[]  openHighLines  = array.new_line()

var float[] openLowPrices  = array.new_float()
var int[]   openLowBars    = array.new_int()
var line[]  openLowLines   = array.new_line()

f_add_high(pivotPrice, pivotBar) =>
    // Draw a horizontal guide from confirmation bar to present; will extend until resolved/expired
    l = line.new(x1=pivotBar, y1=pivotPrice, x2=bar_index, y2=pivotPrice, extend=extend.right, color=missedHighColor, width=1, style=line.style_dashed)
    array.push(openHighPrices, pivotPrice)
    array.push(openHighBars,   pivotBar)
    array.push(openHighLines,  l)

f_add_low(pivotPrice, pivotBar) =>
    l = line.new(x1=pivotBar, y1=pivotPrice, x2=bar_index, y2=pivotPrice, extend=extend.right, color=missedLowColor, width=1, style=line.style_dashed)
    array.push(openLowPrices, pivotPrice)
    array.push(openLowBars,   pivotBar)
    array.push(openLowLines,  l)

f_update_lines() =>
    // Keep visual lines extended forward each bar
    for i = 0 to array.size(openHighLines) - 1
        ln = array.get(openHighLines, i)
        line.set_x2(ln, bar_index)
        line.set_y2(ln, line.get_y1(ln))
    for i = 0 to array.size(openLowLines) - 1
        ln = array.get(openLowLines, i)
        line.set_x2(ln, bar_index)
        line.set_y2(ln, line.get_y1(ln))

// On confirmation bars, register new pivots to track
if not na(ph)
    // ph is at bar index (bar_index - rightLen)
    confirmedBar = bar_index - rightLen
    confirmedPrice = high[rightLen]
    f_add_high(confirmedPrice, confirmedBar)

if not na(pl)
    confirmedBar = bar_index - rightLen
    confirmedPrice = low[rightLen]
    f_add_low(confirmedPrice, confirmedBar)

// Resolve or expire open pivots
var bool missedHighTriggered = false
var bool missedLowTriggered  = false
missedHighTriggered := false
missedLowTriggered  := false

// Iterate highs backward so removals are safe
for i = array.size(openHighPrices) - 1 to 0
    p  = array.get(openHighPrices, i)
    b0 = array.get(openHighBars,   i)
    ln = array.get(openHighLines,  i)

    // Price revisits/touches pivot high when high >= pivot price
    touched = high >= p
    age = bar_index - b0

    if touched
        // Resolved: remove tracking and line
        line.delete(ln)
        array.remove(openHighPrices, i)
        array.remove(openHighBars,   i)
        array.remove(openHighLines,  i)
    else if age > maxResolveBars
        // Missed pivot high
        missedHighTriggered := true
        // Keep the line as visual warning but stop tracking so we don't alert repeatedly
        array.remove(openHighPrices, i)
        array.remove(openHighBars,   i)
        array.remove(openHighLines,  i)

for i = array.size(openLowPrices) - 1 to 0
    p  = array.get(openLowPrices, i)
    b0 = array.get(openLowBars,   i)
    ln = array.get(openLowLines,  i)

    // Price revisits/touches pivot low when low <= pivot price
    touched = low <= p
    age = bar_index - b0

    if touched
        line.delete(ln)
        array.remove(openLowPrices, i)
        array.remove(openLowBars,   i)
        array.remove(openLowLines,  i)
    else if age > maxResolveBars
        missedLowTriggered := true
        array.remove(openLowPrices, i)
        array.remove(openLowBars,   i)
        array.remove(openLowLines,  i)

// Maintain line extensions
f_update_lines()

//==== Alerts ====
// We use alertcondition() as required. Conditions are gated by enable flags to avoid noise.
alertcondition(enableAlerts and alertOnMissedHigh and missedHighTriggered, title="Missed Pivot High", message="A pivot high was not revisited within the maximum wait bars.")
alertcondition(enableAlerts and alertOnMissedLow  and missedLowTriggered,  title="Missed Pivot Low",  message="A pivot low was not revisited within the maximum wait bars.")

// Optional on-chart warnings when a missed pivot occurs (labels)
if missedHighTriggered and showLabels
    label.new(bar_index, high, text="Missed PH", style=label.style_label_down, color=color.new(color.red, 0), textcolor=color.white)
if missedLowTriggered and showLabels
    label.new(bar_index, low,  text="Missed PL", style=label.style_label_up,   color=color.new(color.green, 0), textcolor=color.white)

//==== Notes ====
// - Regular pivots are marked with triangle shapes offset by rightLen so that markers align with the actual pivot bar.
// - Missed pivots are lines that extend to the right from the pivot price; they remain as visual warnings even after alerting.
// - Use TradingView's "Create Alert" on this script and choose the specific alert(s) to receive notifications.
// - Adjust left/right lengths, maxResolveBars, and alert toggles to suit your strategy.

//@version=5
indicator("Pivot High/Low with Missed Retest Alerts (v5)", overlay=true, max_labels_count=500)

//=========================
// Inputs
//=========================
grpPivot   = "Pivot Settings"
leftLen    = input.int(3,  "Left length",  minval=1, maxval=100, group=grpPivot)
rightLen   = input.int(3,  "Right length", minval=1, maxval=100, group=grpPivot)
showPH     = input.bool(true,  "Show Pivot Highs", group=grpPivot)
showPL     = input.bool(true,  "Show Pivot Lows",  group=grpPivot)
phColor    = input.color(color.red,   "Pivot High Color", group=grpPivot)
plColor    = input.color(color.lime,  "Pivot Low Color",  group=grpPivot)
phSize     = input.string("Large", "Pivot High Marker Size", options=["Small","Normal","Large","Huge"], group=grpPivot)
plSize     = input.string("Large", "Pivot Low Marker Size",  options=["Small","Normal","Large","Huge"], group=grpPivot)

// Missed pivot settings
grpMissed  = "Missed Pivot Settings"
missedEnableHigh = input.bool(true,  "Enable Missed Pivot High Alerts", group=grpMissed)
missedEnableLow  = input.bool(true,  "Enable Missed Pivot Low Alerts",  group=grpMissed)
retestBars       = input.int(20, "Retest Window (bars)", minval=1, maxval=500, group=grpMissed)
retestTolPct     = input.float(0.25, "Retest Tolerance (%)", minval=0.0, maxval=5.0, step=0.05, group=grpMissed)
showMissedLabels = input.bool(true, "Show Missed Pivot Labels", group=grpMissed)
missedHighColor  = input.color(color.orange, "Missed Pivot High Label Color", group=grpMissed)
missedLowColor   = input.color(color.aqua,   "Missed Pivot Low Label Color",  group=grpMissed)

//=========================
// Helper: convert marker size
//=========================
sizeFromString(sz) => switch sz
    "Small"  => size.tiny
    "Normal" => size.small
    "Large"  => size.normal
    => size.large

phPlotSize = sizeFromString(phSize)
plPlotSize = sizeFromString(plSize)

//=========================
// Pivot detection (confirmed pivots)
//=========================
ph = ta.pivothigh(high, leftLen, rightLen)
pl = ta.pivotlow(low,  leftLen, rightLen)

// Plot pivot markers at confirmed pivot bar (offset by -rightLen)
if showPH and not na(ph)
    plotshape(ph, title="Pivot High", style=shape.triangledown, color=phColor, location=location.abovebar, offset=-rightLen, size=phPlotSize, text="PH")
if showPL and not na(pl)
    plotshape(pl, title="Pivot Low", style=shape.triangleup,   color=plColor, location=location.belowbar, offset=-rightLen, size=plPlotSize, text="PL")

//=========================
// Missed pivot tracking
// Definition: A pivot is "missed" if price fails to retest the pivot level
// within `retestBars` bars with tolerance `retestTolPct`.
//=========================
var float   lastPHVal      = na
var int     lastPHBarIndex = na
var bool    lastPHRetested = true

var float   lastPLVal      = na
var int     lastPLBarIndex = na
var bool    lastPLRetested = true

// On new confirmed pivot, record it and reset retest flag
if not na(ph)
    lastPHVal      := ph
    lastPHBarIndex := bar_index - rightLen
    lastPHRetested := false

if not na(pl)
    lastPLVal      := pl
    lastPLBarIndex := bar_index - rightLen
    lastPLRetested := false

// Compute tolerance bands
float tol = retestTolPct / 100.0

// Retest checks (while window still open)
// For pivot high: consider retested if high returns within tolerance band at or below pivot price.
// We'll use: high >= lastPHVal * (1 - tol)
bool phWindowOpen = not na(lastPHBarIndex) and (bar_index - lastPHBarIndex) <= retestBars
if phWindowOpen and not lastPHRetested and not na(lastPHVal)
    if high >= lastPHVal * (1 - tol)
        lastPHRetested := true

// For pivot low: consider retested if low returns within tolerance band at or above pivot price.
// We'll use: low <= lastPLVal * (1 + tol)
bool plWindowOpen = not na(lastPLBarIndex) and (bar_index - lastPLBarIndex) <= retestBars
if plWindowOpen and not lastPLRetested and not na(lastPLVal)
    if low <= lastPLVal * (1 + tol)
        lastPLRetested := true

// Determine missed conditions exactly when the window just closed
bool phWindowJustClosed = not na(lastPHBarIndex) and (bar_index - lastPHBarIndex) == retestBars
bool plWindowJustClosed = not na(lastPLBarIndex) and (bar_index - lastPLBarIndex) == retestBars

missedPH = phWindowJustClosed and not lastPHRetested
missedPL = plWindowJustClosed and not lastPLRetested

//=========================
// Chart labels for missed pivots (optional)
//=========================
if showMissedLabels and missedPH
    label.new(lastPHBarIndex, lastPHVal, text="Missed PH", style=label.style_label_down, color=missedHighColor, textcolor=color.black)
if showMissedLabels and missedPL
    label.new(lastPLBarIndex, lastPLVal, text="Missed PL", style=label.style_label_up,   color=missedLowColor,  textcolor=color.black)

//=========================
// Alerts (input-controlled via enable toggles)
// The toggles are embedded in the conditions so the same alert can stay active.
//=========================
alertcondition(missedEnableHigh and missedPH, title="Missed Pivot High", message="Missed Pivot High: no retest within window.")
alertcondition(missedEnableLow  and missedPL, title="Missed Pivot Low",  message="Missed Pivot Low: no retest within window.")

// Optional visual guides: plot pivot levels when active (helps understand retest window)
showGuides = input.bool(false, "Show Active Pivot Guide Lines", group=grpMissed)
var line phGuide = na
var line plGuide = na

// Update/cleanup guide lines for PH
if not na(ph)
    if showGuides
        line.delete(phGuide)
        phGuide := line.new(x1=lastPHBarIndex, y1=lastPHVal, x2=lastPHBarIndex + retestBars, y2=lastPHVal, extend=extend.none, color=color.new(missedHighColor, 60), style=line.style_dotted)
    else
        line.delete(phGuide)

// Update/cleanup guide lines for PL
if not na(pl)
    if showGuides
        line.delete(plGuide)
        plGuide := line.new(x1=lastPLBarIndex, y1=lastPLVal, x2=lastPLBarIndex + retestBars, y2=lastPLVal, extend=extend.none, color=color.new(missedLowColor, 60), style=line.style_dotted)
    else
        line.delete(plGuide)

// Notes for users (commented for reference):
// - leftLen/rightLen control pivot sensitivity and confirmation delay.
// - Create TradingView alerts using the two alert conditions in this script.
// - Use the enable toggles to turn missed-pivot alerts on/off without editing alert rules.

//@version=5
indicator("Pivot High/Low with Missed Retest Alerts", overlay=true, max_labels_count=500, max_lines_count=500)

// =========================
// Inputs
// =========================
leftLen  = input.int(5,  "Left bars",  minval=1)
rightLen = input.int(5,  "Right bars", minval=1)

// Missed retest alert settings
enableMissedRetestAlerts = input.bool(true,  "Enable missed pivot retest alerts")
retestWindowBars         = input.int(50,    "Retest window (bars)", minval=1)
retestTolerance          = input.float(0.25, "Retest tolerance (in ticks or price units)", minval=0.0)
useTicks                 = input.bool(true,  "Tolerance is in ticks (otherwise price)")

// Visual options
showPivotLabels = input.bool(true,  "Show pivot labels")
showPivotPlots  = input.bool(true,  "Show pivot plot shapes")
colorPH         = input.color(color.new(color.red, 0),   "Pivot High color")
colorPL         = input.color(color.new(color.lime, 0),  "Pivot Low color")
missedPHColor   = input.color(color.new(color.fuchsia, 0), "Missed PH marker color")
missedPLColor   = input.color(color.new(color.aqua, 0),    "Missed PL marker color")

// =========================
// Helpers
// =========================
tickSize = syminfo.mintick
_tol(float price) => useTicks ? retestTolerance * tickSize : retestTolerance

// Pivot calculations
ph = ta.pivothigh(high, leftLen, rightLen)
pl = ta.pivotlow(low,  leftLen, rightLen)

isPH = not na(ph)
isPL = not na(pl)

// =========================
// Track last confirmed pivots
// We store the price and the bar_index when the pivot confirmed
var float lastPHPrice = na
var int   lastPHBar   = na
var float lastPLPrice = na
var int   lastPLBar   = na

if isPH
    lastPHPrice := ph
    lastPHBar   := bar_index - rightLen  // pivot confirmation bar index

if isPL
    lastPLPrice := pl
    lastPLBar   := bar_index - rightLen

// =========================
// Retest detection within window and tolerance
// For a pivot high, a retest happens when price trades back up to within tolerance of the pivot price.
// For a pivot low, a retest happens when price trades back down to within tolerance of the pivot price.
phActiveInWindow = not na(lastPHBar) and (bar_index - lastPHBar) <= retestWindowBars
plActiveInWindow = not na(lastPLBar) and (bar_index - lastPLBar) <= retestWindowBars

phTol = _tol(lastPHPrice)
plTol = _tol(lastPLPrice)

// Retest conditions (intrabar):
// We consider a retest satisfied if the bar's high (for PH) or low (for PL) touches the tolerance band.
phRetested = phActiveInWindow and not na(lastPHPrice) and high >= (lastPHPrice - phTol)
plRetested = plActiveInWindow and not na(lastPLPrice) and low  <= (lastPLPrice + plTol)

// Missed retest: when window just expired without a retest
phWindowExpiredNow = phActiveInWindow and (bar_index - lastPHBar) == retestWindowBars
plWindowExpiredNow = plActiveInWindow and (bar_index - lastPLBar) == retestWindowBars

missedPH = phWindowExpiredNow and not phRetested
missedPL = plWindowExpiredNow and not plRetested

// =========================
// Plot/labels for regular pivots
if showPivotPlots
    plotshape(isPH, title="Pivot High", style=shape.triangledown, color=colorPH, location=location.abovebar, size=size.tiny, offset=-rightLen)
    plotshape(isPL, title="Pivot Low",  style=shape.triangleup,   color=colorPL, location=location.belowbar, size=size.tiny, offset=-rightLen)

if showPivotLabels
    if isPH
        label.new(bar_index - rightLen, ph, text="PH", color=color.new(colorPH, 80), textcolor=color.white, style=label.style_label_down)
    if isPL
        label.new(bar_index - rightLen, pl, text="PL", color=color.new(colorPL, 80), textcolor=color.white, style=label.style_label_up)

// Optional visible markers when a missed retest is detected at window expiry
if missedPH
    label.new(bar_index, lastPHPrice, text="Missed PH retest\nwindow expired", color=color.new(missedPHColor, 70), textcolor=color.white, style=label.style_label_down)
if missedPL
    label.new(bar_index, lastPLPrice, text="Missed PL retest\nwindow expired", color=color.new(missedPLColor, 70), textcolor=color.white, style=label.style_label_up)

// =========================
// Alerts
// User-toggleable alertconditions; wire inputs into logic
alertcondition(enableMissedRetestAlerts and missedPH, title="Missed Pivot High Retest", message="Missed retest of Pivot High at {{ticker}} price {{close}}; pivot {{plot("Pivot High")}} within window {{input:retestWindowBars}} and tolerance {{input:retestTolerance}}")
alertcondition(enableMissedRetestAlerts and missedPL, title="Missed Pivot Low Retest",  message="Missed retest of Pivot Low at {{ticker}} price {{close}}; pivot {{plot("Pivot Low")}} within window {{input:retestWindowBars}} and tolerance {{input:retestTolerance}}")

// Inline chart warnings when pivots identified (regular pivots)
var label phWarn = na
var label plWarn = na
if isPH
    phWarn := label.new(bar_index - rightLen, ph, text="Pivot High identified", style=label.style_label_down, color=color.new(color.orange, 70), textcolor=color.white)
if isPL
    plWarn := label.new(bar_index - rightLen, pl, text="Pivot Low identified",  style=label.style_label_up,   color=color.new(color.orange, 70), textcolor=color.white)

// =========================
// Notes (comments):
// - leftLen/rightLen control pivot swing sensitivity.
// - enableMissedRetestAlerts toggles alerts created by the two alertcondition() calls above.
// - retestWindowBars sets how many bars after a pivot confirmation we wait for a retest.
// - retestTolerance sets how close price must come to the pivot price to qualify as a retest.
// - If useTicks is true, tolerance is measured in ticks; otherwise, it is raw price units.
// - Alerts will only fire at the bar where the window expires without a qualifying retest.

Below is a complete, runnable MATLAB example that:

- Generates a binary order-1 Markov source
- Encodes it with a context-adaptive binary arithmetic coder (order-k contexts with adaptive counts)
- Transmits the compressed bitstream through a Binary Symmetric Channel (BSC)
- Decodes on the receiver side with the same adaptive model
- Computes the BER between the original and decoded sequences

Note: Arithmetic coding is extremely sensitive to bit errors; even a single flipped bit often causes catastrophic decoding error propagation. This script still demonstrates the full pipeline as requested.

Copy the entire block into a new MATLAB script file (e.g., demo_ca_ac_bsc.m) and run.

% demo_ca_ac_bsc.m
% Context-adaptive arithmetic coding (binary), BSC channel, and BER in MATLAB.

function demo_ca_ac_bsc
    clc; clear; rng(0);  % Reproducible

    % Parameters
    N = 2000;              % Number of source bits
    P = [0.95, 0.05;       % Transition matrix P(x_t | x_{t-1})
         0.10, 0.90];      % rows = prev state (0/1), cols = next state (0/1)
    p1_init = 0.5;         % Initial probability for state 1 at t=1
    ctx_order = 2;         % Context order (number of previous bits used)
    bsc_p = 0.02;          % Bit-flip probability in BSC

    % 1) Generate Markov source (binary)
    x = gen_markov_binary(N, P, p1_init);

    % 2) Context-adaptive arithmetic encode (binary)
    %    Uses order-k contexts with adaptive integer counts and Laplace(1) smoothing
    [code_bits, enc_state] = ca_arith_encode_binary(x, ctx_order);

    % 3) Transmit through Binary Symmetric Channel (BSC)
    rx_bits = bsc(code_bits, bsc_p);

    % 4) Decode using same adaptive model
    %    Note: Any bit error in codeword may cause large decode errors.
    x_hat = ca_arith_decode_binary(rx_bits, length(x), ctx_order, enc_state.init_ctx);

    % 5) Compute BER
    ber = mean(x ~= x_hat);

    % Report
    fprintf('Original length: %d bits\n', numel(x));
    fprintf('Encoded length:  %d bits\n', numel(code_bits));
    fprintf('BSC p:           %.4f\n', bsc_p);
    fprintf('BER (decoded vs original): %.6f\n', ber);
end

function x = gen_markov_binary(N, P, p1_init)
    % P: 2x2, rows are prev state (0/1 -> 1/2), cols are next state (0/1 -> 1/2)
    x = zeros(1, N);
    x(1) = rand < p1_init;
    for t = 2:N
        prev = x(t-1) + 1;
        p1 = P(prev, 2);
        x(t) = rand < p1;
    end
end

function [bits, state] = ca_arith_encode_binary(x, k)
    % Context-adaptive binary arithmetic encoder with order-k contexts.
    % Uses range coding-like integer arithmetic for robustness in MATLAB.
    % Returns serialized bits as uint8 vector of 0/1.

    % Model state: counts for each context (2^k contexts, symbols {0,1})
    num_ctx = 2^k;
    counts = ones(num_ctx, 2); % Laplace smoothing: start with [1,1]

    % Arithmetic coder state (integer range coder)
    low = uint64(0);
    range = uint64(2^32 - 1); % 32-bit range
    out_bytes = uint8([]);

    % Initial context from first k bits (use zeros before start)
    init_ctx = 0;
    ctx = init_ctx;

    for i = 1:numel(x)
        % Get probabilities from counts
        c0 = double(counts(ctx+1,1));
        c1 = double(counts(ctx+1,2));
        tot = c0 + c1;
        r = uint64(floor(double(range) / tot));
        if x(i) == 0
            range = uint64(r * c0);
        else
            low   = low + uint64(r * c0);
            range = uint64(r * c1);
        end

        % Renormalize (byte output when range small)
        while range <= uint64(2^24-1)
            range = bitshift(range, 8);
            out_bytes(end+1) = uint8(bitshift(low, -24)); %#ok<AGROW>
            low = bitand(bitshift(low, 8), uint64(2^32-1));
        end

        % Update model
        if x(i) == 0
            counts(ctx+1,1) = counts(ctx+1,1) + 1;
        else
            counts(ctx+1,2) = counts(ctx+1,2) + 1;
        end

        % Update context (shift in current bit)
        if k > 0
            ctx = bitand(bitshift(ctx,1) + x(i), num_ctx-1);
        end
    end

    % Finalization: push 4 bytes to disambiguate final interval
    for n = 1:4 %#ok<NASGU>
        out_bytes(end+1) = uint8(bitshift(low, -24)); %#ok<AGROW>
        low = bitand(bitshift(low, 8), uint64(2^32-1));
    end

    % Pack bytes into bits (MSB-first per byte)
    bits = uint8(zeros(1, numel(out_bytes)*8));
    idx = 1;
    for b = 1:numel(out_bytes)
        byte = out_bytes(b);
        for m = 7:-1:0
            bits(idx) = bitget(byte, m+1);
            idx = idx + 1;
        end
    end

    % Return encoder state needed to init decoder context
    state.init_ctx = init_ctx;
end

function x = ca_arith_decode_binary(bits, N, k, init_ctx)
    % Inverse of encoder. Consumes bits packed MSB-first per byte.

    % Re-pack bits into bytes
    nb = ceil(numel(bits)/8);
    in_bytes = uint8(zeros(1, nb));
    idx = 1;
    for b = 1:nb
        val = uint8(0);
        for m = 7:-1:0
            if idx <= numel(bits)
                val = bitor(bitshift(val,1), uint8(bits(idx))); idx = idx + 1;
            else
                val = bitshift(val,1);
            end
        end
        in_bytes(b) = val;
    end

    % Model
    num_ctx = 2^k;
    counts = ones(num_ctx, 2);

    % Range coder state
    low = uint64(0);
    range = uint64(2^32 - 1);
    code = uint64(0);
    rd = 1;

    % Prime code with first 4 bytes (as emitted by encoder)
    for n = 1:4
        code = bitor(bitshift(code,8), uint64(get_byte()));
    end

    x = zeros(1, N, 'uint8');
    ctx = init_ctx;

    for i = 1:N
        c0 = double(counts(ctx+1,1));
        c1 = double(counts(ctx+1,2));
        tot = c0 + c1;

        r = uint64(floor(double(range) / tot));
        split = low + uint64(r * c0);

        if code < split
            sym = 0;
            range = uint64(r * c0);
        else
            sym = 1;
            low   = split;
            range = uint64(r * c1);
        end

        % Renormalize
        while range <= uint64(2^24-1)
            range = bitshift(range, 8);
            low   = bitand(bitshift(low, 8), uint64(2^32-1));
            code  = bitor(bitand(bitshift(code, 8), uint64(2^32-1)), uint64(get_byte()));
        end

        x(i) = uint8(sym);

        % Update model
        if sym == 0
            counts(ctx+1,1) = counts(ctx+1,1) + 1;
        else
            counts(ctx+1,2) = counts(ctx+1,2) + 1;
        end

        % Update context
        if k > 0
            ctx = bitand(bitshift(ctx,1) + sym, num_ctx-1);
        end
    end

    function b = get_byte()
        if rd <= numel(in_bytes)
            b = in_bytes(rd); rd = rd + 1;
        else
            b = uint8(0);
        end
    end
end

function y = bsc(x, p)
    % Binary Symmetric Channel: flip each bit with probability p
    flips = rand(size(x)) < p;
    y = bitxor(uint8(x), uint8(flips));
end

Copy everything below into a single file named demo_ca_ac_bsc.m and run it. It includes the Markov source, context-adaptive binary arithmetic encoder/decoder, BSC simulation, BER calculation, and all helper subfunctions in one runnable MATLAB script.

function demo_ca_ac_bsc
    clc; clear; close all; rng(0);

    % Parameters
    N = 2000;                 % Number of source bits
    P = [0.95, 0.05;          % Transition matrix P(next | prev): rows=prev(0,1), cols=next(0,1)
         0.10, 0.90];
    p0 = 0.5;                 % Initial prob of state 1
    ctx_order = 2;            % Context order for CABAC-style adaptive model
    bsc_p = 0.01;             % BSC crossover probability

    % 1) Generate Markov source bits
    x = markov_source_binary(N, P, p0);

    % 2) Context-adaptive binary arithmetic encode
    [code_bits, enc_state] = cabac_encode(x, ctx_order);

    % 3) Transmit through BSC (to demonstrate error sensitivity)
    y = bsc(code_bits, bsc_p);

    % 4) Context-adaptive binary arithmetic decode
    % NOTE: With channel errors, arithmetic decoding may desynchronize.
    % For a clean reconstruction, set bsc_p=0. Here we still run to show BER impact.
    [x_hat, dec_ok] = cabac_decode(y, ctx_order);

    % 5) Compute BER (lengths might mismatch if desync happens)
    L = min(length(x), length(x_hat));
    if L == 0
        ber = NaN;
    else
        ber = mean(x(1:L) ~= x_hat(1:L));
    end

    fprintf('Encoded length: %d bits (from %d source bits)\n', length(code_bits), length(x));
    fprintf('Decode status: %s\n', string(dec_ok));
    fprintf('BER over %d aligned bits: %g (BSC p=%g)\n', L, ber, bsc_p);

    % Optional quick plots
    figure('Name','Lengths'); bar([length(x) length(code_bits)]); grid on;
    set(gca,'XTickLabel',{'Source','Encoded'}); ylabel('Bits'); title('Compression Lengths');
end

% ======================= Helper subfunctions =======================

function x = markov_source_binary(N, P, p1_init)
% Generate a binary first-order Markov sequence of length N.
% P: 2x2 transition matrix: rows = prev state (0,1) +1 indexing; cols = next (0,1) +1.
    x = zeros(1,N,'uint8');
    x(1) = rand < p1_init; % initial state 1 probability
    for t = 2:N
        prev = x(t-1);
        % Map states {0,1} to indices {1,2}
        pr1 = P(prev+1,2);           % P(next=1 | prev)
        x(t) = rand < pr1;           % draw next bit
    end
end

function [bits, model] = cabac_encode(x, k)
% Binary context-adaptive arithmetic encoder (order-k contexts, adaptive counts)
% Returns a binary bitstream (row vector uint8 of 0/1) and final model.
    if nargin < 2, k = 2; end
    % Initialize range coder state
    low = uint64(0);
    range = uint64(2^32 - 1);   % 32-bit range coder
    pending_bits = 0;
    out = false(1, 0);          % dynamic logical array for bits

    % Adaptive context model: for each context, maintain counts [n0 n1]
    C = 2^k;
    counts = ones(C,2,'uint32'); % start with [1 1] Laplace smoothing

    % Emit a simple header for decoder: ctx order (k) and source length
    out = append_bits(out, uint32_to_bits(uint32(k)));
    out = append_bits(out, uint32_to_bits(uint32(length(x))));

    % Helper to output a bit with pending carry propagation
    function flush_bit(b)
        out = append_bits(out, b);
        while pending_bits > 0
            out = append_bits(out, ~b); % opposite bits
            pending_bits = pending_bits - 1;
        end
    end

    % Main encoding loop
    for i = 1:length(x)
        ctx = context_index(x, i-1, k); % based on past bits
        n0 = double(counts(ctx,1)); n1 = double(counts(ctx,2));
        total = n0 + n1;
        % probability of 0 scaled to range
        % We'll use cumulative: cum0 = 0, cum1 = n0, total = n0+n1
        scaled = uint64(floor((double(range) * n0) / total));
        if x(i) == 0
            range = scaled; % [low, low+scaled)
        else
            low = low + scaled; % [low+scaled, low+range)
            range = range - scaled;
        end

        % Renormalize while range is small
        while range <= uint64(2^24)
            if bitshift(bitand(low, uint64(2^31)), -31) == bitshift(bitand(low+range-1, uint64(2^31)), -31)
                % MSB equal -> output that bit
                b = logical(bitshift(low, -31));
                flush_bit(b);
                low = bitshift(bitand(low, uint64(2^31-1)), 1);
                range = bitshift(range, 1);
            elseif bitand(low, uint64(2^30)) && ~bitand(low+range-1, uint64(2^30))
                % Underflow (E3) condition
                pending_bits = pending_bits + 1;
                low = bitshift(bitand(low, uint64(2^30-1)), 1);
                range = bitshift(range, 1);
                low = bitor(low, uint64(2^0)); % toggle after E3
            else
                break;
            end
        end

        % Update counts (adaptive)
        if x(i) == 0
            counts(ctx,1) = counts(ctx,1) + 1;
        else
            counts(ctx,2) = counts(ctx,2) + 1;
        end
        % Optional rescaling to avoid overflow
        if counts(ctx,1) + counts(ctx,2) > 1e6
            counts(ctx,:) = max(1, floor(double(counts(ctx,:))/2));
        end
    end

    % Finalization: push out MSBs
    for r = 1:33
        b = logical(bitshift(low, -31));
        flush_bit(b);
        low = bitshift(bitand(low, uint64(2^31-1)), 1);
    end

    bits = uint8(out);
    model.counts = counts; %#ok<NASGU>
end

function [x, ok] = cabac_decode(bits, k)
% Binary context-adaptive arithmetic decoder matching cabac_encode
    ok = true;
    if isempty(bits), x = uint8([]); ok = false; return; end

    % Read header
    [k_rd, idx] = bits_to_uint32(bits, 1);
    [N, idx]   = bits_to_uint32(bits, idx);
    if nargin >= 2 && k ~= k_rd
        % Decoder given k overrides header for robustness; but warn
        k = k_rd; % keep in sync
    end

    % Initialize model
    C = 2^k;
    counts = ones(C,2,'uint32');

    % Initialize range coder state
    low = uint64(0);
    range = uint64(2^32 - 1);

    % Load initial code value from next 32 bits (or as many as available)
    code = uint64(0);
    for t = 1:32
        if idx <= numel(bits)
            code = bitor(bitshift(code,1), uint64(bits(idx))); idx = idx + 1;
        else
            code = bitshift(code,1); % pad zeros
        end
    end

    x = zeros(1, double(N), 'uint8');

    for i = 1:N
        ctx = context_index(x, i-1, k);
        n0 = double(counts(ctx,1)); n1 = double(counts(ctx,2));
        total = n0 + n1;
        scaled = uint64(floor((double(range) * n0) / total));

        if code - low < scaled
            % symbol 0
            range = scaled;
            sym = uint8(0);
        else
            low = low + scaled;
            range = range - scaled;
            sym = uint8(1);
        end

        % Renormalize
        renorm_iter = 0;
        while range <= uint64(2^24)
            renorm_iter = renorm_iter + 1;
            if bitshift(bitand(low, uint64(2^31)), -31) == bitshift(bitand(low+range-1, uint64(2^31)), -31)
                % MSB equal
                bmsb = bitshift(low, -31);
                low  = bitshift(bitand(low, uint64(2^31-1)), 1);
                range = bitshift(range, 1);
                % shift in next bit from stream
                if idx <= numel(bits)
                    nextb = uint64(bits(idx)); idx = idx + 1;
                else
                    nextb = uint64(0);
                end
                code = bitor(bitshift(bitand(code, uint64(2^31-1)), 1), nextb);
                %#ok<NASGU>
            elseif bitand(low, uint64(2^30)) && ~bitand(low+range-1, uint64(2^30))
                % Underflow (E3)
                low  = bitshift(bitand(low, uint64(2^30-1)), 1);
                range = bitshift(range, 1);
                if idx <= numel(bits)
                    nextb = uint64(bits(idx)); idx = idx + 1;
                else
                    nextb = uint64(0);
                end
                code = bitor(bitshift(bitand(code, uint64(2^30-1)), 1), nextb);
                low = bitor(low, uint64(2^0));
            else
                break;
            end
            if renorm_iter > 10^7, ok = false; break; end
        end
        if ~ok, break; end

        x(i) = sym;
        % Update counts
        if sym == 0
            counts(ctx,1) = counts(ctx,1) + 1;
        else
            counts(ctx,2) = counts(ctx,2) + 1;
        end
        if counts(ctx,1) + counts(ctx,2) > 1e6
            counts(ctx,:) = max(1, floor(double(counts(ctx,:))/2));
        end
    end
end

function idx = context_index(seq, pos, k)
% Return context index in 1..2^k based on last k bits before position pos
    if k == 0 || pos == 0
        idx = 1; return;
    end
    m = min(k, pos);
    ctx_val = 0;
    for j = 1:m
        ctx_val = bitor(bitshift(ctx_val,1), uint32(seq(pos-j+1)));
    end
    % If fewer than k bits available, left-pad zeros
    ctx_val = bitshift(ctx_val, k - m);
    idx = double(ctx_val) + 1;
end

function y = bsc(x, p)
% Binary Symmetric Channel: flip each bit with prob p
    flips = rand(size(x)) < p;
    y = xor(logical(x), flips);
    y = uint8(y);
end

function bits = uint32_to_bits(u)
% Big-endian 32 bits
    bits = false(1,32);
    for i = 1:32
        bits(i) = bitget(u, 33-i);
    end
    bits = uint8(bits);
end

function [u, idx_out] = bits_to_uint32(bits, idx)
% Read big-endian 32 bits starting at idx (1-based). Pads with zeros if needed.
    val = uint32(0);
    for i = 1:32
        b = 0;
        if idx <= numel(bits)
            b = bits(idx);
        end
        val = bitor(bitshift(val,1), uint32(b~=0));
        idx = idx + 1;
    end
    u = val;
    idx_out = idx;
end

function out = append_bits(out, b)
% Append logical/uint8 vector b to logical vector out
    if isa(b,'logical')
        bb = b;
    else
        bb = logical(b ~= 0);
    end
    out = [out, bb]; %#ok<AGROW>
end

function demo_markov_caac_bsc
% demo_markov_caac_bsc
% Complete, runnable MATLAB script implementing:
% - Binary Markov source
% - Context-adaptive binary arithmetic encoder and matching decoder (order-k)
% - Binary Symmetric Channel (BSC) transmission
% - BER calculation
% No toolboxes required. Encoder/decoder share the same adaptive context model.

    clc; clear; rng(0);

    % Parameters
    N = 2000;                 % number of source bits
    P = [0.95 0.05;           % Markov transition matrix: rows=prev(0/1), cols=next(0/1)
         0.10 0.90];
    p1_init = 0.5;            % Pr(x1=1)
    ctx_order = 2;            % context order k (use previous k bits)
    bsc_p = 1e-5;             % bit-flip probability on the channel

    % 1) Generate binary Markov source
    x = gen_markov_binary(N, P, p1_init);

    % 2) Context-adaptive arithmetic encode (binary) -> compressed bitstream
    encCfg.prec = 32;   % arithmetic coder precision in bits
    encCfg.min_range = uint64(1); % minimum range to avoid collapse
    [bitstream, encSideInfo] = caac_encode_binary(x, ctx_order, encCfg);

    % 3) Transmit through BSC
    rx_bitstream = bsc(bitstream, bsc_p);

    % 4) Decode using matching CA-AC model
    [x_hat, success] = caac_decode_binary(rx_bitstream, numel(x), ctx_order, encCfg);

    % 5) BER against the original source bits
    if ~success
        warning('Decoder reported failure (likely due to channel errors corrupting the arithmetic code).');
    end
    ber = mean(x ~= x_hat);

    % Report
    comp_ratio = numel(x) / numel(bitstream);
    fprintf('Source length: %d bits\n', N);
    fprintf('Encoded length: %d bits\n', numel(bitstream));
    fprintf('Compression ratio (orig/enc): %.3f\n', comp_ratio);
    fprintf('BSC flip prob: %.2e\n', bsc_p);
    fprintf('Decoder success flag: %d\n', success);
    fprintf('BER (source vs decoded): %.3g\n', ber);

end

% ===================== Subfunctions =====================
function x = gen_markov_binary(N, P, p1_init)
% Generate a binary Markov source of length N given transition matrix P.
% P(prev+1, next+1) = Pr(x_t = next | x_{t-1} = prev)
    x = false(1, N);
    x(1) = rand < p1_init;
    for t = 2:N
        prev = x(t-1);
        p_next1 = P(prev+1, 2);
        x(t) = rand < p_next1;
    end
end

function bits_out = bsc(bits_in, p)
% Binary symmetric channel: flips each bit with probability p.
    if p <= 0
        bits_out = bits_in; return;
    end
    flips = rand(size(bits_in)) < p;
    bits_out = xor(bits_in, flips);
end

function [bitstream, side] = caac_encode_binary(x, k, cfg)
% Context-adaptive binary arithmetic encoder (order-k contexts).
% - x: logical row vector of source bits
% - k: context order (0..)
% - cfg: struct with fields prec (<= 64), min_range (uint64)
% Returns:
% - bitstream: logical row vector of compressed bits
% - side: struct (reserved; not required for decoding in this self-contained demo)

    assert(islogical(x) && isrow(x), 'x must be a logical row vector');
    if nargin < 2, k = 0; end
    if nargin < 3 || ~isfield(cfg,'prec'), cfg.prec = 32; end
    if ~isfield(cfg,'min_range'), cfg.min_range = uint64(1); end
    prec = cfg.prec;
    assert(prec >= 8 && prec <= 64);

    Top = uint64(2^prec - 1);
    Half = bitshift(Top+1, -1);  % 2^(prec-1)
    Q1   = bitshift(Top+1, -2);  % 2^(prec-2)
    Q3   = Q1 * 3;               % 3/4 full scale

    low = uint64(0);
    high = Top;
    underflow = uint64(0);

    % Output buffer
    out = false(1, 0);

    % Context model: 2^k contexts, each with counts for [0,1]
    nCtx = 2^k;
    cnt0 = ones(1, nCtx, 'uint32');
    cnt1 = ones(1, nCtx, 'uint32');

    % Helper to get context index from previous k bits (MSB-first)
    ctx_idx = 1;  % valid when k==0

    % Emit a single bit with pending underflow bits inverted accordingly
    function emit_bit(b)
        out(end+1) = logical(b);
        invb = ~logical(b);
        while underflow > 0
            out(end+1) = invb;
            underflow = underflow - 1;
        end
    end

    % Encode all symbols
    prevBits = false(1, 0);
    for t = 1:numel(x)
        if k > 0
            if t == 1
                prevBits = false(1, k); % zero-init context for first symbol(s)
            else
                % take last k bits before t
                idx_start = max(1, t-k);
                prevSlice = x(idx_start:t-1);
                if numel(prevSlice) < k
                    prevBits = [false(1, k-numel(prevSlice)), prevSlice];
                else
                    prevBits = prevSlice;
                end
            end
            % convert to index in [1..2^k]
            v = uint32(0);
            for i = 1:k
                v = bitor(bitshift(v,1), uint32(prevBits(i)));
            end
            ctx_idx = double(v) + 1;
        end

        % Probability interval from counts
        c0 = double(cnt0(ctx_idx));
        c1 = double(cnt1(ctx_idx));
        total = c0 + c1;
        % scale to current range
        range = high - low + 1;
        % cumulative layout: [0..c0) for symbol 0, [c0..total) for symbol 1
        sym = x(t);
        % compute split point
        split = low + uint64(floor((range * c0) / total));
        if ~sym % encoding 0
            high = split - 1;
        else    % encoding 1
            low  = split;
        end

        % Renormalization (E1/E2/E3 conditions)
        while true
            if bitshift(high, -1) == 0 && bitshift(low, -1) == 0 && high < Half
                % MSB is 0 for both -> emit 0
                emit_bit(0);
                % scale up
                low  = bitshift(low, 1);
                high = bitshift(high,1) + 1;
            elseif bitshift(high, -1) == 1 && bitshift(low, -1) == 1
                % MSB is 1 for both -> emit 1
                emit_bit(1);
                low  = bitshift(low - Half, 1);
                high = bitshift(high - Half,1) + 1;
            elseif low >= Q1 && high < Q3
                % underflow region (E3)
                underflow = underflow + 1;
                low  = bitshift(low - Q1,1);
                high = bitshift(high - Q1,1) + 1;
            else
                break;
            end
        end

        % Update counts (adaptive)
        if ~sym
            cnt0(ctx_idx) = cnt0(ctx_idx) + 1;
        else
            cnt1(ctx_idx) = cnt1(ctx_idx) + 1;
        end
        % Optional rescaling to avoid overflow
        if (cnt0(ctx_idx) + cnt1(ctx_idx)) > 2^15
            cnt0(ctx_idx) = bitshift(cnt0(ctx_idx), -1);
            cnt1(ctx_idx) = bitshift(cnt1(ctx_idx), -1);
            cnt0(ctx_idx) = max(cnt0(ctx_idx), uint32(1));
            cnt1(ctx_idx) = max(cnt1(ctx_idx), uint32(1));
        end
    end

    % Finalization: push one termination bit + pending underflow resolution
    underflow = underflow + 1;
    if low < Q1
        emit_bit(0);
        while underflow > 0, out(end+1) = true; underflow = underflow - 1; end
    else
        emit_bit(1);
        while underflow > 0, out(end+1) = false; underflow = underflow - 1; end
    end

    bitstream = out;
    side = struct('k', k, 'prec', cfg.prec); %#ok<NASGU>
end

function [x, success] = caac_decode_binary(bitstream, N, k, cfg)
% Matching context-adaptive arithmetic decoder for caac_encode_binary.
% Inputs mirror the encoder.
% Returns recovered x (logical row) and success flag.
    if nargin < 4 || ~isfield(cfg,'prec'), cfg.prec = 32; end
    if ~islogical(bitstream), bitstream = logical(bitstream); end

    prec = cfg.prec;
    Top = uint64(2^prec - 1);
    Half = bitshift(Top+1, -1);
    Q1   = bitshift(Top+1, -2);
    Q3   = Q1 * 3;

    low = uint64(0);
    high = Top;

    % Bitstream reader
    idx = 1;
    function b = getbit()
        if idx <= numel(bitstream)
            b = uint64(bitstream(idx));
            idx = idx + 1;
        else
            b = uint64(0); % pad zeros after end
        end
    end

    % Initialize code value with prec bits
    code = uint64(0);
    for i = 1:prec
        code = bitor(bitshift(code,1), getbit());
    end

    % Context model
    nCtx = 2^k;
    cnt0 = ones(1, nCtx, 'uint32');
    cnt1 = ones(1, nCtx, 'uint32');

    x = false(1, N);
    success = true;

    for t = 1:N
        % Determine context index
        if k > 0
            if t == 1
                prevBits = false(1, k);
            else
                idx_start = max(1, t-k);
                prevSlice = x(idx_start:t-1);
                if numel(prevSlice) < k
                    prevBits = [false(1, k-numel(prevSlice)), prevSlice];
                else
                    prevBits = prevSlice;
                end
            end
            v = uint32(0);
            for i = 1:k
                v = bitor(bitshift(v,1), uint32(prevBits(i)));
            end
            ctx_idx = double(v) + 1;
        else
            ctx_idx = 1;
        end

        % Current range and cumulative counts
        c0 = double(cnt0(ctx_idx));
        c1 = double(cnt1(ctx_idx));
        total = c0 + c1;

        range = double(high - low + 1);
        % Map code to cumulative position
        % pos in [0, total)
        pos = floor(((double(code - low) + 1) * total - 1) / range);
        if pos < c0
            sym = false;
            new_high = low + uint64(floor((range * c0) / total)) - 1;
            new_low  = low;
        else
            sym = true;
            new_low  = low + uint64(floor((range * c0) / total));
            new_high = high;
        end
        low = new_low; high = new_high;

        % Renormalization: keep code aligned with [low,high]
        while true
            if bitshift(high, -1) == 0 && bitshift(low, -1) == 0 && high < Half
                % MSB 0
                % emit 0 in encoder -> shift
                low  = bitshift(low, 1);
                high = bitshift(high,1) + 1;
                code = bitor(bitshift(code,1), getbit());
            elseif bitshift(high, -1) == 1 && bitshift(low, -1) == 1
                % MSB 1
                low  = bitshift(low - Half, 1);
                high = bitshift(high - Half,1) + 1;
                code = bitor(bitshift(code - Half,1), getbit());
            elseif low >= Q1 && high < Q3
                % underflow region
                low  = bitshift(low - Q1,1);
                high = bitshift(high - Q1,1) + 1;
                code = bitor(bitshift(code - Q1,1), getbit());
            else
                break;
            end
        end

        % Output symbol and update model
        x(t) = sym;
        if ~sym
            cnt0(ctx_idx) = cnt0(ctx_idx) + 1;
        else
            cnt1(ctx_idx) = cnt1(ctx_idx) + 1;
        end
        if (cnt0(ctx_idx) + cnt1(ctx_idx)) > 2^15
            cnt0(ctx_idx) = bitshift(cnt0(ctx_idx), -1);
            cnt1(ctx_idx) = bitshift(cnt1(ctx_idx), -1);
            cnt0(ctx_idx) = max(cnt0(ctx_idx), uint32(1));
            cnt1(ctx_idx) = max(cnt1(ctx_idx), uint32(1));
        end

        % Basic safety: if interval collapses, declare failure
        if high < low
            success = false; break;
        end
    end

    x = x(:).';
end

function demo_ca_ac_bsc
% demo_ca_ac_bsc.m
% Single-file MATLAB script implementing:
% - Binary order-1 Markov source
% - Context-adaptive binary arithmetic coding (order-k, adaptive counts)
% - Transmission over Binary Symmetric Channel (BSC)
% - Matching decoder
% - BER computation
% All helper functions are included below in this same file. Base MATLAB only.

clc; clear; rng(0); %#ok<CLSCR>

% Parameters
N = 2000;                   % number of source bits
P = [0.95, 0.05;            % Transition matrix P(x_t | x_{t-1})
     0.10, 0.90];           % rows: prev (0/1), cols: next (0/1)
p0 = 0.5;                   % Pr(X1=1)
ctx_order = 2;              % context order k
bsc_p = 1e-4;               % bit-flip probability in channel

% 1) Generate binary Markov source
x = gen_markov_binary(N, P, p0);

% 2) Context-adaptive arithmetic coding (binary)
% Build contexts from past k bits (zeros for warm-up). Adaptive integer counts with Laplace(1,1) prior.
[bitstream, enc_state] = ca_ac_encode_binary(x, ctx_order);

% 3) Transmit through BSC
rx_bitstream = bsc_channel(bitstream, bsc_p);

% 4) Decode (note: any channel error may catastrophically derail AC decoding)
[x_hat, dec_ok] = ca_ac_decode_binary(rx_bitstream, numel(x), ctx_order);

% 5) Compute BER on successfully decoded length (if failed, lengths may mismatch)
if dec_ok && numel(x_hat) == numel(x)
    ber = mean(x_hat ~= x);
else
    % If catastrophic failure, try to compute BER over min length for visibility
    L = min(numel(x_hat), numel(x));
    ber = mean(x_hat(1:L) ~= x(1:L));
end

% Report
fprintf('Source length          : %d\n', N);
fprintf('Context order (k)      : %d\n', ctx_order);
fprintf('BSC flip prob (p)      : %.2e\n', bsc_p);
fprintf('Tx bitstream length    : %d bits\n', numel(bitstream));
fprintf('Rx/Decode status       : %s\n', ternary(dec_ok,'OK','FAIL'));
fprintf('BER (reported)         : %.6f\n', ber);

% Quick sanity prints
fprintf('First 32 src bits:    %s\n', char('0' + x(1:min(32,end))));
fprintf('First 32 decoded bits:%s\n', char('0' + x_hat(1:min(32,end))));

end % function demo_ca_ac_bsc

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: Binary Markov source
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function x = gen_markov_binary(N, P, p1_init)
% x: row vector of 0/1 bits length N
x = zeros(1, N, 'uint8');
x(1) = rand < p1_init;
for t = 2:N
    prev = x(t-1);
    % Map prev in {0,1} to row index {1,2}
    row = prev + 1;
    p1 = P(row, 2); % probability of next=1
    x(t) = rand < p1;
end
x = uint8(x);
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: Context-adaptive binary arithmetic encoder
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function [bitstream, state] = ca_ac_encode_binary(x, k)
% x: 0/1 row vector
% k: context order
% Outputs: bitstream (row vector of 0/1 uint8), encoder state (for inspection)

% Range coder parameters (integer arithmetic)
BITS = 32;                     % coding precision
FULL = uint64(2^BITS - 1);
HALF = bitshift(FULL, -1);
QUART = bitshift(FULL, -2);
THREEQ = FULL - QUART;

low = uint64(0);
high = FULL;
underflow = uint64(0);
out = uint8([]);

% Context model: for 2^k contexts, maintain counts for symbol 0 and 1
C = max(1, 2^k);
count0 = ones(1, C, 'uint64'); % Laplace prior: start with 1,1
count1 = ones(1, C, 'uint64');

% context buffer initialized to zeros
ctx_buf = zeros(1, k, 'uint8');

for i = 1:numel(x)
    % Context index from last k bits (MSB-first): sum b_j * 2^(k-j)
    if k == 0
        ctx = 1;
    else
        ctx = 1 + sum(bitshift(uint32(ctx_buf), uint32(k-1:-1:0)));
    end

    % Compute cumulative counts for binary alphabet {0,1}
    c0 = count0(ctx);
    c1 = count1(ctx);
    tot = c0 + c1;           % uint64

    % Arithmetic coding step for symbol s in {0,1}
    s = uint8(x(i));

    % Map symbol to interval using cumulative: [0..c0) for 0, [c0..tot) for 1
    range = high - low + 1;
    if s == 0
        high = low + uint64(floor(double(range) * double(c0) / double(tot))) - 1;
        low  = low + uint64(floor(double(range) * double(0)  / double(tot)));
    else
        high = low + uint64(floor(double(range) * double(tot) / double(tot))) - 1;
        low  = low + uint64(floor(double(range) * double(c0)  / double(tot)));
    end

    % Renormalization loop
    while true
        if bitshift(high, - (BITS-1)) == bitshift(low, - (BITS-1))
            % MSB equal: emit bit
            bit = uint8(bitshift(high, - (BITS-1))); % 0 or 1
            out(end+1) = bit; %#ok<AGROW>
            % Flush underflow bits (complements)
            while underflow > 0
                out(end+1) = bitxor(bit, 1); %#ok<AGROW>
                underflow = underflow - 1;
            end
            % Shift out MSB
            low  = bitshift(bitand(low, HALF-1), 1);
            high = bitshift(bitand(high, HALF-1), 1) + 1 + (HALF-1);
        elseif (low >= QUART) && (high < THREEQ)
            % Underflow region
            low  = bitshift(low - QUART, 1);
            high = bitshift(high - QUART, 1) + 1 + (HALF-1);
            underflow = underflow + 1;
        else
            break;
        end
    end

    % Update model (adaptive)
    if s == 0
        count0(ctx) = count0(ctx) + 1;
    else
        count1(ctx) = count1(ctx) + 1;
    end

    % Simple count rescaling to avoid overflow
    if (count0(ctx) + count1(ctx)) > 2^20
        count0(ctx) = bitshift(count0(ctx), -1);
        count1(ctx) = bitshift(count1(ctx), -1);
        % keep nonzero
        count0(ctx) = max(count0(ctx), uint64(1));
        count1(ctx) = max(count1(ctx), uint64(1));
    end

    % Slide context
    if k > 0
        ctx_buf = [ctx_buf(2:end), s]; %#ok<AGROW>
    end
end

% Finalization: emit one more bit to disambiguate interval
underflow_local = underflow;
bit = uint8(bitshift(low, - (BITS-1))); % choose MSB of low
out(end+1) = bit; %#ok<AGROW>
while underflow_local > 0
    out(end+1) = bitxor(bit, 1); %#ok<AGROW>
    underflow_local = underflow_local - 1;
end

bitstream = uint8(out);

% Return state for inspection (optional)
state.count0 = count0;
state.count1 = count1;
state.k = k;
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: Context-adaptive binary arithmetic decoder
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function [x, ok] = ca_ac_decode_binary(bitstream, N, k)
% bitstream: row vector uint8 bits {0,1}
% N: number of symbols to decode
% k: context order

BITS = 32;
FULL = uint64(2^BITS - 1);
HALF = bitshift(FULL, -1);
QUART = bitshift(FULL, -2);
THREEQ = FULL - QUART;

low = uint64(0);
high = FULL;

% Reader for bits
rd.idx = 1;
rd.bits = uint8(bitstream(:)).';

% Initialize code value with BITS bits (pad zeros if needed)
code = uint64(0);
for i = 1:BITS
    code = bitshift(code, 1);
    code = code + uint64(readbit(rd));
end

C = max(1, 2^k);
count0 = ones(1, C, 'uint64');
count1 = ones(1, C, 'uint64');
ctx_buf = zeros(1, k, 'uint8');

x = zeros(1, N, 'uint8');
ok = true;

for i = 1:N
    if k == 0
        ctx = 1;
    else
        ctx = 1 + sum(bitshift(uint32(ctx_buf), uint32(k-1:-1:0)));
    end

    c0 = count0(ctx);
    c1 = count1(ctx);
    tot = c0 + c1;

    range = double(high - low + 1);
    % Compute split point for symbol 0 interval
    split = low + uint64(floor(range * double(c0) / double(tot))) - 1;

    % Determine symbol by locating code in [low..split] or [split+1..high]
    if code <= split
        s = uint8(0);
        high = split;
    else
        s = uint8(1);
        low = split + 1;
    end

    % Renormalize while MSBs equal or in underflow region
    while true
        if bitshift(high, - (BITS-1)) == bitshift(low, - (BITS-1))
            % shift out MSB
            low  = bitshift(bitand(low, HALF-1), 1);
            high = bitshift(bitand(high, HALF-1), 1) + 1 + (HALF-1);
            code = bitshift(bitand(code, HALF-1), 1) + uint64(readbit(rd));
        elseif (low >= QUART) && (high < THREEQ)
            low  = bitshift(low - QUART, 1);
            high = bitshift(high - QUART, 1) + 1 + (HALF-1);
            code = bitshift(code - QUART, 1) + uint64(readbit(rd));
        else
            break;
        end
    end

    % Output and update model
    x(i) = s;
    if s == 0
        count0(ctx) = count0(ctx) + 1;
    else
        count1(ctx) = count1(ctx) + 1;
    end
    if (count0(ctx) + count1(ctx)) > 2^20
        count0(ctx) = bitshift(count0(ctx), -1);
        count1(ctx) = bitshift(count1(ctx), -1);
        count0(ctx) = max(count0(ctx), uint64(1));
        count1(ctx) = max(count1(ctx), uint64(1));
    end

    if k > 0
        ctx_buf = [ctx_buf(2:end), s]; %#ok<AGROW>
    end
end

% If we consumed all requested symbols but still have trailing bits, that's ok.
% If we ran out of bits prematurely, mark not ok.
if rd.idx > numel(rd.bits) + BITS + 2 % loose heuristic
    ok = false;
end
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: Binary Symmetric Channel (bit flips with prob p)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function y = bsc_channel(x, p)
% x: vector of uint8 bits {0,1}
flip = rand(size(x)) < p;
y = bitxor(uint8(x), uint8(flip));
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: read one bit from reader struct (returns 0 if past end)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function b = readbit(rd)
if rd.idx <= numel(rd.bits)
    b = rd.bits(rd.idx);
else
    b = uint8(0);
end
rd.idx = rd.idx + 1;
assignin('caller','rd',rd);
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Helper: simple ternary string
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function s = ternary(cond, a, b)
if cond, s = a; else, s = b; end
end

