use proc_macro::TokenStream;
use quote::quote;
use syn::{spanned::Spanned, Error, LitInt};

#[proc_macro]
pub fn twice(input: TokenStream) -> TokenStream {
    let lit: LitInt = match syn::parse(input) {
        Ok(v) => v,
        Err(e) => return e.to_compile_error().into(),
    };

    let value = match lit.base10_parse::<u64>() {
        Ok(v) => v,
        Err(e) => {
            let err = Error::new(lit.span(), format!("expected an integer literal: {e}"));
            return err.to_compile_error().into();
        }
    };

    quote!(#value * 2).into()
}

Derive macro (unchanged behavior, panic-free)
use proc_macro::TokenStream;
use quote::quote;
use syn::{spanned::Spanned, DeriveInput, Error};

#[proc_macro_derive(MyDerive)]
pub fn my_derive(input: TokenStream) -> TokenStream {
    let ast: DeriveInput = match syn::parse(input) {
        Ok(v) => v,
        Err(e) => return e.to_compile_error().into(),
    };

    let expanded = expand(ast).unwrap_or_else(|e| e.to_compile_error());
    TokenStream::from(expanded)
}

fn expand(ast: DeriveInput) -> Result<proc_macro2::TokenStream, syn::Error> {
    let ident = &ast.ident;
    let data = match &ast.data {
        syn::Data::Struct(s) => s,
        _ => {
            return Err(Error::new(
                ast.span(),
                "#[derive(MyDerive)] is only supported on structs",
            ))
        }
    };

    if data.fields.iter().next().is_none() {
        return Err(Error::new(data.fields.span(), "struct must have at least one field"));
    }

    Ok(quote! {
        impl #ident {
            pub fn my_derive_marker() -> &'static str { "ok" }
        }
    })
}

Attribute macro (fixed for syn v2; correct arg parsing, complete)
use proc_macro::TokenStream;
use quote::quote;
use syn::{spanned::Spanned, Error, ItemFn, Meta, Token};
use syn::parse::{Parse, ParseStream};

// Simple args: #[my_attr(name = "value")]
struct MyAttrArgs {
    name: Option<syn::LitStr>,
}

impl Parse for MyAttrArgs {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        if input.is_empty() {
            return Ok(MyAttrArgs { name: None });
        }
        // Parse: name = "..." (optionally with trailing comma)
        let path: syn::Path = input.parse()?;
        if !path.is_ident("name") {
            return Err(Error::new(path.span(), "expected `name`"));
        }
        input.parse::<Token![=]>()?;
        let val: syn::LitStr = input.parse()?;
        if !input.is_empty() {
            // Allow one optional trailing comma only
            let _ = input.parse::<Token![,]>()?;
            if !input.is_empty() {
                return Err(Error::new(input.span(), "unexpected tokens after arguments"));
            }
        }
        Ok(MyAttrArgs { name: Some(val) })
    }
}

#[proc_macro_attribute]
pub fn my_attr(args: TokenStream, input: TokenStream) -> TokenStream {
    // Parse the item first; never panic.
    let func: ItemFn = match syn::parse(input) {
        Ok(v) => v,
        Err(e) => return e.to_compile_error().into(),
    };

    // Parse attribute args with a custom parser (syn v2-compatible).
    let args: MyAttrArgs = match syn::parse(args) {
        Ok(v) => v,
        Err(e) => return e.to_compile_error().into(),
    };

    // Use the parsed value (optional), but keep example minimal.
    let _name_str = args.name.as_ref().map(|s| s.value()).unwrap_or_else(|| "default".to_string());

    // Return the function unchanged to keep the example runnable.
    quote!(#func).into()
}

Notes
- Avoid unwrap/expect; convert syn::Error to tokens via to_compile_error().
- The attribute argument parser is explicit and minimal, works with syn v2, and produces clear diagnostics with correct spans.
- If you prefer helpers, you can also parse Meta directly with syn::Meta::parse, e.g. let meta = syn::Meta::parse(args_ts) and then match Meta::NameValue where path.is_ident("name").

