use proc_macro::TokenStream;
use proc_macro2::Span;
use quote::quote;
use syn::{parse::Parse, parse::ParseStream, parse_macro_input, AttributeArgs, Error, Ident, ItemFn, Lit, LitStr, Meta, NestedMeta, Result as SynResult};

// If you prefer not to use proc-macro-error, remove these and the attribute below.
use proc_macro_error::{abort, emit_error, proc_macro_error};

// Attribute arguments: #[greet(name = "World")]
// We'll support exactly one key: `name = "..."`.
#[derive(Debug, Default)]
struct GreetArgs {
    name: Option<LitStr>,
}

impl Parse for GreetArgs {
    fn parse(input: ParseStream) -> SynResult<Self> {
        // Parse as AttributeArgs to be lenient and compatible with syn v2 attribute parsing.
        let args = AttributeArgs::parse_terminated(input)?;
        let mut out = GreetArgs::default();
        for nested in args {
            match nested {
                NestedMeta::Meta(Meta::NameValue(nv)) => {
                    if nv.path.is_ident("name") {
                        match nv.value {
                            Lit::Str(s) => {
                                if out.name.is_some() {
                                    return Err(Error::new_spanned(
                                        nv,
                                        "duplicate `name` argument",
                                    ));
                                }
                                out.name = Some(s);
                            }
                            other => {
                                return Err(Error::new_spanned(
                                    other,
                                    "`name` must be a string literal, e.g., name = \"Alice\"",
                                ));
                            }
                        }
                    } else {
                        return Err(Error::new_spanned(
                            nv.path,
                            "unsupported argument; expected `name = \"...\"`",
                        ));
                    }
                }
                other => {
                    return Err(Error::new_spanned(
                        other,
                        "unsupported syntax; expected `name = \"...\"`",
                    ));
                }
            }
        }
        Ok(out)
    }
}

#[proc_macro_error]
#[proc_macro_attribute]
pub fn greet(attr: TokenStream, item: TokenStream) -> TokenStream {
    // Parse the target item first, returning a compiler error if not a function.
    let mut input_fn: ItemFn = match syn::parse(item.clone()) {
        Ok(f) => f,
        Err(e) => return proc_macro_error::emit_error!(e).into(),
    };

    // Parse attribute args with graceful erroring (no panic).
    let args = match parse_macro_input::parse::<GreetArgs>(attr) {
        Ok(a) => a,
        Err(e) => return proc_macro_error::emit_error!(e).into(),
    };

    // Determine the greeting name, defaulting if omitted.
    let name_lit = args
        .name
        .unwrap_or_else(|| LitStr::new("World", Span::call_site()));

    // Inject a println! at function start.
    let greet_stmt = quote! {
        println!("Hello, {}!", #name_lit);
    };

    // Insert the statement at the beginning of the function body.
    if let Some(block) = input_fn.block.stmts.get_mut(0) {
        // We will just prepend; building a new vec is simpler and clear.
    }
    let mut new_stmts = Vec::new();
    new_stmts.push(syn::parse_quote!(#greet_stmt));
    new_stmts.extend(input_fn.block.stmts.clone());
    input_fn.block.stmts = new_stmts;

    TokenStream::from(quote! { #input_fn })
}

