Option B (programmatic scrape at build time): Node script using cheerio to parse the HTML table.
// package.json deps: "node-fetch", "cheerio"
// scripts/fetch-planets.js
import fetch from "node-fetch";
import { load } from "cheerio";
import { writeFileSync } from "fs";

const URL = "https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_table_m.html";
const nameMap = { "Mercury":"Mercury","Venus":"Venus","Earth":"Earth","Mars":"Mars","Jupiter":"Jupiter","Saturn":"Saturn","Uranus":"Uranus","Neptune":"Neptune" };

function parseNumber(s){
  return Number(String(s).replace(/[^0-9.+\-eE]/g, ""));
}

const res = await fetch(URL);
const html = await res.text();
const $ = load(html);

// The table lists multiple quantities per row; we extract semimajor axis (AU), orbital period (days), and equatorial radius (km)
const table = $("table").first();
const headers = table.find("tr").first().find("th,td").map((_,el)=>$(el).text().trim()).get();

// Find column indices
const colIndexByHeader = (regex) => headers.findIndex(h => regex.test(h));
const iName = 0; // first column lists quantity names; planets are columns
// Identify quantity rows by their label text
let idxRowA = -1, idxRowP = -1, idxRowR = -1;
const rows = table.find("tr").slice(1).toArray();
const planetNames = [];

// Read planet column order from header row 2 (planets)
const headerPlanets = $(rows[0]).find("td").map((_,el)=>$(el).text().trim()).get();
for (const p of headerPlanets) if (nameMap[p]) planetNames.push(nameMap[p]);

rows.forEach((row, rIdx) => {
  const cells = $(row).find("td").map((_,el)=>$(el).text().trim()).get();
  const label = cells[0]?.toLowerCase();
  if (/semimajor axis \(au\)/i.test(cells[0])) idxRowA = rIdx;
  if (/orbital period \(days\)/i.test(cells[0])) idxRowP = rIdx;
  if (/(equatorial )?radius \(km\)/i.test(cells[0])) idxRowR = rIdx;
});

function valuesAt(rowIdx){
  const cells = $(rows[rowIdx]).find("td").map((_,el)=>$(el).text().trim()).get();
  // cells[0] is label; following cells align with planet columns
  return cells.slice(1).map(parseNumber);
}

const A = valuesAt(idxRowA);
const P = valuesAt(idxRowP);
const R = valuesAt(idxRowR);

const planets = planetNames.map((name, i) => ({
  name,
  a_AU: A[i],
  period_days: P[i],
  radius_km: R[i]
}));

writeFileSync("data/planets.json", JSON.stringify({ planets }, null, 2));
console.log("Wrote data/planets.json from:", URL);

