Step 4 — JavaScript: load data, scale distances, animate
// src/main.js
const dpr = Math.max(1, window.devicePixelRatio || 1);
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

function resize(){
  canvas.width = Math.floor(innerWidth * dpr);
  canvas.height = Math.floor(innerHeight * dpr);
  canvas.style.width = innerWidth + 'px';
  canvas.style.height = innerHeight + 'px';
}
addEventListener('resize', resize); resize();

// Fetch parsed planetary data (from NASA Planetary Fact Sheet)
async function loadPlanets(){
  const res = await fetch('../data/planets.json');
  if (!res.ok) throw new Error('Failed to load planets.json');
  const json = await res.json();
  return json.planets;
}

// Mapping NASA data to simulation parameters
// - Distance scaling: choose pixels per AU
// - Angular speed: omega = 2*pi / period_seconds, where period_seconds = period_days*86400
// - For a circular approximation (e ~ 0), radius of orbit = a_AU
const PX_PER_AU_BASE = 120; // adjust for screen; will auto-fit later

function fitScale(planets){
  const maxAU = Math.max(...planets.map(p => p.a_AU));
  const margin = 40 * dpr;
  const fit = Math.min((canvas.width/2 - margin) / maxAU, PX_PER_AU_BASE * dpr);
  return Math.max(20 * dpr, fit);
}

function kmToPxRadius(km, pxPerAU){
  const earthKm = 6371; // normalize for visibility
  const minPx = 2*dpr;
  const scale = 6 * dpr; // exaggeration factor
  return Math.max(minPx, (km/earthKm) * (pxPerAU/50) * scale);
}

let planets = [];
let pxPerAU = PX_PER_AU_BASE * dpr;
let simDaysPerSec = 365; // UI-controlled

const timeScaleInput = document.getElementById('timeScale');
const timeScaleVal = document.getElementById('timeScaleVal');
timeScaleInput.addEventListener('input', e => {
  simDaysPerSec = Number(e.target.value);
  timeScaleVal.textContent = String(simDaysPerSec);
});

function drawScene(t){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.save();
  ctx.translate(canvas.width/2, canvas.height/2);

  // Sun
  ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--sun');
  ctx.beginPath();
  ctx.arc(0,0, 8*dpr, 0, Math.PI*2);
  ctx.fill();

  // Orbits
  ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--orbit');
  ctx.lineWidth = 1*dpr;
  for (const p of planets){
    ctx.beginPath();
    ctx.arc(0,0, p.a_AU * pxPerAU, 0, Math.PI*2);
    ctx.stroke();
  }

  // Planets
  for (const p of planets){
    const omega = 2*Math.PI / (p.period_days * 86400); // rad/sec
    const angle = p.phase0 + omega * p.simTimeSeconds;
    const r = p.a_AU * pxPerAU;
    const x = r * Math.cos(angle);
    const y = r * Math.sin(angle);

    ctx.fillStyle = '#9ec9ff';
    ctx.beginPath();
    ctx.arc(x, y, kmToPxRadius(p.radius_km, pxPerAU), 0, Math.PI*2);
    ctx.fill();
  }

  ctx.restore();
}

let last = performance.now();
function loop(now){
  const dt = Math.min(0.05, (now - last) / 1000); // clamp
  last = now;
  // advance simulation time in seconds for each planet
  for (const p of planets){
    p.simTimeSeconds += dt * simDaysPerSec * 86400; // days/sec -> sec
  }
  drawScene(now/1000);
  requestAnimationFrame(loop);
}

loadPlanets().then(list => {
  planets = list.map((p,i) => ({
    ...p,
    phase0: Math.random()*Math.PI*2, // start angle
    simTimeSeconds: 0
  }));
  pxPerAU = fitScale(planets);
  requestAnimationFrame(loop);
});

Step 5 — Mapping explained (using NASA data directly)
- Semimajor axis (a_AU from Planetary Fact Sheet) → orbit radius on canvas: radius_px = a_AU * pxPerAU.
- Orbital period (period_days from Planetary Fact Sheet) → angular velocity: omega = 2π / (period_days × 86400).
- Planetary radius (radius_km from Planetary Fact Sheet) → drawn circle radius: exaggerated scaling for visibility via kmToPxRadius.

