// src/render/scale.js
// Map astronomical units (AU) and planet radii (km) to pixels for rendering.

export function makeScales({ canvasWidth, canvasHeight, planets }) {
  // Compute a scale so Neptune fits comfortably within the canvas.
  const maxAU = Math.max(...planets.map(p => p.a_AU));
  // Reserve 10% padding around the farthest orbit.
  const usable = Math.min(canvasWidth, canvasHeight) * 0.9;
  const AU_to_px = usable / (2 * maxAU); // radius fit: center to edge

  // Radius scaling: make Earth ~6 px radius, proportional by sqrt to avoid huge gas giants
  const earth = planets.find(p => p.id === 'earth');
  const earth_px = 6;
  const km_to_px = earth ? (earth_px / Math.sqrt(earth.radius_km)) : (6 / Math.sqrt(6371));

  return { AU_to_px, km_to_px };
}
