// src/main.js
import { makeScales } from './render/scale.js';
import { State } from './core/state.js';

const canvas = document.getElementById('view');
const ctx = canvas.getContext('2d');
const legend = document.getElementById('legend');
const timeScaleInput = document.getElementById('timeScale');
const timeScaleValue = document.getElementById('timeScaleValue');

let planets = [];
let AU_to_px = 1;
let km_to_px = 1;

function resizeCanvas() {
  const dpr = Math.max(1, window.devicePixelRatio || 1);
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.floor(rect.width * dpr);
  canvas.height = Math.floor(rect.height * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // draw in CSS pixels
  if (planets.length) {
    const s = makeScales({ canvasWidth: canvas.width / dpr, canvasHeight: canvas.height / dpr, planets });
    AU_to_px = s.AU_to_px; km_to_px = s.km_to_px;
  }
}

async function loadPlanets() {
  const res = await fetch('../data/planets.json', { cache: 'no-store' });
  if (!res.ok) throw new Error('Failed to load planets.json');
  const json = await res.json();
  planets = json.planets;
  // Build legend
  legend.innerHTML = planets.map(p => `
    <div class=\"row\"><span class=\"swatch\" style=\"background:${p.color}\"></span>${p.name}
      <span style=\"margin-left:auto; color:#6c7686\">a=${p.a_AU.toFixed(2)} AU · P=${p.period_days.toFixed(0)} d</span>
    </div>`).join('');
  resizeCanvas();
}

function drawSun() {
  const cx = canvas.clientWidth / 2;
  const cy = canvas.clientHeight / 2;
  ctx.save();
  ctx.translate(cx, cy);
  // Sun approximate radius 696,340 km -> scaled
  const sun_r_px = Math.max(8, Math.sqrt(696340) * km_to_px);
  const grad = ctx.createRadialGradient(0,0,0, 0,0,sun_r_px);
  grad.addColorStop(0, '#fff1a8');
  grad.addColorStop(1, '#ffb300');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(0, 0, sun_r_px, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawOrbits() {
  const cx = canvas.clientWidth / 2;
  const cy = canvas.clientHeight / 2;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.strokeStyle = 'rgba(255,255,255,0.08)';
  ctx.lineWidth = 1;
  for (const p of planets) {
    const r = p.a_AU * AU_to_px;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawPlanets(tDays) {
  // Map orbital period (days) to angular velocity: omega = 2π / period
  const cx = canvas.clientWidth / 2;
  const cy = canvas.clientHeight / 2;
  ctx.save();
  ctx.translate(cx, cy);
  for (const p of planets) {
    const r_orbit = p.a_AU * AU_to_px;
    const omega = (2 * Math.PI) / p.period_days; // rad/day
    const theta = omega * tDays; // simple circular orbits
    const x = Math.cos(theta) * r_orbit;
    const y = Math.sin(theta) * r_orbit;

    // Planet radius scaled (sqrt scaling to compress dynamic range)
    const pr = Math.max(2, Math.sqrt(p.radius_km) * km_to_px);

    // Orbit dot
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(x, y, pr, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function frame(ts) {
  // Convert ms to days: 1 real second = State.timeScale days for visibility
  const dt_ms = Math.min(50, (frame.prev ?? ts) && (ts - (frame.prev ?? ts)));
  frame.prev = ts;
  const dt_s = dt_ms / 1000;
  State.t += dt_s * State.timeScale; // days

  ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
  drawSun();
  drawOrbits();
  drawPlanets(State.t);
  requestAnimationFrame(frame);
}

function initUI() {
  timeScaleInput.addEventListener('input', () => {
    State.timeScale = parseFloat(timeScaleInput.value);
    timeScaleValue.textContent = `${State.timeScale.toFixed(1)}x`;
  });
  timeScaleValue.textContent = `${State.timeScale.toFixed(1)}x`;
}

window.addEventListener('resize', resizeCanvas);

(async function start() {
  initUI();
  resizeCanvas();
  await loadPlanets();
  requestAnimationFrame(frame);
})();
```

How the NASA data maps to the simulation
- Distance: a_AU (astronomical units) × AU_to_px → orbit radius in pixels.
- Speed: period_days → angular velocity ω = 2π / period_days (rad/day); simulation time t (days) advances per frame by timeScale.
- Size: radius_km scaled to pixels using sqrt(radius_km) × km_to_px to keep giants readable while preserving relative feel.

Running locally
- Run the fetch script once: node scripts/fetch-planets.js
- Start a static server from the project root so that /public can load ../data/planets.json, e.g.:
  - npx http-server .
  - or: npx serve .
- Open http://localhost:PORT/public/

Optional improvements and tips
- Performance: batch drawing by layer (orbits first, then planets), avoid per-frame allocations, cap dt for stability.
- Visuals: add subtle orbit ticks, glow shaders via offscreen canvas, or label planets with fade-in on hover.
- Accuracy: incorporate eccentricities and mean anomalies (from NASA/JPL or HORIZONS) for elliptical orbits; apply Kepler’s equation.
- Responsiveness: recompute scales on resize; clamp min/max planet radii for readability.
"""
