Minimal HLSL (Custom node in M_Composite)
float3 Composite(float2 uv)
{
    float3 tCol = Texture2DSample(TerrainColor, TerrainColorSampler, uv).rgb;
    float3 mCol = Texture2DSample(MountainColor, MountainColorSampler, uv).rgb;
    float  tZ   = Texture2DSample(TerrainDepth, TerrainDepthSampler, uv).r;
    float  mZ   = Texture2DSample(MountainDepth, MountainDepthSampler, uv).r;

    bool tValid = isfinite(tZ) && (tZ < 1e19);
    bool mValid = isfinite(mZ) && (mZ < 1e19);

    if (!tValid && !mValid) return float3(0,0,0);
    if (!tValid) return mCol;
    if (!mValid) return tCol;

    bool mFront = (mZ <= tZ);
    float delta = abs(tZ - mZ);

    float w = 1.0 - smoothstep(SeamThickness, SeamFeather, delta);

    float3 front = mFront ? mCol : tCol;
    float3 back  = mFront ? tCol : mCol;

    return lerp(front, back, w);
}

4) Wire into camera
- Add a Post Process Volume (Unbound). Add M_Composite as a Blendable. Assign the four RTs to the material parameters via Blueprint on BeginPlay (get references to SceneCapture targets).

5) Ensuring isolation and no cross-diffuse
- Each SceneCapture renders only its object set; no material samples from the other’s diffuse.
- The Post Process Material mixes final shaded colors only in a narrow depth band.

6) Performance notes
- Prefer half-float color RTs, R32F for linear depth; set capture resolution near main viewport resolution.
- Update SceneCaptures every frame or only when needed.

Simple diagram (contact-band blending)
Camera
  |
  v
[ Screen pixels ]
   |------ far apart (no blend) ------|-- contact band (smooth mix) --| mountain-front
Depth tZ:  ......................_____|____----
Depth mZ:  ____-------------------____|____
Color out: terrain OR mountain       -> blends only within the narrow band

This approach guarantees: smooth seam hiding while preventing the terrain from ever sampling mountain diffuse (and vice versa); only final colors are blended in post based on depth proximity.

Below are concrete steps for Unity (URP/HDRP) and Unreal Engine 5 to render terrain and mountain into separate color/depth targets, plus minimal shader/compositing snippets and an ASCII diagram of the contact-band blend. This preserves each object’s own diffuse and blends only in a narrow seam band to avoid color bleed.

ASCII contact-band diagram

Camera view (side)

   mountain      seam/contact band           terrain
      /\            <---- blend ---->           
     /  \_____.____________________             
             ^  ^                   
             |  |                   
             |  +-- outer edge (no blend)
             +----- inner edge (max blend)

Blend weight w = 1 - smoothstep(inner=thickness, outer=feather, |Δdepth|)
Front surface fades toward back only within this band; outside, no mixing.

Unity (URP/HDRP)

Goal: Render terrain and mountain into two RenderTextures (color + depth) and composite in a post-process pass.

1) Create render targets
- Two color RTs (ARGBHalf or DefaultHDR): TerrainColor, MountainColor
- Two depth RTs (R32_SFloat or 24/32-bit): TerrainDepth, MountainDepth
- Match camera resolution and MSAA settings as desired.

2) Draw terrain-only pass
URP (ScriptableRendererFeature/Pass) or HDRP (Custom Pass):
- Configure to render only objects on Terrain layer.
- Set render target: TerrainColor (color), TerrainDepth (depth).
- Clear color/depth, then DrawRenderers filtering by Terrain layer + appropriate shader pass tags.

3) Draw mountain-only pass
- Same as step 2 but filter Mountain layer and set MountainColor/MountainDepth RTs.

4) Fullscreen composite pass (after both offscreen passes)
- Bind TerrainColor, TerrainDepth, MountainColor, MountainDepth as textures.
- Output to camera color (or a final RT you then blit to camera).
- Uniforms: seamThickness (meters), seamFeather (meters), cameraNear, cameraFar.

5) Minimal HLSL fragment (URP/HDRP) for compositing
Note: If your depth textures are non-linear [0..1], linearize with Unity’s helper or custom function.

// HLSL snippet (URP/HDRP compatible)
TEXTURE2D(TerrainColorTex);  SAMPLER(samp);
TEXTURE2D(MountainColorTex); SAMPLER(samp);
TEXTURE2D(TerrainDepthTex);  SAMPLER(samp);
TEXTURE2D(MountainDepthTex); SAMPLER(samp);
CBUFFER_START(SeamParams)
float seamThickness;   // e.g., 0.15 (view-space meters)
float seamFeather;     // e.g., 0.30 (> thickness)
float nearPlane;
float farPlane;
CBUFFER_END

float LinearizeDepth(float z01, float n, float f)
{
    // Unity: z01 is hardware depth [0,1], perspective
    float z = z01 * 2.0 - 1.0;
    return (2.0 * n * f) / (f + n - z * (f - n));
}

float Smoothstep(float e0, float e1, float x)
{
    float t = saturate((x - e0) / max(e1 - e0, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

float4 CompositePS(float2 uv) : SV_Target
{
    float3 cT = TerrainColorTex.Sample(samp, uv).rgb;
    float3 cM = MountainColorTex.Sample(samp, uv).rgb;

    float dT01 = TerrainDepthTex.Sample(samp, uv).r;
    float dM01 = MountainDepthTex.Sample(samp, uv).r;

    bool tValid = dT01 < 1.0; // assume 1.0 == no geometry
    bool mValid = dM01 < 1.0;

    float3 bg = float3(0,0,0);
    if (!tValid && !mValid) return float4(bg, 1);

    float dT = tValid ? LinearizeDepth(dT01, nearPlane, farPlane) : 1e30;
    float dM = mValid ? LinearizeDepth(dM01, nearPlane, farPlane) : 1e30;

    bool mFront = mValid && (!tValid || dM <= dT);
    bool tFront = tValid && (!mValid || dT <  dM);

    float3 baseC = mFront ? cM : cT;
    if (!tValid || !mValid)
        return float4(baseC, 1);

    float delta = abs(dT - dM);
    float w = 1.0 - Smoothstep(seamThickness, seamFeather, delta);

    // Blend only along depth order to avoid color diffusion
    if (mFront)
        baseC = lerp(cM, cT, w); // mountain front blends toward terrain behind
    else
        baseC = lerp(cT, cM, w); // terrain front blends toward mountain behind

    return float4(saturate(baseC), 1);
}

URP implementation notes
- Create a ScriptableRendererFeature with three passes:
  1) TerrainRT pass: set RenderTarget(TerrainColor, TerrainDepth), Filtering: Terrain layer.
  2) MountainRT pass: set RenderTarget(MountainColor, MountainDepth), Filtering: Mountain layer.
  3) Composite pass: Blit to CameraColor using CompositePS.
- Ensure Camera doesn’t draw default objects in between; rely on these offscreen passes + final composite.

HDRP implementation notes
- Use two Fullscreen Custom Passes in the Before/After Opaque injection points or a Custom Pass Volume:
  1) Render Objects (Terrain layer) to Terrain RTs.
  2) Render Objects (Mountain layer) to Mountain RTs.
  3) Fullscreen custom pass to composite with the HLSL above.
- In HDRP, use RTHandleSystem and bind depth explicitly; toggle Clear flags per pass.

Unreal Engine 5 (UE5)

Goal: Two separate SceneCapture2D actors (or render passes via Composure) produce terrain-only and mountain-only color+depth, then a material performs the composite.

1) Create two SceneCapture2D actors
- CaptureTerrain and CaptureMountain. Set both to capture Final Color (LDR/HDR as needed) and SceneDepth.
- Assign each a custom ShowOnly list or use CustomDepth Stencil/Actor Hidden In Game to isolate:
  - CaptureTerrain: ShowOnly = Terrain actors; HiddenActors = Mountain actors.
  - CaptureMountain: ShowOnly = Mountain actors; HiddenActors = Terrain actors.
- Output to two Render Target 2D assets:
  - RT_TerrainColor (RGBA16F), RT_TerrainDepth (R32f)
  - RT_MountainColor (RGBA16F), RT_MountainDepth (R32f)
- Match resolutions to your main viewport for best results.

2) Ensure depth export
- In the SceneCapture, enable Capture Source = Final Color (HDR) in RGB, SceneDepth in A (or separately capture depth via a second capture/midas). Alternatively, use Composure or Render Layers to guarantee linear depth access.

3) Composite material
- Create a Material (Domain: Post Process or Surface for a full-screen quad in UMG/Composure) set to Unlit.
- Add TextureObject/TextureSample nodes for RT_TerrainColor, RT_MountainColor, RT_TerrainDepth, RT_MountainDepth.
- Convert hardware depth to linear view depth. In a Material Function:
  LinearizeDepth(z01) = (2*n*f)/(f+n - (2*z01-1)*(f-n))
  Provide Near/Far via Material Parameter Collection.
- Compute:
  - Valid masks: tValid = (dT01 < 1), mValid = (dM01 < 1)
  - dT, dM = LinearizeDepth(dT01), LinearizeDepth(dM01)
  - mFront = mValid && (!tValid || dM <= dT)
  - base = mFront ? cM : cT; if not both valid, output base
  - w = 1 - smoothstep(thickness, feather, abs(dT - dM))
  - out = mFront ? lerp(cM, cT, w) : lerp(cT, cM, w)
- Output out as Emissive Color.

4) Apply composite
- Use a Post Process Volume with the composite material (Material Domain: Post Process, Blendable). Or use Composure: feed both captures into a Compositing Element and add a custom material pass with the logic above.

Minimal HLSL/UE material custom code (Custom node)

float LinearizeDepth(float z01, float n, float f)
{
    float z = z01 * 2.0 - 1.0;
    return (2.0 * n * f) / (f + n - z * (f - n));
}

float SmoothstepUE(float e0, float e1, float x)
{
    float t = saturate((x - e0) / max(e1 - e0, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

// Inputs: cT,cM (float3), dT01,dM01 (float), n,f, thickness, feather, valid flags (0/1)
void CompositeUE(
    float3 cT, float3 cM, float dT01, float dM01,
    float n, float f, float thickness, float feather,
    float tValid, float mValid,
    out float3 outColor)
{
    if ((tValid < 0.5) && (mValid < 0.5)) { outColor = float3(0,0,0); return; }
    float dT = (tValid > 0.5) ? LinearizeDepth(dT01, n, f) : 1e30;
    float dM = (mValid > 0.5) ? LinearizeDepth(dM01, n, f) : 1e30;
    bool mFront = (mValid > 0.5) && ((tValid < 0.5) || (dM <= dT));
    float3 baseC = mFront ? cM : cT;
    if (!((tValid > 0.5) && (mValid > 0.5))) { outColor = baseC; return; }
    float delta = abs(dT - dM);
    float w = 1.0 - SmoothstepUE(thickness, feather, delta);
    outColor = mFront ? lerp(cM, cT, w) : lerp(cT, cM, w);
}

Key settings to prevent diffusion/bleed
- Strict separation: Terrain and Mountain are shaded in isolation into distinct RTs; no cross-sampling of each other’s materials.
- Depth-ordered blending in a narrow contact band only; beyond the band, choose strictly front-most color.
- Use linearized depth in view space for consistent seam thickness across the frame.

This setup blends smoothly at the seam while guaranteeing the terrain never receives the mountain’s diffuse and vice versa.

Below are concrete, copy-pastable compositing snippets and the completed Unity URP/HDRP and UE5 setups that: pick front/back per pixel from two depth textures, linearize depth, and apply a contact-band blend. The URP renderer feature is finished to write linear depth to dedicated RTs and invoke the composite.

Depth conventions assumed
- Unity: depth textures are raw hardware depth in [0,1]; use _ZBufferParams to linearize to view-space depth (meters).
- Unreal: SceneDepth is in device depth [0,1]; use MaterialExpressionSceneDepth/AbsoluteWorldPosition or explicit linearization via InvProjection.

1) Unity URP — Completed Renderer Feature and Passes (writes color+linear depth for terrain/mountain, then composites)
Files
- Assets/Scripts/ContactBandFeature.cs
- Assets/Shaders/ContactBandComposite.hlsl
- Assets/Shaders/WriteLinearDepth.hlsl (replacement/override for depth export)

ContactBandComposite.hlsl (URP/HDRP full-screen composite)

cbuffer ContactBandParams : register(b0)
{
    float SeamThickness;   // e.g., 0.15 (meters)
    float SeamFeather;     // e.g., 0.30 (meters)
}

Texture2D TerrainColorTex   : register(t0);
Texture2D TerrainDepthTex   : register(t1);
Texture2D MountainColorTex  : register(t2);
Texture2D MountainDepthTex  : register(t3);
SamplerState LinearClamp    : register(s0);

float smoothstep(float a, float b, float x)
{
    float t = saturate((x - a) / max(b - a, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

struct VSOut {
    float4 posCS : SV_Position;
    float2 uv    : TEXCOORD0;
};

float4 Composite(float2 uv)
{
    float4 tc = TerrainColorTex.Sample(LinearClamp, uv);
    float4 mc = MountainColorTex.Sample(LinearClamp, uv);
    float  td = TerrainDepthTex.Sample(LinearClamp, uv).r; // linear view depth (meters)
    float  md = MountainDepthTex.Sample(LinearClamp, uv).r; // linear view depth (meters)

    // Choose front/back by smaller linear depth (closer to camera)
    bool terrainFront = (td > 0.0) && ((md <= 0.0) ? true : (td <= md));

    float4 frontC = terrainFront ? tc : mc;
    float4 backC  = terrainFront ? mc : tc;
    float  frontD = terrainFront ? td : md;
    float  backD  = terrainFront ? md : td;

    // If back is missing (<= 0), no blend
    if (backD <= 0.0)
        return frontC;

    float delta = abs(frontD - backD);
    float w = 1.0 - smoothstep(SeamThickness, SeamFeather, delta);

    // Blend only in the contact band
    return lerp(frontC, backC, w);
}

float4 Frag(VSOut i) : SV_Target
{
    return Composite(i.uv);
}

// Minimal pass for URP/HDRP will bind this as a full-screen pass

WriteLinearDepth.hlsl (replacement/override pass to output linear view depth to RFloat RT)

CBUFFER_START(UnityPerCamera)
float4 _ZBufferParams; // provided by Unity
CBUFFER_END

float LinearEyeDepth(float raw01)
{
    // Unity helper: LinearEyeDepth = 1 / (a * raw + b)
    return 1.0 / (raw01 * _ZBufferParams.x + _ZBufferParams.y);
}

struct VSOut {
    float4 posCS : SV_Position;
};

float4 FragDepthOnly(VSOut i, float depth01 : SV_Depth) : SV_Target
{
    float lin = LinearEyeDepth(depth01);
    return float4(lin, 0, 0, 0);
}

ContactBandFeature.cs (URP Renderer Feature; two offscreen color+depth passes + composite)

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        public RenderPassEvent eventBeforeComposite = RenderPassEvent.AfterRenderingOpaques;
        public Material compositeMaterial; // Uses ContactBandComposite.hlsl
        public Shader depthWriteShader;    // Uses WriteLinearDepth.hlsl (frag outputs linear depth)
        public int width = 0;   // 0 = camera size
        public int height = 0;
        public RenderTextureFormat colorFmt = RenderTextureFormat.ARGBHalf;
        public RenderTextureFormat depthFmt = RenderTextureFormat.RFloat;
        public float seamThickness = 0.15f;
        public float seamFeather = 0.30f;
    }

    class OffscreenSet
    {
        public int colorID, depthID;
        public RenderTargetIdentifier colorRT, depthRT;
        public FilteringSettings filtering;
        public string tag;
        public ShaderTagId[] shaderTags = new ShaderTagId[] {
            new ShaderTagId("UniversalForward"), new ShaderTagId("UniversalForwardOnly"), new ShaderTagId("SRPDefaultUnlit")
        };
    }

    class OffscreenRenderPass : ScriptableRenderPass
    {
        Settings settings;
        OffscreenSet terrainSet, mountainSet;
        Material depthMat;
        RenderTextureDescriptor baseDesc;

        public OffscreenRenderPass(Settings s)
        {
            settings = s;
            renderPassEvent = s.eventBeforeComposite;
            terrainSet = new OffscreenSet{ tag = "Terrain" };
            mountainSet = new OffscreenSet{ tag = "Mountain" };
            terrainSet.colorID = Shader.PropertyToID("_TerrainColor");
            terrainSet.depthID = Shader.PropertyToID("_TerrainDepth");
            mountainSet.colorID = Shader.PropertyToID("_MountainColor");
            mountainSet.depthID = Shader.PropertyToID("_MountainDepth");
            terrainSet.filtering = new FilteringSettings(RenderQueueRange.opaque, s.terrainLayer);
            mountainSet.filtering = new FilteringSettings(RenderQueueRange.opaque, s.mountainLayer);
            depthMat = s.depthWriteShader ? new Material(s.depthWriteShader) : null;
        }

        public void SetupDesc(RenderTextureDescriptor cameraDesc)
        {
            baseDesc = cameraDesc;
            if (settings.width > 0) baseDesc.width = settings.width;
            if (settings.height > 0) baseDesc.height = settings.height;
            baseDesc.msaaSamples = 1;
            baseDesc.depthBufferBits = 0;
        }

        void AllocRTs(CommandBuffer cmd, OffscreenSet set)
        {
            var colDesc = baseDesc;
            colDesc.colorFormat = settings.colorFmt;
            cmd.GetTemporaryRT(set.colorID, colDesc, FilterMode.Bilinear);

            var depDesc = baseDesc;
            depDesc.colorFormat = settings.depthFmt; // RFloat
            cmd.GetTemporaryRT(set.depthID, depDesc, FilterMode.Point);

            set.colorRT = new RenderTargetIdentifier(set.colorID);
            set.depthRT = new RenderTargetIdentifier(set.depthID);
        }

        void DrawSet(ScriptableRenderContext ctx, CommandBuffer cmd, ref RenderingData rd, OffscreenSet set)
        {
            // 1) Draw shaded color normally into colorRT
            ConfigureTarget(set.colorRT);
            ConfigureClear(ClearFlag.All, Color.clear);
            var sorting = SortingCriteria.CommonOpaque;
            var drawSettings = CreateDrawingSettings(set.shaderTags[0], ref rd, sorting);
            // Additional shader tags
            for (int i = 1; i < set.shaderTags.Length; ++i) drawSettings.SetShaderPassName(i, set.shaderTags[i]);
            ctx.DrawRenderers(rd.cullResults, ref drawSettings, ref set.filtering);

            // 2) Draw linear depth into depthRT using replacement shader (depthMat)
            if (depthMat != null)
            {
                ConfigureTarget(set.depthRT);
                ConfigureClear(ClearFlag.All, Color.clear);
                var depthDraw = CreateDrawingSettings(new ShaderTagId("DepthOnly"), ref rd, sorting);
                depthDraw.overrideMaterial = depthMat;
                ctx.DrawRenderers(rd.cullResults, ref depthDraw, ref set.filtering);
            }
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTextureDescriptor)
        {
            AllocRTs(cmd, terrainSet);
            AllocRTs(cmd, mountainSet);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get("ContactBand_Offscreen");
            using (new ProfilingScope(cmd, new ProfilingSampler("ContactBand_Offscreen")))
            {
                context.ExecuteCommandBuffer(cmd); cmd.Clear();
                DrawSet(context, cmd, ref renderingData, terrainSet);
                DrawSet(context, cmd, ref renderingData, mountainSet);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void FrameCleanup(CommandBuffer cmd)
        {
            cmd.ReleaseTemporaryRT(terrainSet.colorID);
            cmd.ReleaseTemporaryRT(terrainSet.depthID);
            cmd.ReleaseTemporaryRT(mountainSet.colorID);
            cmd.ReleaseTemporaryRT(mountainSet.depthID);
        }
    }

    class CompositePass : ScriptableRenderPass
    {
        Settings settings;
        Material mat;
        public CompositePass(Settings s)
        {
            settings = s;
            mat = s.compositeMaterial;
            renderPassEvent = RenderPassEvent.AfterRendering;
        }
        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            if (mat == null) return;
            var cmd = CommandBufferPool.Get("ContactBand_Composite");
            using (new ProfilingScope(cmd, new ProfilingSampler("ContactBand_Composite")))
            {
                mat.SetFloat("SeamThickness", settings.seamThickness);
                mat.SetFloat("SeamFeather", settings.seamFeather);
                // The offscreen RTs are bound by name below via global textures set implicitly by URP temp RTs
                cmd.Blit(null, BuiltinRenderTextureType.CameraTarget, mat, 0);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }

    public Settings settings = new Settings();
    OffscreenRenderPass offscreenPass;
    CompositePass compositePass;

    public override void Create()
    {
        offscreenPass = new OffscreenRenderPass(settings);
        compositePass = new CompositePass(settings);
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        offscreenPass.SetupDesc(renderingData.cameraData.cameraTargetDescriptor);
        renderer.EnqueuePass(offscreenPass);
        renderer.EnqueuePass(compositePass);
    }
}

Material setup (URP/HDRP)
- Create a Shader Graph or custom HLSL shader that exposes:
  - _TerrainColor (t0), _TerrainDepth (t1), _MountainColor (t2), _MountainDepth (t3)
  - SeamThickness, SeamFeather uniforms
- Ensure the composite material’s pass calls Frag from ContactBandComposite.hlsl.

2) Unity HDRP — Full-screen Custom Pass binding the same HLSL
- Create a FullScreen Custom Pass and assign a Material that uses ContactBandComposite.hlsl.
- Bind Terrain/Mountain color+depth RTs from preceding DrawRenderers custom passes to t0..t3.
- Set SeamThickness/SeamFeather to scene scale (meters).

3) UE5 — Material setup for front/back selection, linearization, and contact-band blend
Nodes (Material Domain: Post Process or Composure Compositing Material)
Inputs
- TextureObject TerrainColorRT (HDR)
- TextureObject MountainColorRT (HDR)
- TextureObject TerrainDepthRT (R32F linear depth meters)
- TextureObject MountainDepthRT (R32F linear depth meters)
- Scalars: SeamThickness, SeamFeather

Graph
- Sample TerrainColor = TextureSample(TerrainColorRT, SceneTexCoord)
- Sample MountainColor = TextureSample(MountainColorRT, SceneTexCoord)
- td = TextureSample(TerrainDepthRT).r
- md = TextureSample(MountainDepthRT).r
- frontIsTerrain = And(td > 0, Or(md <= 0, td <= md))
- frontColor = Lerp(MountainColor, TerrainColor, frontIsTerrain)
- backColor  = Lerp(TerrainColor, MountainColor, frontIsTerrain)
- frontD = Lerp(md, td, frontIsTerrain)
- backD  = Lerp(td, md, frontIsTerrain)
- hasBack = backD > 0
- delta = Abs(frontD - backD)
- w = 1 - SmoothStep(SeamThickness, SeamFeather, delta)
- outColor = Select(frontColor, Lerp(frontColor, backColor, w), hasBack)
- BaseColor/EmissiveColor = outColor (in Post Process, plug into Emissive)

If you must derive linear depth from device depth in UE:
- td_lin = 1 / (A * td_raw + B); same for md. Use View.WorldToClip or InvProj params via Custom node if needed. Prefer writing linear depth directly when capturing.

4) ASCII contact-band diagram (prevents color bleed)
               Camera
                 \
Terrain surface -----====================----- Mountain surface
                  ^   contact band (blend)   ^
                  |                          |
             front-most wins           front-most wins
- Each object shades into its own color target; only final shaded pixels are conditionally mixed based on linear depth proximity. No diffuse/BRDF from the other object is sampled during its shading, so colors don’t bleed.

Notes
- Choose SeamThickness/SeamFeather in world units matching your scene scale.
- Ensure depth RTs store linear eye depth (meters). If a pixel is empty for a layer, store 0 (used as sentinel above).
- In URP, confirm the replacement depth shader runs for all opaque passes you care about; add tags for SRPDefaultUnlit where needed.

Concise explanation
A contact‑band blend prevents color bleed by only mixing colors within a thin screen‑space band around the depth discontinuity (the contact edge) between the terrain and mountain. Outside the band, each pixel shows only the nearest surface (no diffusion). Inside the band, a short falloff blends along the normal/depth gradient, limiting mixing to the immediate contact region and avoiding large‑scale color transfer.

Copy‑pastable HLSL full‑screen composite (Unity URP/HDRP)
// Works in both URP/HDRP full-screen passes. Assumes two color inputs
// (terrainColorTex, mountainColorTex) and two linear depth inputs
// (terrainLinearDepth, mountainLinearDepth) rendered at the same resolution.
// Blend only in a narrow contact band near the depth crossing.

CBUFFER_START(_CompositeParams)
    float _BandPx;        // contact band half-width in pixels (e.g., 2.0)
    float _FeatherPx;     // feather width inside the band (e.g., 1.5)
    float _DepthEps;      // epsilon to avoid z-fighting (e.g., 1e-4)
CBUFFER_END

TEXTURE2D(_TerrainColor);     SAMPLER(sampler_TerrainColor);
TEXTURE2D(_MountainColor);    SAMPLER(sampler_MountainColor);
TEXTURE2D(_TerrainLinDepth);  SAMPLER(sampler_TerrainLinDepth);
TEXTURE2D(_MountainLinDepth); SAMPLER(sampler_MountainLinDepth);

struct VSOut {
    float4 posCS : SV_Position;
    float2 uv    : TEXCOORD0;
};

float bandWeight(float dpx, float bandPx, float featherPx)
{
    // dpx: signed pixel-distance to contact (0 at contact center)
    float a = abs(dpx);
    float inner = bandPx - featherPx;
    // Hard outside band
    if (a >= bandPx) return 0.0;
    // Full mix inside inner core
    if (a <= inner) return 1.0;
    // Feather edge (smoothstep from 1 to 0)
    float t = saturate((a - inner) / max(featherPx, 1e-6));
    return 1.0 - t*t*(3.0 - 2.0*t);
}

// Estimate signed distance to contact using depth difference gradient
float contactDistancePx(float2 uv, float2 texelSize)
{
    // Finite differences on linear depth difference
    float dzc = 0.0; // will be filled by caller via global loads to avoid redundant fetches
    return 0.0; // placeholder not used directly here (see inline implementation below)
}

float4 Composite(float2 uv, float2 texelSize)
{
    float4 colT = _TerrainColor.SampleLevel(sampler_TerrainColor, uv, 0);
    float4 colM = _MountainColor.SampleLevel(sampler_MountainColor, uv, 0);

    float zT = _TerrainLinDepth.SampleLevel(sampler_TerrainLinDepth, uv, 0).r;
    float zM = _MountainLinDepth.SampleLevel(sampler_MountainLinDepth, uv, 0).r;

    // Choose front/back per pixel
    bool terrainFront = (zT + _DepthEps) <= (zM);
    float4 colFront = terrainFront ? colT : colM;
    float4 colBack  = terrainFront ? colM : colT;
    float  zFront   = terrainFront ? zT   : zM;
    float  zBack    = terrainFront ? zM   : zT;

    // Compute signed distance (in pixels) to contact using gradient of depth delta
    // Depth delta field
    float d0 = zBack - zFront; // positive when back is behind front

    // Sample neighbors for gradient magnitude (sobel-lite)
    float2 o = texelSize;
    float dzdx = (( _MountainLinDepth.SampleLevel(sampler_MountainLinDepth, uv + float2(o.x,0), 0).r
                  - _TerrainLinDepth.SampleLevel (sampler_TerrainLinDepth,  uv + float2(o.x,0), 0).r)
                - ( _MountainLinDepth.SampleLevel(sampler_MountainLinDepth, uv - float2(o.x,0), 0).r
                  - _TerrainLinDepth.SampleLevel (sampler_TerrainLinDepth,  uv - float2(o.x,0), 0).r)) * 0.5;
    float dzdy = (( _MountainLinDepth.SampleLevel(sampler_MountainLinDepth, uv + float2(0,o.y), 0).r
                  - _TerrainLinDepth.SampleLevel (sampler_TerrainLinDepth,  uv + float2(0,o.y), 0).r)
                - ( _MountainLinDepth.SampleLevel(sampler_MountainLinDepth, uv - float2(0,o.y), 0).r
                  - _TerrainLinDepth.SampleLevel (sampler_TerrainLinDepth,  uv - float2(0,o.y), 0).r)) * 0.5;

    float grad = max(length(float2(dzdx, dzdy)), 1e-6);

    // Approx signed pixel distance to the zero-crossing of d0
    // Scale depth delta by gradient and convert to pixel units
    float dpx = d0 / grad; // pixels to contact along steepest gradient

    // Contact-band weight 0..1
    float w = bandWeight(dpx, _BandPx, _FeatherPx);

    // Inside band, blend colors; outside, use front only. Prevent diffusion beyond band.
    float4 col = lerp(colFront, colBack, w);
    col.a = 1.0;
    return col;
}

// URP/HDRP full-screen pass entry
struct Attributes { float3 vertex : POSITION; float2 uv : TEXCOORD0; };
struct Varyings  { float4 posCS : SV_Position; float2 uv : TEXCOORD0; };

Varyings Vert(Attributes IN)
{
    Varyings OUT;
    OUT.posCS = float4(IN.vertex.xy, 0.0, 1.0);
    OUT.uv = IN.uv;
    return OUT;
}

float4 Frag(Varyings IN) : SV_Target
{
    // Note: pass _ScreenParams.zw or _RTHandleScale for texelSize depending on pipeline
    // For URP/HDRP bind a float2 _TexelSize = 1/RTSize
    extern float2 _TexelSize;
    return Composite(IN.uv, _TexelSize);
}

// Unity shader snippet wrapper (place in an HLSL file included by a FullScreenPass)
// Ensure you bind:
// _TerrainColor, _MountainColor, _TerrainLinDepth, _MountainLinDepth,
// _BandPx, _FeatherPx, _DepthEps, and _TexelSize.

UE5 Material (copy‑pastable node setup description)
- Create TextureObject parameters: TerrainColor, MountainColor.
- Create TextureObject parameters (R16F/R32F): TerrainLinearDepth, MountainLinearDepth (already linearized; see below if not).
- Sample both color and depth with TextureSample nodes using ScreenPosition (ViewportUV) as UVs.
- Compute front/back:
  1) Add ScalarParameter DepthEps (1e-4). Compare (TerrainDepth + DepthEps) <= MountainDepth → TerrainFront (If node outputs 1/0).
  2) Use Lerp nodes to pick FrontColor/BackColor and FrontDepth/BackDepth based on TerrainFront.
- Contact band:
  1) Make TexelSize: add ScalarParameters RTWidth, RTHeight; make float2(1/RTWidth, 1/RTHeight).
  2) Compute depth delta d0 = BackDepth - FrontDepth.
  3) Sample neighbor depths for gradient: sample TerrainDepth and MountainDepth at offsets (+/-TexelSize.x,0) and (0,+/-TexelSize.y). Compute dzdx, dzdy exactly as in HLSL, then grad = length(float2(dzdx,dzdy)); clamp to >= 1e-6.
  4) dpx = d0 / grad.
  5) Band parameters: ScalarParameters BandPx (2.0), FeatherPx (1.5). Inner = BandPx - FeatherPx. a = abs(dpx). Weight w =
     - If a >= BandPx → 0
     - Else if a <= Inner → 1
     - Else w = 1 - smoothstep(0,1, (a - Inner)/max(FeatherPx,1e-6)).
- Final color = Lerp(FrontColor, BackColor, w). Plug to Emissive (Unlit) or BaseColor in a post-process material.

If your depths are not linear
- Unity: write linear eye depth to the two depth RTs (see URP feature below). For HDRP, use LinearEyeDepth from _CameraDepthTexture when sourcing geometry, or render custom passes to dedicated RTs.
- UE5: linearize scene depth as LinZ = SceneDepth (DeviceZ) converted via InvProjection. In material, use PixelDepth and ResolvedSceneDepth with a custom node: LinZ = r.z / r.w after multiplying by the inverse projection, or use the Material Expression SceneDepth node with ConvertToLinearEyeSpace enabled (5.3+). Ensure both terrain and mountain are captured into separate render targets.

URP: Renderer Feature and Passes to write linear depth RTs and invoke composite
// Minimal ScriptableRendererFeature that:
// 1) Allocates two RTHandles for terrain and mountain linear depths and two for colors.
// 2) Renders terrain and mountain layers separately (LayerMasks) to those RTs.
// 3) Runs a full-screen composite pass with the HLSL above.

// Files: ContactBandCompositeFeature.cs
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandCompositeFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        public Material blitMat; // material using the HLSL composite (Frag)
        public float bandPx = 2f;
        public float featherPx = 1.5f;
        public float depthEps = 1e-4f;
    }

    class DepthColorPass : ScriptableRenderPass
    {
        string m_ProfilerTag;
        FilteringSettings filtering;
        ShaderTagId[] shaderTags = new ShaderTagId[] {
            new ShaderTagId("UniversalForward"),
            new ShaderTagId("SRPDefaultUnlit")
        };

        RTHandle colorRT;
        RTHandle depthLinRT;
        RenderTargetIdentifier cameraDepth;

        public DepthColorPass(string tag, LayerMask layer)
        {
            m_ProfilerTag = tag;
            filtering = new FilteringSettings(RenderQueueRange.all, layer);
        }

        public void Setup(RTHandle color, RTHandle depthLin, RenderTargetIdentifier camDepth)
        {
            colorRT = color;
            depthLinRT = depthLin;
            cameraDepth = camDepth;
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTextureDescriptor)
        {
            ConfigureTarget(colorRT, depthLinRT);
            ConfigureClear(ClearFlag.All, Color.clear);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(m_ProfilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(m_ProfilerTag)))
            {
                // Draw filtered objects
                var sort = SortingCriteria.CommonOpaque;
                var drawingSettings = CreateDrawingSettings(shaderTags, ref renderingData, sort);
                drawingSettings.perObjectData |= PerObjectData.None;

                context.ExecuteCommandBuffer(cmd);
                cmd.Clear();
                context.DrawRenderers(renderingData.cullResults, ref drawingSettings, ref filtering);

                // Linearize the camera depth into depthLinRT (full-screen)
                // Assumes a small material/shader that reads _CameraDepthTexture and writes linear eye depth
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void FrameCleanup(CommandBuffer cmd) {}
    }

    class CompositePass : ScriptableRenderPass
    {
        Material mat;
        RTHandle srcTerrainColor, srcMountainColor, srcTerrainDepth, srcMountainDepth;
        RTHandle destination;
        Vector2 texelSize;
        float bandPx, featherPx, depthEps;

        public CompositePass(Material m)
        {
            mat = m;
        }

        public void Setup(RTHandle tCol, RTHandle mCol, RTHandle tZ, RTHandle mZ, RTHandle dst, Vector2 texSize,
                          float band, float feather, float eps)
        {
            srcTerrainColor = tCol; srcMountainColor = mCol;
            srcTerrainDepth = tZ;  srcMountainDepth = mZ;
            destination = dst;
            texelSize = texSize;
            bandPx = band; featherPx = feather; depthEps = eps;
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get("ContactBandComposite");
            using (new ProfilingScope(cmd, new ProfilingSampler("ContactBandComposite")))
            {
                cmd.SetGlobalTexture("_TerrainColor", srcTerrainColor);
                cmd.SetGlobalTexture("_MountainColor", srcMountainColor);
                cmd.SetGlobalTexture("_TerrainLinDepth", srcTerrainDepth);
                cmd.SetGlobalTexture("_MountainLinDepth", srcMountainDepth);
                cmd.SetGlobalFloat("_BandPx", bandPx);
                cmd.SetGlobalFloat("_FeatherPx", featherPx);
                cmd.SetGlobalFloat("_DepthEps", depthEps);
                cmd.SetGlobalVector("_TexelSize", new Vector4(texelSize.x, texelSize.y, 0, 0));

                Blitter.BlitCameraTexture(cmd, srcTerrainColor, destination, mat, 0);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }

    public Settings settings = new Settings();

    RTHandle tColor, mColor, tDepthLin, mDepthLin, compositeOut;
    DepthColorPass terrainPass, mountainPass;
    CompositePass compositePass;

    public override void Create()
    {
        terrainPass = new DepthColorPass("TerrainPass", settings.terrainLayer) { renderPassEvent = RenderPassEvent.BeforeRenderingTransparents };
        mountainPass = new DepthColorPass("MountainPass", settings.mountainLayer) { renderPassEvent = RenderPassEvent.BeforeRenderingTransparents + 1 };
        compositePass = new CompositePass(settings.blitMat) { renderPassEvent = RenderPassEvent.BeforeRenderingPostProcessing };
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        var desc = renderingData.cameraData.cameraTargetDescriptor;
        desc.depthBufferBits = 0;

        RenderingUtils.ReAllocateIfNeeded(ref tColor,    desc, FilterMode.Bilinear, TextureWrapMode.Clamp, name: "_TColor");
        RenderingUtils.ReAllocateIfNeeded(ref mColor,    desc, FilterMode.Bilinear, TextureWrapMode.Clamp, name: "_MColor");

        var zDesc = desc; zDesc.graphicsFormat = UnityEngine.Experimental.Rendering.GraphicsFormat.R16_SFloat;
        RenderingUtils.ReAllocateIfNeeded(ref tDepthLin, zDesc, FilterMode.Point, TextureWrapMode.Clamp, name: "_TZLin");
        RenderingUtils.ReAllocateIfNeeded(ref mDepthLin, zDesc, FilterMode.Point, TextureWrapMode.Clamp, name: "_MZLin");

        RenderingUtils.ReAllocateIfNeeded(ref compositeOut, desc, FilterMode.Bilinear, TextureWrapMode.Clamp, name: "_CompositeOut");

        var camDepth = renderer.cameraDepthTarget;
        terrainPass.Setup(tColor, tDepthLin, camDepth);
        mountainPass.Setup(mColor, mDepthLin, camDepth);

        renderer.EnqueuePass(terrainPass);
        renderer.EnqueuePass(mountainPass);

        // Use camera color target as destination
        compositePass.Setup(tColor, mColor, tDepthLin, mDepthLin, renderer.cameraColorTargetHandle,
                            new Vector2(1f / desc.width, 1f / desc.height), settings.bandPx, settings.featherPx, settings.depthEps);
        renderer.EnqueuePass(compositePass);
    }

    protected override void Dispose(bool disposing)
    {
        tColor?.Release(); mColor?.Release();
        tDepthLin?.Release(); mDepthLin?.Release();
        compositeOut?.Release();
    }
}

Notes
- To write linear eye depth into tDepthLin/mDepthLin, create a tiny full-screen shader/pass that samples _CameraDepthTexture and converts to linear eye depth using URP’s LinearEyeDepth, then Blit into the target RTHandle at the end of each DepthColorPass. Alternatively, modify your terrain/mountain shaders to output SV_Depth and a linearized depth value to an extra MRT.
- HDRP: use a Custom Pass (Before Post Process) to bind the same HLSL and equivalent color/depth RTs from terrain/mountain rendering. The composite HLSL remains identical.
- This method prevents diffusion across objects because blending is strictly gated to pixels where the signed distance to the depth contact is within the narrow band; elsewhere the back surface never contributes.

