bool IsTradingHourUTC()
{
   // Parse comma-separated hours to skip in UTC
   if(StringLen(InpSkipHoursUTC)==0) return true;
   datetime now = TimeCurrent();
   MqlDateTime t; TimeToStruct(now,t);
   string hours[]; int n = StringSplit(InpSkipHoursUTC, ',', hours);
   for(int i=0;i<n;i++)
   {
      string s = StringTrim(hours[i]);
      if(StringLen(s)==0) continue;
      int h = (int)StringToInteger(s);
      if(h==t.hour) return false; // skip this hour
   }
   return true;
}

bool OnePositionPerSymbol()
{
   // Check there is no open/queued position or order for this symbol+magic
   int total = PositionsTotal();
   for(int i=0;i<total;i++)
   {
      string sym = PositionGetSymbol(i);
      if(sym==gSymbol)
      {
         if(PositionSelectByTicket(PositionGetTicket(i)))
         {
            long mg; PositionGetInteger(POSITION_MAGIC, mg);
            if((ulong)mg == InpMagicNumber) return false;
         }
      }
   }
   // Also check pending orders for same symbol+magic
   int ototal = OrdersTotal();
   for(int j=0;j<ototal;j++)
   {
      if(OrderSelect(j, SELECT_BY_POS))
      {
         string osym = OrderGetString(ORDER_SYMBOL);
         long mg = OrderGetInteger(ORDER_MAGIC);
         if(osym==gSymbol && (ulong)mg==InpMagicNumber) return false;
      }
   }
   return true;
}

bool UpdateSymbolInfo()
{
