bool CopyLatest(const int handle, const int count, double &buff[])
{
   ArraySetAsSeries(buff,true);
   int copied = CopyBuffer(handle, 0, 0, count, buff);
   if(copied < count)
   {
      Print("[WARN] CopyBuffer short read handle=", handle, " copied=", copied, " err=", GetLastError());
      return false;
   }
   return true;
}

// Round lots to broker step and bounds
double NormalizeLots(double lots)
{
   if(lots<gMinVolume) lots = gMinVolume;
   if(lots>gMaxVolume) lots = gMaxVolume;
   double steps = MathRound(lots / gVolStep);
   double norm  = steps * gVolStep;
   norm = MathMax(gMinVolume, MathMin(gMaxVolume, norm));
   return norm;
}

// Compute position size by risk percentage and ATR-based stop distance
bool ComputePositionSize(bool isBuy, double entryPrice, double slPrice, double &outLots)
{
   outLots = 0.0;
   double equity = AccountInfoDouble(ACCOUNT_EQUITY);
   double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
   double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);

   if(InpMinMarginLevelPct>0 && marginLevel>0 && marginLevel < InpMinMarginLevelPct)
   {
      PrintFormat("[RISK] Margin level %.2f%% below threshold %.2f%%. No trade.", marginLevel, InpMinMarginLevelPct);
      return false;
   }

   // Risk amount in account currency
   double riskAmt = equity * (InpRiskPerTradePct/100.0);
   if(riskAmt <= 0)
   {
      Print("[RISK] Computed risk amount <= 0");
      return false;
   }

   double stopDistance = MathAbs(entryPrice - slPrice);
   if(stopDistance <= gPoint* (gStopsLevelPoints+1))
   {
      Print("[RISK] Stop distance too small vs stops level.");
      return false;
   }

   // Value per point per 1 lot
   double contractSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_CONTRACT_SIZE);
   if(contractSize<=0) contractSize=100000.0; // fallback typical FX
   double pipValuePerLot = (gTickValue/gTickSize) * gPoint; // value of 1 point per lot
   double lossPerLot = (stopDistance / gPoint) * pipValuePerLot; // currency loss per lot if SL hits
   if(lossPerLot<=0)
   {
      Print("[RISK] Invalid lossPerLot calc.");
      return false;
   }

   double lotsByRisk = riskAmt / lossPerLot;
   if(lotsByRisk <= 0)
   {
      Print("[RISK] lotsByRisk <= 0");
      return false;
   }

   // Margin constraint via OrderCalcMargin and free-margin usage cap
   MqlTick tk; SymbolInfoTick(gSymbol, tk);
   double priceForMargin = isBuy ? tk.ask : tk.bid;
   double lotsTest = MathMax(gMinVolume, MathMin(gMaxVolume, lotsByRisk));

   // Apply free margin usage cap: single trade margin <= cap% of free margin
   double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
   if(cap<=0)
   {
      Print("[RISK] Free margin cap <=0");
      return false;
   }

   // Find lots constrained by margin cap using iterative reduction
   double marginNeeded=0.0;
   if(!OrderCalcMargin(ORDER_TYPE_BUY, gSymbol, lotsTest, priceForMargin, marginNeeded))
   {
      Print("[ERR] OrderCalcMargin failed. Err=", GetLastError());
      return false;
   }

   if(marginNeeded > cap)
   {
      // scale down proportionally
      double scale = cap / marginNeeded;
      lotsTest = lotsTest * MathMax(0.0, MathMin(1.0, scale));
      // ensure within bounds
      lotsTest = MathMax(gMinVolume, MathMin(gMaxVolume, lotsTest));
      // recalc to verify
      if(!OrderCalcMargin(ORDER_TYPE_BUY, gSymbol, lotsTest, priceForMargin, marginNeeded))
      {
         Print("[ERR] OrderCalcMargin(recheck) failed. Err=", GetLastError());
         return false;
      }
      if(marginNeeded > cap)
      {
         PrintFormat("[RISK] Even minimal scaled lots exceed cap (need %.2f > cap %.2f).", marginNeeded, cap);
         return false;
      }
   }

   // Also require marginNeeded < freeMargin (basic sanity)
   if(marginNeeded >= freeMargin)
   {
      PrintFormat("[RISK] Margin needed %.2f >= free margin %.2f.", marginNeeded, freeMargin);
      return false;
   }

   outLots = NormalizeLots(lotsTest);
   if(outLots < gMinVolume - 1e-8)
   {
      Print("[RISK] Computed lots below min volume.");
      return false;
   }
   return true;
}

bool GetSignal(bool &buySignal, bool &sellSignal, double &atr, double &fast0, double &slow0)
{
   buySignal=false; sellSignal=false; atr=0.0; fast0=0.0; slow0=0.0;

   // Ensure we evaluate on closed bars
   MqlRates rates[]; ArraySetAsSeries(rates, true);
   if(CopyRates(gSymbol, InpTimeframe, 0, 3, rates) < 3) return false;
   if(lastClosedBarTime == rates[1].time) return false; // already processed

   double emaFast[3], emaSlow[3], rsi[3], atrBuf[3];
   if(!CopyLatest(hFastEMA, 3, emaFast)) return false;
   if(!CopyLatest(hSlowEMA, 3, emaSlow)) return false;
   if(!CopyLatest(hRSI, 3, rsi)) return false;
   if(!CopyLatest(hATR, 3, atrBuf)) return false;

   // Use bar[1] as last closed bar, bar[2] previous
   double fastPrev = emaFast[2], fastLast = emaFast[1];
   double slowPrev = emaSlow[2], slowLast = emaSlow[1];
   double rsiLast  = rsi[1];
   atr = atrBuf[1];
   fast0 = fastLast; slow0 = slowLast;

   if(InpATR_MinFilter>0 && atr < InpATR_MinFilter) return false;

   // Cross with RSI filter
   bool bullishCross = (fastPrev < slowPrev) && (fastLast > slowLast);
   bool bearishCross = (fastPrev > slowPrev) && (fastLast < slowLast);

   if(bullishCross && rsiLast >= InpRSI_Buy) buySignal = true;
   if(bearishCross && rsiLast <= InpRSI_Sell) sellSignal = true;

   if(!(buySignal||sellSignal)) return false;

   // Mark processed bar time
   lastClosedBarTime = rates[1].time;
   return true;
}

bool CheckSpreadOK()
{
   MqlTick tk; if(!SymbolInfoTick(gSymbol, tk)) return false;
   double spreadPoints = (tk.ask - tk.bid) / gPoint;
   if(spreadPoints > InpMaxSpreadPoints)
   {
      PrintFormat("[FILTER] Spread %.1f > max %d points. Skip.", spreadPoints, InpMaxSpreadPoints);
      return false;
   }
   return true;
}

void PlaceOrder(bool isBuy, double atr)
{
   MqlTick tk; if(!SymbolInfoTick(gSymbol, tk)) { Print("[ERR] No tick."); return; }
   double price = isBuy ? tk.ask : tk.bid;

   // Compute SL/TP via ATR multiples and RR
   double slDist = MathMax(gPoint*(gStopsLevelPoints+1), atr * InpATR_SL_Mult);
   double sl = isBuy ? price - slDist : price + slDist;
   double tpDist = slDist * InpRR;
   double tp = isBuy ? price + tpDist : price - tpDist;

   // Respect stops level
   double minStop = gPoint * (gStopsLevelPoints + 1);
   if(isBuy)
   {
      if((price - sl) < minStop) sl = price - minStop;
      if((tp - price) < minStop) tp = price + minStop;
   }
   else
   {
      if((sl - price) < minStop) sl = price + minStop;
      if((price - tp) < minStop) tp = price - minStop;
   }

   // Compute lots with robust checks
   double lots=0.0;
   if(!ComputePositionSize(isBuy, price, sl, lots)) return;

   trade.SetExpertMagicNumber(InpMagicNumber);
   trade.SetDeviationInPoints(InpSlippagePoints);

   bool ok=false;
   if(isBuy)
      ok = trade.Buy(lots, gSymbol, price, sl, tp, "EMA/RSI/ATR Buy");
   else
      ok = trade.Sell(lots, gSymbol, price, sl, tp, "EMA/RSI/ATR Sell");

   if(!ok)
   {
      Print("[ERR] Order send failed. RetCode=", trade.ResultRetcode(), " Desc=", trade.ResultRetcodeDescription());
   }
   else
   {
      PrintFormat("[INFO] Order placed %s lots=%.2f price=%.5f SL=%.5f TP=%.5f", isBuy?"BUY":"SELL", lots, price, sl, tp);
   }
}

void ManagePosition()
{
   // One-position-per-symbol; manage SL move to BE and trailing based on ATR
   if(!PositionSelect(gSymbol)) return;
   long mg; PositionGetInteger(POSITION_MAGIC, mg);
   if((ulong)mg != InpMagicNumber) return;

   double posPrice   = PositionGetDouble(POSITION_PRICE_OPEN);
   double posSL      = PositionGetDouble(POSITION_SL);
   double posTP      = PositionGetDouble(POSITION_TP);
   double posVolume  = PositionGetDouble(POSITION_VOLUME);
   long   posType    = PositionGetInteger(POSITION_TYPE);

   MqlTick tk; if(!SymbolInfoTick(gSymbol, tk)) return;
   double price = (posType==POSITION_TYPE_BUY)? tk.bid : tk.ask; // use exit side

   // Pull ATR for trailing
   double atrBuf[2]; if(!CopyLatest(hATR, 2, atrBuf)) return; double atr = atrBuf[1];
   double slTrailDist = atr * InpATR_TrailMult;

   // Compute BE trigger
   double slRiskDist = MathAbs(posPrice - posSL);
   if(slRiskDist<=0) slRiskDist = atr * InpATR_SL_Mult; // fallback
   double beTriggerPrice;
   if(posType==POSITION_TYPE_BUY)
      beTriggerPrice = posPrice + InpBreakevenRR * slRiskDist;
   else
      beTriggerPrice = posPrice - InpBreakevenRR * slRiskDist;

   bool needModify=false; double newSL = posSL;

   // Move to breakeven if reached
   if(InpBreakevenRR>0)
   {
      if(posType==POSITION_TYPE_BUY && price >= beTriggerPrice)
      {
         double beSL = MathMax(posSL, posPrice + (gPoint*(gStopsLevelPoints+1))*0.5 - gPoint); // slightly above open to cover costs
         if(beSL > newSL) { newSL = beSL; needModify=true; }
      }
      else if(posType==POSITION_TYPE_SELL && price <= beTriggerPrice)
      {
         double beSL = MathMin(posSL, posPrice - (gPoint*(gStopsLevelPoints+1))*0.5 + gPoint);
         if(beSL < newSL) { newSL = beSL; needModify=true; }
      }
   }

   // ATR trailing
   if(InpAllowTrailing && atr>0)
   {
      if(posType==POSITION_TYPE_BUY)
      {
         double trailSL = price - slTrailDist;
         if(trailSL > newSL) { newSL = trailSL; needModify=true; }
      }
      else
      {
         double trailSL = price + slTrailDist;
         if(trailSL < newSL || newSL==0.0) { newSL = trailSL; needModify=true; }
      }
   }

   // Respect stops level
   double minStop = gPoint * (gStopsLevelPoints + 1);
   if(posType==POSITION_TYPE_BUY)
   {
      if((price - newSL) < minStop) newSL = price - minStop;
   }
   else
   {
      if((newSL - price) < minStop) newSL = price + minStop;
   }

   // Avoid worsening SL
   if(posType==POSITION_TYPE_BUY && newSL <= posSL) needModify=false;
   if(posType==POSITION_TYPE_SELL && newSL >= posSL && posSL!=0.0) needModify=false;

   if(needModify)
   {
      trade.SetExpertMagicNumber(InpMagicNumber);
      bool ok = trade.PositionModify(gSymbol, NormalizeDouble(newSL, gDigits), posTP);
      if(!ok)
         Print("[ERR] Position modify failed. Ret=", trade.ResultRetcode(), " ", trade.ResultRetcodeDescription());
      else
         PrintFormat("[INFO] Trailing/BE updated SL=%.5f (vol=%.2f)", newSL, posVolume);
   }
}

int OnInit()
{
   if(!UpdateSymbolInfo()) return(INIT_FAILED);
   if(!CreateIndicators()) return(INIT_FAILED);
   lastClosedBarTime = 0;
   Print("[INIT] EMA/RSI/ATR EA initialized on ", gSymbol, " TF=", (int)InpTimeframe);
   return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
   if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
   if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
   if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
   if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
   if(!UpdateSymbolInfo()) return;

   // Session/spread filters
   if(!IsTradingHourUTC()) return;
   if(!CheckSpreadOK())   return;

   // Manage existing position first
   ManagePosition();

   // Enforce one-position-per-symbol
   if(!OnePositionPerSymbol()) return;

   // Generate signal on new closed bar
   bool buySig=false, sellSig=false; double atr=0.0, f0=0.0, s0=0.0;
   if(!GetSignal(buySig, sellSig, atr, f0, s0)) return;

   if(buySig==sellSig) return; // no ambiguous signals

   PlaceOrder(buySig, atr);
}

// Notes:
// - This EA uses equity-based sizing with per-trade free-margin cap and margin level gate.
// - OrderCalcMargin ensures required margin fits the cap and current free margin.
// - Always forward-test on a demo account and optimize inputs per symbol/TF.
// - Past performance does not guarantee future results.

//+------------------------------------------------------------------+
//|                                       EMA_RSI_ATR_Manager.mq5    |
//|   EMA Cross + RSI + ATR with robust risk & margin management     |
//|   One-position-per-symbol, spread/session filters, trailing SL   |
//+------------------------------------------------------------------+
#property strict
#property version   "1.20"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct           = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Min margin level (%) required to open trades (<=0 to ignore)
input double          InpMaxLeveragePerTrade       = 50.0;  // Soft cap: implied leverage of new position (not hard check)
input ulong           InpMagicNumber               = 987654321; // Magic number

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//+------------------------------------------------------------------+
//| Utility: Parse skip hours string to bool map                     |
//+------------------------------------------------------------------+
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//+------------------------------------------------------------------+
//| Utility: Refresh and cache symbol trading info                   |
//+------------------------------------------------------------------+
bool RefreshSymbolInfo(const string sym)
{
  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//+------------------------------------------------------------------+
//| Utility: Normalize lot volume to broker step                     |
//+------------------------------------------------------------------+
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-9);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  // Keep 2 decimals for most FX; adjust if needed
  return NormalizeDouble(v, (int)MathMax(0, (int)MathRound(-MathLog10(gVolStep))));
}

//+------------------------------------------------------------------+
//| Utility: Normalize price to symbol digits                        |
//+------------------------------------------------------------------+
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//+------------------------------------------------------------------+
//| Utility: Check if any open position exists for this symbol       |
//+------------------------------------------------------------------+
bool HasAnyPositionOnSymbol(const string sym)
{
  for(int i=0;i<PositionsTotal();i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

//+------------------------------------------------------------------+
//| Utility: Find our own (magic) position on this symbol            |
//+------------------------------------------------------------------+
bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0; typeOut=-1; slOut=0; tpOut=0; volumeOut=0; priceOpenOut=0;
  for(int i=0;i<PositionsTotal();i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;
    ticketOut     = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut       = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut  = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut         = PositionGetDouble(POSITION_SL);
    tpOut         = PositionGetDouble(POSITION_TP);
    volumeOut     = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//+------------------------------------------------------------------+
//| Utility: Get last closed candle time                             |
//+------------------------------------------------------------------+
datetime LastClosedBarTime(const string sym, ENUM_TIMEFRAMES tf)
{
  MqlRates rates[];
  if(CopyRates(sym, tf, 0, 3, rates) < 2) return 0;
  ArraySetAsSeries(rates, true);
  return rates[1].time;
}

//+------------------------------------------------------------------+
//| Utility: Spread filter (points)                                  |
//+------------------------------------------------------------------+
bool SpreadOK(const string sym)
{
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return false;
  double spreadPoints = (tick.ask - tick.bid) / gPoint;
  return (spreadPoints <= InpMaxSpreadPoints);
}

//+------------------------------------------------------------------+
//| Utility: Session hour filter (UTC)                               |
//+------------------------------------------------------------------+
bool SessionOK()
{
  datetime now = TimeCurrent();
  MqlDateTime dt; TimeToStruct(now, dt);
  int hourUTC = dt.hour; // server time often UTC or near; adapt if needed
  if(hourUTC<0 || hourUTC>23) return true;
  return !gSkipHour[hourUTC];
}

//+------------------------------------------------------------------+
//| Indicator values on closed bar                                   |
//+------------------------------------------------------------------+
bool GetIndicators(const string sym, ENUM_TIMEFRAMES tf,
                   double &emaFastPrev, double &emaFastCur,
                   double &emaSlowPrev, double &emaSlowCur,
                   double &rsiPrev, double &rsiCur,
                   double &atrPrev, double &atrCur)
{
  double f[3], s[3], r[3], a[3];
  ArraySetAsSeries(f,true); ArraySetAsSeries(s,true);
  ArraySetAsSeries(r,true); ArraySetAsSeries(a,true);

  if(CopyBuffer(hFastEMA,0,0,3,f)<3) return false;
  if(CopyBuffer(hSlowEMA,0,0,3,s)<3) return false;
  if(CopyBuffer(hRSI,0,0,3,r)<3) return false;
  if(CopyBuffer(hATR,0,0,3,a)<3) return false;

  emaFastCur = f[0];  emaFastPrev = f[1];
  emaSlowCur = s[0];  emaSlowPrev = s[1];
  rsiCur     = r[0];  rsiPrev     = r[1];
  atrCur     = a[0];  atrPrev     = a[1];

  return (emaFastCur!=0 && emaSlowCur!=0 && atrCur!=0);
}

//+------------------------------------------------------------------+
//| Signal generation (on closed bar)                                |
//+------------------------------------------------------------------+
int GenerateSignal(const string sym, ENUM_TIMEFRAMES tf, double &atr, double &slPrice, double &tpPrice, bool &isBuy)
{
  double efp, efc, esp, esc, rp, rc, ap, ac;
  if(!GetIndicators(sym, tf, efp, efc, esp, esc, rp, rc, ap, ac)) return 0;

  atr = ac;
  if(InpATR_MinFilter>0 && atr < InpATR_MinFilter) return 0;

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return 0;

  // EMA cross with RSI filter
  bool bullCross = (efp <= esp) && (efc > esc) && (rc >= InpRSI_Buy);
  bool bearCross = (efp >= esp) && (efc < esc) && (rc <= InpRSI_Sell);

  if(bullCross)
  {
    isBuy = true;
    double slDist = atr * InpATR_SL_Mult;
    slPrice = NormalizePrice(tick.bid - slDist);
    double tpDist = (slDist * InpRR);
    tpPrice = NormalizePrice(tick.ask + tpDist);
    return 1;
  }
  if(bearCross)
  {
    isBuy = false;
    double slDist = atr * InpATR_SL_Mult;
    slPrice = NormalizePrice(tick.ask + slDist);
    double tpDist = (slDist * InpRR);
    tpPrice = NormalizePrice(tick.bid - tpDist);
    return -1;
  }
  return 0;
}

//+------------------------------------------------------------------+
//| Compute position size from equity risk and SL distance           |
//+------------------------------------------------------------------+
double ComputeVolumeFromRisk(const string sym, bool isBuy, double entryPrice, double slPrice)
{
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double riskMoney = MathMax(0.0, equity * InpRiskPerTradePct/100.0);
  if(riskMoney <= 0.0) return 0.0;

  double slDistAbs = MathAbs(entryPrice - slPrice);
  if(slDistAbs <= 0.0) return 0.0;

  // Value per point per lot
  double pointValuePerLot = gTickValue * (gPoint / gTickSize);
  if(pointValuePerLot <= 0.0) return 0.0;

  double slPoints = slDistAbs / gPoint;
  if(slPoints <= 0.0) return 0.0;

  // Money loss per lot at SL
  double lossPerLot = slPoints * pointValuePerLot;
  if(lossPerLot <= 0.0) return 0.0;

  double rawLots = riskMoney / lossPerLot;
  return NormalizeVolume(rawLots);
}

//+------------------------------------------------------------------+
//| Pre-trade risk/margin validation and volume capping              |
//+------------------------------------------------------------------+
bool ValidateAndCapByMargin(const string sym, ENUM_ORDER_TYPE type, double entryPrice, double &volume)
{
  if(volume<=0.0) return false;

  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double equity     = AccountInfoDouble(ACCOUNT_EQUITY);
  double balance    = AccountInfoDouble(ACCOUNT_BALANCE);

  // Current margin level (%) if available
  double marginLevel = 0.0;
  double marginUsed  = AccountInfoDouble(ACCOUNT_MARGIN);
  if(marginUsed > 0.0)
    marginLevel = (equity / marginUsed) * 100.0;

  if(InpMinMarginLevelPct>0.0 && marginLevel>0.0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("Blocked: margin level %.2f%% below required %.2f%%", marginLevel, InpMinMarginLevelPct);
    return false;
  }

  // Calculate margin required for desired volume; iteratively reduce if needed
  double maxMarginUse = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(maxMarginUse <= 0.0)
  {
    Print("Blocked: max margin use computed <= 0");
    return false;
  }

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return false;
  double price = (type==ORDER_TYPE_BUY ? tick.ask : tick.bid);

  // Check leverage heuristic (soft cap): not exceeding InpMaxLeveragePerTrade times equity
  // Implied position notional = price * contract size * lots. We'll approximate via margin calc below.

  for(int i=0;i<20;i++)
  {
    double marginReq=0.0;
    if(!OrderCalcMargin(type, sym, volume, price, marginReq))
    {
      PrintFormat("OrderCalcMargin failed for vol %.2f, err %d", volume, GetLastError());
      return false;
    }

    if(marginReq <= maxMarginUse && marginReq < freeMargin)
      break;

    // Reduce by step and continue
    volume = NormalizeVolume(volume * 0.8);
    if(volume < gMinVolume)
    {
      PrintFormat("Blocked: volume fell below min after margin cap. FreeMargin=%.2f Need<=%.2f", freeMargin, maxMarginUse);
      return false;
    }
  }

  // Recompute final margin and do final checks
  double finalMargin=0.0;
  if(!OrderCalcMargin(type, sym, volume, price, finalMargin))
  {
    PrintFormat("OrderCalcMargin final failed: err %d", GetLastError());
    return false;
  }

  if(finalMargin > maxMarginUse || finalMargin >= freeMargin)
  {
    PrintFormat("Blocked: final margin %.2f exceeds cap %.2f or free %.2f", finalMargin, maxMarginUse, freeMargin);
    return false;
  }

  // Soft leverage check (approximate): position notional ~= price * lot size
  double contractSize = SymbolInfoDouble(sym, SYMBOL_TRADE_CONTRACT_SIZE);
  double notional = price * contractSize * volume;
  double impliedLev = (equity>0.0 ? notional / equity : 0.0);
  if(InpMaxLeveragePerTrade>0.0 && impliedLev > InpMaxLeveragePerTrade)
  {
    // downsize to meet implied leverage cap
    double targetLots = volume * (InpMaxLeveragePerTrade / impliedLev);
    volume = NormalizeVolume(targetLots);
    if(volume < gMinVolume)
    {
      PrintFormat("Blocked: implied leverage %.1fx exceeds cap %.1fx and downsized vol < min", impliedLev, InpMaxLeveragePerTrade);
      return false;
    }
  }

  return true;
}

//+------------------------------------------------------------------+
//| Open trade with full checks, SL/TP                               |
//+------------------------------------------------------------------+
bool PlaceOrder(const string sym, bool isBuy, double slPrice, double tpPrice)
{
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { Print("No tick"); return false; }
  double entry = isBuy ? tick.ask : tick.bid;

  // Respect stops/freeze levels
  int minStops = gStopsLevelPoints;
  double minStopDist = minStops * gPoint;
  if(minStops>0)
  {
    if(isBuy)
    {
      if(entry - slPrice < minStopDist) slPrice = NormalizePrice(entry - minStopDist);
      if(tpPrice - entry < minStopDist) tpPrice = NormalizePrice(entry + minStopDist);
    }
    else
    {
      if(slPrice - entry < minStopDist) slPrice = NormalizePrice(entry + minStopDist);
      if(entry - tpPrice < minStopDist) tpPrice = NormalizePrice(entry - minStopDist);
    }
  }

  // Volume from risk
  double volume = ComputeVolumeFromRisk(sym, isBuy, entry, slPrice);
  if(volume < gMinVolume)
  {
    PrintFormat("Computed volume %.4f < min lot %.4f", volume, gMinVolume);
    return false;
  }

  // Margin validation and capping
  ENUM_ORDER_TYPE type = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  double v = volume;
  if(!ValidateAndCapByMargin(sym, type, entry, v))
    return false;

  volume = v;

  trade.SetDeviationInPoints(InpSlippagePoints);
  trade.SetExpertMagicNumber(InpMagicNumber);

  bool ok = isBuy ? trade.Buy(volume, sym, entry, slPrice, tpPrice) : trade.Sell(volume, sym, entry, slPrice, tpPrice);
  if(!ok)
  {
    PrintFormat("Order send failed: ret=%d err=%d", ok, GetLastError());
    return false;
  }

  return true;
}

//+------------------------------------------------------------------+
//| Trailing stop and breakeven                                      |
//+------------------------------------------------------------------+
void ManageOpenPosition(const string sym)
{
  ulong ticket; long type; double openPrice, sl, tp, vol;
  if(!GetOurPosition(sym, ticket, type, openPrice, sl, tp, vol)) return;

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return;
  double atrCur[]; ArraySetAsSeries(atrCur, true);
  double atr = 0.0;
  double buf[1];
  if(CopyBuffer(hATR,0,0,1,buf)==1) atr = buf[0];
  if(atr<=0) return;

  double trailDist = atr * InpATR_TrailMult;
  int minStops = gStopsLevelPoints;
  double minStopDist = minStops * gPoint;
  double bePrice = openPrice; // breakeven

  if(type == POSITION_TYPE_BUY)
  {
    double price = tick.bid;
    // Breakeven
    if(InpBreakevenRR>0)
    {
      double slInitDist = openPrice - sl;
      if(slInitDist>0)
      {
        double beTrigger = openPrice + (slInitDist * InpBreakevenRR);
        if(price >= beTrigger && (sl < bePrice))
        {
          double newSL = NormalizePrice(MathMax(bePrice, price - trailDist));
          if(minStops>0 && price - newSL < minStopDist) newSL = NormalizePrice(price - minStopDist);
          if(newSL > sl)
            trade.PositionModify(sym, newSL, tp);
        }
      }
    }
    // Trailing
    if(InpAllowTrailing)
    {
      double desiredSL = NormalizePrice(price - trailDist);
      if(minStops>0 && price - desiredSL < minStopDist) desiredSL = NormalizePrice(price - minStopDist);
      if(desiredSL > sl)
        trade.PositionModify(sym, desiredSL, tp);
    }
  }
  else if(type == POSITION_TYPE_SELL)
  {
    double price = tick.ask;
    if(InpBreakevenRR>0)
    {
      double slInitDist = sl - openPrice;
      if(slInitDist>0)
      {
        double beTrigger = openPrice - (slInitDist * InpBreakevenRR);
        if(price <= beTrigger && (sl > bePrice))
        {
          double newSL = NormalizePrice(MathMin(bePrice, price + trailDist));
          if(minStops>0 && newSL - price < minStopDist) newSL = NormalizePrice(price + minStopDist);
          if(newSL < sl)
            trade.PositionModify(sym, newSL, tp);
        }
      }
    }
    if(InpAllowTrailing)
    {
      double desiredSL = NormalizePrice(price + trailDist);
      if(minStops>0 && desiredSL - price < minStopDist) desiredSL = NormalizePrice(price + minStopDist);
      if(desiredSL < sl)
        trade.PositionModify(sym, desiredSL, tp);
    }
  }
}

//+------------------------------------------------------------------+
//| OnInit                                                           |
//+------------------------------------------------------------------+
int OnInit()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym)) return INIT_FAILED;

  ParseSkipHours(InpSkipHoursUTC);

  // Create indicators
  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Indicator handle creation failed");
    return INIT_FAILED;
  }

  gLastClosedBarTime = LastClosedBarTime(sym, InpTimeframe);
  if(gLastClosedBarTime==0) Print("Warning: could not fetch last closed bar time yet.");

  trade.SetExpertMagicNumber(InpMagicNumber);
  return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
//| OnDeinit                                                         |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE)  IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE)  IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)      IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)      IndicatorRelease(hATR);
}

//+------------------------------------------------------------------+
//| OnTick                                                           |
//+------------------------------------------------------------------+
void OnTick()
{
  const string sym = _Symbol;

  // Update symbol info periodically (e.g., on each tick for safety)
  if(!RefreshSymbolInfo(sym)) return;

  // Spread and session filters
  if(!SpreadOK(sym)) return;
  if(!SessionOK()) return;

  // One-position-per-symbol (any position blocks new entries)
  if(HasAnyPositionOnSymbol(sym))
  {
    // Still manage our own position (trailing/breakeven)
    ManageOpenPosition(sym);
    return;
  }

  // Process new bar only
  datetime lastBar = LastClosedBarTime(sym, InpTimeframe);
  if(lastBar==0 || lastBar==gLastClosedBarTime) return;
  gLastClosedBarTime = lastBar;

  double atr, sl, tp; bool isBuy;
  int sig = GenerateSignal(sym, InpTimeframe, atr, sl, tp, isBuy);
  if(sig==0) return;

  if(!PlaceOrder(sym, isBuy, sl, tp)) return;
}

//+------------------------------------------------------------------+
//| Notes:                                                           |
//| - This EA implements: EMA cross + RSI filter, ATR-based SL/TP,   |
//|   trailing stop/breakeven, spread/session filters, one-position  |
//|   per symbol, equity-based sizing, OrderCalcMargin checks, free  |
//|   margin/margin-level validation, and per-trade margin caps.     |
//| - Thorough logging provided for error handling and blockers.     |
//| - Test in Strategy Tester, optimize parameters, and forward test.|
//+------------------------------------------------------------------+

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|  EMA Cross + RSI + ATR with robust risk & margin controls        |
//|  One-position-per-symbol, spread/session filters, trailing stop  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.50"
#property description "EMA Cross + RSI + ATR strategy with full trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity risk per trade (e.g., 0.5 = 0.5%)
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if projected margin level < this (%); ignored if <=0
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//========================
// Utility & Helpers
//========================
void LogLastError(const string context)
{
  int code = GetLastError();
  PrintFormat("%s | Error %d: %s", context, code, ErrorDescription(code));
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    Print("Invalid symbol trading parameters");
    return false;
  }
  return true;
}

bool CreateIndicators()
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);

  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    LogLastError("CreateIndicators failed");
    return false;
  }
  return true;
}

bool CopyLatest(const int handle, double &val)
{
  double buf[];
  if(CopyBuffer(handle,0,0,2,buf)<2)
  {
    LogLastError("CopyBuffer failed");
    return false;
  }
  val = buf[0];
  return true;
}

bool CopyLatest2(const int handle, double &cur, double &prev)
{
  double buf[];
  if(CopyBuffer(handle,0,0,3,buf)<3)
  {
    LogLastError("CopyBuffer(2) failed");
    return false;
  }
  cur  = buf[0];
  prev = buf[1];
  return true;
}

bool IsSessionTradable()
{
  datetime now_utc = TimeCurrent();
  MqlDateTime t; TimeToStruct(now_utc, t);
  if(t.hour>=0 && t.hour<24 && gSkipHour[t.hour]) return false;
  return true;
}

bool HasOpenPosition()
{
  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    if(PositionGetInteger(POSITION_MAGIC)==(long)InpMagicNumber && PositionGetString(POSITION_SYMBOL)==gSymbol)
      return true;
  }
  return false;
}

int PositionDirection()
{
  if(!PositionSelect(gSymbol)) return 0;
  if((ulong)PositionGetInteger(POSITION_MAGIC)!=(ulong)InpMagicNumber) return 0;
  long type = PositionGetInteger(POSITION_TYPE);
  if(type==POSITION_TYPE_BUY) return 1;
  if(type==POSITION_TYPE_SELL) return -1;
  return 0;
}

// Round volume to broker step/limits
double NormalizeVolume(double vol)
{
  if(vol<gMinVolume) vol = gMinVolume;
  if(vol>gMaxVolume) vol = gMaxVolume;
  double steps = MathRound((vol - gMinVolume)/gVolStep);
  double v = gMinVolume + steps*gVolStep;
  v = MathMax(gMinVolume, MathMin(v, gMaxVolume));
  return v;
}

// Compute volume using equity risk %, ATR stop, and OrderCalcMargin to respect margin caps
bool ComputeVolumeWithRisk(bool isBuy, double entry_price, double sl_price, double &out_volume)
{
  out_volume = 0.0;
  if(sl_price<=0 || entry_price<=0) return false;

  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double max_loss = equity * (InpRiskPerTradePct/100.0);
  if(max_loss<=0) return false;

  double tick_value = gTickValue;
  double tick_size  = gTickSize;
  if(tick_value<=0 || tick_size<=0) return false;

  double stop_distance = MathAbs(entry_price - sl_price);
  if(stop_distance < tick_size)
    stop_distance = tick_size;

  // Value per lot for the stop distance
  double money_per_lot_at_stop = (stop_distance / tick_size) * tick_value;
  if(money_per_lot_at_stop<=0) return false;

  // Raw volume from risk
  double vol_from_risk = max_loss / money_per_lot_at_stop;

  // Now enforce margin constraints via OrderCalcMargin and free-margin cap
  double vol = MathMax(gMinVolume, vol_from_risk);
  vol = MathMin(vol, gMaxVolume);

  // Projected margin usage must be <= cap of free margin
  double margin_cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(margin_cap<=0) return false;

  // Binary search to fit both: margin cap and at least minimal risk-derived volume
  double lo = gMinVolume;
  double hi = MathMin(vol, gMaxVolume);
  if(hi < gMinVolume) return false;

  double best = 0.0;
  for(int iter=0; iter<32; ++iter)
  {
    double mid = NormalizeVolume((lo+hi)/2.0);
    if(mid<=0) break;

    double price = entry_price;
    ENUM_ORDER_TYPE type = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
    double req_margin = 0.0;
    if(!OrderCalcMargin(type, gSymbol, mid, price, req_margin))
    {
      LogLastError("OrderCalcMargin failed in sizing");
      return false;
    }

    // Check free margin and cap
    bool ok_margin_cap = (req_margin <= margin_cap);

    // Project margin level after opening position: MarginLevel% = Equity / Margin * 100
    double current_margin = AccountInfoDouble(ACCOUNT_MARGIN);
    double projected_margin = current_margin + req_margin;
    double projected_margin_level = (projected_margin>0 ? (equity / projected_margin) * 100.0 : DBL_MAX);
    bool ok_margin_level = (InpMinMarginLevelPct<=0.0) || (projected_margin_level >= InpMinMarginLevelPct);

    if(ok_margin_cap && ok_margin_level)
    {
      best = mid;
      lo = mid; // try bigger
    }
    else
    {
      hi = mid; // too big
    }
  }

  // Ensure the best volume still aligns with risk (can't exceed free margin constraints by construction)
  if(best <= 0.0)
    return false;

  out_volume = NormalizeVolume(best);
  if(out_volume < gMinVolume)
    return false;

  // Final margin recheck at chosen volume
  double final_margin = 0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, out_volume, entry_price, final_margin))
  {
    LogLastError("OrderCalcMargin final check failed");
    return false;
  }
  double final_free = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(final_margin > final_free)
    return false;

  double current_margin2 = AccountInfoDouble(ACCOUNT_MARGIN);
  double projected_margin2 = current_margin2 + final_margin;
  double projected_level2 = (projected_margin2>0 ? (AccountInfoDouble(ACCOUNT_EQUITY) / projected_margin2) * 100.0 : DBL_MAX);
  if(InpMinMarginLevelPct>0.0 && projected_level2 < InpMinMarginLevelPct)
    return false;

  return true;
}

bool GetSignals(bool &buy_signal, bool &sell_signal)
{
  buy_signal=false; sell_signal=false;

  double emaFastCur, emaFastPrev, emaSlowCur, emaSlowPrev, rsiCur, atrCur;
  if(!CopyLatest2(hFastEMA, emaFastCur, emaFastPrev)) return false;
  if(!CopyLatest2(hSlowEMA, emaSlowCur, emaSlowPrev)) return false;
  if(!CopyLatest(hRSI, rsiCur)) return false;
  if(!CopyLatest(hATR, atrCur)) return false;

  if(InpATR_MinFilter>0.0 && atrCur < InpATR_MinFilter)
    return true; // no trade due low volatility

  bool crossUp   = (emaFastPrev <= emaSlowPrev) && (emaFastCur > emaSlowCur);
  bool crossDown = (emaFastPrev >= emaSlowPrev) && (emaFastCur < emaSlowCur);

  if(crossUp && rsiCur >= InpRSI_Buy)
    buy_signal = true;
  if(crossDown && rsiCur <= InpRSI_Sell)
    sell_signal = true;

  return true;
}

bool SpreadOK()
{
  MqlTick tk; if(!SymbolInfoTick(gSymbol, tk)) { LogLastError("SymbolInfoTick"); return false; }
  double spread_points = (tk.ask - tk.bid) / gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

// Place order with SL/TP calculated from ATR multipliers and RR
bool PlaceOrder(bool isBuy)
{
  MqlTick tk; if(!SymbolInfoTick(gSymbol, tk)) { LogLastError("SymbolInfoTick in PlaceOrder"); return false; }

  double atrCur; if(!CopyLatest(hATR, atrCur)) return false;
  double sl, tp, entry;
  if(isBuy)
  {
    entry = tk.ask;
    sl = entry - InpATR_SL_Mult * atrCur;
    double rr_dist = InpRR * (entry - sl);
    tp = entry + rr_dist;
  }
  else
  {
    entry = tk.bid;
    sl = entry + InpATR_SL_Mult * atrCur;
    double rr_dist = InpRR * (sl - entry);
    tp = entry - rr_dist;
  }

  // Respect broker stops level/freeze
  int min_dist_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double min_dist = min_dist_pts * gPoint;
  if(isBuy)
  {
    if((entry - sl) < min_dist) sl = entry - min_dist;
    if((tp - entry) < min_dist) tp = entry + min_dist;
  }
  else
  {
    if((sl - entry) < min_dist) sl = entry + min_dist;
    if((entry - tp) < min_dist) tp = entry - min_dist;
  }

  // Compute volume using risk and margin constraints
  double vol=0.0;
  if(!ComputeVolumeWithRisk(isBuy, entry, sl, vol))
  {
    Print("ComputeVolumeWithRisk failed or constraints not met");
    return false;
  }

  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool result=false;
  if(isBuy)
    result = trade.Buy(vol, gSymbol, entry, sl, tp, "EMA_RSI_ATR Buy");
  else
    result = trade.Sell(vol, gSymbol, entry, sl, tp, "EMA_RSI_ATR Sell");

  if(!result)
  {
    LogLastError("Order send failed");
    return false;
  }
  return true;
}

void ManagePosition()
{
  if(!PositionSelect(gSymbol)) return;
  if((ulong)PositionGetInteger(POSITION_MAGIC)!=(ulong)InpMagicNumber) return;

  if(!InpAllowTrailing) return;

  double atrCur; if(!CopyLatest(hATR, atrCur)) return;

  long type = PositionGetInteger(POSITION_TYPE);
  double open_price = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl = PositionGetDouble(POSITION_SL);
  double tp = PositionGetDouble(POSITION_TP);
  double price_current = (type==POSITION_TYPE_BUY) ? SymbolInfoDouble(gSymbol, SYMBOL_BID)
                                                   : SymbolInfoDouble(gSymbol, SYMBOL_ASK);

  // Breakeven logic
  if(InpBreakevenRR>0.0)
  {
    double initial_risk = MathAbs(open_price - sl);
    if(initial_risk>0)
    {
      double rr = MathAbs(price_current - open_price) / initial_risk;
      if(rr >= InpBreakevenRR)
      {
        double be_sl = (type==POSITION_TYPE_BUY) ? open_price + (gPoint* (gStopsLevelPoints>0?gStopsLevelPoints:0))
                                                 : open_price - (gPoint* (gStopsLevelPoints>0?gStopsLevelPoints:0));
        if(type==POSITION_TYPE_BUY && (sl<be_sl))
          trade.PositionModify(gSymbol, be_sl, tp);
        if(type==POSITION_TYPE_SELL && (sl>be_sl || sl==0.0))
          trade.PositionModify(gSymbol, be_sl, tp);
      }
    }
  }

  // ATR trailing
  double trail = InpATR_TrailMult * atrCur;
  if(trail <= 0) return;

  if(type==POSITION_TYPE_BUY)
  {
    double new_sl = price_current - trail;
    // respect min distance
    int min_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
    double min_d = min_pts * gPoint;
    if((price_current - new_sl) < min_d) new_sl = price_current - min_d;
    if(new_sl > sl && new_sl < price_current)
      trade.PositionModify(gSymbol, new_sl, tp);
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double new_sl = price_current + trail;
    int min_pts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
    double min_d = min_pts * gPoint;
    if((new_sl - price_current) < min_d) new_sl = price_current + min_d;
    if((sl==0.0 || new_sl < sl) && new_sl > price_current)
      trade.PositionModify(gSymbol, new_sl, tp);
  }
}

//========================
// Standard Events
//========================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("RefreshSymbolInfo failed");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  if(!CreateIndicators())
  {
    Print("CreateIndicators failed");
    return(INIT_FAILED);
  }

  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(!RefreshSymbolInfo(_Symbol)) return;

  // One-position-per-symbol rule
  if(HasOpenPosition())
  {
    ManagePosition();
    return;
  }

  if(!IsSessionTradable()) return;
  if(!SpreadOK()) return;

  // Ensure indicators are ready
  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    if(!CreateIndicators()) return;
  }

  bool buySig=false, sellSig=false;
  if(!GetSignals(buySig, sellSig)) return;
  if(!buySig && !sellSig) return;

  // For actual placement, ComputeVolumeWithRisk will enforce all constraints.
  if(buySig)
  {
    if(!PlaceOrder(true)) { /* error logged inside */ }
  }
  else if(sellSig)
  {
    if(!PlaceOrder(false)) { /* error logged inside */ }
  }
}
